_THREADPOOL_LIMITER = None

def configure_runtime_cores(requested):
    """Apply a conservative process/thread budget across supported numerical libraries."""
    global _THREADPOOL_LIMITER
    try:
        n=int(requested)
    except Exception:
        n=0
    if n <= 0:
        n=max(1, (os.cpu_count() or 1))
    n=max(1, min(n, os.cpu_count() or n))
    # Respect an explicitly requested total CPU budget and avoid nested oversubscription.
    for key in ("OMP_NUM_THREADS","OPENBLAS_NUM_THREADS","MKL_NUM_THREADS",
                "NUMEXPR_NUM_THREADS","VECLIB_MAXIMUM_THREADS","GDAL_NUM_THREADS"):
        os.environ[key]=str(n)
    try:
        from threadpoolctl import threadpool_limits
        _THREADPOOL_LIMITER=threadpool_limits(limits=n)
    except Exception:
        _THREADPOOL_LIMITER=None
    return n

@contextmanager
def stage_progress(label):
    """Visible one-stage progress/timing wrapper used around non-iterative heavy stages."""
    t0=time.perf_counter()
    try:
        from tqdm import tqdm as _tqdm_stage
        bar=_tqdm_stage(total=1,desc=label,unit="stage",leave=True)
    except Exception:
        bar=None
        print(f"[stage] {label} ...",flush=True)
    try:
        yield
    finally:
        dt=time.perf_counter()-t0
        if bar is not None:
            bar.update(1); bar.set_postfix_str(f"{dt:.1f}s"); bar.close()
        else:
            print(f"[stage] {label}: done in {dt:.1f}s",flush=True)

def _parse_environment_modifiers(values):
    out=[]
    for raw in (values or []):
        for item in str(raw).split(","):
            item=item.strip().lower()
            if item and item not in out:
                out.append(item)
    return out

def apply_environment_modifiers(args):
    """Composable field-condition modifiers. They enable diagnostics or conservative
    defaults only; they never silently apply destructive correction."""
    mods=_parse_environment_modifiers(getattr(args,"environment",None))
    notes=[]
    valid={"quiet","ploughed","volcanic","heterogeneous","ferrous","rough-terrain","wet","dry","saline"}
    bad=[m for m in mods if m not in valid]
    if bad:
        raise SystemExit("Unknown --environment value(s): %s. Valid: %s" %
                         (", ".join(bad), ", ".join(sorted(valid))))
    if "ploughed" in mods:
        args.plough_diagnostic=True
        notes.append("environment=ploughed: furrow periodicity diagnostic enabled; orientation matching acquisition is NOT treated as evidence against ploughing")
    if "volcanic" in mods:
        if getattr(args,"soil_environment","auto")=="auto":
            args.soil_environment="volcanic-basaltic"
        notes.append("environment=volcanic: volcanic-basaltic geological context selected")
    if "heterogeneous" in mods:
        if not _flag_provided("--regional-iterations"):
            args.regional_iterations=max(int(getattr(args,"regional_iterations",3)),4)
        if not _flag_provided("--local-noise-window"):
            args.local_noise_window=min(float(getattr(args,"local_noise_window",4.0)),3.0)
        notes.append("environment=heterogeneous: stronger robust background diagnostics and more local noise estimation")
    if "ferrous" in mods:
        args.auto_qc=True
        notes.append("environment=ferrous: artifact/QC diagnostics emphasized; no automatic spike repair")
    if "rough-terrain" in mods:
        if not _flag_provided("--statistic"):
            args.statistic="median"
        if not _flag_provided("--fill-distance"):
            args.fill_distance=min(float(getattr(args,"fill_distance",0.5)),0.5)
        notes.append("environment=rough-terrain: robust median aggregation and conservative interpolation support")
    if "wet" in mods and getattr(args,"soil_environment","auto")=="auto":
        args.soil_environment="wetland-peat"; notes.append("environment=wet: wetland/peat context selected")
    if "saline" in mods and getattr(args,"soil_environment","auto")=="auto":
        args.soil_environment="saline-coastal"; notes.append("environment=saline: saline/coastal context selected")
    if "dry" in mods and getattr(args,"soil_environment","auto")=="auto":
        args.soil_environment="arid-desert"; notes.append("environment=dry: arid context selected")
    if "quiet" in mods:
        notes.append("environment=quiet: no extra correction enabled")
    return notes

