def _doctor():
    required=['numpy','scipy','pyproj','rasterio','matplotlib','tqdm','skimage','PIL','geopandas','shapely','pyogrio','pandas','xyzservices','threadpoolctl']
    optional=['contextily','metpy','ppigrf','samgeo']
