def _which_or_path(name: str) -> str:
    p = shutil.which(name)
    if p:
        return p
    if Path(name).exists():
        return str(Path(name).resolve())
    raise SystemExit(
        f"Required RTKLIB executable not found: {name}. Install RTKLIB rnx2rtkp or pass an explicit path."
    )


def _open_text(path: Path):
    path = Path(path)
    if path.suffix.lower() == ".gz":
        return gzip.open(path, "rt", encoding="ascii", errors="replace")
    return path.open("r", encoding="ascii", errors="replace")


def inspect_rinex(path: Path) -> dict:
    """Inspect a RINEX observation/navigation file without receiver-specific assumptions."""
    path = Path(path)
    info = {
        "path": str(path),
        "size_bytes": path.stat().st_size,
        "is_rinex": False,
        "version": None,
        "file_type": None,
        "satellite_system": None,
        "marker_name": None,
        "marker_number": None,
        "receiver": None,
        "antenna": None,
        "approx_position_xyz_m": None,
        "time_first_obs": None,
        "time_last_obs": None,
        "interval_s": None,
        "observation_types": [],
    }
    with _open_text(path) as fh:
        for i, line in enumerate(fh):
            if i > 20000:
                break
            label = line[60:80].strip() if len(line) >= 61 else ""
            if i == 0 and "RINEX VERSION / TYPE" in line:
                info["is_rinex"] = True
                try:
                    info["version"] = float(line[:9].strip())
                except Exception:
                    info["version"] = line[:9].strip() or None
                info["file_type"] = line[20:21].strip() or None
                info["satellite_system"] = line[40:41].strip() or None
            if label == "MARKER NAME":
                info["marker_name"] = line[:60].strip()
            elif label == "MARKER NUMBER":
                info["marker_number"] = line[:20].strip()
            elif label == "REC # / TYPE / VERS":
                info["receiver"] = line[:60].rstrip()
            elif label == "ANT # / TYPE":
                info["antenna"] = line[:60].rstrip()
            elif label == "APPROX POSITION XYZ":
                try:
                    info["approx_position_xyz_m"] = [float(v) for v in line[:60].split()[:3]]
                except Exception:
                    pass
            elif label == "INTERVAL":
                try:
                    info["interval_s"] = float(line[:10].strip())
                except Exception:
                    pass
            elif label in ("TIME OF FIRST OBS", "TIME OF LAST OBS"):
                vals = line[:43].split()
                if len(vals) >= 6:
                    try:
                        sec = float(vals[5]); whole = int(sec); micro = int(round((sec-whole)*1e6))
                        if micro >= 1_000_000:
                            whole += 1; micro -= 1_000_000
                        dt = _dt.datetime(int(vals[0]), int(vals[1]), int(vals[2]), int(vals[3]), int(vals[4]), whole, micro,
                                          tzinfo=_dt.timezone.utc)
                        info["time_first_obs" if label == "TIME OF FIRST OBS" else "time_last_obs"] = dt.isoformat()
                    except Exception:
                        pass
            elif label in ("SYS / # / OBS TYPES", "# / TYPES OF OBSERV"):
                toks = line[:60].split()
                info["observation_types"].extend(t for t in toks if re.fullmatch(r"[A-Z][0-9A-Z]{1,2}", t))
            if label == "END OF HEADER":
                break
    info["observation_types"] = sorted(set(info["observation_types"]))
    return info


def validate_rinex(path: Path, expected: str | None = None) -> dict:
    info = inspect_rinex(path)
    if not info["is_rinex"]:
        raise SystemExit(f"Not recognized as RINEX: {path}")
    # RINEX type O = observation. Navigation file letters vary by generation/system;
    # we therefore enforce observation files strictly and only require RINEX for nav.
    if expected == "observation" and str(info.get("file_type") or "").upper() != "O":
        raise SystemExit(f"RINEX observation file expected, but header type is {info.get('file_type')!r}: {path}")
    return info


def _llh_to_ecef(lat: float, lon: float, h: float):
    tr = Transformer.from_crs(4979, 4978, always_xy=True)
    x, y, z = tr.transform(float(lon), float(lat), float(h))
    return float(x), float(y), float(z)


def _ecef_to_llh(x: float, y: float, z: float):
    tr = Transformer.from_crs(4978, 4979, always_xy=True)
    lon, lat, h = tr.transform(float(x), float(y), float(z))
    return float(lat), float(lon), float(h)


def _ecef_delta_to_enu(dx, dy, dz, lat_deg, lon_deg):
    lat=np.deg2rad(lat_deg); lon=np.deg2rad(lon_deg)
    sl,cl=np.sin(lon),np.cos(lon); sp,cp=np.sin(lat),np.cos(lat)
    e=-sl*dx+cl*dy
    n=-sp*cl*dx-sp*sl*dy+cp*dz
    u=cp*cl*dx+cp*sl*dy+sp*dz
    return float(e),float(n),float(u)


def _parse_rtklib_pos_line(line: str):
    s = line.strip()
    if not s or s.startswith("%") or s.startswith("#"):
        return None
    m = re.match(r"^(\d{4})[/-](\d{2})[/-](\d{2})\s+(\d{2}):(\d{2}):(\d{2}(?:\.\d+)?)\s+(.+)$", s)
    if not m:
        return None
    year, mon, day, hh, mm = map(int, m.group(1,2,3,4,5)); sec = float(m.group(6))
    whole = int(sec); micro = int(round((sec-whole)*1e6))
    if micro >= 1_000_000:
        whole += 1; micro -= 1_000_000
    try:
        dt = _dt.datetime(year,mon,day,hh,mm,whole,micro,tzinfo=_dt.timezone.utc)
    except Exception:
        return None
    toks = m.group(7).split()
    if len(toks) < 3:
        return None
    try:
        lat, lon, h = map(float, toks[:3])
    except Exception:
        return None
    q = int(float(toks[3])) if len(toks)>3 else 0
    ns = int(float(toks[4])) if len(toks)>4 else 0
    vals=[]
    for t in toks[5:]:
        try: vals.append(float(t))
        except Exception: vals.append(np.nan)
    row={"time_utc":dt.isoformat().replace("+00:00","Z"),"unix_s":dt.timestamp(),
         "lat":lat,"lon":lon,"height_m":h,"quality":q,"nsat":ns}
    keys=("sdn_m","sde_m","sdu_m","sdne_m","sdeu_m","sdun_m","age_s","ratio")
    for k,v in zip(keys,vals): row[k]=v
    return row


def read_rtklib_pos(path: Path):
    rows=[]
    with Path(path).open("r",encoding="utf-8",errors="replace") as f:
        for line in f:
            r=_parse_rtklib_pos_line(line)
            if r: rows.append(r)
    if not rows:
        raise ValueError(f"No latitude/longitude rows could be parsed from RTKLIB POS file: {path}")
    return rows


def write_trajectory_csv(rows, path: Path):
    """Write a normalized derived trajectory. Source observations remain RINEX-only."""
    path=Path(path); path.parent.mkdir(parents=True,exist_ok=True)
    fields=["time_utc","unix_s","lat","lon","height_m","quality","nsat","sdn_m","sde_m","sdu_m","age_s","ratio"]
    with path.open("w",newline="",encoding="utf-8") as f:
        w=csv.DictWriter(f,fieldnames=fields,extrasaction="ignore"); w.writeheader()
        for r in rows:w.writerow(r)
    return path


def _run_relative(rover_obs: Path, base_obs: Path, nav_files, output_pos: Path, *, mode: str,
                  exe="rnx2rtkp", config=None, base_llh=None, extra_args=None):
    """Run RTKLIB relative kinematic/static positioning from RINEX only."""
    exe=_which_or_path(exe)
    rover_obs=Path(rover_obs); base_obs=Path(base_obs); output_pos=Path(output_pos)
    nav_files=[Path(x) for x in (nav_files if isinstance(nav_files,(list,tuple)) else [nav_files]) if x]
    validate_rinex(rover_obs,"observation"); validate_rinex(base_obs,"observation")
    if not nav_files:
        raise SystemExit("At least one RINEX navigation file is required")
    for p in nav_files: validate_rinex(p,None)
    output_pos.parent.mkdir(parents=True,exist_ok=True)
    mode_code={"kinematic":"2","static":"3"}[mode]
    cmd=[exe]
    if config:
        cmd += ["-k",str(config)]
    else:
        cmd += ["-p",mode_code,"-f","2","-t","-u"]
    if base_llh:
        x,y,z=_llh_to_ecef(*base_llh)
        cmd += ["-r",f"{x:.4f}",f"{y:.4f}",f"{z:.4f}"]
    if extra_args: cmd += list(extra_args)
    cmd += ["-o",str(output_pos),str(rover_obs),str(base_obs)] + [str(p) for p in nav_files]
    print(f"Running RTKLIB relative {mode} solution:\n  " + " ".join(cmd), flush=True)
    cp=subprocess.run(cmd,capture_output=True,text=True)
    log=output_pos.with_suffix(output_pos.suffix+".log")
    log.write_text("COMMAND\n"+" ".join(cmd)+"\n\nSTDOUT\n"+(cp.stdout or "")+"\nSTDERR\n"+(cp.stderr or ""),encoding="utf-8")
    if cp.returncode!=0 or not output_pos.exists():
        raise SystemExit(f"rnx2rtkp failed ({cp.returncode}). See {log}\n{cp.stderr or cp.stdout}")
    return output_pos


def run_ppk(rover_obs: Path, base_obs: Path, nav_files, output_pos: Path, *, exe="rnx2rtkp", config=None,
            base_llh=None, extra_args=None):
    return _run_relative(rover_obs,base_obs,nav_files,output_pos,mode="kinematic",exe=exe,config=config,
                         base_llh=base_llh,extra_args=extra_args)


def run_static_base(site_base_obs: Path, reference_obs: Path, nav_files, output_pos: Path, *, exe="rnx2rtkp",
                    config=None, reference_llh=None):
    return _run_relative(site_base_obs,reference_obs,nav_files,output_pos,mode="static",exe=exe,config=config,
                         base_llh=reference_llh)


def _quality_subset(rows, max_quality=2):
    if max_quality<=0:return list(rows)
    fixed=[r for r in rows if int(r.get("quality",0))==1]
    if fixed:return fixed
    float_rows=[r for r in rows if int(r.get("quality",0)) in (0,2)]
    if float_rows:return float_rows
    return [r for r in rows if int(r.get("quality",99))<=max_quality]


def static_solution_coordinate(rows, max_quality=2):
    use=_quality_subset(rows,max_quality)
    if not use: raise ValueError("Static solution has no acceptable epochs")
    x=[];y=[];z=[]
    for r in use:
        xx,yy,zz=_llh_to_ecef(r["lat"],r["lon"],r.get("height_m",0.0)); x.append(xx);y.append(yy);z.append(zz)
    med=(float(np.median(x)),float(np.median(y)),float(np.median(z)))
    lat,lon,h=_ecef_to_llh(*med)
    d=np.sqrt((np.asarray(x)-med[0])**2+(np.asarray(y)-med[1])**2+(np.asarray(z)-med[2])**2)
    return {"lat":lat,"lon":lon,"height_m":h,"ecef_xyz_m":list(med),"epochs_used":len(use),
            "quality_counts":{str(k):sum(int(r.get('quality',0))==k for r in use) for k in sorted(set(int(r.get('quality',0)) for r in use))},
            "ecef_mad_m":float(1.4826*np.median(np.abs(d-np.median(d)))) if len(d)>1 else 0.0}


def write_base_solution_json(solution: dict, path: Path, provenance: dict | None=None):
    obj={"schema":"multimag-rinex-base-solution-v1","version":VERSION,"solution":solution,"provenance":provenance or {}}
    path=Path(path); path.parent.mkdir(parents=True,exist_ok=True); path.write_text(json.dumps(obj,indent=2),encoding="utf-8"); return path


def _read_corrected_base(value_path: Path):
    p=Path(value_path)
    if p.suffix.lower()==".pos": return static_solution_coordinate(read_rtklib_pos(p))
    obj=json.loads(p.read_text(encoding="utf-8"))
    sol=obj.get("solution",obj)
    if not all(k in sol for k in ("lat","lon","height_m")):
        raise ValueError(f"Corrected-base file lacks lat/lon/height_m: {p}")
    return {"lat":float(sol["lat"]),"lon":float(sol["lon"]),"height_m":float(sol["height_m"])}


def make_base_shift(field_base_llh, corrected_base_llh, *, source=None):
    flat,flon,fh=map(float,field_base_llh); clat,clon,ch=map(float,corrected_base_llh)
    fx,fy,fz=_llh_to_ecef(flat,flon,fh); cx,cy,cz=_llh_to_ecef(clat,clon,ch)
    dx,dy,dz=cx-fx,cy-fy,cz-fz
    e,n,u=_ecef_delta_to_enu(dx,dy,dz,flat,flon)
    return {"schema":"multimag-rinex-base-shift-v1","version":VERSION,
            "field_base_llh":{"lat":flat,"lon":flon,"height_m":fh},
            "corrected_base_llh":{"lat":clat,"lon":clon,"height_m":ch},
            "ecef_delta_m":{"dx":dx,"dy":dy,"dz":dz},
            "local_shift_at_field_base_m":{"east":e,"north":n,"up":u},
            "horizontal_shift_m":float(np.hypot(e,n)),
            "source":source or {}}


def write_base_shift_json(obj: dict, path: Path):
    path=Path(path); path.parent.mkdir(parents=True,exist_ok=True); path.write_text(json.dumps(obj,indent=2),encoding="utf-8"); return path


def load_base_shift(path: Path):
    obj=json.loads(Path(path).read_text(encoding="utf-8"))
    if obj.get("schema")!="multimag-rinex-base-shift-v1":
        raise ValueError(f"Not a Multimag RINEX base-shift file: {path}")
    d=obj.get("ecef_delta_m",{})
    return float(d["dx"]),float(d["dy"]),float(d["dz"]),obj


def apply_ecef_shift_llh(lon,lat,height,shift_xyz):
    lon=np.asarray(lon,float); lat=np.asarray(lat,float); height=np.asarray(height,float)
    fwd=Transformer.from_crs(4979,4978,always_xy=True); inv=Transformer.from_crs(4978,4979,always_xy=True)
    x,y,z=fwd.transform(lon,lat,height); dx,dy,dz=shift_xyz
    lo,la,h=inv.transform(np.asarray(x)+dx,np.asarray(y)+dy,np.asarray(z)+dz)
    return np.asarray(lo,float),np.asarray(la,float),np.asarray(h,float)


def load_trajectory(path: Path):
    """Load a derived RTKLIB POS or legacy normalized trajectory table.

    MagSurveyPy GNSS workflows use RINEX as raw input. CSV support is retained
    only for backward compatibility with trajectories generated by older Multimag versions.
    """
    path=Path(path)
    if path.suffix.lower()==".pos": rows=read_rtklib_pos(path)
    else:
        text=path.read_text(encoding="utf-8",errors="replace")
        first=next((ln for ln in text.splitlines() if ln.strip()),"")
        delim="," if first.count(",")>=first.count("\t") else "\t"
        rdr=csv.DictReader(text.splitlines(),delimiter=delim)
        lower={str(k).strip().lower():k for k in (rdr.fieldnames or [])}
        def field(*names):
            for n in names:
                if n in lower:return lower[n]
            return None
        ft=field("time_utc","time","timestamp","datetime"); fu=field("unix_s","unix","epoch")
        flat=field("lat","latitude"); flon=field("lon","longitude","long"); fh=field("height_m","height","alt")
        fq=field("quality","q"); fns=field("nsat","satellites")
        if (not ft and not fu) or not flat or not flon: raise ValueError("Trajectory table requires time, lat and lon")
        rows=[]
        for rr in rdr:
            try:
                if fu and rr.get(fu): ts=float(rr[fu])
                else:
                    s=str(rr[ft]).strip(); s=s[:-1]+"+00:00" if s.endswith("Z") else s
                    dt=_dt.datetime.fromisoformat(s); dt=dt if dt.tzinfo else dt.replace(tzinfo=_dt.timezone.utc); ts=dt.timestamp()
                rows.append({"time_utc":_dt.datetime.fromtimestamp(ts,tz=_dt.timezone.utc).isoformat().replace("+00:00","Z"),
                             "unix_s":ts,"lat":float(rr[flat]),"lon":float(rr[flon]),
                             "height_m":float(rr[fh]) if fh and rr.get(fh) else np.nan,
                             "quality":int(float(rr[fq])) if fq and rr.get(fq) else 0,
                             "nsat":int(float(rr[fns])) if fns and rr.get(fns) else 0})
            except Exception: continue
    rows=sorted(rows,key=lambda r:r["unix_s"])
    ded=[]
    for r in rows:
        if ded and abs(r["unix_s"]-ded[-1]["unix_s"])<1e-6:
            old=ded[-1]; oq=old.get("quality",0); nq=r.get("quality",0)
            if oq==0 or (nq>0 and nq<oq):ded[-1]=r
        else:ded.append(r)
    if len(ded)<2:raise ValueError("Corrected trajectory must contain at least two time epochs")
    return ded


def trajectory_summary(rows):
    q=[int(r.get("quality",0)) for r in rows]
    return {"epochs":len(rows),"start_utc":rows[0]["time_utc"],"end_utc":rows[-1]["time_utc"],
            "duration_s":float(rows[-1]["unix_s"]-rows[0]["unix_s"]),
            "quality_counts":{str(k):int(q.count(k)) for k in sorted(set(q))}}


def _plan_text(mode):
    common="""Raw GNSS source format: RINEX observation + RINEX navigation only.\nRTKLIB rnx2rtkp performs the carrier-phase solution; MagSurveyPy applies the result to magnetic samples by time.\n"""
    plans={
      "radio-rtk":common+"""RADIO RTK\nA) Best: rover RINEX + field-base RINEX + navigation; provide the precise base LLH if known -> kinematic PPK.\nB) If rover raw RINEX was NOT logged but radio RTK was internally precise relative to a wrongly assigned base coordinate: determine the true base coordinate from static RINEX against a known CORS/reference RINEX, then create/apply a constant base shift. This corrects the datum/origin only; it does not recreate rover carrier-phase observations.\n""",
      "network-rtk":common+"""NETWORK RTK\nIf the rover logged RINEX, post-process it against a nearby CORS/network-station RINEX file plus navigation. This is the proper way to repair questionable network-RTK epochs. Without rover RINEX, the original RTK coordinates cannot be retrospectively re-solved at carrier-phase level.\n""",
      "autonomous":common+"""AUTONOMOUS GNSS\nTo improve autonomous rover coordinates, the moving rover must have logged RINEX during the magnetic survey. Combine it with a simultaneous static base/CORS RINEX and navigation in kinematic PPK. A static base RINEX alone cannot phase-correct coordinates from a rover that did not log raw observations.\n""",
    }
    return plans[mode]


def gnss_build_parser():
    p=argparse.ArgumentParser(description=GNSS_DESCRIPTION,formatter_class=argparse.RawDescriptionHelpFormatter,epilog="""
Examples
--------
Inspect RINEX:
  mspy gnss inspect base.obs

Show the recommended RINEX workflow:
  mspy gnss plan --mode radio-rtk

True kinematic PPK from rover + base/CORS RINEX:
  mspy gnss ppk --rover-obs rover.obs --base-obs base.obs \\
    --nav brdc.nav --base-llh 46.023 25.267 612.4 -o Result/GNSS/site_PPK.pos

Determine an unknown field-base coordinate from static RINEX against a known CORS:
  mspy gnss static-base --base-obs field_base.obs --reference-obs CORS.obs \\
    --nav brdc.nav --reference-llh 46.1000 25.3000 530.0 -o Result/GNSS/field_base_static.pos

Create a constant correction for radio RTK when the base was assigned the wrong coordinate:
  mspy gnss base-shift --field-base-llh 46.0200 25.2600 600.0 \\
    --corrected-base-solution Result/GNSS/field_base_static.pos -o Result/GNSS/base_shift.json

Then apply to the magnetic survey:
  mspy survey multichannel --project Site --rinex-base-shift /path/to/base_shift.json

Important: for autonomous/network RTK, a static base RINEX alone is insufficient if the
moving rover did not log RINEX observations.  For radio RTK, a constant base shift is only
appropriate when the relative rover-to-base geometry was good and the main error was the
coordinate assigned to the base station.
""")
    p.add_argument("command",choices=("inspect","plan","ppk","static-base","base-shift","trajectory"))
    p.add_argument("input",nargs="?",type=Path)
    p.add_argument("-o","--output",type=Path)
    p.add_argument("--mode",choices=("radio-rtk","network-rtk","autonomous"),default="radio-rtk")
    p.add_argument("--rover-obs",type=Path,help="Moving-rover RINEX observation file")
    p.add_argument("--base-obs",type=Path,help="Static field-base RINEX observation file")
    p.add_argument("--reference-obs",type=Path,help="Known CORS/reference RINEX observation file used to solve an unknown field base")
    p.add_argument("--nav",type=Path,action="append",default=[],help="RINEX navigation file; repeat if needed")
    p.add_argument("--ppk-config",type=Path,help="Optional validated RTKLIB configuration")
    p.add_argument("--base-llh",nargs=3,type=float,metavar=("LAT","LON","HEIGHT_M"),help="Precise coordinate of the PPK base")
    p.add_argument("--reference-llh",nargs=3,type=float,metavar=("LAT","LON","HEIGHT_M"),help="Precise coordinate of the CORS/reference station")
    p.add_argument("--field-base-llh",nargs=3,type=float,metavar=("LAT","LON","HEIGHT_M"),help="Coordinate assigned to the radio-RTK base during fieldwork")
    p.add_argument("--corrected-base-llh",nargs=3,type=float,metavar=("LAT","LON","HEIGHT_M"),help="Corrected/true field-base coordinate")
    p.add_argument("--corrected-base-solution",type=Path,help="Static RTKLIB .pos or MagSurveyPy base-solution JSON containing corrected base coordinate")
    p.add_argument("--max-quality",type=int,default=2,help="Maximum RTKLIB Q retained for coordinate estimation. Default 2")
    p.add_argument("--rnx2rtkp",default="rnx2rtkp")
    p.add_argument("--version",action="version",version=f"%(prog)s {VERSION} — {AUTHOR} — {WEBSITE}")
    return p


def gnss_main():
    a=gnss_build_parser().parse_args(); _banner()
    if a.command=="inspect":
        if not a.input:raise SystemExit("inspect requires a RINEX file")
        print(json.dumps(inspect_rinex(a.input),indent=2))
    elif a.command=="plan":
        print(_plan_text(a.mode))
    elif a.command=="ppk":
        if not a.rover_obs or not a.base_obs or not a.nav:
            raise SystemExit("PPK requires --rover-obs, --base-obs and at least one --nav RINEX file")
        out=a.output or Path("ppk_solution.pos")
        pos=run_ppk(a.rover_obs,a.base_obs,a.nav,out,exe=a.rnx2rtkp,config=a.ppk_config,base_llh=a.base_llh)
        rows=read_rtklib_pos(pos); csvp=write_trajectory_csv(rows,pos.with_name(pos.stem+"_trajectory.csv"))
        print(json.dumps({"solution":str(pos),"derived_trajectory":str(csvp),"summary":trajectory_summary(rows)},indent=2))
    elif a.command=="static-base":
        if not a.base_obs or not a.reference_obs or not a.nav:
            raise SystemExit("static-base requires --base-obs (unknown site base), --reference-obs (known CORS) and --nav")
        if not a.reference_llh:
            raise SystemExit("static-base requires --reference-llh for the known reference/CORS coordinate")
        out=a.output or Path("field_base_static.pos")
        pos=run_static_base(a.base_obs,a.reference_obs,a.nav,out,exe=a.rnx2rtkp,config=a.ppk_config,reference_llh=a.reference_llh)
        rows=read_rtklib_pos(pos); sol=static_solution_coordinate(rows,a.max_quality)
        js=write_base_solution_json(sol,pos.with_name(pos.stem+"_base_solution.json"),{
            "site_base_rinex":str(a.base_obs),"reference_rinex":str(a.reference_obs),"navigation_rinex":[str(x) for x in a.nav],
            "reference_llh":list(a.reference_llh)})
        print(json.dumps({"solution":str(pos),"base_solution":str(js),"coordinate":sol},indent=2))
    elif a.command=="base-shift":
        if not a.field_base_llh:
            raise SystemExit("base-shift requires --field-base-llh: the coordinate assigned to the radio-RTK base during fieldwork")
        source={}
        corrected=None
        if a.corrected_base_llh:
            corrected=list(a.corrected_base_llh); source={"method":"explicit corrected coordinate"}
        elif a.corrected_base_solution:
            sol=_read_corrected_base(a.corrected_base_solution); corrected=[sol["lat"],sol["lon"],sol["height_m"]]
            source={"method":"static RINEX solution","file":str(a.corrected_base_solution)}
        elif a.base_obs and a.reference_obs and a.nav and a.reference_llh:
            pos=(a.output or Path("base_shift.json")).with_suffix(".static.pos")
            run_static_base(a.base_obs,a.reference_obs,a.nav,pos,exe=a.rnx2rtkp,config=a.ppk_config,reference_llh=a.reference_llh)
            sol=static_solution_coordinate(read_rtklib_pos(pos),a.max_quality); corrected=[sol["lat"],sol["lon"],sol["height_m"]]
            source={"method":"static RINEX relative solution","site_base_rinex":str(a.base_obs),"reference_rinex":str(a.reference_obs),"static_solution":str(pos)}
        else:
            raise SystemExit("Provide --corrected-base-llh, --corrected-base-solution, or the RINEX static-base inputs (--base-obs --reference-obs --nav --reference-llh)")
        obj=make_base_shift(a.field_base_llh,corrected,source=source); out=a.output or Path("base_shift.json")
        write_base_shift_json(obj,out); print(json.dumps(obj,indent=2))
    else:
        if not a.input or a.input.suffix.lower()!=".pos":
            raise SystemExit("trajectory accepts a derived RTKLIB .pos solution; raw GNSS source data must be RINEX")
        rows=read_rtklib_pos(a.input); out=a.output or a.input.with_name(a.input.stem+"_trajectory.csv")
        write_trajectory_csv(rows,out); print(json.dumps({"trajectory":str(out),"summary":trajectory_summary(rows)},indent=2))


