def _parse_positive_scales(text,name):
    try: vals=[float(v.strip()) for v in str(text).split(',') if v.strip()]
    except Exception as exc: raise SystemExit(f"{name} must be comma-separated positive metres") from exc
    if not vals or any((not np.isfinite(v) or v<=0) for v in vals): raise SystemExit(f"{name} requires positive finite metre values")
    return vals


def estimate_spatial_sensor_bias(x,y,v,sensor,cell_size,args,max_points=900000):
    """Estimate persistent channel offsets from spatially co-observed cells.

    The estimator deliberately avoids the old assumption that simultaneously
    sampled sensors see identical ground.  It block-medians each sensor in map
    coordinates and compares only cells occupied by >=2 sensors. Three nearby
    block scales are used as an internal stability test.  The returned auto gate
    is intentionally strict; failure means diagnostic-only, never forced editing.
    """
    ids=np.array(sorted(set(int(q) for q in np.asarray(sensor) if int(q)>0)),int)
    info={'active':False,'reason':'fewer than two sensor channels','offsets':{},'rows':[],'auto_apply':False}
    if len(ids)<2 or len(v)<100: return {},info
    n=len(v); step=max(1,int(np.ceil(n/max_points)))
    xs=np.asarray(x)[::step]; ys=np.asarray(y)[::step]; vs=np.asarray(v)[::step]; ss=np.asarray(sensor)[::step].astype(int)
    good=np.isfinite(xs)&np.isfinite(ys)&np.isfinite(vs)&(ss>0); xs,ys,vs,ss=xs[good],ys[good],vs[good],ss[good]
    if len(vs)<100: return {},info
    centre=max(float(getattr(args,'sensor_bias_cell',1.0)),max(float(cell_size)*3.0,0.5))
    scales=sorted(set([max(float(cell_size)*2.0,centre*0.75),centre,centre*1.5]))
    per={int(i):[] for i in ids}; counts={int(i):[] for i in ids}; within={int(i):[] for i in ids}
    for sc in scales:
        xmin=np.floor(xs.min()/sc)*sc; xmax=np.ceil(xs.max()/sc)*sc; ymin=np.floor(ys.min()/sc)*sc; ymax=np.ceil(ys.max()/sc)*sc
        xe=np.arange(xmin,xmax+sc*1.01,sc); ye=np.arange(ymin,ymax+sc*1.01,sc)
        grids=[]
        for sid in ids:
            m=ss==sid
            if m.sum()<5: grids.append(np.full((len(ye)-1,len(xe)-1),np.nan)); continue
            g,_,_,_=binned_statistic_2d(xs[m],ys[m],vs[m],statistic='median',bins=(xe,ye)); grids.append(g.T)
        stack=np.stack(grids,axis=0); occ=np.isfinite(stack); nsen=occ.sum(axis=0)
        baseline=np.ma.median(np.ma.masked_invalid(stack),axis=0).filled(np.nan)
        for j,sid in enumerate(ids):
            mask=np.isfinite(stack[j])&(nsen>=2)&np.isfinite(baseline)
            rr=stack[j][mask]-baseline[mask]
            if len(rr):
                med=float(np.median(rr)); mad=float(1.4826*np.median(np.abs(rr-med)))
                per[int(sid)].append(med); counts[int(sid)].append(int(len(rr))); within[int(sid)].append(mad)
    rows=[]; raw_offsets={}
    for sid in ids:
        arr=np.asarray(per[int(sid)],float)
        if not len(arr):
            rows.append({'sensor':int(sid),'offset':np.nan,'scale_stability_sigma':np.nan,'within_cell_sigma':np.nan,'coobserved_cells':0,'scales_tested':0,'supported':False}); continue
        off=float(np.median(arr)); stab=float(1.4826*np.median(np.abs(arr-off))) if len(arr)>1 else 0.0
        w=float(np.median(within[int(sid)])) if within[int(sid)] else np.nan; nc=int(min(counts[int(sid)])) if counts[int(sid)] else 0
        raw_offsets[int(sid)]=off
        rows.append({'sensor':int(sid),'offset':off,'scale_stability_sigma':stab,'within_cell_sigma':w,'coobserved_cells':nc,'scales_tested':int(len(arr)),'supported':False})
    if not raw_offsets: return {},info
    center=float(np.median(list(raw_offsets.values())))
    offsets={sid:float(val-center) for sid,val in raw_offsets.items()}
    global_sigma=max(grid_robust_scale(vs),1e-9)
    mincells=max(20,int(getattr(args,'sensor_bias_min_cells',120)))
    max_stab=max(0.20,0.18*global_sigma)
    supported=[]
    for r in rows:
        sid=int(r['sensor']); r['offset_to_subtract']=offsets.get(sid,np.nan)
        offabs=abs(float(r['offset_to_subtract'])) if np.isfinite(r['offset_to_subtract']) else np.nan
        relative_limit=max(0.18,0.55*offabs+0.05) if np.isfinite(offabs) and offabs>=0.20 else max_stab
        r['relative_stability_limit']=float(relative_limit)
        r['supported']=bool(np.isfinite(r['offset']) and r['coobserved_cells']>=mincells and r['scales_tested']>=2 and np.isfinite(r['scale_stability_sigma']) and r['scale_stability_sigma']<=min(max_stab,relative_limit))
        supported.append(r['supported'])
    enough=bool(rows and all(supported))
    spread=float(np.std(list(offsets.values()))) if offsets else 0.0
    meaningful=spread>=max(0.15,0.04*global_sigma)
    auto_apply=bool(enough and meaningful)
    reason='stable multi-scale co-observation solution' if auto_apply else ('insufficient co-observed support/stability' if not enough else 'channel offsets too small to justify correction')
    info={'active':True,'reason':reason,'offsets':offsets,'rows':rows,'auto_apply':auto_apply,'sampled_points':int(len(vs)),'sample_stride':int(step),'tested_cell_sizes_m':scales,'global_robust_sigma':global_sigma,'offset_spread':spread,'max_allowed_scale_stability_sigma':max_stab,'minimum_coobserved_cells':mincells}
    return offsets,info


def write_spatial_sensor_bias_qc(path,info,mode,applied):
    rows=info.get('rows') or []
    fields=['sensor','offset','offset_to_subtract','scale_stability_sigma','relative_stability_limit','within_cell_sigma','coobserved_cells','scales_tested','supported','mode','applied']
    with Path(path).open('w',newline='',encoding='utf-8') as fh:
        w=csv.DictWriter(fh,fieldnames=fields); w.writeheader()
        for r in rows:
            q={k:r.get(k,'') for k in fields}; q['mode']=mode; q['applied']=bool(applied); w.writerow(q)


def perona_malik_denoise(grid,noise_sigma,strength=0.55,iterations=None):
    """Light Perona-Malik anisotropic diffusion, returned in original units."""
    a=np.asarray(grid,float); valid=np.isfinite(a)
    if not valid.any(): return a.copy()
    u=_nearest_fill_nan(a).astype(float,copy=True)
    st=float(np.clip(strength,0,1)); niter=int(iterations or round(6+12*st)); kappa=max(float(noise_sigma)*(1.8+1.8*(1-st)),0.08*grid_robust_scale(u[valid]),1e-9); gamma=0.16
    for _ in range(max(1,niter)):
        dn=np.zeros_like(u); ds=np.zeros_like(u); de=np.zeros_like(u); dw=np.zeros_like(u)
        dn[1:]=u[:-1]-u[1:]; ds[:-1]=u[1:]-u[:-1]; dw[:,1:]=u[:,:-1]-u[:,1:]; de[:,:-1]=u[:,1:]-u[:,:-1]
        cn=np.exp(-(dn/kappa)**2); cs=np.exp(-(ds/kappa)**2); ce=np.exp(-(de/kappa)**2); cw=np.exp(-(dw/kappa)**2)
        u += gamma*(cn*dn+cs*ds+ce*de+cw*dw)
    u[~valid]=np.nan; return u


def _restoration_method(name,grid,noise_sigma,strength):
    a=np.asarray(grid,float); valid=np.isfinite(a); work=_nearest_fill_nan(a)
    st=float(np.clip(strength,0.05,1.0)); sigma=max(float(noise_sigma),1e-9)
    if name=='anisotropic': out=perona_malik_denoise(a,sigma,st)
    elif name=='tv':
        try: from skimage.restoration import denoise_tv_chambolle
        except Exception as exc: raise RuntimeError('TV restoration requires scikit-image') from exc
        out=denoise_tv_chambolle(work,weight=max(0.02,sigma*(0.08+0.22*st)),channel_axis=None)
    elif name=='bilateral':
        try: from skimage.restoration import denoise_bilateral
        except Exception as exc: raise RuntimeError('bilateral restoration requires scikit-image') from exc
        out=denoise_bilateral(work,sigma_color=max(0.15*sigma,sigma*(0.35+0.45*st)),sigma_spatial=max(1.0,1.0+2.0*st),channel_axis=None,bins=10000,mode='reflect')
    elif name=='wavelet':
        try: from skimage.restoration import denoise_wavelet
        except Exception as exc: raise RuntimeError('wavelet restoration requires scikit-image') from exc
        out=denoise_wavelet(work,sigma=sigma*(0.55+0.35*st),method='BayesShrink',mode='soft',rescale_sigma=True,channel_axis=None)
    elif name=='nlm':
        try: from skimage.restoration import denoise_nl_means
        except Exception as exc: raise RuntimeError('non-local means requires scikit-image') from exc
        out=denoise_nl_means(work,h=sigma*(0.45+0.45*st),sigma=sigma,fast_mode=True,patch_size=3,patch_distance=max(3,int(round(3+3*st))),channel_axis=None,preserve_range=True)
    else: raise ValueError(name)
    out=np.asarray(out,float); out[~valid]=np.nan; return out


def restoration_suite(grid,local_noise,args,cores=1):
    mode=str(getattr(args,'restoration_suite','off'))
    if mode=='off': return {},{}
    vals=local_noise[np.isfinite(local_noise)] if local_noise is not None else np.asarray([])
    noise=float(np.median(vals)) if len(vals) else max(0.10*grid_robust_scale(grid),1e-6)
    names=['anisotropic','tv','bilateral'] + (['wavelet','nlm'] if mode=='full' else [])
    strength=float(getattr(args,'restoration_strength',0.55))
    out={}; errors={}
    # Independent filters are ideal coarse-grained work units. Threads avoid
    # duplicating million-cell rasters while SciPy/scikit-image kernels release
    # the GIL in their heavy numerical sections.
    from concurrent.futures import ThreadPoolExecutor,as_completed
    workers=max(1,min(int(cores),len(names)))
    with ThreadPoolExecutor(max_workers=workers) as ex:
        fut={ex.submit(_restoration_method,n,grid,noise,strength):n for n in names}
        try:
            iterator=tqdm(as_completed(fut),total=len(fut),desc=f"Denoising/restoration ({workers} core{'s' if workers!=1 else ''})",unit="method")
        except Exception:
            iterator=as_completed(fut)
        for f in iterator:
            n=fut[f]
            try: out[n]=f.result()
            except Exception as exc: errors[n]=str(exc)
    if out:
        stack=np.stack([out[n] for n in names if n in out],axis=0)
        all_nan = ~np.isfinite(stack).any(axis=0)
        safe_stack = stack.copy()
        safe_stack[:, all_nan] = 0.0
        with np.errstate(all='ignore'):
            out['consensus'] = np.nanmedian(safe_stack, axis=0)
        out['consensus'][all_nan] = np.nan
    return out,{'noise_sigma':noise,'strength':strength,'errors':errors,'methods':list(out)}


def restoration_metrics(reference,candidate,background=None):
    valid=np.isfinite(reference)&np.isfinite(candidate)
    if valid.sum()<10: return {}
    r=reference[valid]; c=candidate[valid]; d=c-r
    corr=float(np.corrcoef(r,c)[0,1]) if np.std(r)>0 and np.std(c)>0 else np.nan
    rms=float(np.sqrt(np.mean(d*d))); p95=float(np.percentile(np.abs(d),95)); rs=max(grid_robust_scale(reference),1e-9)
    rw=_nearest_fill_nan(reference); cw=_nearest_fill_nan(candidate)
    rg=np.hypot(*np.gradient(gaussian_filter(rw,0.8,mode='nearest'))); cg=np.hypot(*np.gradient(gaussian_filter(cw,0.8,mode='nearest')))
    em=np.isfinite(rg)&np.isfinite(cg); edgecorr=float(np.corrcoef(rg[em],cg[em])[0,1]) if em.sum()>10 and np.std(rg[em])>0 and np.std(cg[em])>0 else np.nan
    detail_r=rw-gaussian_filter(rw,2.0,mode='nearest'); detail_c=cw-gaussian_filter(cw,2.0,mode='nearest')
    noise_ratio=float(grid_robust_scale(detail_c[valid])/max(grid_robust_scale(detail_r[valid]),1e-9))
    return {'correlation_to_reference':corr,'edge_correlation':edgecorr,'rms_change':rms,'p95_abs_change':p95,'rms_change_sigma':rms/rs,'fine_detail_ratio':noise_ratio}


def filter_performance_metrics(reference,candidate):
    """Archaeology-oriented comparison of a cleaning/filtering candidate."""
    m=restoration_metrics(reference,candidate)
    valid=np.isfinite(reference)&np.isfinite(candidate)
    if valid.sum()<20:
        return {**m,"safe_for_archaeology":False,"balanced_score":float("nan")}
    rw=_nearest_fill_nan(reference); cw=_nearest_fill_nan(candidate)
    rh=rw-gaussian_filter(rw,1.0,mode="nearest")
    ch=cw-gaussian_filter(cw,1.0,mode="nearest")
    nr=max(grid_robust_scale(rh[valid]),1e-12); nc=max(grid_robust_scale(ch[valid]),1e-12)
    noise_reduction=float(1.0-nc/nr)
    ar=np.abs(reference[valid]-np.nanmedian(reference[valid])); ac=np.abs(candidate[valid]-np.nanmedian(candidate[valid]))
    p95r=max(float(np.percentile(ar,95)),1e-12); p95c=float(np.percentile(ac,95))
    amp_ratio=p95c/p95r
    corr=float(m.get("correlation_to_reference",np.nan)); edge=float(m.get("edge_correlation",np.nan))
    detail=float(m.get("fine_detail_ratio",np.nan)); change=float(m.get("rms_change_sigma",np.nan))
    safe=bool(np.isfinite(corr) and corr>=0.95 and np.isfinite(edge) and edge>=0.90 and
              np.isfinite(amp_ratio) and 0.70<=amp_ratio<=1.30 and
              np.isfinite(detail) and detail>=0.55 and np.isfinite(change) and change<=0.75)
    ng=float(np.clip(noise_reduction/0.45,0,1))
    corr_s=float(np.clip(corr,0,1)) if np.isfinite(corr) else 0
    edge_s=float(np.clip(edge,0,1)) if np.isfinite(edge) else 0
    amp_s=float(np.clip(1-abs(amp_ratio-1.0)/0.35,0,1)) if np.isfinite(amp_ratio) else 0
    detail_s=float(np.clip(detail/0.80,0,1)) if np.isfinite(detail) else 0
    change_s=float(np.clip(1-change/0.75,0,1)) if np.isfinite(change) else 0
    balanced=100.0*(0.24*ng+0.22*edge_s+0.18*corr_s+0.15*amp_s+0.13*detail_s+0.08*change_s)
    preservation=100.0*(0.35*edge_s+0.30*corr_s+0.20*amp_s+0.15*detail_s)
    return {**m,"high_frequency_noise_sigma_reference":nr,"high_frequency_noise_sigma_candidate":nc,
            "noise_reduction_fraction":noise_reduction,"p95_anomaly_amplitude_ratio":amp_ratio,
            "safe_for_archaeology":safe,"balanced_score":balanced,"preservation_score":preservation}


def write_filter_performance_report(report_dir,png_dir,prefix,reference,candidates):
    rows=[]
    for name,g in candidates.items():
        mm=filter_performance_metrics(reference,g); mm["method"]=name; rows.append(mm)
    rows.sort(key=lambda r:float(r.get("balanced_score",-1e9)) if np.isfinite(r.get("balanced_score",np.nan)) else -1e9,reverse=True)
    safe=[r for r in rows if r.get("safe_for_archaeology")]
    balanced=(safe or rows)[0] if rows else None
    preservation=max(rows,key=lambda r:r.get("preservation_score",-1e9)) if rows else None
    denoise_pool=safe or rows
    denoise=max(denoise_pool,key=lambda r:r.get("noise_reduction_fraction",-1e9)) if denoise_pool else None

    fields=["method","balanced_score","preservation_score","safe_for_archaeology","noise_reduction_fraction",
            "correlation_to_reference","edge_correlation","p95_anomaly_amplitude_ratio","fine_detail_ratio",
            "rms_change_sigma","rms_change","p95_abs_change"]
    csvp=Path(report_dir)/f"{prefix}_filter_performance.csv"
    with csvp.open("w",newline="",encoding="utf-8") as fh:
        w=csv.DictWriter(fh,fieldnames=fields);w.writeheader()
        for r in rows:w.writerow({k:r.get(k,"") for k in fields})

    summary={
        "software_version":VERSION,
        "policy":"Recommendations compare processing candidates, not archaeological truth. Inspect difference rasters before interpretation.",
        "best_balanced":balanced["method"] if balanced else None,
        "best_preservation":preservation["method"] if preservation else None,
        "strongest_safe_denoising":denoise["method"] if denoise else None,
        "rows":rows,
        "gate":{"correlation_min":0.95,"edge_correlation_min":0.90,"amplitude_ratio":[0.70,1.30],"fine_detail_ratio_min":0.55,"rms_change_sigma_max":0.75}
    }
    jsp=Path(report_dir)/f"{prefix}_filter_recommendation.json";jsp.write_text(json.dumps(summary,indent=2,default=str),encoding="utf-8")

    def fmt(v,d=3):
        try:return f"{float(v):.{d}f}"
        except:return ""
    trs=[]
    for r in rows:
        flag="YES" if r.get("safe_for_archaeology") else "NO"
        trs.append("<tr>"+f"<td><b>{r['method']}</b></td><td>{fmt(r.get('balanced_score'),1)}</td><td>{flag}</td>"
                   f"<td>{fmt(100*r.get('noise_reduction_fraction',0),1)}%</td><td>{fmt(r.get('correlation_to_reference'))}</td>"
                   f"<td>{fmt(r.get('edge_correlation'))}</td><td>{fmt(r.get('p95_anomaly_amplitude_ratio'))}</td>"
                   f"<td>{fmt(r.get('fine_detail_ratio'))}</td><td>{fmt(r.get('rms_change_sigma'))}</td></tr>")
    hp=Path(report_dir)/f"{prefix}_filter_performance.html"
    hp.write_text(f"""<!doctype html><meta charset="utf-8"><title>{prefix} filter performance</title>
<style>body{{font-family:system-ui;max-width:1200px;margin:auto;padding:2rem;color:#172033}}table{{border-collapse:collapse;width:100%}}th,td{{padding:.55rem;border-bottom:1px solid #ddd;text-align:right}}th:first-child,td:first-child{{text-align:left}}.good{{background:#ecfdf5;padding:1rem;border-left:5px solid #059669}}.note{{background:#fff7ed;padding:1rem;border-left:5px solid #ea580c}}</style>
<h1>{prefix} — filtering / cleaning performance</h1>
<div class="good"><b>Best balanced:</b> {summary['best_balanced']} &nbsp; | &nbsp; <b>Best preservation:</b> {summary['best_preservation']} &nbsp; | &nbsp; <b>Strongest safe denoising:</b> {summary['strongest_safe_denoising']}</div>
<p class="note">The ranking is a processing QC aid, not an archaeological classifier. A smooth image can score poorly if it suppresses edges, amplitudes or fine-scale signal. Always inspect the difference rasters.</p>
<table><thead><tr><th>Method</th><th>Balanced score</th><th>Preservation gate</th><th>Noise reduction</th><th>Field corr.</th><th>Edge corr.</th><th>P95 amplitude ratio</th><th>Fine-detail ratio</th><th>RMS change / σ</th></tr></thead><tbody>{''.join(trs)}</tbody></table>
<p>Balanced score combines high-frequency noise reduction with field, edge, amplitude and fine-detail preservation. Gate limits are stored in the JSON report.</p>""",encoding="utf-8")

    chart=None
    if rows:
        try:
            import matplotlib.pyplot as plt
            names=[r["method"] for r in rows][::-1]; vals=[r["balanced_score"] for r in rows][::-1]
            fig,ax=plt.subplots(figsize=(9,max(4,0.55*len(rows)+1.5)),constrained_layout=True)
            ax.barh(names,vals);ax.set_xlim(0,100);ax.set_xlabel("Balanced processing score [0–100]")
            ax.set_title(f"{prefix}: filtering / cleaning performance")
            chart=Path(png_dir)/f"{prefix}_filter_performance.png";fig.savefig(chart,dpi=220,bbox_inches="tight");plt.close(fig)
        except Exception as exc:
            print(f"Filter-performance chart warning: {exc}",file=sys.stderr)
    return rows,summary,[csvp,jsp,hp]+([chart] if chart else [])




def wallis_relative_display(grid,cell_size,window_m=4.0,strength=0.85):
    valid=np.isfinite(grid); work=_nearest_fill_nan(grid); sig=max(float(window_m)/float(cell_size)/2.355,1.0)
    mu=gaussian_filter(work,sig,mode='nearest'); dev=work-mu; var=gaussian_filter(dev*dev,sig,mode='nearest'); std=np.sqrt(np.maximum(var,1e-12)); floor=max(0.12*grid_robust_scale(work[valid]),1e-9)
    z=dev/np.maximum(std,floor); local=np.tanh(z/2.7)
    globalz=np.tanh((work-np.median(work[valid]))/max(3.0*grid_robust_scale(work[valid]),1e-9))
    out=float(strength)*local+(1-float(strength))*globalz; out[~valid]=np.nan; return out


def multiscale_persistence(grid,cell_size,scales_m):
    valid=np.isfinite(grid); work=_nearest_fill_nan(grid); zs=[]
    for sc in scales_m:
        bg=gaussian_filter(work,sigma=max(float(sc)/float(cell_size),1.0),mode='nearest'); res=work-bg; sig=max(grid_robust_scale(res[valid]),1e-9); zs.append(res/sig)
    z=np.stack(zs,axis=0); med=np.nanmedian(z,axis=0); sign=np.sign(med); active=(np.abs(z)>=0.8)&(np.sign(z)==sign[None,...]); persistence=np.mean(active,axis=0); signed=sign*persistence
    persistence[~valid]=np.nan; signed[~valid]=np.nan; return persistence,signed


def multiscale_morphology(grid,cell_size,scales_m):
    try:
        from skimage.morphology import disk,white_tophat,black_tophat
    except Exception as exc: raise RuntimeError('morphological suite requires scikit-image') from exc
    valid=np.isfinite(grid); work=_nearest_fill_nan(grid); pos=[]; neg=[]
    for sc in scales_m:
        rad=max(1,int(round(float(sc)/float(cell_size))))
        fp=disk(rad)
        pos.append(np.asarray(white_tophat(work,footprint=fp),float)); neg.append(np.asarray(black_tophat(work,footprint=fp),float))
    p=np.maximum.reduce(pos); n=np.maximum.reduce(neg); signed=p-n
    p[~valid]=np.nan; n[~valid]=np.nan; signed[~valid]=np.nan; return p,n,signed


def potential_field_interpretation(grid,cell_size,pad_fraction=0.20):
    valid=np.isfinite(grid); setup=_fft_padded_work(grid,pad_fraction)
    if setup is None:
        nan=np.full_like(grid,np.nan,float); return {'horizontal_gradient':nan,'vertical_derivative':nan,'tilt_angle':nan,'analytic_signal':nan}
    vv,work,py,px=setup; fr=_fft_frequency_grid(work.shape,cell_size); F=np.fft.fft2(work); vd=np.real(np.fft.ifft2(F*(2*np.pi*fr)))[py:py+grid.shape[0],px:px+grid.shape[1]]
    filled=_nearest_fill_nan(grid); gy,gx=np.gradient(filled,float(cell_size),float(cell_size)); hg=np.hypot(gx,gy); tilt=np.arctan2(vd,np.maximum(hg,1e-12)); ana=np.sqrt(hg*hg+vd*vd)
    out={'horizontal_gradient':hg,'vertical_derivative':vd,'tilt_angle':tilt,'analytic_signal':ana}
    for a in out.values(): a[~valid]=np.nan
    return out


def write_relative_preview(path,grid,extent,title,args,cmap='gray_r',symmetric=True):
    import matplotlib.pyplot as plt
    fig,ax=plt.subplots(figsize=(10,7),constrained_layout=True); vals=grid[np.isfinite(grid)]
    if not len(vals): lo,hi=-1,1
    elif symmetric:
        hi=max(float(np.percentile(np.abs(vals),99)),1e-9); lo=-hi
    else: lo=float(np.percentile(vals,1)); hi=float(np.percentile(vals,99)); hi=max(hi,lo+1e-9)
    disp=_spatial_array(grid,args)
    im=ax.imshow(disp,origin='upper',extent=extent,cmap=cmap,vmin=lo,vmax=hi,interpolation='nearest'); ax.set_title(title); _format_projected_axes(ax,extent,fontsize=8); _publication_colorbar(fig,ax,im,attribute_label('value'),getattr(args,'colorbar_position','right'),fontsize=7.5); fig.savefig(path,dpi=max(220,int(getattr(args,'figure_dpi',220))),bbox_inches='tight'); plt.close(fig)


def write_archaeology_gallery(path,reference,restored,wallis,persistence,morph_signed,edges,extent,args,analysis_source=None,analysis_label='Analysis source'):
    import matplotlib.pyplot as plt
    src=reference if analysis_source is None else analysis_source
    panels=[('Measured reference',reference,'div'),(analysis_label,src,'div'),('Wallis local contrast (display only)',wallis,'gray'),('TV restoration',restored.get('tv',src),'div'),('Restoration consensus',restored.get('consensus',src),'div'),('Multiscale persistence',persistence,'seq'),('Multiscale signed morphology',morph_signed,'div'),('Tilt angle',edges.get('tilt_angle',src),'div')]
    fig,axs=plt.subplots(2,4,figsize=(20,10),constrained_layout=True)
    for ax,(title,g,kind) in zip(axs.ravel(),panels):
        vals=g[np.isfinite(g)]
        if kind=='seq': lo,hi=0,1; cmap='viridis'
        elif kind=='gray': lo,hi=-1,1; cmap='gray_r'
        else:
            hi=max(float(np.percentile(np.abs(vals),98.5)) if len(vals) else 1.0,1e-9); lo=-hi; cmap=resolved_cmap(getattr(args,'cmap','gray'),getattr(args,'normal_gray',False))
        disp=_spatial_array(g,args)
        im=ax.imshow(disp,origin='upper',extent=extent,cmap=cmap,vmin=lo,vmax=hi,interpolation='nearest'); ax.set_title(title,fontsize=10); _format_projected_axes(ax,extent,target_x=4,target_y=4,fontsize=7); _publication_colorbar(fig,ax,im,'Magnetic / relative value',getattr(args,'colorbar_position','right'),fontsize=7)
    fig.suptitle('Archaeological magnetic interpretation suite — measured reference preserved; enhanced branches are aids, not ground truth',fontsize=14)
    fig.savefig(path,dpi=max(220,int(getattr(args,'figure_dpi',220))),bbox_inches='tight'); plt.close(fig)


def protected_directional_leveling(grid, cs, heading_deg, spacing_m, args):
    """Orientation-constrained, archaeology-protected 2-D stripe levelling.

    Eligible energy must be long/coherent ALONG the known acquisition direction
    but short-period ACROSS it.  This is estimated in the 2-D Fourier domain,
    then spatially faded around strong residuals and strong edges.  The measured
    raster is never overwritten and AUTO acceptance requires both substantial
    anisotropy reduction and high field/edge correlation.
    """
    from scipy.ndimage import gaussian_filter, sobel
    a=np.asarray(grid,float); valid=np.isfinite(a); mode=str(getattr(args,'protected_leveling','off'))
    info={'active':False,'applied':False,'mode':mode,'reason':'disabled or no acquisition geometry','heading_deg':float(heading_deg) if np.isfinite(heading_deg) else None,'spacing_m':float(spacing_m)}
    zero=np.where(valid,0.0,np.nan)
    if mode=='off' or not np.isfinite(heading_deg) or spacing_m<=0 or valid.sum()<100:
        return a.copy(),a.copy(),zero,info
    work=_nearest_fill_nan(a); ny,nx=work.shape
    py=1<<int(np.ceil(np.log2(max(2,ny)))); px=1<<int(np.ceil(np.log2(max(2,nx))))
    pad=np.pad(work,((0,py-ny),(0,px-nx)),mode='reflect'); F=np.fft.fft2(pad)
    kx=np.fft.fftfreq(px,d=float(cs))[None,:]; ky=np.fft.fftfreq(py,d=float(cs))[:,None]
    th=np.deg2rad(float(heading_deg)); kpar=kx*np.cos(th)+ky*np.sin(th); kcross=-kx*np.sin(th)+ky*np.cos(th)
    along=max(float(getattr(args,'protected_level_min_along',8.0)),2*float(spacing_m)); kp=1.0/max(along,1e-9)
    H_along=np.exp(-((np.abs(kpar)/max(kp,1e-12))**4))
    wmin=max(float(getattr(args,'protected_level_cross_min',0.45)),2.0*float(cs)*1.01); wmax=max(float(getattr(args,'protected_level_cross_max',4.0)),wmin*1.1)
    f_lo=1.0/wmax; f_hi=min(1.0/wmin,0.98/(2.0*float(cs))); kc=np.abs(kcross); order=4
    H_hp=1.0/(1.0+(f_lo/np.maximum(kc,1e-12))**(2*order)); H_lp=1.0/(1.0+(kc/max(f_hi,1e-12))**(2*order)); H=H_along*H_hp*H_lp; H[0,0]=0.0
    comp=np.fft.ifft2(F*H).real[:ny,:nx]
    # Remove any leaked broad component; eligible correction must remain a residual/corrugation field.
    comp-=gaussian_filter(comp,sigma=max(float(getattr(args,'stripe_background',3.0))/float(cs)*2.0,2.0),mode='nearest')
    broad=gaussian_filter(work,sigma=max(float(getattr(args,'stripe_background',3.0))/float(cs),1.0),mode='nearest'); residual=work-broad; rs=max(grid_robust_scale(residual[valid]),1e-9)
    ampw=np.exp(-((np.abs(residual)/(3.0*rs))**4))
    gx=sobel(work,axis=1,mode='nearest')/(8*max(float(cs),1e-9)); gy=sobel(work,axis=0,mode='nearest')/(8*max(float(cs),1e-9)); grad=np.hypot(gx,gy); gv=grad[valid]; gs=max(float(np.percentile(gv,92)) if len(gv) else 1.0,1e-9); edgew=np.exp(-((grad/(2.0*gs))**4))
    protect=np.clip(ampw*edgew,0.12,1.0); strength=float(np.clip(getattr(args,'protected_level_strength',0.55),0,1)); removed=comp*protect*strength; removed[~valid]=np.nan
    candidate=a.copy(); candidate[valid]=a[valid]-removed[valid]
    raw_spec=analyse_noise_spectrum(a,cs,args); cand_spec=analyse_noise_spectrum(candidate,cs,args); raw_an=float(raw_spec.get('stripe_anisotropy',np.nan)); cand_an=float(cand_spec.get('stripe_anisotropy',np.nan)); reduction=float(1-cand_an/raw_an) if np.isfinite(raw_an) and raw_an>0 and np.isfinite(cand_an) else np.nan
    met=restoration_metrics(a,candidate); fc=float(met.get('correlation_to_reference',np.nan)); ec=float(met.get('edge_correlation',np.nan))
    fine=float(met.get('fine_detail_ratio',np.nan)); auto_ok=bool(np.isfinite(reduction) and reduction>=float(getattr(args,'protected_level_min_reduction',0.20)) and np.isfinite(fc) and fc>=float(getattr(args,'protected_level_min_correlation',0.985)) and np.isfinite(ec) and ec>=float(getattr(args,'protected_level_min_edge_correlation',0.97)) and np.isfinite(fine) and fine>=float(getattr(args,'protected_level_min_fine_detail',0.90)) and cand_an<raw_an)
    applied=bool(mode=='on' or (mode=='auto' and auto_ok))
    info.update(active=True,applied=applied,reason=('AUTO preservation gate passed' if applied and mode=='auto' else ('forced by user' if applied else 'candidate did not pass AUTO preservation gate')),strength=strength,min_along_m=along,cross_wavelength_min_m=wmin,cross_wavelength_max_m=wmax,raw_directional_anisotropy=raw_an,candidate_directional_anisotropy=cand_an,anisotropy_reduction_fraction=reduction,field_correlation=fc,edge_correlation=ec,rms_change=met.get('rms_change'),fine_detail_ratio=met.get('fine_detail_ratio'),protection_mean=float(np.nanmean(protect[valid])),auto_gate=auto_ok)
    return (candidate if applied else a.copy()),candidate,removed,info



def _track_surface_heading(x,y,track_ids):
    """Robust dominant along-track orientation (degrees from +X, modulo 180)."""
    x=np.asarray(x,float); y=np.asarray(y,float); tids=np.asarray(track_ids,np.int64)
    if len(tids)==0: return 0.0
    maxid=int(np.max(tids)) if len(tids) else 0
    # Track ids produced by read_asc_track_ids are compact enough for indexed reductions.
    if maxid>max(1000000,20*len(np.unique(tids))):
        uniq,inv=np.unique(tids,return_inverse=True); tuse=inv; maxid=len(uniq)-1
    else:
        tuse=tids
    n=len(tuse); first=np.full(maxid+1,n,dtype=np.int64); last=np.full(maxid+1,-1,dtype=np.int64)
    idx=np.arange(n,dtype=np.int64); np.minimum.at(first,tuse,idx); np.maximum.at(last,tuse,idx)
    good=(last>=0)&(first<n)&(last>first)
    if not np.any(good): return 0.0
    dx=x[last[good]]-x[first[good]]; dy=y[last[good]]-y[first[good]]
    span=np.hypot(dx,dy); ok=np.isfinite(span)&(span>1.0)
    if not np.any(ok): return 0.0
    th=np.arctan2(dy[ok],dx[ok]); w=np.clip(span[ok],1.0,np.nanpercentile(span[ok],90) if np.any(ok) else 1.0)
    c=np.sum(w*np.cos(2*th)); ss=np.sum(w*np.sin(2*th)); ang=0.5*np.arctan2(ss,c)
    return float((np.rad2deg(ang)+180.0)%180.0)


def _resample_physical_tracks(x,y,v,track_ids,along_step,heading_deg):
    """Reduce dense samples to one bounded along-line series per physical trajectory.

    PRM-normalized ASC rows are source-block ordered with sensors interleaved.
    This implementation exploits that structure and processes one source block
    at a time, avoiding a site-wide 6+ million-row sort and keeping memory
    bounded on large archaeological surveys. A generic sorted fallback is used
    only when source blocks are not monotonic.
    """
    x=np.asarray(x,float); y=np.asarray(y,float); v=np.asarray(v,float); tids=np.asarray(track_ids,np.int64)
    th=np.deg2rad(float(heading_deg)); ct=np.cos(th); st=np.sin(th); step=max(float(along_step),1e-4)
    rx=[]; ry=[]; rz=[]; rt=[]; ru=[]; rw=[]; next_segment=0

    def add_track(xg,yg,zg):
        nonlocal next_segment
        if len(zg)<2: return
        ug=xg*ct+yg*st; wg=-xg*st+yg*ct
        good=np.isfinite(ug)&np.isfinite(wg)&np.isfinite(zg)
        if good.sum()<2: return
        ug=ug[good]; wg=wg[good]; zg=zg[good]
        # Ensure monotonic along-coordinate while retaining local value support.
        if ug[-1] < ug[0]: ug=ug[::-1]; wg=wg[::-1]; zg=zg[::-1]
        if np.any(np.diff(ug)<-1e-6):
            oo=np.argsort(ug,kind='stable'); ug=ug[oo]; wg=wg[oo]; zg=zg[oo]
        u0=float(ug[0]); bi=np.floor((ug-u0)/step+0.5).astype(np.int64); bi-=bi.min(); nb=int(bi.max())+1
        cnt=np.bincount(bi,minlength=nb).astype(float); su=np.bincount(bi,weights=ug,minlength=nb); swv=np.bincount(bi,weights=wg,minlength=nb); sz=np.bincount(bi,weights=zg,minlength=nb)
        have=cnt>0
        if have.sum()<2: return
        ub=su[have]/cnt[have]; wb=swv[have]/cnt[have]; zb=sz[have]/cnt[have]; bb=np.flatnonzero(have)
        cuts=np.r_[0,np.flatnonzero(np.diff(bb)>1)+1,len(bb)]
        for c0,c1 in zip(cuts[:-1],cuts[1:]):
            if c1-c0<2: continue
            uu=ub[c0:c1]; ww=wb[c0:c1]; zz=zb[c0:c1]; xx=uu*ct-ww*st; yy=uu*st+ww*ct; n=len(uu)
            rx.append(xx); ry.append(yy); rz.append(zz); ru.append(uu); rw.append(ww); rt.append(np.full(n,next_segment,dtype=np.int64)); next_segment+=1

    # read_asc_track_ids encodes source category * 64 + sensor. PRM ASC export
    # is deterministic and source-block ordered, so process those blocks in place.
    src=tids//64
    monotonic=bool(len(src)<2 or np.all(src[1:]>=src[:-1]))
    if monotonic:
        bounds=np.r_[0,np.flatnonzero(src[1:]!=src[:-1])+1,len(src)]
        for a,b in zip(bounds[:-1],bounds[1:]):
            tb=tids[a:b]
            for tid in np.unique(tb):
                m=(tb==tid); add_track(x[a:b][m],y[a:b][m],v[a:b][m])
    else:
        # Generic normalized ASC fallback. Individual-track masks are slower but
        # avoid the large temporary arrays of a global lexicographic sort.
        for tid in np.unique(tids):
            m=(tids==tid); add_track(x[m],y[m],v[m])
    if not rx: raise ValueError('track-surface could not reconstruct any physical trajectory segments')
    return (np.concatenate(rx),np.concatenate(ry),np.concatenate(rz),np.concatenate(rt),np.concatenate(ru),np.concatenate(rw),int(next_segment))

def track_surface_grid(x,y,v,xedges,yedges,track_ids,neighbors=4,radius=0.75,power=2.0,cores=1,
                       along_step=0.125,cross_method='adaptive',cross_tracks=4,max_gap=1.25,
                       edge_extrapolation=0.25,cell_size=0.25):
    """Track-aware archaeological surface reconstruction.

    Dense temporal sampling is first reduced independently along every real
    source+sensor trajectory. At each raster node one value per independent
    trajectory is considered. The production linear mode then interpolates only
    between the physically bracketing tracks, which removes the alternating
    near-track/between-track support texture without high-order overshoot.
    """
    from scipy.spatial import cKDTree
    x=np.asarray(x,float); y=np.asarray(y,float); v=np.asarray(v,float); tids=np.asarray(track_ids,np.int64)
    ok=np.isfinite(x)&np.isfinite(y)&np.isfinite(v); x=x[ok]; y=y[ok]; v=v[ok]; tids=tids[ok]
    if len(v)<3: raise ValueError('track-surface requires at least three valid measurements')
    heading=_track_surface_heading(x,y,tids)
    auto_step=max(0.02,min(float(cell_size)*0.5,0.125)); along=float(along_step) if float(along_step)>0 else auto_step
    rx,ry,rz,rt,ru,rw,nsegments=_resample_physical_tracks(x,y,v,tids,along,heading)
    pts=np.c_[rx,ry]; tree=cKDTree(pts,compact_nodes=True,balanced_tree=True)
    xc=(np.asarray(xedges[:-1])+np.asarray(xedges[1:]))/2.0; yc=(np.asarray(yedges[:-1])+np.asarray(yedges[1:]))/2.0
    ny,nx=len(yc),len(xc); out=np.full((ny,nx),np.nan,np.float32); sdout=np.full((ny,nx),np.nan,np.float32); cntout=np.zeros((ny,nx),np.uint16)
    bracket=np.zeros((ny,nx),np.uint8); gapout=np.full((ny,nx),np.nan,np.float32); alongout=np.full((ny,nx),np.nan,np.float32); nearcross=np.full((ny,nx),np.nan,np.float32)
    th=np.deg2rad(heading); ct=np.cos(th); st=np.sin(th)
    ntrack=max(2,int(cross_tracks)); candidate_k=min(len(rz),max(32,ntrack*16))
    # Small chunks keep k-neighbour matrices bounded even for million-cell rasters.
    target_entries=1_500_000; q_per=max(nx,int(target_entries//max(candidate_k,1))); chunk_rows=max(1,min(ny,q_per//max(nx,1)))
    search_radius=max(float(radius),float(max_gap)*0.75,along*3.0); atol=max(along*0.80,float(cell_size)*0.35)
    eps=1e-9; cross_method=str(cross_method).lower()
    if cross_method not in {'adaptive','linear','idw'}: raise ValueError('--track-cross-method must be adaptive, linear or idw')
    for r0 in tqdm(range(0,ny,chunk_rows),desc='Track-surface reconstruction',unit='chunk'):
        r1=min(ny,r0+chunk_rows); gx,gy=np.meshgrid(xc,yc[r0:r1]); q=np.c_[gx.ravel(),gy.ravel()]
        uq=q[:,0]*ct+q[:,1]*st; wq=-q[:,0]*st+q[:,1]*ct
        d,ii=tree.query(q,k=candidate_k,distance_upper_bound=search_radius,workers=max(1,int(cores)))
        if candidate_k==1: d=d[:,None]; ii=ii[:,None]
        valid=np.isfinite(d)&(ii<len(rz)); safe=np.where(valid,ii,0); seg=rt[safe]
        # Keep nearest support sample from each reconstructed physical segment.
        unique=np.zeros_like(valid,dtype=bool)
        for jj in range(candidate_k):
            first=valid[:,jj]
            if jj: first &= ~np.any((seg[:,:jj]==seg[:,jj,None])&valid[:,:jj],axis=1)
            unique[:,jj]=first
        # Along-track alignment prevents a nearby but longitudinally displaced
        # segment from acting as cross-track support.
        du=np.abs(ru[safe]-uq[:,None]); unique &= du<=atol
        rank=np.cumsum(unique,axis=1); use=unique&(rank<=ntrack)
        cnt=use.sum(1); zz=rz[safe]; cc=rw[safe]-wq[:,None]
        eu=np.where(use,d,np.inf); sd=np.min(eu,axis=1); ac=np.where(use,np.abs(cc),np.inf); nearest_cross=np.min(ac,axis=1)
        left=use&(cc<=0); right=use&(cc>=0)
        il=np.argmin(np.where(left,np.abs(cc),np.inf),axis=1); ir=np.argmin(np.where(right,np.abs(cc),np.inf),axis=1)
        rows=np.arange(len(q)); hasl=np.any(left,axis=1); hasr=np.any(right,axis=1)
        cl=cc[rows,il]; cr=cc[rows,ir]; zl=zz[rows,il]; zr=zz[rows,ir]
        both=hasl&hasr; gap=np.where(both,cr-cl,np.nan); goodbr=both&np.isfinite(gap)&(gap>=-1e-8)&(gap<=float(max_gap)+1e-9)
        exact=nearest_cross<=max(0.02,float(cell_size)*0.08)
        edge=(~goodbr)&np.isfinite(nearest_cross)&(nearest_cross<=float(edge_extrapolation)+1e-9)
        pred=np.full(len(q),np.nan,float)
        den=np.maximum(gap,eps); alpha=np.clip((-cl)/den,0.0,1.0); pair_val=zl*(1-alpha)+zr*alpha
        nearest_j=np.argmin(np.where(use,d,np.inf),axis=1); zn=zz[rows,nearest_j]
        gooddomain=goodbr|exact|edge
        if cross_method=='linear':
            pred[goodbr]=pair_val[goodbr]; pred[exact|edge]=zn[exact|edge]
        elif cross_method=='idw':
            distw=np.sqrt(np.maximum(cc*cc + (0.5*du)**2,1e-12)); ww=np.where(use,1.0/np.maximum(distw,1e-5)**float(power),0.0); sw=ww.sum(1)
            vals=(ww*zz).sum(1)/np.maximum(sw,eps); pred[gooddomain]=vals[gooddomain]
        else:
            # Adaptive quiet-field equalisation. A weighted first-order fit across
            # independent tracks suppresses alternating support/baseline stripes.
            # Strong local +/- ranges use the bracketing pair instead, preserving
            # compact dipoles and avoiding polynomial ringing.
            wc=np.where(use,1.0/np.maximum(np.abs(cc)+0.20*float(cell_size),1e-5),0.0)
            sw=wc.sum(1); sc=(wc*cc).sum(1); scc=(wc*cc*cc).sum(1); sz=(wc*zz).sum(1); scz=(wc*cc*zz).sum(1)
            det=sw*scc-sc*sc; fit=np.full(len(q),np.nan,float); np.divide((sz*scc-sc*scz),det,out=fit,where=np.abs(det)>1e-10)
            # Global robust scale is only a switch criterion; it never rescales data.
            gscale=1.4826*np.nanmedian(np.abs(v-np.nanmedian(v)))+eps
            local_min0=np.where(use,zz,np.inf).min(1); local_max0=np.where(use,zz,-np.inf).max(1); strong=(local_max0-local_min0)>4.0*gscale
            aval=np.where(strong|~np.isfinite(fit),pair_val,fit)
            pred[goodbr]=aval[goodbr]; pred[exact|edge]=zn[exact|edge]
        # Positive/linear weights should already be bounded; clamp defensively to
        # the independent-track envelope to guarantee no dipole overshoot.
        lmin=np.where(use,zz,np.inf).min(1); lmax=np.where(use,zz,-np.inf).max(1); fin=np.isfinite(pred)&(cnt>0); pred[fin]=np.clip(pred[fin],lmin[fin],lmax[fin])
        rr=slice(r0,r1); shape=(r1-r0,nx)
        out[rr]=pred.reshape(shape).astype(np.float32); sdout[rr]=np.where(cnt>0,sd,np.nan).reshape(shape).astype(np.float32); cntout[rr]=np.minimum(cnt,65535).reshape(shape).astype(np.uint16)
        bracket[rr]=goodbr.reshape(shape).astype(np.uint8); gapout[rr]=gap.reshape(shape).astype(np.float32); alongout[rr]=np.where(cnt>0,np.min(np.where(use,du,np.inf),axis=1),np.nan).reshape(shape).astype(np.float32); nearcross[rr]=np.where(cnt>0,nearest_cross,np.nan).reshape(shape).astype(np.float32)
    fin=np.isfinite(out); br=bracket.astype(bool)&fin
    info={'method':'track-surface','heading_deg':float(heading),'along_step_m':float(along),'cross_method':cross_method,'cross_tracks':int(ntrack),'max_cross_gap_m':float(max_gap),'edge_extrapolation_m':float(edge_extrapolation),'search_radius_m':float(search_radius),'input_points':int(len(v)),'resampled_track_points':int(len(rz)),'physical_track_segments':int(nsegments),'supported_nodes':int(fin.sum()),'total_nodes':int(out.size),'support_fraction':float(fin.mean()),'bracketed_fraction_of_supported':float(br.sum()/max(fin.sum(),1)),'median_independent_tracks':float(np.nanmedian(cntout[fin])) if fin.any() else 0.0,'median_cross_gap_m':float(np.nanmedian(gapout[br])) if br.any() else None,'p95_cross_gap_m':float(np.nanpercentile(gapout[br],95)) if br.any() else None}
    maps={'independent_track_count':cntout.astype(np.float32),'bracketing_status':bracket.astype(np.float32),'cross_track_gap':gapout,'along_track_support_misfit':alongout,'nearest_track_distance':nearcross}
    return out,sdout,cntout,info,maps

def direct_point_grid(x,y,v,xedges,yedges,method='survey-local',neighbors=12,radius=0.75,power=2.0,cores=1,track_ids=None,track_along_step=0.0,track_cross_method='adaptive',track_cross_tracks=4,track_max_gap=1.25,track_edge_extrapolation=0.25,cell_size=0.25,return_support_maps=False):
    """Reconstruct grid nodes directly from original XYZ measurements.

    This deliberately bypasses preliminary cell aggregation.  The production
    methods are local and bounded, which is important for compact bipolar
    anomalies: positive-weight IDW cannot create values outside the local
    measured envelope, and the local-linear option is explicitly clamped to
    that envelope.  Unsupported nodes remain NaN.
    """
    from scipy.spatial import cKDTree
    x=np.asarray(x,float); y=np.asarray(y,float); v=np.asarray(v,float)
    ok=np.isfinite(x)&np.isfinite(y)&np.isfinite(v)
    x=x[ok]; y=y[ok]; v=v[ok]
    if track_ids is not None:
        track_ids=np.asarray(track_ids)[ok].astype(np.int64,copy=False)
    if len(v)<3: raise ValueError('direct point gridding requires at least three valid measurements')
    if neighbors<1: raise ValueError('--point-neighbors must be >= 1')
    if radius<=0: raise ValueError('--point-radius must be > 0')
    if power<=0: raise ValueError('--point-power must be > 0')
    xc=(np.asarray(xedges[:-1])+np.asarray(xedges[1:]))/2.0
    yc=(np.asarray(yedges[:-1])+np.asarray(yedges[1:]))/2.0
    ny,nx=len(yc),len(xc)
    out=np.full((ny,nx),np.nan,dtype=np.float32)
    support_dist=np.full((ny,nx),np.nan,dtype=np.float32)
    support_count=np.zeros((ny,nx),dtype=np.uint16)
    pts=np.c_[x,y]
    tree=cKDTree(pts,compact_nodes=True,balanced_tree=True)
    method=str(method).lower()
    if method=='track-surface':
        if track_ids is None: raise ValueError('track-surface direct gridding requires PRM/source trajectory IDs')
        result=track_surface_grid(x,y,v,xedges,yedges,track_ids,neighbors=neighbors,radius=radius,power=power,cores=cores,along_step=track_along_step,cross_method=track_cross_method,cross_tracks=track_cross_tracks,max_gap=track_max_gap,edge_extrapolation=track_edge_extrapolation,cell_size=cell_size)
        if return_support_maps: return result
        return result[:4]
    if method=='track-balanced' and track_ids is None:
        raise ValueError('track-balanced direct gridding requires PRM/source trajectory IDs')
    k_requested=min(max(1,int(neighbors)),len(v))
    k=min(max(k_requested, min(len(v),k_requested*5 if method=='track-balanced' else k_requested)),len(v))
    chunk_rows=max(1,min(ny,int(max(1,180000//max(nx,1)))))
    eps=1e-9
    for r0 in tqdm(range(0,ny,chunk_rows),desc='Direct point gridding',unit='chunk'):
        r1=min(ny,r0+chunk_rows)
        gx,gy=np.meshgrid(xc,yc[r0:r1])
        q=np.c_[gx.ravel(),gy.ravel()]
        d,ii=tree.query(q,k=k,distance_upper_bound=float(radius),workers=max(1,int(cores)))
        if k==1:
            d=d[:,None]; ii=ii[:,None]
        valid=np.isfinite(d)&(ii<len(v))
        if method=='track-balanced':
            safe0=np.where(valid,ii,0)
            tids=track_ids[safe0]
            unique=np.zeros_like(valid,dtype=bool)
            # cKDTree neighbours are distance ordered. Retain only the nearest
            # measured sample from each physical PRM+sensor trajectory, then at
            # most --point-neighbors trajectories. This makes cross-track support
            # comparable to line-based geophysical gridding and stops dozens of
            # centimetre-spaced samples from one lane swamping neighbouring lanes.
            for jj in range(k):
                first=valid[:,jj]
                if jj:
                    first &= ~np.any((tids[:,:jj]==tids[:,jj,None]) & valid[:,:jj],axis=1)
                unique[:,jj]=first
            rank=np.cumsum(unique,axis=1)
            valid=unique & (rank<=k_requested)
        cnt=valid.sum(axis=1)
        sd=np.where(valid,d,np.inf).min(axis=1)
        pred=np.full(len(q),np.nan,dtype=float)
        # Safe indexing for missing neighbours.
        safeii=np.where(valid,ii,0)
        zz=v[safeii]
        local_min=np.where(valid,zz,np.inf).min(axis=1)
        local_max=np.where(valid,zz,-np.inf).max(axis=1)
        exact=valid[:,0]&(d[:,0]<=1e-10)
        pred[exact]=zz[exact,0]
        usable=(cnt>0)&~exact
        if method=='nearest':
            pred[usable]=zz[usable,0]
        elif method in {'idw','survey-local','track-balanced'}:
            # survey-local uses a slightly steeper kernel in high-contrast
            # neighbourhoods so compact +/- dipoles are not broadened by distant
            # samples, while retaining strictly positive weights.
            pw=np.full(len(q),float(power))
            if method in {'survey-local','track-balanced'}:
                # Use the local measured envelope as the contrast diagnostic.
                # This avoids all-NaN reductions for unsupported nodes and keeps
                # strong compact +/- neighbourhoods more local without changing
                # the positive-weight/non-overshooting character of IDW.
                gr=1.4826*np.nanmedian(np.abs(v-np.nanmedian(v)))+eps
                local_span=np.where(cnt>0,local_max-local_min,0.0)
                pw=np.where(local_span>4.0*gr,np.maximum(float(power),3.0),float(power))
            w=np.where(valid,1.0/np.maximum(d,1e-6)**pw[:,None],0.0)
            sw=w.sum(axis=1)
            vals=(w*zz).sum(axis=1)/np.maximum(sw,eps)
            pred[usable]=vals[usable]
        elif method=='local-linear':
            # Weighted plane z=a+b*dx+c*dy evaluated at the output node (a).
            # Batch normal equations are ridge-stabilised and the prediction is
            # clamped to the local measured envelope to prevent cubic-like ringing.
            dx=x[safeii]-q[:,0,None]; dy=y[safeii]-q[:,1,None]
            w=np.where(valid,1.0/np.maximum(d,1e-5)**float(power),0.0)
            sw=w.sum(1); sx=(w*dx).sum(1); sy=(w*dy).sum(1)
            sxx=(w*dx*dx).sum(1); syy=(w*dy*dy).sum(1); sxy=(w*dx*dy).sum(1)
            sz=(w*zz).sum(1); sxz=(w*dx*zz).sum(1); syz=(w*dy*zz).sum(1)
            M=np.empty((len(q),3,3),float); B=np.c_[sz,sxz,syz]
            M[:,0,0]=sw; M[:,0,1]=M[:,1,0]=sx; M[:,0,2]=M[:,2,0]=sy
            M[:,1,1]=sxx; M[:,1,2]=M[:,2,1]=sxy; M[:,2,2]=syy
            ridge=np.maximum(sw,1.0)*1e-10
            M[:,1,1]+=ridge; M[:,2,2]+=ridge
            enough=cnt>=3
            try:
                coef=np.linalg.solve(M,B); lp=coef[:,0]
            except np.linalg.LinAlgError:
                lp=np.full(len(q),np.nan)
            # IDW fallback for singular/local-collinear cases.
            wi=np.where(valid,1.0/np.maximum(d,1e-6)**float(power),0.0); swi=wi.sum(1)
            idw=(wi*zz).sum(1)/np.maximum(swi,eps)
            lp=np.where(enough&np.isfinite(lp),lp,idw)
            pred[usable]=lp[usable]
        else:
            raise ValueError(f'unknown direct point method: {method}')
        finite=np.isfinite(pred)&(cnt>0)
        pred[finite]=np.minimum(np.maximum(pred[finite],local_min[finite]),local_max[finite])
        rr=slice(r0,r1)
        out[rr,:]=pred.reshape(r1-r0,nx).astype(np.float32)
        support_dist[rr,:]=np.where(cnt>0,sd,np.nan).reshape(r1-r0,nx).astype(np.float32)
        support_count[rr,:]=np.minimum(cnt,65535).reshape(r1-r0,nx).astype(np.uint16)
    info={'method':method,'neighbors':int(k_requested),'candidate_neighbors':int(k),'radius_m':float(radius),'power':float(power),
          'input_points':int(len(v)),'supported_nodes':int(np.isfinite(out).sum()),'total_nodes':int(out.size),
          'support_fraction':float(np.isfinite(out).mean())}
    if return_support_maps: return out,support_dist,support_count,info,{}
    return out,support_dist,support_count,info

def grid_main():
    global CURRENT_VALUE_UNITS
    args=grid_build_parser().parse_args()
    args._array_orientation="south-up"
    runtime_cores=configure_runtime_cores(getattr(args,'cores',0))
    startup_banner()
    print(f"CPU budget: {runtime_cores} core(s); multiprocessing/BLAS/GDAL limited to this budget where supported.",flush=True)
    CURRENT_VALUE_UNITS=args.value_units
    args.output.mkdir(parents=True,exist_ok=True)
    apply_figure_preset(args)
    if args.full_archaeology:
        # FULL generates a documented set of derived products; it does not define a single preferred interpretation image.
        # The quantitative reference is never smoothed, destriped, repaired,
        # plough-filtered or segmented implicitly.  Full mode enables diagnostics
        # plus multiple explicitly labelled interpretation/restoration branches.
        args.auto_qc=True; args.support_maps=True; args.stability_map=True
        args.comparison_panel=True; args.archaeology_subtle=True
        if not _flag_provided('--no-export-points'): args.export_points=True
        args.plough_diagnostic=True; args.noise_diagnostic=True
        args.figure_preset='publication'; apply_figure_preset(args)
        if not _flag_provided('--sensor-bias-correction'):
            args.sensor_bias_correction='diagnostic'
        if not _flag_provided('--restoration-suite'):
            args.restoration_suite='off'
        if not _flag_provided('--protected-leveling'):
            args.protected_leveling='diagnostic'
        args.interpretation_suite=True
        args.microlevel_candidate=False
    if args.auto:
        # Auto mode is intentionally conservative and transparent. Contextual
        # archaeology presets, when supplied, are combined with these data-driven settings.
        args.auto_noise=True
        args.auto_qc=True
        args.support_maps=True
        args.comparison_panel=True
        args.archaeology_subtle=True
        if not _flag_provided("--plough-filter"):
            args.plough_filter="auto"
    if args.cell_size<=0 or args.fill_distance<0: raise SystemExit("Require --cell-size > 0 and --fill-distance >= 0")
    if args.low_pass>0 and args.smooth>0: raise SystemExit("Use either --low-pass or --smooth, not both")
    if (args.display_min is None)!=(args.display_max is None): raise SystemExit("Use --display-min and --display-max together")
    if not (0<args.subtle_percentile<100): raise SystemExit("--subtle-percentile must be between 0 and 100")
    if args.subtle_background_scale<=0: raise SystemExit("--subtle-background-scale must be > 0")
    if not (0<=args.subtle_strong_opacity<=1 and 0<=args.subtle_only_strong_opacity<=1 and 0<=args.subtle_context_weight<=1): raise SystemExit("Subtle opacity/context values must be 0..1")
    if args.subtle_display_sigma<=0 or args.subtle_asinh_width<=0 or args.subtle_fade_power<=0: raise SystemExit("Subtle display parameters must be > 0")
    if args.local_noise_window<=0 or args.regional_iterations<1 or args.regional_tuning<=0 or args.stability_snr<=0: raise SystemExit("QC/regional/stability parameters must be > 0")
    if not (0 <= args.spline_tension <= 1): raise SystemExit("--spline-tension must be between 0 and 1")
    if args.spline_iterations<1 or args.spline_tolerance<0 or args.rbf_neighbors<4 or args.kriging_neighbors<4: raise SystemExit("Invalid spline/RBF/kriging parameters")
    if args.kriging_range<=0 or args.kriging_nugget<0: raise SystemExit("Kriging requires range > 0 and nugget >= 0")
    if not (0 < args.cv_fraction < 0.5): raise SystemExit("--cv-fraction must be between 0 and 0.5")
    if args.fft_order<1 or args.fft_padding<0: raise SystemExit("Invalid FFT order/padding")
    if args.plough_search_min_wavelength<=0 or args.plough_search_max_wavelength<=args.plough_search_min_wavelength: raise SystemExit("Plough search wavelengths require 0 < min < max")
    if not (0<=args.plough_strength<=1) or args.plough_notch_width<=0 or args.plough_harmonics<1 or args.plough_angle_tolerance<=0: raise SystemExit("Invalid plough-filter strength/notch/harmonics/angle tolerance")
    if args.artifact_z<=0 or args.artifact_window<=0 or args.artifact_max_area<=0 or args.artifact_dipole_radius<=0: raise SystemExit("Artifact cleaning parameters must be > 0")
    if args.stripe_background<=0 or not (0<=args.stripe_strength<=1): raise SystemExit("Require --stripe-background > 0 and --stripe-strength in 0..1")
    if args.analysis_scale<=0 or args.local_analysis_window<=0: raise SystemExit("Analysis scales must be > 0")
    if not (0 <= args.grid_alpha <= 1 and 0 <= args.basemap_alpha <= 1): raise SystemExit("Grid/basemap alpha must be 0..1")
    if args.figure_dpi < 72: raise SystemExit("--figure-dpi must be >= 72 after preset resolution")
    if args.interpolation_comparison:
        args.interpolation_cv=True
    # Legacy volcanic switch resolves through the composable MagSurveyPy context system.
    if args.archaeology_volcanic:
        if args.archaeology_preset=="general": args.archaeology_preset="volcanic"
        if args.soil_environment=="auto": args.soil_environment="volcanic-basaltic"
    env_notes=apply_environment_modifiers(args)
    context_notes=apply_archaeology_context(args)
