    track_ids_all=read_asc_track_ids(args.input) if (getattr(args,'grid_source','binned')=='points' and getattr(args,'point_method','') in {'track-balanced','track-surface'}) else None
    if track_ids_all is not None and len(track_ids_all)!=len(v): raise SystemExit('Track-ID rows do not match ASC measurement rows.')
    crossover_corr_all=None; crossover_meta={}; crossover_applied=False
    if getattr(args,'crossover_corrections',None):
        try:
            crossover_corr_all,crossover_meta=_load_crossover_correction_vector(args.input,args.crossover_corrections)
            if len(crossover_corr_all)!=len(v): raise ValueError(f'correction rows {len(crossover_corr_all)} != ASC rows {len(v)}')
            crossover_applied=bool(crossover_meta.get('applied',False))
            print(f"Crossover/tie-network correction metadata loaded: applied={crossover_applied}; constraints={crossover_meta.get('constraints',0)}; improvement={100*float(crossover_meta.get('improvement_fraction',0.0)):.1f}%",flush=True)
        except Exception as exc:
            raise SystemExit(f'Failed to load crossover correction metadata: {exc}')
    removed_zone=None
    if not args.keep_zone_prefix and np.nanmedian(np.abs(x))>=10_000_000:
        removed_zone=int(abs(np.nanmedian(x))//1_000_000); x=x-np.sign(np.nanmedian(x))*removed_zone*1_000_000
    keep=np.isfinite(x)&np.isfinite(y)&np.isfinite(v)&(sensor>0)
    if args.sensor!="all": keep &= sensor==int(args.sensor)
    if args.clip>0: keep &= np.abs(v)<=args.clip
    if crossover_corr_all is not None: crossover_corr_all=np.asarray(crossover_corr_all)[keep]
    if track_ids_all is not None: track_ids_all=np.asarray(track_ids_all)[keep]
    x,y,v,sensor=x[keep],y[keep],v[keep],sensor[keep]
    if not len(v): raise SystemExit("No points remain after filtering")
    v_uncalibrated=v.copy()
    if crossover_applied and crossover_corr_all is not None:
        v=v_uncalibrated-np.asarray(crossover_corr_all,dtype=float)
        print(f"Applied crossover/tie-network point correction to analysis branch; measured values remain preserved for Bz_grid.",flush=True)
    v_crossover_levelled=v.copy()
    cs=args.cell_size
    # ------------------------------------------------------------------
    # Spatial sensor/channel calibration.  This is NOT traverse zeroing.
    # Persistent offsets are estimated only from coarse spatial cells seen
    # by multiple sensors and checked at several cell sizes.  Auto mode is
    # deliberately gated; if it does not pass, values remain untouched.
    # ------------------------------------------------------------------
    pre_outputs=[]
    bias_mode=str(getattr(args,'sensor_bias_correction','off'))
    sensor_bias_info={'active':False,'reason':'disabled','offsets':{},'rows':[],'auto_apply':False}
    sensor_bias_offsets={}
    sensor_bias_applied=False
    v_bias_candidate=None
    if bias_mode!='off':
        sensor_bias_offsets,sensor_bias_info=estimate_spatial_sensor_bias(x,y,v,sensor,cs,args)
        sensor_bias_applied=bool(bias_mode=='apply' or (bias_mode=='auto' and sensor_bias_info.get('auto_apply',False)))
        if sensor_bias_offsets:
            correction=np.array([sensor_bias_offsets.get(int(s),0.0) for s in sensor],dtype=float)
            v_bias_candidate=v_uncalibrated-correction
        if sensor_bias_applied and sensor_bias_offsets:
            v=v_bias_candidate.copy()
            print('Spatial sensor calibration APPLIED: '+', '.join(f'S{k}={sensor_bias_offsets[k]:+.3f}' for k in sorted(sensor_bias_offsets))+' '+magnetic_unit(),flush=True)
        else:
            print('Spatial sensor calibration diagnostic only: '+str(sensor_bias_info.get('reason','QC gate not passed')),flush=True)
        qcsv=args.output/f"{prefix}_spatial_sensor_bias_QC.csv"
        qjson=args.output/f"{prefix}_spatial_sensor_bias_QC.json"
        write_spatial_sensor_bias_qc(qcsv,sensor_bias_info,bias_mode,sensor_bias_applied)
        qjson.write_text(json.dumps({'software_version':VERSION,'mode':bias_mode,'applied':sensor_bias_applied,**sensor_bias_info},indent=2,default=str),encoding='utf-8')
        pre_outputs += [qcsv,qjson]
    xmin=np.floor(x.min()/cs)*cs; xmax=np.ceil(x.max()/cs)*cs; ymin=np.floor(y.min()/cs)*cs; ymax=np.ceil(y.max()/cs)*cs
    xedges=np.arange(xmin,xmax+cs*1.01,cs); yedges=np.arange(ymin,ymax+cs*1.01,cs)
    point_grid_info=None; point_support_distance=None; point_support_count=None; point_support_maps={}
    with tqdm(total=3,desc="Building base grid",unit="stage") as gp:
        base_uncalibrated=None; base_bias_candidate=None
        if getattr(args,'grid_source','binned')=='points':
            gp.set_postfix_str("direct original-point reconstruction")
            base,point_support_distance,point_support_count,point_grid_info,point_support_maps=direct_point_grid(
                x,y,v,xedges,yedges,method=args.point_method,neighbors=args.point_neighbors,
                radius=args.point_radius,power=args.point_power,cores=cores,track_ids=track_ids_all,
                track_along_step=getattr(args,'track_along_step',0.0),track_cross_method=getattr(args,'track_cross_method','adaptive'),
                track_cross_tracks=getattr(args,'track_cross_tracks',4),track_max_gap=getattr(args,'track_max_gap',1.25),
                track_edge_extrapolation=getattr(args,'track_edge_extrapolation',0.25),cell_size=cs,return_support_maps=True)
            if sensor_bias_applied or crossover_applied:
                base_uncalibrated,_,_,_=direct_point_grid(x,y,v_uncalibrated,xedges,yedges,method=args.point_method,neighbors=args.point_neighbors,radius=args.point_radius,power=args.point_power,cores=cores,track_ids=track_ids_all,track_along_step=getattr(args,'track_along_step',0.0),track_cross_method=getattr(args,'track_cross_method','adaptive'),track_cross_tracks=getattr(args,'track_cross_tracks',4),track_max_gap=getattr(args,'track_max_gap',1.25),track_edge_extrapolation=getattr(args,'track_edge_extrapolation',0.25),cell_size=cs)
            if v_bias_candidate is not None:
                base_bias_candidate,_,_,_=direct_point_grid(x,y,v_bias_candidate,xedges,yedges,method=args.point_method,neighbors=args.point_neighbors,radius=args.point_radius,power=args.point_power,cores=cores,track_ids=track_ids_all,track_along_step=getattr(args,'track_along_step',0.0),track_cross_method=getattr(args,'track_cross_method','adaptive'),track_cross_tracks=getattr(args,'track_cross_tracks',4),track_max_gap=getattr(args,'track_max_gap',1.25),track_edge_extrapolation=getattr(args,'track_edge_extrapolation',0.25),cell_size=cs)
            print(f"Direct point grid: method={args.point_method}; input={len(v):,} measured points; support={100*float(point_grid_info.get('support_fraction',0)):.1f}% of output nodes; radius={args.point_radius:g} m; neighbours={args.point_neighbors}",flush=True)
        else:
            gp.set_postfix_str("aggregating magnetic values")
            base,_,_,_=binned_statistic_2d(x,y,v,statistic=args.statistic,bins=(xedges,yedges)); base=base.T
            if sensor_bias_applied or crossover_applied:
                base_uncalibrated,_,_,_=binned_statistic_2d(x,y,v_uncalibrated,statistic=args.statistic,bins=(xedges,yedges)); base_uncalibrated=base_uncalibrated.T
            if v_bias_candidate is not None:
                base_bias_candidate,_,_,_=binned_statistic_2d(x,y,v_bias_candidate,statistic=args.statistic,bins=(xedges,yedges)); base_bias_candidate=base_bias_candidate.T
        gp.update(1)
        gp.set_postfix_str("measurement density")
        count_grid,_,_,_=binned_statistic_2d(x,y,v,statistic="count",bins=(xedges,yedges)); count_grid=count_grid.T; gp.update(1)
        # In point mode the reconstructed surface is derived from original XYZ
        # support; measurement density remains a separate physical-support map.
        observed_mask=(np.isfinite(base) if getattr(args,'grid_source','binned')=='points' else (count_grid>0))
        gp.set_postfix_str("grid geometry"); gp.update(1)
    auto_assessment=preflight_statistics(x,y,v,base,count_grid,args) if args.auto else {}
    auto_cvrows=[]
    if args.auto and not interpolation_explicit:
        chosen,auto_cvrows=auto_interpolation_selection(base,args,cores)
        methods=[chosen]
        auto_assessment["interpolation_candidates"]=auto_cvrows
        auto_assessment["selected_interpolation"]=chosen
        print(f"AUTO interpolation: {chosen}")
        # Dense grids need only local gap filling; sparse grids remain capped conservatively.
        if not _flag_provided("--fill-distance"):
            occ=auto_assessment["grid_occupancy_fraction"]
            args.fill_distance=max(cs*1.4, min(0.50, 0.35 if occ>=0.35 else 0.50))
            auto_assessment["selected_fill_distance_m"]=args.fill_distance
    if args.auto and not _flag_provided("--subtle-percentile"):
        tail=auto_assessment.get("tail_ratio_p99_p90",1.0)
        args.subtle_percentile=96.0 if tail>4.0 else (94.0 if tail>2.5 else 92.0)
        auto_assessment["selected_subtle_percentile"]=args.subtle_percentile
    xcent=(xedges[:-1]+xedges[1:])/2; ycent=(yedges[:-1]+yedges[1:])/2
