        eff=apply_auto_noise_settings(args,analysis) if (analysis is not None and args.auto_noise) else args
        if analysis:
            npng,ntxt=write_noise_diagnostics(args.output,analysis,prefix,method if multi else ""); outputs.extend([p for p in (npng,ntxt) if p])
        # Keep the Bz reference minimally processed. Auto-noise smoothing belongs
        # only to the subtle branch unless the user explicitly requested --low-pass/--smooth.
        ref_args=copy.copy(args)
        if args.auto_noise and not _flag_provided("--low-pass") and not _flag_provided("--smooth"):
            ref_args.low_pass=0.0; ref_args.smooth=0.0
        reference=apply_filters(raw,ref_args,xcent,ycent)
        reference_uncalibrated=apply_filters(raw_uncalibrated,ref_args,xcent,ycent) if (sensor_bias_applied or crossover_applied) else reference.copy()
        reference_crossover=reference.copy()
        reference_bias_candidate=apply_filters(raw_bias_candidate,ref_args,xcent,ycent) if raw_bias_candidate is not None else None
        # Select a source for DERIVED archaeological interpretation only.  A
        # rejected calibration may still be useful if an independent spectral
