        # the field wholesale.  Bz_grid remains untouched regardless.
        interpretation_reference=reference
        interpretation_source_label='QC-gated sensor-calibrated Bz' if sensor_bias_applied else ('Crossover-levelled Bz' if crossover_applied else 'Measured Bz reference')
        bias_candidate_selection={'available':bool(reference_bias_candidate is not None),'recommended_for_interpretation':False}
        if (not sensor_bias_applied) and reference_bias_candidate is not None and args.full_archaeology:
            raw_spec=analysis if analysis is not None else analyse_noise_spectrum(reference,cs,args)
            cand_spec=analyse_noise_spectrum(reference_bias_candidate,cs,args)
            raw_an=float(raw_spec.get('stripe_anisotropy',np.nan)); cand_an=float(cand_spec.get('stripe_anisotropy',np.nan))
            vm=np.isfinite(reference)&np.isfinite(reference_bias_candidate)
            corr=float(np.corrcoef(reference[vm],reference_bias_candidate[vm])[0,1]) if vm.sum()>20 and np.std(reference[vm])>0 and np.std(reference_bias_candidate[vm])>0 else np.nan
            reduction=float(1-cand_an/raw_an) if np.isfinite(raw_an) and raw_an>0 and np.isfinite(cand_an) else np.nan
            recommended=bool(np.isfinite(reduction) and reduction>=0.25 and np.isfinite(corr) and corr>=0.80 and raw_an>=2.0 and cand_an<raw_an)
            bias_candidate_selection.update(raw_directional_anisotropy=raw_an,candidate_directional_anisotropy=cand_an,anisotropy_reduction_fraction=reduction,correlation_to_reference=corr,recommended_for_interpretation=recommended,policy='spectral/correlation gate affects derived interpretation only; quantitative calibration QC remains unchanged')
