        plough_params=detect_ploughing(interpretation_reference,analyse_noise_spectrum(interpretation_reference,cs,args) if need_noise_analysis else analysis,args) if (args.plough_filter!="none" or getattr(args,'plough_diagnostic',False)) else {"active":False,"reason":"disabled"}
        apply_plough=bool(args.plough_filter!="none" and plough_params.get("active"))
        plough_reference,plough_removed=plough_filter_grid(interpretation_reference,args,plough_params) if apply_plough else (interpretation_reference.copy(),np.zeros_like(reference))
        # Audited cleaning is an interpretation branch only. Start from the
