        cleaned_branch=plough_reference.copy()
        artifact_mask=np.zeros_like(reference,dtype=float); artifact_conf=np.zeros_like(reference,dtype=float); artifact_removed=np.zeros_like(reference,dtype=float)
        artifact_info={"candidate_pixels":0,"repaired_pixels":0,"policy":"off"}
