"""Display/image utilities for the MagSurveyPy Archaeological Magnetometry Prospection Suite.

`enhance` is display-only and never replaces quantitative magnetic rasters.
`pansharpen` is intended for external RGB+pan remote-sensing imagery, not for
single-band magnetic data.

Author: Alexandru Hegyi, PhD
Website: https://alexandruhegyi.com
"""
import argparse, math, os, re
from pathlib import Path
import numpy as np
AUTHOR='Alexandru Hegyi, PhD'; WEBSITE='https://alexandruhegyi.com'; VERSION=APP_VERSION
SOFTWARE='MagSurveyPy Archaeological Magnetometry Prospection Suite'

IMAGE_DESCRIPTION = 'Display-oriented magnetic raster enhancement and external image utilities.\n\nProvides contrast/enhancement operations for figures and optional RGB+panchromatic image utilities. These tools are for visualization/support products; they do not replace the quantitative magnetic GeoTIFF.'

def image_banner():
    if os.environ.get('MULTIMAG_CHILD') == '1':
        return
    print('='*78); print(f'{SOFTWARE} — image utilities — Version {VERSION}')
    print(f'Developed by {AUTHOR} | {WEBSITE} | alexandruhegyi@gmail.com'); print('='*78)

def image_parser():
    p=argparse.ArgumentParser(description=IMAGE_DESCRIPTION)
    sp=p.add_subparsers(dest='cmd',required=True)
    e=sp.add_parser('enhance',help='Display-only enhancement of a raster/image')
    e.add_argument('input',type=Path); e.add_argument('-o','--output',type=Path,required=True)
    e.add_argument('--method',choices=('linear','asinh','clahe','local-normalization','unsharp'),default='asinh')
    e.add_argument('--upscale',type=int,choices=(1,2,3,4),default=2)
    e.add_argument('--unsharp-amount',type=float,default=0.8)
    e.add_argument('--cmap',default='gray_r'); e.add_argument('--dpi',type=int,default=300)
    ps=sp.add_parser('pansharpen',help='Pansharpen external RGB multispectral imagery with a panchromatic raster')
    ps.add_argument('rgb',type=Path); ps.add_argument('pan',type=Path); ps.add_argument('-o','--output',type=Path,required=True)
    ps.add_argument('--method',choices=('brovey',),default='brovey')
    p.add_argument('--version',action='version',version=f'%(prog)s {VERSION} — {AUTHOR} — {WEBSITE}')
    return p

def image_robust_scale(a):
    f=a[np.isfinite(a)]; med=np.median(f); s=1.4826*np.median(np.abs(f-med)); return float(s if s>1e-12 else max(np.std(f),1e-9))

def enhance(a,method,amount):
    from scipy.ndimage import gaussian_filter
    valid=np.isfinite(a); f=a[valid]; med=float(np.median(f)); sig=image_robust_scale(a); filled=np.where(valid,a,med)
    if method=='linear': out=filled
    elif method=='asinh': out=np.arcsinh((filled-med)/(0.6*sig)); out/=max(np.nanmax(np.abs(out)),1e-9)
    elif method=='clahe':
        from skimage.exposure import equalize_adapthist
        lo,hi=np.percentile(f,[1,99]); n=np.clip((filled-lo)/max(hi-lo,1e-9),0,1); out=2*equalize_adapthist(n,clip_limit=.02)-1
    elif method=='local-normalization':
        mu=gaussian_filter(filled,3); sd=np.sqrt(np.maximum(gaussian_filter((filled-mu)**2,3),1e-12)); out=np.tanh((filled-mu)/(3*sd))
    else:
        blur=gaussian_filter(filled,1.0); out=filled+amount*(filled-blur)
    out=np.asarray(out,float); out[~valid]=np.nan; return out

def run_enhance(a):
    import rasterio, matplotlib.pyplot as plt
    from PIL import Image
    inp=a.input
    if inp.suffix.lower() in {'.tif','.tiff'}:
        with rasterio.open(inp) as ds: arr=ds.read(1,masked=True).filled(np.nan).astype(float)
    else:
        im=np.asarray(Image.open(inp).convert('L'),float); arr=im
    out=enhance(arr,a.method,a.unsharp_amount)
    a.output.parent.mkdir(parents=True,exist_ok=True)
    fig,ax=plt.subplots(figsize=(10*a.upscale/2,8*a.upscale/2)); f=out[np.isfinite(out)]
    if a.method in {'asinh','clahe','local-normalization'}: vmin,vmax=-1,1
    else:
        med=np.median(f); lim=max(3*image_robust_scale(out),np.percentile(np.abs(f-med),98)); vmin,vmax=med-lim,med+lim
    ax.imshow(out,cmap=a.cmap,vmin=vmin,vmax=vmax,interpolation='lanczos'); ax.axis('off'); fig.savefig(a.output,dpi=a.dpi,bbox_inches='tight',pad_inches=0); plt.close(fig); print(a.output)

def run_pansharpen(a):
    import rasterio
    from rasterio.warp import reproject,Resampling
    with rasterio.open(a.pan) as pan_ds:
        pan=pan_ds.read(1).astype(float); profile=pan_ds.profile.copy(); ptransform=pan_ds.transform; pcrs=pan_ds.crs; pshape=pan.shape
    with rasterio.open(a.rgb) as rgb_ds:
        if rgb_ds.count<3: raise SystemExit('RGB raster must have at least 3 bands')
        bands=[]
        for i in range(1,4):
            dst=np.empty(pshape,dtype='float32')
            reproject(rgb_ds.read(i),dst,src_transform=rgb_ds.transform,src_crs=rgb_ds.crs,dst_transform=ptransform,dst_crs=pcrs,resampling=Resampling.cubic)
            bands.append(dst.astype(float))
    rgb=np.stack(bands); pan_norm=pan/max(np.nanpercentile(pan,99.5),1e-9); rgb_sum=np.maximum(rgb.sum(axis=0),1e-9)
    out=rgb*(3*pan_norm)[None,:,:]/rgb_sum[None,:,:]
    # Restore each RGB band's robust dynamic range for a visually sensible remote-sensing product.
    for i in range(3):
        q=np.nanpercentile(out[i],[1,99]); out[i]=np.clip((out[i]-q[0])/max(q[1]-q[0],1e-9),0,1)
    profile.update(count=3,dtype='uint8',compress='deflate')
    a.output.parent.mkdir(parents=True,exist_ok=True)
    with rasterio.open(a.output,'w',**profile) as ds:
        ds.write((out*255).astype('uint8')); ds.update_tags(author=AUTHOR,website=WEBSITE,software=SOFTWARE,note='Brovey pansharpening of external RGB+pan imagery; not magnetic data')
    print(a.output)

def image_main():
    image_banner(); a=image_parser().parse_args(); run_enhance(a) if a.cmd=='enhance' else run_pansharpen(a)


