    p.add_argument('--polarity',choices=('positive','negative','both','absolute'),default='both',help='Magnetic anomaly sign. both (default) segments positive and negative anomalies independently so touching opposite-polarity responses are not merged into one polygon. absolute treats |response| as one unsigned mask')
    p.add_argument('--threshold',type=float,default=0.0,help='Absolute threshold in raster units for method=threshold')
