    p.add_argument('--adaptive-window',type=float,default=3.0,metavar='METRES',help='Local threshold window for adaptive mode. Default 3 m')
    p.add_argument('--adaptive-offset',type=float,default=0.0)
    p.add_argument('--min-area',type=float,default=0.25,metavar='M2')
    p.add_argument('--max-area',type=float,default=0.0,metavar='M2',help='0 disables upper area filter')
    p.add_argument('--min-peak',type=float,default=0.0,help='Minimum absolute peak within a candidate; 0 disables')
    p.add_argument('--max-peak',type=float,default=0.0,help='Maximum absolute peak; useful for excluding strong ferrous/geological responses. 0 disables')
    p.add_argument('--min-mean-abs',type=float,default=0.0,help='Minimum |mean| candidate response. 0 disables')
    p.add_argument('--opening',type=float,default=0.0,metavar='METRES',help='Binary opening radius. 0 disables')
    p.add_argument('--closing',type=float,default=0.25,metavar='METRES',help='Binary closing radius. Default 0.25 m')
    p.add_argument('--fill-holes-area',type=float,default=0.25,metavar='M2')
    p.add_argument('--simplify',type=float,default=0.05,metavar='METRES',help='Polygon simplification tolerance. 0 disables')
