_TRAJECTORY_CACHE = {}
_BASE_SHIFT_CACHE = {}


PRM_DESCRIPTION = 'Multichannel magnetic acquisition through the supported PRM field-data adapter.\n\nDecodes acquisition geometry and magnetic phase data, removes exact duplicate files, performs per-sensor overlap-segment clipping, can attempt stable whole-swath physical thinning with explicit local geometry QC/fail-safe fallback, writes acquisition/QC/ASC products, and can then call the instrument-independent raster engine.'

def _load_base_shift_cached(path_text):
    if not path_text:
        return None
    key=str(Path(path_text).resolve())
    if key not in _BASE_SHIFT_CACHE:
        _BASE_SHIFT_CACHE[key]=load_base_shift(Path(key))
    return _BASE_SHIFT_CACHE[key]


def _apply_base_shift_gps(gps, path_text):
    """Apply a constant ECEF translation derived from a corrected radio-RTK base.

    This is intentionally distinct from PPK.  It is valid when the rover/base relative
    geometry was already precise and the field base was assigned an erroneous absolute
    coordinate.  The shift JSON is produced by the RINEX positioning module.
    """
    if not path_text:
        return gps
    shift=_load_base_shift_cached(path_text)
    dx,dy,dz,_=shift
    out=np.asarray(gps,float).copy()
    lon,lat,h=apply_ecef_shift_llh(out[:,0],out[:,1],out[:,2],(dx,dy,dz))
    out[:,0]=lon; out[:,1]=lat; out[:,2]=h
    return out


def prm_build_parser():
    epilog = r"""
MagSurveyPy practical examples
-------------------------
Routine archaeology:
  mspy prm Export/ -o Result \
    --site-name Site --cell-size 0.25 --archaeology-subtle --cores 8

QC-gated physical thinning attempt (native 0.25 m -> requested 0.50 m):
  mspy prm Export/ -o Result \
    --site-name Site --track-spacing 0.5 --thinning-policy strict --swath-overlap-filter auto --cores 8

Full archaeological export/QC mode (no automatic filtering/repair/OBIA):
  mspy prm Export/ -o Result \
    --site-name Site --full-archaeology --cell-size 0.25 --statistic median --cores 8

Volcanic / extremely magnetic ground:
  mspy prm Breb_Export/ -o Breb_Result \
    --site-name Breb --cell-size 0.25 --archaeology-volcanic --cmap gray --cores 8

Interpolation comparison with observed-cell cross-validation:
  mspy prm Export/ -o Compare \
    --interpolation fill,idw,spline-tension,bicubic,ordinary-kriging \
    --interpolation-comparison --fill-distance 0.5

Explicit archaeological wavelength band:
  mspy prm Export/ -o Band \
    --fft-filter butterworth-bandpass --fft-min-wavelength 0.5 \
    --fft-max-wavelength 6 --fft-order 4 --export-filter-removed

Upward continuation:
  --upward-continuation 0.15,0.25,0.35
  --upward-continuation auto
  --continuation-band 0.20,1.50

Scientific cautions
-------------------
* every interpolation method is capped by --fill-distance;
* bilinear/bicubic are the scattered-data linear/Clough-Tocher equivalents;
* spline/cubic/RBF surfaces may overshoot strong magnetic responses;
* high-pass filters can remove broad archaeology; low-pass filters can erase
  small archaeology;
* nonlinear display enhancement changes PNG contrast only, not GeoTIFF values;
* the volcanic preset preserves the Bz reference and applies automatic upward
  continuation only to the subtle-analysis branch.

Coordinate handling
-------------------
--crs auto is the default. Survey GPS selects a local projected CRS. Explicit
projected CRS values are supported; geographic output requests are generated
from a metric internal processing CRS.
"""
    p = argparse.ArgumentParser(description=PRM_DESCRIPTION, epilog=epilog, formatter_class=argparse.RawDescriptionHelpFormatter, allow_abbrev=False)
    p.add_argument("input", type=Path, nargs="+", help="One or more MonSX/SENSYS export folders (PRMs found recursively)")
    p.add_argument("-o", "--output", type=Path, default=Path("Magnetic_Result"), help="Output directory")
    p.add_argument("--site-name", help="Site/output prefix. Recommended for clean filenames, e.g. --site-name Priddy")

    g = p.add_argument_group("Grid and interpolation")
    g.add_argument("--cell-size", type=float, default=0.25, help="Grid cell size in metres. Default: 0.25")
    g.add_argument("--statistic", choices=("median", "mean"), default="median", help="Cell statistic used by the traditional binned grid. Default: median")
    g.add_argument("--grid-source", choices=("binned","points"), default="binned", help=argparse.SUPPRESS)
    g.add_argument("--point-method", choices=("track-surface","survey-local","track-balanced","idw","local-linear","nearest"), default="survey-local", help=argparse.SUPPRESS)
    g.add_argument("--point-neighbors", type=int, default=12, help=argparse.SUPPRESS)
    g.add_argument("--point-radius", type=float, default=0.75, metavar="METRES", help=argparse.SUPPRESS)
    g.add_argument("--point-power", type=float, default=2.0, help=argparse.SUPPRESS)
    g.add_argument("--track-along-step", type=float, default=0.0, metavar="METRES", help=argparse.SUPPRESS)
    g.add_argument("--track-cross-method", choices=("adaptive","linear","idw"), default="adaptive", help=argparse.SUPPRESS)
    g.add_argument("--track-cross-tracks", type=int, default=4, metavar="N", help=argparse.SUPPRESS)
    g.add_argument("--track-max-gap", type=float, default=1.25, metavar="METRES", help=argparse.SUPPRESS)
    g.add_argument("--track-edge-extrapolation", type=float, default=0.25, metavar="METRES", help=argparse.SUPPRESS)
    g.add_argument("--fill-distance", type=float, default=0.5, help="Maximum distance in metres from directly supported measured/binned cells over which missing raster cells may be filled. Default: 0.50 m. Smaller values preserve unsupported gaps but can leave holes; larger values improve continuity but can bridge genuinely unsurveyed ground. For dense archaeological multisensor surveys, begin around one to two physical track spacings. Directly measured/binned cells remain unchanged in gaps mode.")
    g.add_argument("--interpolation-mode", choices=("gaps","surface"), default="gaps", help="Interpolation mode. gaps (default) preserves directly measured/binned cells and fills only missing supported cells within --fill-distance. surface requests continuous supported-surface evaluation; the production Bz reference remains separate and the `process interpolate` stage creates the continuous archaeological surface. A 0.50 m cell size is a raster setting, not physical track thinning.")
    g.add_argument("--interpolation", action="append", default=None, metavar="METHOD[,METHOD...]", help="Interpolation method(s): fill, survey-local, tin-linear, tin-cubic, local-idw, nearest, idw, linear, cubic, biharmonic, natural-neighbor, barnes, spline/RBF/kriging, none. Default: fill. Local methods are usually safer for dense archaeology; spline/cubic/RBF candidates can overshoot strong anomalies and should be used deliberately rather than selected only for smooth appearance.")
    g.add_argument("--idw-power", type=float, default=2.0, help="IDW power. Default: 2")
    g.add_argument("--idw-neighbors", type=int, default=8, help="IDW neighbours. Default: 8")
    g.add_argument("--idw-radius", type=float, default=0.0, metavar="METRES", help="Optional IDW search radius; 0 uses --fill-distance")
    g.add_argument("--spline-smoothing", type=float, default=0.0, help="Spline/RBF smoothing regularization. Default: 0")
    g.add_argument("--spline-tension", type=float, default=0.65, metavar="0..1", help="Built-in spline tension; 0=bending, 1=membrane. Default: 0.65")
    g.add_argument("--spline-iterations", type=int, default=300, help="Maximum spline-tension iterations. Default: 300")
    g.add_argument("--spline-tolerance", type=float, default=1e-4, help="Spline-tension convergence tolerance. Default: 1e-4")
    g.add_argument("--rbf-smoothing", type=float, default=0.0, help="RBF smoothing. Default: 0")
    g.add_argument("--rbf-epsilon", type=float, default=1.0, help="RBF epsilon for multiquadric kernels. Default: 1")
    g.add_argument("--rbf-neighbors", type=int, default=32, help="Local RBF neighbours. Default: 32")
    g.add_argument("--kriging-neighbors", type=int, default=12, help="Local ordinary-kriging neighbours. Default: 12")
    g.add_argument("--kriging-range", type=float, default=2.0, metavar="METRES", help="Spherical variogram range. Default: 2 m")
