    g.add_argument("--no-export-points", action="store_true", help="Suppress point-CSV export in full archaeology; the ASC remains the authoritative point dataset.")
    g.add_argument("--stop-after-asc", action="store_true", help="Run acquisition decoding/QC and write the normalized ASC, then stop before raster gridding. Useful when field-data processing and raster enhancement are intentionally separate stages.")
    g.add_argument("--stop-after-thinning-qc", action="store_true", help="Run discovery, duplicate/overlap/acquisition geometry and physical thinning analysis, write thinning QC, then stop before PRM-to-ASC conversion. This is a diagnostic option and never changes source data.")

    t = p.add_argument_group("Global survey-track thinning")
    t.add_argument("--track-spacing", "--target-line-spacing", dest="track_spacing", type=float, default=0.0, metavar="METRES", help="Requested physical cross-line spacing between retained measured trajectories. MagSurveyPy uses stable swath-relative phase selection: one real sensor pattern is retained for each surviving swath, with no mid-swath parity switches or invented tracks. 0 disables thinning")
    t.add_argument("--prm-step", "--line-step", dest="prm_step", type=int, default=1, help="Keep every Nth PRM/swath before conversion. Primarily a diagnostic/downsampling control; it is NOT sensor-line thinning. Default: 1")
    t.add_argument("--thin-inputs", default="all", metavar="ALL|LIST", help="Input datasets receiving global track thinning: all, 1, 1,3, or folder names. Default: all")
    t.add_argument("--track-lattice-tolerance", type=float, default=0.0, metavar="METRES", help="Advanced maximum offset from a nominal target line when a new trajectory is first assigned. Continuity handovers are governed primarily by nearest real-track geometry. 0 uses the MagSurveyPy adaptive tolerance; recommended")
    t.add_argument("--thinning-policy", choices=("strict","warn","force"), default="warn", help="What to do when requested thinning fails local geometry QC. strict rejects thinning and keeps the unthinned primary ASC; warn applies it but reports warnings; force applies regardless. --full-archaeology defaults to strict unless explicitly overridden.")

    ov = p.add_argument_group("Swath overlap / duplicate-position correction")
