    gn.add_argument("--position-time-offset", type=float, default=0.0, metavar="SECONDS", help="Add this offset to PRM filename-derived UTC timestamps before matching a RINEX-derived PPK trajectory. Default: 0")
    gn.add_argument("--position-alignment", choices=("off","auto"), default="off", help="Magnetic-to-position alignment. off (default) uses the native SENSYS PRM block timing and GPS boundary fixes directly. auto is an advanced crossover experiment and is never applied unless explicitly requested.")
