    f = p.add_argument_group("Conservative archaeological processing")
    f.add_argument("--despike", type=float, default=0.0, metavar="MAD", help="Along-track Hampel despike threshold; 4 is conservative; 0 disables")
    f.add_argument("--despike-window", type=int, default=11, help="Odd Hampel window in samples. Default: 11")
    f.add_argument("--destripe", choices=("median", "linear", "none"), default="median", help="Per-PRM/per-sensor baseline correction. Default: median. --full-archaeology keeps median because it is the acquisition-level correction that preserves the stable result on multi-PRM surveys; use --destripe none explicitly for an untouched zero-level diagnostic")
    f.add_argument("--sensor-leveling", choices=("off","diagnostic","apply"), default="off", help="Legacy synchronized fixed inter-sensor bias diagnostic/apply mode. For final raster merging, the spatial --sensor-bias-correction diagnostic/auto mode is safer because laterally separated sensors do not observe identical geology at the same timestamp.")
    f.add_argument("--frame-heading", choices=("auto","swath","smooth","instantaneous"), default="smooth", help="Heading used to project physical probe offsets. smooth (default) uses a locally smoothed trajectory tangent and closely follows SENSYS DLMGPS probe allocation. auto, swath and instantaneous remain available for diagnostics or unusual geometries.")
