    f.add_argument("--sensor-bias-correction", choices=("off","diagnostic","auto","apply"), default="diagnostic", help="Spatial persistent sensor/channel bias estimation during raster analysis. diagnostic (default) reports the correction but leaves the quantitative reference unchanged; auto applies only if multi-scale spatial QC passes; apply forces the spatial correction. This is preferred over synchronized per-row leveling for laterally separated sensors.")
    f.add_argument("--vehicle-artifact", choices=("off","flag","auto","repair"), default="off", help="Detect short synchronized common-mode transients affecting most sensors, as can occur from towing vehicle/electronics. flag only reports; auto/repair replace only short high-confidence events before gridding. Broad or persistent common-mode anomalies are NEVER auto-repaired. Default: off")
    f.add_argument("--vehicle-z", type=float, default=8.0, metavar="SIGMA", help="Robust common-mode transient threshold. Default: 8 sigma")
