    f.add_argument("--vehicle-min-sensor-fraction", type=float, default=0.80, metavar="0..1", help="Minimum fraction of sensors showing a same-sign synchronous transient. Default: 0.80")
    f.add_argument("--low-pass", type=float, default=0.0, metavar="SIGMA_M", help="Manual Gaussian low-pass sigma in metres; 0 disables")
    f.add_argument("--smooth", type=float, default=0.0, metavar="SIGMA_M", help="Legacy alias for --low-pass")
    f.add_argument("--median-filter", type=float, default=0.0, metavar="WIDTH_M", help="Optional 2-D median width in metres; 0 disables")
    f.add_argument("--high-pass", type=float, default=0.0, metavar="SIGMA_M", help="Optional Gaussian broad-background subtraction; 0 disables")
    f.add_argument("--median-high-pass", type=float, default=0.0, metavar="WIDTH_M", help="Subtract a broad median background; 0 disables")
    f.add_argument("--fft-filter", choices=("none","butterworth-lowpass","butterworth-highpass","butterworth-bandpass","gaussian-lowpass","gaussian-highpass","gaussian-bandpass"), default="none", help="Optional padded 2-D FFT filter")
    f.add_argument("--fft-min-wavelength", "--fft-low-wavelength", dest="fft_min_wavelength", type=float, default=0.0, metavar="METRES", help="Shortest wavelength retained by FFT low/band-pass")
    f.add_argument("--fft-max-wavelength", "--fft-high-wavelength", dest="fft_max_wavelength", type=float, default=0.0, metavar="METRES", help="Longest wavelength retained by FFT high/band-pass")
    f.add_argument("--fft-order", type=int, default=4, help="Butterworth order. Default: 4")
    f.add_argument("--fft-padding", type=float, default=0.20, help="Reflect padding fraction for FFT filters and continuation. Default: 0.20")
    f.add_argument("--upward-continuation", default="", metavar="AUTO|HEIGHT[,HEIGHT...]", help="Generate upward-continued products at height(s) in metres")
    f.add_argument("--apply-upward-to-subtle", action="store_true", help="Use first/auto upward continuation for subtle analysis only")
    f.add_argument("--continuation-band", default="", metavar="H1,H2", help="Generate UC(H1)-UC(H2) band product")
    f.add_argument("--export-filter-removed", action="store_true", help="Export component removed by explicit filter stack")
    f.add_argument("--remove-plane", action="store_true", help="Subtract a first-order planar background")
    f.add_argument("--auto-noise", action="store_true", help="Measure power spectrum and select conservative low-pass/background scale automatically")
    f.add_argument("--auto-noise-max-sigma", type=float, default=0.35, help="Maximum automatic low-pass sigma in metres. Default: 0.35")
    f.add_argument("--auto-noise-min-sigma", type=float, default=0.08, help="Minimum non-zero automatic low-pass sigma. Default: 0.08")
    f.add_argument("--auto-noise-floor-factor", type=float, default=3.0, help="PSD/noise-floor ratio for spectral knee. Default: 3")
