# =============================================================================
# Unified MagSurveyPy command router
# =============================================================================

def _embedded_run(module_name, argv):
    """Compatibility hook used by the import/PRM wrappers to call the grid engine."""
    if module_name!='multimag_grid':
        raise RuntimeError(f'Unknown internal engine: {module_name}')
    old=sys.argv[:]
    try:
        sys.argv=[f'{Path(str(old[0]).split()[0]).name} grid',*list(argv)]
        return grid_main()
    finally:
        sys.argv=old



