def _print_command_help(command):
    if command=='rtk': command='gnss'
    if command=='point-grid':
        print('POINT-GRID — direct original-XYZ raster reconstruction\n\nThis command uses the normal grid engine with --grid-source points. It bypasses preliminary cell median/mean aggregation, so compact bipolar anomalies are reconstructed from the original measurement cloud. Recommended starting method: --point-method survey-local, --point-neighbors 8-12, --point-radius 0.5-0.75 m. Original ASC values remain unchanged.\n')
        command='grid'
    builders={'prm':prm_build_parser,'grid':grid_build_parser,'enhance':enhance_parser,'gnss':gnss_build_parser,
              'process':process_parser,'assemble':assemble_parser,'segment':segment_parser,'image':image_parser}
    if command in {'ai-corpus','ai-prepare','ai-train','ai-enhance'}:
        helps={
          'ai-corpus':'AI-CORPUS — list/init/fetch a curated CC-BY archaeological magnetometry web corpus. Fetch preserves per-site citation and licence metadata; it does not scrape arbitrary images.',
          'ai-prepare':'AI-PREPARE — convert clean/quantitative magnetic GeoTIFFs into patch pairs by applying realistic blur, track/stripe texture, background drift, correlated noise and spikes. Prefer site-level train/validation separation.',
          'ai-train':'AI-TRAIN — train MagRestoreLite, a residual correction network. Requires PyTorch. The model is constrained to restore rather than regenerate the map; checkpoints are interpretation-only.',
          'ai-enhance':'AI-ENHANCE — tiled inference from a trained checkpoint. Writes AI_restored, AI_correction and AI_uncertainty; never overwrites the measured or deterministic source raster.'}
        print(helps[command]+'\n\nRun the command without enough arguments to see argparse option details.')
        return
    if command in {'thin','overlap-clean','denoise','background','plough','reproject','surface-compare','denoise-adaptive','clean-map','regularize-points'}:
        print((_standalone_help_text(command) or '').strip())
        return
    if command in {'presentation','filter','total-field','bartington'}:
        fn={'presentation':_presentation_display,'filter':_manual_filter,'total-field':_total_field,'bartington':_bartington_fluxgate}[command]
        try:
            fn(['--help'])
        except SystemExit as exc:
            return int(exc.code or 0)
        return 0
    if command=='doctor':
        print('''DOCTOR — installation/dependency diagnostics
Usage:
  mspy doctor
  mspy doctor --help

Checks the Python runtime and classifies dependencies as REQUIRED, OPTIONAL or EXTERNAL.
Required: NumPy, SciPy, pyproj, rasterio, matplotlib, tqdm, scikit-image, Pillow, geopandas, shapely.
Optional: pandas, contextily, xyzservices, samgeo, threadpoolctl, metpy, torch.
External: RTKLIB rnx2rtkp, needed only for true PPK/static GNSS solving.

A missing optional package does not disable normal archaeological magnetic processing. A missing rnx2rtkp disables only workflows that explicitly require RTKLIB. Run doctor after creating/upgrading an environment and include its output when reporting installation problems.''')
        return
    if command=='auto':
        print('AUTO chooses `prm` when INPUT is a directory or .prm file; otherwise it chooses `process`.\n')
        print('Examples:\n  mspy auto Survey_Export/ -o Result --auto --cores 8\n  mspy auto survey.dat -o Result --auto\n')
        print('For all PRM options: mspy help prm')
        print('For ASCII/DAT import options: mspy help process')
        return
    if command not in builders: raise SystemExit(f'Unknown command for help: {command}')
    p=builders[command](); p.prog=f'{Path(sys.argv[0]).name} {command}'; p.print_help()


# =============================================================================
# OPTIONAL MAGNETOMETRY-SPECIFIC AI RESTORATION / SUPER-RESOLUTION
# =============================================================================

def _ai_seed_catalog_path():
    return Path(__file__).resolve().with_name('AI_WEB_DATASETS.csv')

def _ai_require_torch():
    try:
        import torch
        return torch
    except Exception as e:
        raise SystemExit('PyTorch is required for ai-train/ai-enhance. Install it in your environment, e.g. `pip install torch`, then run `mspy doctor`.') from e

def _ai_robust_norm(a):
    import numpy as np
    x=np.asarray(a,dtype=np.float32)
    m=np.isfinite(x)
    if not np.any(m): return x,0.0,1.0
    med=float(np.nanmedian(x[m])); mad=float(np.nanmedian(np.abs(x[m]-med)))
    sig=max(1.4826*mad,float(np.nanstd(x[m]))*0.15,1e-6)
    y=(x-med)/sig
    y=np.clip(y,-8,8).astype(np.float32)
    return y,med,sig

def _ai_degrade_patch(clean,rng):
    import numpy as np
    from scipy.ndimage import gaussian_filter
    x=np.asarray(clean,dtype=np.float32).copy()
    h,w=x.shape
    # blur / interpolation softness
    sig=float(rng.uniform(0.0,1.4))
    if sig>0.12: x=gaussian_filter(x,sig,mode='nearest')
    # broad geological/background drift
    yy,xx=np.mgrid[0:h,0:w].astype(np.float32)
    xx=(xx-(w-1)/2)/max(w,1); yy=(yy-(h-1)/2)/max(h,1)
    if rng.random()<0.85:
        a,b,c=rng.normal(0,[0.18,0.18,0.08])
        x=x+a*xx+b*yy+c*(xx*xx-yy*yy)
    # directional stripes / track texture
    if rng.random()<0.9:
        th=float(rng.uniform(0,np.pi)); wl=float(rng.uniform(5,36)); amp=float(rng.uniform(0.02,0.22))
        u=np.cos(th)*np.arange(w)[None,:]+np.sin(th)*np.arange(h)[:,None]
        phase=float(rng.uniform(0,2*np.pi))
        x=x+amp*np.sin((2*np.pi/wl)*u+phase).astype(np.float32)
        # occasional lane offsets
        if rng.random()<0.55:
            period=max(2,int(rng.integers(2,8)))
            offs=rng.normal(0,amp*0.6,size=(int(np.ceil(h/period)),1)).astype(np.float32)
            lane=np.repeat(offs,period,axis=0)[:h]
            x=x+lane
    # gaussian + correlated noise
    ns=float(rng.uniform(0.015,0.16)); x=x+rng.normal(0,ns,size=x.shape).astype(np.float32)
    if rng.random()<0.55:
        corr=gaussian_filter(rng.normal(0,1,size=x.shape).astype(np.float32),float(rng.uniform(0.7,2.2)))
        corr/=max(float(np.std(corr)),1e-6); x=x+corr*float(rng.uniform(0.01,0.08))
    # sparse spikes
    if rng.random()<0.65:
        n=int(rng.uniform(0.0003,0.003)*h*w)
        if n>0:
            iy=rng.integers(0,h,n); ix=rng.integers(0,w,n)
            x[iy,ix]+=rng.normal(0,1.2,n).astype(np.float32)
    return np.clip(x,-10,10).astype(np.float32)

def _ai_collect_rasters(inputs,product='clean_map'):
    out=[]
    for item in inputs:
        p=Path(item)
        if p.is_dir():
            try: r=_resolve_project_raster(p,product); out.append(r); continue
            except SystemExit: pass
            try: r=_resolve_project_raster(p,'Bz_grid'); out.append(r); continue
            except SystemExit: pass
            out.extend(sorted(p.rglob('*.tif'))+sorted(p.rglob('*.tiff')))
        elif p.is_file() and p.suffix.lower() in {'.tif','.tiff'}: out.append(p)
    # de-dup
    seen=set(); rr=[]
    for p in out:
        k=str(Path(p).resolve())
        if k not in seen: seen.add(k); rr.append(Path(p))
    return rr

def _ai_corpus(argv):
    import argparse,csv,json,urllib.request,shutil
    p=argparse.ArgumentParser(prog='magsurveypy.py ai-corpus',description='Curated openly licensed archaeological magnetometry web-corpus helper. No unlicensed scraping.')
    p.add_argument('action',choices=['list','init','fetch'])
    p.add_argument('-o','--output',default='AI_Corpus')
    p.add_argument('--ids',default='all',help='Comma-separated catalog IDs or all.')
    p.add_argument('--include-processed',action='store_true',help='Also fetch processed greyscale ZIPs when catalogued.')
    p.add_argument('--overwrite',action='store_true'); p.add_argument('--extract',action='store_true',help='Extract downloaded ZIP archives into each site folder.')
    a=p.parse_args(argv)
    cat=_ai_seed_catalog_path()
    if not cat.exists(): raise SystemExit(f'Missing seed catalog: {cat}')
    rows=list(csv.DictReader(cat.open(encoding='utf-8')))
    chosen=rows if a.ids=='all' else [r for r in rows if r['id'] in {x.strip() for x in a.ids.split(',')}]
    if a.action=='list':
        print(f'Curated web datasets ({len(rows)} total; all licences verified in catalog):')
        for r in rows: print(f"  {r['id']}: {r['title']} | {r['license']} | raw={r['raw_size']} | {r['doi']}")
        return 0
    od=Path(a.output); od.mkdir(parents=True,exist_ok=True); shutil.copy2(cat,od/'AI_WEB_DATASETS.csv')
    if a.action=='init':
        (od/'README.txt').write_text('Use `mspy ai-corpus fetch -o '+str(od)+' --ids all --include-processed` on an internet-connected machine. Always retain citation/license metadata.\n',encoding='utf-8')
        print(f'AI corpus workspace initialized: {od}'); return 0
    for r in chosen:
        sd=od/r['id']; sd.mkdir(parents=True,exist_ok=True)
        meta={k:v for k,v in r.items()}; (sd/'LICENSE_CITATION.json').write_text(json.dumps(meta,indent=2),encoding='utf-8')
        todo=[('raw_url','raw')]
        if a.include_processed: todo += [('processed_url','processed')]
        for key,label in todo:
            url=(r.get(key) or '').strip()
            if not url: continue
            fn=url.rsplit('/',1)[-1]; dest=sd/fn
            if dest.exists() and not a.overwrite: print(f'SKIP existing {dest}'); continue
            print(f'Downloading {r["id"]} {label}: {fn}',flush=True)
            try:
                req=urllib.request.Request(url,headers={'User-Agent':'Multimag-AI-Corpus/1.3 Alexandru-Hegyi'})
                with urllib.request.urlopen(req,timeout=120) as src, dest.open('wb') as dst: shutil.copyfileobj(src,dst,1024*1024)
            except Exception as e:
                print(f'WARNING: download failed for {url}: {e}'); continue
            if a.extract and dest.suffix.lower()=='.zip' and dest.exists():
                try:
                    import zipfile
                    with zipfile.ZipFile(dest) as zf: zf.extractall(sd/'extracted')
                    print(f'Extracted: {dest.name} -> {sd/"extracted"}')
                except Exception as e: print(f'WARNING: could not extract {dest}: {e}')
    print(f'Corpus fetch finished: {od}'); return 0

def _ai_prepare(argv):
    import argparse,csv,json
    import numpy as np
    import rasterio
    from tqdm import tqdm
    p=argparse.ArgumentParser(prog='magsurveypy.py ai-prepare',description='Create magnetometry restoration training pairs from quantitative/clean GeoTIFFs using realistic synthetic degradation.')
    p.add_argument('input',nargs='+')
    p.add_argument('-o','--output',required=True)
    p.add_argument('--source-product',default='clean_map')
    p.add_argument('--patch-size',type=int,default=192)
    p.add_argument('--stride',type=int,default=128)
    p.add_argument('--variants',type=int,default=3)
    p.add_argument('--min-valid',type=float,default=0.90)
    p.add_argument('--val-fraction',type=float,default=0.20)
    p.add_argument('--seed',type=int,default=42)
    p.add_argument('--max-patches-per-site',type=int,default=2000); p.add_argument('--target-class',choices=['quantitative','deterministic-clean','processed-greyscale'],default='deterministic-clean')
    a=p.parse_args(argv)
    rasters=_ai_collect_rasters(a.input,a.source_product)
    if not rasters: raise SystemExit('No training GeoTIFFs resolved. Supply TIFFs or project folders containing clean_map/Bz_grid.')
    od=Path(a.output); pd=od/'patches'; pd.mkdir(parents=True,exist_ok=True); rng=np.random.default_rng(a.seed)
    # site-level split: all rasters from one archaeological site stay together.
    def site_key(rp):
        q=Path(rp)
        for anc in [q.parent,*q.parents]:
            if anc.name.lower() in {'geotiff','extracted'} and anc.parent.name:
                return anc.parent.name
        return q.stem.split('_')[0] if '_' in q.stem else q.stem
    raster_sites=[site_key(r) for r in rasters]
    unique_sites=sorted(set(raster_sites)); perm=np.arange(len(unique_sites)); rng.shuffle(perm)
    nval=max(1,int(round(len(unique_sites)*a.val_fraction))) if len(unique_sites)>1 else 0
    val_sites={unique_sites[i] for i in perm[:nval]}
    rows=[]; total=0
    for si,rp in enumerate(rasters):
        sk=raster_sites[si]; split='val' if sk in val_sites else 'train'
        with rasterio.open(rp) as ds:
            arr=ds.read(1).astype(np.float32); nd=ds.nodata
            valid=np.isfinite(arr) & (arr!=nd if nd is not None else True)
        ps=a.patch_size; count=0
        for y in range(0,max(1,arr.shape[0]-ps+1),a.stride):
            for x in range(0,max(1,arr.shape[1]-ps+1),a.stride):
                if y+ps>arr.shape[0] or x+ps>arr.shape[1]: continue
                vv=valid[y:y+ps,x:x+ps]
                if float(vv.mean())<a.min_valid: continue
                clean=arr[y:y+ps,x:x+ps].copy(); clean[~vv]=np.nanmedian(clean[vv])
                clean,med,sig=_ai_robust_norm(clean)
                for vi in range(a.variants):
                    degraded=_ai_degrade_patch(clean,rng)
                    fn=f'{rp.stem}__y{y:05d}_x{x:05d}_v{vi:02d}.npz'
                    np.savez_compressed(pd/fn,clean=clean.astype(np.float32),degraded=degraded.astype(np.float32),median=np.float32(med),sigma=np.float32(sig))
                    rows.append({'file':fn,'split':split,'site':sk,'source':str(rp),'y':y,'x':x,'variant':vi})
                    total+=1
                count+=1
                if count>=a.max_patches_per_site: break
            if count>=a.max_patches_per_site: break
    if not rows: raise SystemExit('No patches passed --min-valid. Reduce min-valid or use a smaller patch size.')
    with (od/'manifest.csv').open('w',newline='',encoding='utf-8') as f:
        w=csv.DictWriter(f,fieldnames=rows[0].keys()); w.writeheader(); w.writerows(rows)
    report={'software_version':APP_VERSION,'rasters':[str(x) for x in rasters],'patches':total,'patch_size':a.patch_size,'stride':a.stride,'variants':a.variants,'split_policy':'site-level when >1 source; single-site dataset has no independent validation site','degradation':['blur','broad drift','directional stripes/lane offsets','gaussian/correlated noise','spikes'],'target_class':a.target_class,'scientific_policy':'targets are never overwritten; generated pairs are synthetic training data, not measurements'}
    (od/'dataset_report.json').write_text(json.dumps(report,indent=2),encoding='utf-8')
    print(f'AI training dataset prepared: {od} | patches={total} | train={sum(r["split"]=="train" for r in rows)} | val={sum(r["split"]=="val" for r in rows)}')
    return 0

def _ai_model(torch,channels=32,blocks=6):
    nn=torch.nn
    class ResidualBlock(nn.Module):
        def __init__(self,c):
            super().__init__(); self.net=nn.Sequential(nn.Conv2d(c,c,3,padding=1),nn.GELU(),nn.Conv2d(c,c,3,padding=1))
        def forward(self,x): return x+0.2*self.net(x)
    class MagRestoreLite(nn.Module):
        def __init__(self):
            super().__init__(); self.head=nn.Conv2d(1,channels,3,padding=1); self.body=nn.Sequential(*[ResidualBlock(channels) for _ in range(blocks)]); self.tail=nn.Conv2d(channels,1,3,padding=1)
        def forward(self,x):
            corr=self.tail(self.body(self.head(x)))
            return x+corr,corr
    return MagRestoreLite()

def _ai_train(argv):
    import argparse,csv,json,math,time
    import numpy as np
    torch=_ai_require_torch(); from torch.utils.data import Dataset,DataLoader
    p=argparse.ArgumentParser(prog='magsurveypy.py ai-train',description='Train MagRestoreLite: a residual archaeological-magnetometry restoration network.')
    p.add_argument('dataset'); p.add_argument('-o','--output',required=True)
    p.add_argument('--epochs',type=int,default=30); p.add_argument('--batch-size',type=int,default=8); p.add_argument('--lr',type=float,default=2e-4)
    p.add_argument('--channels',type=int,default=32); p.add_argument('--blocks',type=int,default=6); p.add_argument('--device',choices=['auto','cpu','cuda'],default='auto'); p.add_argument('--seed',type=int,default=42); p.add_argument('--workers',type=int,default=0)
    a=p.parse_args(argv); torch.manual_seed(a.seed); np.random.seed(a.seed)
    dd=Path(a.dataset); rows=list(csv.DictReader((dd/'manifest.csv').open(encoding='utf-8')))
    class Pairs(Dataset):
        def __init__(self,split): self.rows=[r for r in rows if r['split']==split] or ([r for r in rows] if split=='train' else [])
        def __len__(self): return len(self.rows)
        def __getitem__(self,i):
            z=np.load(dd/'patches'/self.rows[i]['file']); return torch.from_numpy(z['degraded'][None]),torch.from_numpy(z['clean'][None])
    tr=Pairs('train'); va=Pairs('val')
    if len(tr)==0: raise SystemExit('No training patches in manifest.csv')
    dev='cuda' if a.device=='auto' and torch.cuda.is_available() else ('cpu' if a.device=='auto' else a.device)
    if dev=='cuda' and not torch.cuda.is_available(): raise SystemExit('CUDA requested but unavailable.')
    model=_ai_model(torch,a.channels,a.blocks).to(dev); opt=torch.optim.AdamW(model.parameters(),lr=a.lr,weight_decay=1e-5)
    tl=DataLoader(tr,batch_size=a.batch_size,shuffle=True,num_workers=a.workers); vl=DataLoader(va,batch_size=a.batch_size,shuffle=False,num_workers=a.workers) if len(va) else None
    def grad(x): return torch.cat((x[:,:,:,1:]-x[:,:,:,:-1],x[:,:,1:,:]-x[:,:,:-1,:]),dim=-1) if False else None
    def loss_fn(pred,target,corr):
        l1=torch.nn.functional.smooth_l1_loss(pred,target,beta=0.25)
        gx1=pred[:,:,:,1:]-pred[:,:,:,:-1]; gx2=target[:,:,:,1:]-target[:,:,:,:-1]
        gy1=pred[:,:,1:,:]-pred[:,:,:-1,:]; gy2=target[:,:,1:,:]-target[:,:,:-1,:]
        edge=(gx1-gx2).abs().mean()+(gy1-gy2).abs().mean()
        amp=(torch.quantile(pred.flatten(1).abs(),0.95,dim=1)-torch.quantile(target.flatten(1).abs(),0.95,dim=1)).abs().mean()
        # low-weight correction penalty discourages hallucinated changes
        reg=corr.abs().mean()
        return l1+0.18*edge+0.08*amp+0.015*reg,{'l1':l1.item(),'edge':edge.item(),'amp':amp.item(),'reg':reg.item()}
    od=Path(a.output); od.mkdir(parents=True,exist_ok=True); hist=[]; best=float('inf'); t0=time.time()
    for ep in range(1,a.epochs+1):
        model.train(); ls=[]
        for xb,yb in tl:
            xb=xb.to(dev); yb=yb.to(dev); opt.zero_grad(set_to_none=True); pred,corr=model(xb); loss,_=loss_fn(pred,yb,corr); loss.backward(); torch.nn.utils.clip_grad_norm_(model.parameters(),1.0); opt.step(); ls.append(float(loss.item()))
        v=float('nan')
        if vl:
            model.eval(); vv=[]
            with torch.no_grad():
                for xb,yb in vl:
                    pred,corr=model(xb.to(dev)); loss,_=loss_fn(pred,yb.to(dev),corr); vv.append(float(loss.item()))
            v=float(np.mean(vv)) if vv else float('nan')
        score=v if np.isfinite(v) else float(np.mean(ls)); hist.append({'epoch':ep,'train_loss':float(np.mean(ls)),'val_loss':v})
        print(f'AI train epoch {ep}/{a.epochs}: train={np.mean(ls):.5f} val={v:.5f}',flush=True)
        ck={'version':APP_VERSION,'model':'MagRestoreLite','channels':a.channels,'blocks':a.blocks,'state_dict':model.state_dict(),'epoch':ep,'scientific_status':'AI_RESTORATION_INTERPRETATION_ONLY'}
        torch.save(ck,od/'last.pt')
        if score<best: best=score; torch.save(ck,od/'best.pt')
    (od/'training_history.json').write_text(json.dumps({'software_version':APP_VERSION,'device':dev,'dataset':str(dd),'epochs':a.epochs,'best_loss':best,'seconds':time.time()-t0,'history':hist,'policy':'Residual model; outputs are derived interpretation products and must not replace measured Bz.'},indent=2),encoding='utf-8')
    print(f'Training complete: {od}/best.pt'); return 0

def _ai_enhance(argv):
    import argparse,json
    import numpy as np
    import rasterio
    from rasterio.transform import Affine
    import matplotlib.pyplot as plt
    torch=_ai_require_torch()
    p=argparse.ArgumentParser(prog='magsurveypy.py ai-enhance',description='Apply a trained MagRestore model to a magnetic GeoTIFF/project with tiled inference and uncertainty.')
    p.add_argument('input'); p.add_argument('-o','--output',required=True); p.add_argument('--model',required=True); p.add_argument('--source-product',default='clean_map'); p.add_argument('--strength',type=float,default=0.75); p.add_argument('--tile-size',type=int,default=256); p.add_argument('--overlap',type=int,default=32); p.add_argument('--device',choices=['auto','cpu','cuda'],default='auto')
    a=p.parse_args(argv); source=_resolve_project_raster(a.input,a.source_product); od=Path(a.output); (od/'GeoTIFF').mkdir(parents=True,exist_ok=True); (od/'PNG').mkdir(exist_ok=True); (od/'Reports').mkdir(exist_ok=True)
    dev='cuda' if a.device=='auto' and torch.cuda.is_available() else ('cpu' if a.device=='auto' else a.device)
    ck=torch.load(a.model,map_location=dev,weights_only=False); model=_ai_model(torch,int(ck.get('channels',32)),int(ck.get('blocks',6))).to(dev); model.load_state_dict(ck['state_dict']); model.eval()
    with rasterio.open(source) as ds: arr=ds.read(1).astype(np.float32); profile=ds.profile.copy(); nd=ds.nodata
    valid=np.isfinite(arr) & ((arr!=nd) if nd is not None else True); fill=float(np.nanmedian(arr[valid])); work=arr.copy(); work[~valid]=fill; norm,med,sig=_ai_robust_norm(work)
    h,w=norm.shape; ts=max(64,a.tile_size); ov=max(0,min(a.overlap,ts//3)); step=max(16,ts-2*ov); acc=np.zeros((h,w),np.float32); wt=np.zeros((h,w),np.float32); sq=np.zeros((h,w),np.float32)
    # TTA transforms give a practical epistemic/stability proxy
    tforms=[lambda x:x,lambda x:torch.flip(x,[-1]),lambda x:torch.flip(x,[-2])]
    invs=[lambda x:x,lambda x:torch.flip(x,[-1]),lambda x:torch.flip(x,[-2])]
    ys=list(range(0,max(1,h-ts+1),step)); xs=list(range(0,max(1,w-ts+1),step));
    if not ys or ys[-1]!=max(0,h-ts): ys.append(max(0,h-ts))
    if not xs or xs[-1]!=max(0,w-ts): xs.append(max(0,w-ts))
    with torch.no_grad():
        for y in ys:
            for x in xs:
                patch=norm[y:min(y+ts,h),x:min(x+ts,w)]; ph,pw=patch.shape
                inp=torch.from_numpy(patch[None,None]).to(dev); preds=[]
                for tf,iv in zip(tforms,invs):
                    pr,_=model(tf(inp)); preds.append(iv(pr))
                st=torch.stack(preds); mean=st.mean(0)[0,0].cpu().numpy(); var=st.var(0,unbiased=False)[0,0].cpu().numpy()
                win=np.ones((ph,pw),np.float32)
                acc[y:y+ph,x:x+pw]+=mean*win; sq[y:y+ph,x:x+pw]+=var*win; wt[y:y+ph,x:x+pw]+=win
    pred=acc/np.maximum(wt,1e-6); unc=np.sqrt(sq/np.maximum(wt,1e-6)); strength=float(np.clip(a.strength,0,1)); restored_norm=norm+strength*(pred-norm); restored=restored_norm*sig+med; correction=restored-work; uncertainty=unc*sig
    restored[~valid]=np.nan; correction[~valid]=np.nan; uncertainty[~valid]=np.nan
    prefix=source.stem.replace('_clean_map','').replace('_Bz_grid','')
    def write(name,data,product):
        pp=profile.copy(); pp.update(dtype='float32',count=1,nodata=np.nan,compress='deflate')
        fp=od/'GeoTIFF'/f'{prefix}_{name}.tif'
        with rasterio.open(fp,'w',**pp) as dst: dst.write(data.astype(np.float32),1); dst.update_tags(software=APP_VERSION,author=APP_AUTHOR,product=product,source=str(source),model=str(a.model),scientific_status='AI_DERIVED_INTERPRETATION_ONLY')
        return fp
    rp=write('AI_restored',restored,'magnetometry-specific AI restored display/interpretation raster'); cp=write('AI_correction',correction,'AI-added/removed correction audit'); up=write('AI_uncertainty',uncertainty,'TTA prediction variability / uncertainty proxy')
    vals=work[valid]; lim=float(np.nanpercentile(np.abs(vals-np.nanmedian(vals)),98)); lim=max(lim,1e-6)
    fig,axs=plt.subplots(1,4,figsize=(16,5),constrained_layout=True)
    for ax,dat,title in zip(axs,[work,restored,correction,uncertainty],['Input','AI restored','AI correction','Uncertainty']):
        if title=='Uncertainty': im=ax.imshow(dat,cmap='gray_r')
        else: im=ax.imshow(dat,cmap='gray_r',vmin=-lim if title!='AI correction' else -lim*0.5,vmax=lim if title!='AI correction' else lim*0.5)
        ax.set_title(title); ax.set_axis_off()
    fig.savefig(od/'PNG'/f'{prefix}_AI_comparison.png',dpi=180); plt.close(fig)
    rep={'software_version':APP_VERSION,'source':str(source),'model':str(a.model),'strength':strength,'outputs':[str(rp),str(cp),str(up)],'scientific_status':'AI-derived interpretation only; original magnetic raster is unchanged','warning':'AI restoration can hallucinate/sharpen unsupported structure. Always inspect AI_correction and AI_uncertainty against the native Bz.'}
    (od/'Reports'/f'{prefix}_AI_report.json').write_text(json.dumps(rep,indent=2),encoding='utf-8')
    print(f'AI restored raster: {rp}\nAudit correction: {cp}\nUncertainty: {up}\nOriginal source was not overwritten.'); return 0


