def _archaeomag_read_raster(input_path, source_product='Bz_grid'):
    """Resolve and read one quantitative/derived raster with NoData as NaN."""
    import rasterio
    source=_resolve_project_raster(Path(input_path),source_product)
    with rasterio.open(source) as ds:
        arr=ds.read(1).astype(float)
        nod=ds.nodata
        if nod is not None:
            arr[arr==nod]=np.nan
        return source,arr,ds.transform,(str(ds.crs) if ds.crs else 'local'),ds.profile.copy()


def _archaeomag_write_like(path, data, transform, crs, tags, label):
    return write_geotiff(Path(path),np.asarray(data,float),transform,crs,tags,label,source_orientation='north-up')


def _remove_small_binary_components(mask, min_cells):
    if min_cells<=1: return np.asarray(mask,bool)
    from scipy.ndimage import label
    lab,n=label(np.asarray(mask,bool))
    if n==0: return np.asarray(mask,bool)
    cnt=np.bincount(lab.ravel())
    keep=cnt>=int(min_cells); keep[0]=False
    return keep[lab]


def _presentation_display(argv):
    """Create a quiet-context archaeological presentation magnetogram.

    The magnetic-unit presentation field is a derived interpretation product,
    while the normalized display raster is explicitly unitless. Neither
    overwrites or replaces the quantitative source.
    """
    import argparse, json
    import numpy as np
    import matplotlib.pyplot as plt
    from scipy.ndimage import gaussian_filter
    p=argparse.ArgumentParser(prog='magsurveypy.py presentation',formatter_class=argparse.RawDescriptionHelpFormatter,
      description="""Create a publication/interpretation magnetogram with a genuinely quiet magnetic context and progressively emphasized anomalies.

Unlike a hard threshold/clip image, this command first constructs a smoothed low-amplitude LOCAL magnetic context, then blends the original cleaned residual back according to continuous anomaly significance and spatial coherence. Strong anomalies are emphasized without replacing the entire background by a binary mask. The magnetic-unit presentation field is not hard-clipped. Optional asinh/sigmoid contrast is written separately as a unitless DISPLAY raster.

Recommended order:
  quantitative Bz -> regularized network (optional) -> clean-map -> presentation

The input is never overwritten. Use the quantitative/cleaned raster for measurements; use presentation products for visual interpretation and figures.""")
    p.add_argument('input',type=Path,help='GeoTIFF or project/stage folder containing the source raster.')
    p.add_argument('-o','--output',type=Path,required=True,help='Output stage. With project routing, -o Site_PRESENTATION becomes Results/Site/PRESENTATION/.')
    p.add_argument('--site-name',default=None,help='Optional output prefix; normally inferred from the source.')
    p.add_argument('--source-product',default='clean_map',help='Logical source product. Default: clean_map. Bz_grid is allowed but deterministic cleaning is recommended first.')
    p.add_argument('--mode',choices=('natural','publication','anomaly-emphasis','flat'),default='publication',help='natural retains more low-amplitude context; publication is the recommended balanced figure; anomaly-emphasis strongly subdues weak texture; flat approaches a neutral background while retaining a small coherent context.')
    p.add_argument('--threshold-mode',choices=('robust-z','absolute','percentile'),default='robust-z',help='How anomaly significance starts. robust-z is portable between sites; absolute uses magnetic units; percentile uses the absolute residual percentile.')
    p.add_argument('--threshold',type=float,default=1.3,help='Start of anomaly emphasis. robust-z default 1.3 sigma. Values below this remain mainly in the quiet context.')
    p.add_argument('--full-threshold',type=float,default=2.8,help='Significance where the full cleaned residual is restored. Default 2.8 robust sigma. Must exceed --threshold in robust-z/absolute modes.')
    p.add_argument('--background-scale',type=float,default=8.0,metavar='METRES',help='Broad regional/background scale. Default 8 m. It is estimated for decomposition but only a restrained fraction is retained in the presentation context.')
    p.add_argument('--context-smooth',type=float,default=0.45,metavar='METRES',help='Smoothing scale of the low-amplitude local magnetic context. Default 0.45 m. Larger values make the background quieter; too large can blur weak archaeology.')
    p.add_argument('--context-gain',type=float,default=None,metavar='0..1',help='Amplitude of the quiet local magnetic context. Mode defaults: natural 0.55, publication 0.32, anomaly-emphasis 0.14, flat 0.05. Increase to retain more background texture.')
    p.add_argument('--regional-gain',type=float,default=0.03,metavar='0..1',help='Small fraction of broad regional background retained for spatial context. Default 0.03. Set 0 for a completely leveled presentation background.')
    p.add_argument('--coherence-scale',type=float,default=0.50,metavar='METRES',help='Spatial scale used to down-weight isolated single-cell responses while favouring coherent anomalies. Default 0.50 m. Set 0 to disable.')
    p.add_argument('--softness',type=float,default=0.35,metavar='0..1',help='Blend softness. Default 0.35. Larger gives a gentler transition between context and full anomaly; smaller makes anomaly emphasis more selective.')
    p.add_argument('--polarity',choices=('both','positive','negative'),default='both',help='Polarity used for significance. Default both; normally recommended for archaeological magnetic data.')
    p.add_argument('--min-area',type=float,default=0.0,metavar='M2',help='Optional minimum coherent anomaly-seed area. 0 disables. Use cautiously because genuine small pits/fired features may be compact.')
    p.add_argument('--contrast-mode',choices=('linear','asinh','sigmoid'),default='asinh',help='Contrast transform for the UNIT-LESS display raster/PNG only. Default asinh preserves weak anomalies while compressing extreme dipoles. The magnetic-unit presentation field is not transformed.')
    p.add_argument('--display-range',type=float,default=0.0,metavar='MAGNETIC_UNITS',help='Symmetric magnetic range mapped to near-full black/white in the display product. 0=robust automatic range. This controls visualization only; it does not clip the magnetic-unit presentation field.')
    p.add_argument('--asinh-width',type=float,default=0.0,metavar='MAGNETIC_UNITS',help='Asinh transition width. 0=automatic from robust sigma. Larger is more linear; smaller compresses strong anomalies more strongly.')
    # Compatibility aliases are intentionally hidden from public help.
    p.add_argument('--background-opacity',type=float,dest='context_gain',help=argparse.SUPPRESS)
    p.add_argument('--clip-sigma',type=float,default=0.0,help=argparse.SUPPRESS)
    p.add_argument('--cores',type=int,default=0)
    a=p.parse_args(argv)
    if a.background_scale<=0 or a.context_smooth<0 or a.coherence_scale<0 or not 0<=a.regional_gain<=1 or not 0<=a.softness<=1:
        raise SystemExit('Invalid presentation scale/gain/softness setting.')
    if a.context_gain is not None and not 0<=a.context_gain<=1:
        raise SystemExit('--context-gain must be in 0..1.')
    source,ref,transform,crs,profile=_archaeomag_read_raster(a.input,a.source_product)
    configure_runtime_cores(a.cores)
    valid=np.isfinite(ref)
    if valid.sum()<16: raise SystemExit('Too few valid cells for presentation processing.')
    cs=float(abs(transform.a)); prefix=_site_slug_from_source(source,a.site_name)
    root=Path(a.output); gd=root/'GeoTIFF'; pd=_native_png_dirs(root)['products']; rd=root/'Reports'
    for d in (gd,rd): d.mkdir(parents=True,exist_ok=True)

    bgargs=argparse.Namespace(regional_method='robust-gaussian',subtle_background_scale=float(a.background_scale),cell_size=cs,regional_iterations=4,regional_tuning=2.7)
    with stage_progress(f'Presentation: robust regional decomposition ({a.background_scale:g} m)'):
        regional=robust_regional_background(ref,bgargs)
    residual=ref-regional; residual[~valid]=np.nan
    sig=max(grid_robust_scale(residual[valid]),1e-12)

    if a.context_smooth>0:
        context_local=nan_gaussian(residual,max(a.context_smooth/cs,0.01))
    else:
        context_local=residual.copy()
    reg_center=float(np.nanmedian(regional[valid]))
    regional_centered=regional-reg_center

    gains={'natural':0.55,'publication':0.32,'anomaly-emphasis':0.14,'flat':0.05}
    context_gain=float(gains[a.mode] if a.context_gain is None else a.context_gain)
    quiet_context=context_gain*context_local + float(a.regional_gain)*regional_centered
    quiet_context[~valid]=np.nan

    absres=np.abs(residual)
    if a.polarity=='positive': significance_base=np.maximum(residual,0.0)
    elif a.polarity=='negative': significance_base=np.maximum(-residual,0.0)
    else: significance_base=absres

    if a.threshold_mode=='robust-z':
        start=float(a.threshold)*sig; full=float(a.full_threshold)*sig
    elif a.threshold_mode=='absolute':
        start=float(a.threshold); full=float(a.full_threshold)
    else:
        if not 0<a.threshold<100: raise SystemExit('--threshold percentile must be between 0 and 100.')
        start=float(np.nanpercentile(significance_base[valid],a.threshold))
        fp=float(a.full_threshold)
        full=float(np.nanpercentile(significance_base[valid],fp if 0<fp<100 else min(99.5,max(a.threshold+5,97.0))))
    if start<0 or full<=start:
        raise SystemExit('--full-threshold must be greater than --threshold after conversion to magnetic units.')

    t=np.clip((significance_base-start)/max(full-start,1e-12),0.0,1.0)
    w=t*t*(3.0-2.0*t)
    softness=float(a.softness)
    if softness>0:
        mid=(significance_base-(start+full)/2.0)/max((full-start)*(0.18+0.55*softness),1e-12)
        wl=1.0/(1.0+np.exp(-np.clip(mid,-30,30)))
        wl=np.where(significance_base<=start,0.0,np.where(significance_base>=full,1.0,wl))
        w=(1-softness)*w+softness*wl

    if a.coherence_scale>0:
        sigma_px=max(a.coherence_scale/cs,0.01)
        ws=gaussian_filter(np.where(valid,w,0.0),sigma=sigma_px,mode='nearest')
        den=gaussian_filter(valid.astype(float),sigma=sigma_px,mode='nearest')
        wsn=np.zeros_like(ws,dtype=float)
        np.divide(ws,den,out=wsn,where=den>1e-6)
        w=w*(0.30+0.70*np.clip(wsn,0,1))

    hard=valid & (significance_base>=start)
    if a.min_area>0:
        hard=_remove_small_binary_components(hard,max(1,int(round(a.min_area/(cs*cs)))))
        w=np.where(hard,w,0.0)
    w[~valid]=0.0

    presentation=np.where(valid,quiet_context + w*(residual-quiet_context),np.nan)
    anomaly_emphasis=np.where(valid,w*residual,np.nan)

    finite=presentation[valid]
    auto_range=max(float(np.nanpercentile(np.abs(finite-np.nanmedian(finite)),99.0)),2.5*sig,1e-9)
    disp_range=float(a.display_range) if a.display_range>0 else auto_range
    width=float(a.asinh_width) if a.asinh_width>0 else max(0.70*sig,0.12*disp_range,1e-9)
    x=presentation/max(disp_range,1e-12)
    if a.contrast_mode=='linear':
        display=np.tanh(x*1.25)
    elif a.contrast_mode=='sigmoid':
        display=np.tanh(x*1.8)
    else:
        display=np.arcsinh(presentation/width)/max(np.arcsinh(disp_range/width),1e-12)
        display=np.tanh(display)/np.tanh(1.0)
    display=np.where(valid,np.clip(display,-1.0,1.0),np.nan)

    tags={'author':AUTHOR,'website':WEBSITE,'software':APP_NAME,'version':APP_VERSION,'source':str(source),'product':'DISPLAY/INTERPRETATION presentation magnetic field','mode':a.mode,'threshold_mode':a.threshold_mode,'threshold_start_magnetic_units':start,'threshold_full_magnetic_units':full,'context_gain':context_gain,'regional_gain':a.regional_gain,'warning':'Derived interpretation product. Quantitative source remains unchanged.'}
    fieldp=gd/f'{prefix}_presentation_field.tif'
    dispp=gd/f'{prefix}_presentation_display.tif'
    anop=gd/f'{prefix}_anomaly_emphasis.tif'
    ctxp=gd/f'{prefix}_context_background.tif'
    wp=gd/f'{prefix}_significance_weight.tif'
    _archaeomag_write_like(fieldp,presentation,transform,crs,tags,magnetic_label('Presentation magnetic field'))
    _archaeomag_write_like(dispp,display,transform,crs,{**tags,'product':'DISPLAY_ONLY normalized contrast intensity','contrast_mode':a.contrast_mode,'display_range_magnetic_units':disp_range,'units':'unitless [-1,1]'},'Display intensity [-1..1]')
    _archaeomag_write_like(anop,anomaly_emphasis,transform,crs,{**tags,'product':'DISPLAY/INTERPRETATION significance-weighted anomaly component'},magnetic_label('Anomaly emphasis'))
    _archaeomag_write_like(ctxp,quiet_context,transform,crs,{**tags,'product':'DISPLAY/INTERPRETATION quiet local magnetic context'},magnetic_label('Quiet magnetic context'))
    _archaeomag_write_like(wp,np.where(valid,w,np.nan),transform,crs,{**tags,'product':'anomaly significance/coherence weight','units':'0..1'},'Significance weight [0..1]')

    fig,axs=plt.subplots(1,4,figsize=(16,5),constrained_layout=True)
    lim=max(float(np.nanpercentile(np.abs(residual[valid]),98.5)),2*sig)
    for ax,dat,title,vmin,vmax in [
        (axs[0],ref,'Source',-lim,lim),
        (axs[1],quiet_context,'Quiet magnetic context',-lim,lim),
        (axs[2],presentation,'Presentation field',-lim,lim),
        (axs[3],display,'Display contrast',-1,1)]:
        ax.imshow(dat,origin='upper',cmap='gray_r',vmin=vmin,vmax=vmax); ax.set_title(title); ax.set_axis_off()
    import matplotlib.cm as cm
    from matplotlib.colors import Normalize
    sm=cm.ScalarMappable(norm=Normalize(vmin=-lim,vmax=lim),cmap='gray_r'); sm.set_array([])
    cb=fig.colorbar(sm,ax=list(axs[:3]),orientation='horizontal',fraction=.050,pad=.055,aspect=45); cb.set_label('Magnetic value (nT/m) — shared scale for first three panels')
    fig.savefig(pd/f'{prefix}_presentation_comparison.png',dpi=220,bbox_inches='tight'); plt.close(fig)

    rep={'software_version':APP_VERSION,'application':APP_NAME,'source':str(source),'cell_size_m':cs,'mode':a.mode,'threshold_mode':a.threshold_mode,'threshold_start_input':a.threshold,'threshold_start_magnetic_units':start,'threshold_full_magnetic_units':full,'robust_sigma':sig,'background_scale_m':a.background_scale,'context_smooth_m':a.context_smooth,'context_gain':context_gain,'regional_gain':a.regional_gain,'coherence_scale_m':a.coherence_scale,'softness':a.softness,'polarity':a.polarity,'contrast_mode':a.contrast_mode,'display_range_magnetic_units':disp_range,'context_std':float(np.nanstd(quiet_context[valid])),'presentation_std':float(np.nanstd(presentation[valid])),'mean_significance_weight':float(np.nanmean(w[valid])),'fraction_weight_gt_0p5':float(np.mean(w[valid]>0.5)),'products':{'presentation_field':str(fieldp),'presentation_display':str(dispp),'anomaly_emphasis':str(anop),'context_background':str(ctxp),'significance_weight':str(wp)},'scientific_status':'DISPLAY/INTERPRETATION PRODUCT. Quantitative source raster is unchanged.'}
    (rd/f'{prefix}_presentation_report.json').write_text(json.dumps(rep,indent=2),encoding='utf-8')
    print(f'Presentation magnetic field: {fieldp}\nDisplay contrast raster: {dispp}\nQuiet magnetic context: {ctxp}\nOriginal source was not overwritten.',flush=True)
    return 0

def _manual_filter(argv):
    """Explicit one-output manual filter stack for experienced users."""
    import argparse,json
    import matplotlib.pyplot as plt
    from scipy.ndimage import median_filter
    p=argparse.ArgumentParser(prog='magsurveypy.py filter',formatter_class=argparse.RawDescriptionHelpFormatter,
      description='''Apply an explicit, auditable magnetic filter stack to one raster. The command writes the final filtered raster, the total removed component, one comparison PNG and a JSON report rather than flooding the project with derivatives.

Recommended archaeological uses:
  Gaussian low-pass       suppress sub-cell/high-frequency noise; can blur small pits/walls.
  Gaussian high-pass      remove broad geology/regional drift; can remove broad archaeological features.
  FFT Butterworth band    retain a controlled wavelength band; useful for scale-specific interpretation.
  Median low/high-pass    robust against spikes but can alter compact anomaly shape.
  Upward continuation     physically meaningful potential-field smoothing of shallow/high-frequency sources.
  Plane removal           remove broad linear regional slope.
  Directional notch       suppress repetitive long stripes at a known direction; always inspect the removed component.

Every option changes a derived product only; the input raster is never overwritten.''')
    p.add_argument('input',nargs='?',type=Path,help='Input quantitative raster or project/stage folder.')
    p.add_argument('--input',dest='input_option',type=Path,default=None,help='Explicit alternative to the positional input path. Both forms use the same raster-filter engine.')
    p.add_argument('-o','--output',type=Path,default=None,help='Output directory. In project mode this defaults to Results/FILTER_RASTER.'); p.add_argument('--site-name',default=None); p.add_argument('--source-product',default='Bz_grid')
    p.add_argument('--low-pass',type=float,default=0.0,metavar='METRES',help='Gaussian smoothing sigma in metres. 0 off. Typical dense archaeology 0.10-0.50 m. Larger removes more fine detail.')
    p.add_argument('--high-pass',type=float,default=0.0,metavar='METRES',help='Subtract a Gaussian background with this sigma. 0 off. Typical local archaeology 2-10 m. Smaller removes increasingly broad archaeological signal.')
    p.add_argument('--median-low-pass',type=float,default=0.0,metavar='METRES',help='Median window width in metres. 0 off. Useful for spikes/ferrous speckle, but can reshape compact anomalies.')
    p.add_argument('--median-high-pass',type=float,default=0.0,metavar='METRES',help='Subtract a median background of this width. 0 off. Robust regional removal; use cautiously on broad structures.')
    p.add_argument('--fft-filter',choices=('none','butterworth-lowpass','butterworth-highpass','butterworth-bandpass','gaussian-lowpass','gaussian-highpass','gaussian-bandpass'),default='none')
    p.add_argument('--fft-min-wavelength',type=float,default=0.0,metavar='METRES',help='Shortest wavelength retained by FFT low/band-pass. Must exceed about two cells.')
    p.add_argument('--fft-max-wavelength',type=float,default=0.0,metavar='METRES',help='Longest wavelength retained by FFT high/band-pass.')
    p.add_argument('--fft-order',type=int,default=4,help='Butterworth roll-off order. Higher is sharper but can ring; default 4.')
    p.add_argument('--fft-padding',type=float,default=0.20,help='Reflection padding fraction for FFT filters. Default 0.20 reduces edge ringing.')
    p.add_argument('--upward-continuation',type=float,default=0.0,metavar='METRES',help='Potential-field upward continuation height. 0 off. 0.1-0.5 m can suppress shallow clutter while retaining deeper coherent anomalies.')
    p.add_argument('--remove-plane',action='store_true',help='Least-squares planar trend removal. Useful for broad field slope; can remove real very broad archaeology.')
    p.add_argument('--directional-notch',action='store_true',help='Apply a long-stripe directional notch using --stripe-angle/--stripe-strength. Interpretation filter only.')
    p.add_argument('--stripe-angle',type=float,default=float('nan'),metavar='DEG',help='Stripe direction from East, 0-180. Required with --directional-notch unless --stripe-auto is used.')
    p.add_argument('--stripe-auto',action='store_true',help='Estimate dominant directional stripe orientation from the spectrum.')
    p.add_argument('--stripe-strength',type=float,default=0.55,metavar='0..1')
    p.add_argument('--stripe-min-wavelength',type=float,default=0.5,metavar='METRES'); p.add_argument('--stripe-max-wavelength',type=float,default=3.5,metavar='METRES')
    p.add_argument('--export-steps',action='store_true',help='Also write each intermediate filter step. Default writes only final + total removed.')
    p.add_argument('--cores',type=int,default=0)
    a=p.parse_args(argv)
    if a.input is not None and a.input_option is not None:
        raise SystemExit('Provide the raster source either positionally or with --input, not both.')
    a.input=a.input_option if a.input_option is not None else a.input
    if a.input is None:
        raise SystemExit('A raster source is required. Provide INPUT or --input INPUT.')
    if a.output is None:
        raise SystemExit('An output directory is required outside project mode. Add -o OUTPUT, or use --project PROJECT for automatic Results/FILTER_RASTER routing.')
    source,ref,transform,crs,profile=_archaeomag_read_raster(a.input,a.source_product); configure_runtime_cores(a.cores)
    source_unit=_raster_magnetic_unit(source)
    valid=np.isfinite(ref); cs=float(abs(transform.a)); prefix=_site_slug_from_source(source,a.site_name)
    root=Path(a.output); gd=root/'GeoTIFF'; pd=_native_png_dirs(root)['comparison']; rd=root/'Reports'; [d.mkdir(parents=True,exist_ok=True) for d in (gd,rd)]
    out=ref.copy(); steps=[]
    def save_step(label,data):
        steps.append(label)
        if a.export_steps: _archaeomag_write_like(gd/f'{prefix}_filter_{len(steps):02d}_{label}.tif',data,transform,crs,{'software':APP_NAME,'version':APP_VERSION,'source':str(source),'product':f'intermediate filter step {label}'},magnetic_label(label))
    if a.median_low_pass>0:
        out=nan_median(out,_odd_pixels(a.median_low_pass,cs)); save_step('median_lowpass',out)
    if a.low_pass>0:
        out=nan_gaussian(out,a.low_pass/cs); save_step('gaussian_lowpass',out)
    if a.fft_filter!='none':
        out=fft_filter_grid(out,cs,a.fft_filter,a.fft_min_wavelength,a.fft_max_wavelength,a.fft_order,a.fft_padding); save_step(a.fft_filter.replace('-','_'),out)
    if a.remove_plane:
        ny,nx=out.shape; xs=transform.c+(np.arange(nx)+0.5)*transform.a; ys=transform.f+(np.arange(ny)+0.5)*transform.e
        out=remove_plane(out,xs,ys); save_step('plane_removed',out)
    if a.high_pass>0:
        out=out-nan_gaussian(out,a.high_pass/cs); save_step('gaussian_highpass',out)
    if a.median_high_pass>0:
        out=out-nan_median(out,_odd_pixels(a.median_high_pass,cs)); save_step('median_highpass',out)
    if a.upward_continuation>0:
        out=upward_continue_grid(out,cs,a.upward_continuation,a.fft_padding); save_step('upward_continuation',out)
    stripe_info=None
    if a.directional_notch:
        angle=float(a.stripe_angle)
        if a.stripe_auto:
            # Reuse the same tested spectral diagnostic used by the archaeological
            # cleaning workflow.  Manual raster filtering exposes only the
            # orientation estimate, so use its standard diagnostic thresholds.
            auto_args=argparse.Namespace(
                auto_noise_floor_factor=3.0,
                auto_noise_min_sigma=0.08,
                auto_noise_max_sigma=0.35,
                stripe_anisotropy_threshold=2.5,
            )
            ana=analyse_noise_spectrum(out,cs,auto_args)
            angle=float(ana.get('stripe_orientation_deg',float('nan')))
        if not np.isfinite(angle): raise SystemExit('Directional notch requires --stripe-angle DEG or --stripe-auto.')
        out,rem,stripe_info=_v123_fast_directional_stripe(out,cs,angle,a.stripe_strength,background_scale_m=max(a.high_pass,3.0),cross_min_m=a.stripe_min_wavelength,cross_max_m=a.stripe_max_wavelength); save_step('directional_notch',out)
    out[~valid]=np.nan; removed=ref-out; removed[~valid]=np.nan
    final=gd/f'{prefix}_filtered.tif'; remp=gd/f'{prefix}_filter_removed_total.tif'
    tags={'author':AUTHOR,'website':WEBSITE,'software':APP_NAME,'version':APP_VERSION,'source':str(source),'product':'explicit manual magnetic filter stack','steps':','.join(steps),'warning':'Derived filtered product. Inspect removed component before archaeological interpretation.'}
    _archaeomag_write_like(final,out,transform,crs,tags,magnetic_label('Filtered magnetic field')); _archaeomag_write_like(remp,removed,transform,crs,{**tags,'product':'total component removed by manual filter stack'},magnetic_label('Filter removed component'))
    _native_three_panel_comparison(pd/f'{prefix}_filter_comparison.png',ref,out,removed,('Source','Filtered','Removed component'),unit_label=(f'Magnetic value ({source_unit})' if source_unit!='magnetic units' else 'Magnetic value'))
    rep={'software_version':APP_VERSION,'source':str(source),'cell_size_m':cs,'steps':steps,'parameters':vars(a),'stripe_info':stripe_info,'metrics_vs_source':restoration_metrics(ref,out),'products':{'filtered':str(final),'removed':str(remp)},'scientific_status':'DERIVED FILTERED PRODUCT; input source unchanged.'}
    (rd/f'{prefix}_filter_report.json').write_text(json.dumps(rep,indent=2,default=str),encoding='utf-8')
    print(f'Filtered raster: {final}\nRemoved-component audit: {remp}\nOriginal source was not overwritten.',flush=True); return 0


def _tf_time_seconds(date_s,time_s):
    from datetime import datetime
    ds=str(date_s).strip(); ts=str(time_s).strip()
    for fmt in ('%m/%d/%y %H:%M:%S.%f','%m/%d/%Y %H:%M:%S.%f','%Y-%m-%d %H:%M:%S.%f','%d/%m/%Y %H:%M:%S.%f'):
        try: return datetime.strptime(ds+' '+ts,fmt)
        except Exception: pass
    # tolerate integer-second time
    for fmt in ('%m/%d/%y %H:%M:%S','%m/%d/%Y %H:%M:%S','%Y-%m-%d %H:%M:%S','%d/%m/%Y %H:%M:%S'):
        try: return datetime.strptime(ds+' '+ts,fmt)
        except Exception: pass
    return None


def _tf_read_geometrics_dat(path):
    import pandas as pd
    p=Path(path)
    df=pd.read_csv(p,sep=r'\s+',engine='python')
    cols={str(c).upper():c for c in df.columns}
    req=('X','Y','READING')
    if not all(k in cols for k in req): raise ValueError(f'{p}: expected Geometrics DAT columns X Y READING; found {list(df.columns)}')
    out=pd.DataFrame({'X':pd.to_numeric(df[cols['X']],errors='coerce'),'Y':pd.to_numeric(df[cols['Y']],errors='coerce'),'READING':pd.to_numeric(df[cols['READING']],errors='coerce')})
    out['TIME']=df[cols['TIME']].astype(str) if 'TIME' in cols else ''
    out['DATE']=df[cols['DATE']].astype(str) if 'DATE' in cols else ''
    out['LINE']=pd.to_numeric(df[cols['LINE']],errors='coerce') if 'LINE' in cols else np.nan
    out['MARK']=pd.to_numeric(df[cols['MARK']],errors='coerce') if 'MARK' in cols else np.nan
    out['SOURCE_FILE']=p.name
    out=out[np.isfinite(out.X)&np.isfinite(out.Y)&np.isfinite(out.READING)].reset_index(drop=True)
    return out


def _tf_read_geometrics_stn(path,sensor=2):
    """Read G-858-style STN marker/data records and reconstruct XY between marks."""
    import pandas as pd
    rows=[]; marks=[]; p=Path(path)
    with p.open('r',encoding='utf-8',errors='ignore') as fh:
        for line in fh:
            t=line.split()
            if not t: continue
            if t[0]=='99': continue
            if t[0]=='3' and len(t)>=9:
                try: marks.append({'idx':len(rows),'x':float(t[1]),'y':float(t[2]),'time':t[3],'date':t[4],'line':float(t[6]),'mark':float(t[7])})
                except Exception: pass
            elif t[0]=='0' and len(t)>=6:
                try:
                    r1=float(t[1]); r2=float(t[2]); val=r1 if int(sensor)==1 else (r2 if int(sensor)==2 else 0.5*(r1+r2))
                    rows.append({'READING':val,'SENSOR1':r1,'SENSOR2':r2,'TIME':t[3],'DATE':t[4]})
                except Exception: pass
    if not rows: raise ValueError(f'{p}: no Geometrics STN data records found')
    n=len(rows); X=np.full(n,np.nan); Y=np.full(n,np.nan); LINE=np.full(n,np.nan); MARK=np.full(n,np.nan)
    # Interpolate positions between consecutive physical mark records.  Marker idx
    # is the number of data samples encountered before that mark; this matches the
    # Geometrics station-stream structure and does not invent intermediate bends.
    for i in range(len(marks)-1):
        a,b=marks[i],marks[i+1]; i0=max(0,min(n-1,a['idx'])); i1=max(i0+1,min(n,b['idx']))
        cnt=max(1,i1-i0)
        f=np.arange(cnt,dtype=float)/cnt
        X[i0:i1]=a['x']+(b['x']-a['x'])*f; Y[i0:i1]=a['y']+(b['y']-a['y'])*f; LINE[i0:i1]=a['line']; MARK[i0:i1]=a['mark']
    if marks:
        # Fill leading/trailing samples conservatively from nearest marker/segment.
        first=min(n-1,marks[0]['idx']); X[:first+1]=np.where(np.isfinite(X[:first+1]),X[:first+1],marks[0]['x']); Y[:first+1]=np.where(np.isfinite(Y[:first+1]),Y[:first+1],marks[0]['y']); LINE[:first+1]=np.where(np.isfinite(LINE[:first+1]),LINE[:first+1],marks[0]['line']); MARK[:first+1]=np.where(np.isfinite(MARK[:first+1]),MARK[:first+1],marks[0]['mark'])
        last=marks[-1]; j=min(n-1,last['idx']); X[j:]=np.where(np.isfinite(X[j:]),X[j:],last['x']); Y[j:]=np.where(np.isfinite(Y[j:]),Y[j:],last['y']); LINE[j:]=np.where(np.isfinite(LINE[j:]),LINE[j:],last['line']); MARK[j:]=np.where(np.isfinite(MARK[j:]),MARK[j:],last['mark'])
    df=pd.DataFrame(rows); df['X']=X; df['Y']=Y; df['LINE']=LINE; df['MARK']=MARK; df['SOURCE_FILE']=p.name; df['GEOMETRY_FROM_MARKS']=bool(marks)
    return df


def _tf_synthetic_line_marks(df,line_spacing=0.5,mark_spacing=5.0):
    """Fill missing LINE/MARK labels from existing XY; coordinates are never changed."""
    import pandas as pd
    q=df.copy(); xy=q[['X','Y']].to_numpy(float); good=np.isfinite(xy).all(axis=1)
    if not good.any(): return q
    cen=np.nanmedian(xy[good],axis=0); A=xy[good]-cen
    try:
        _,_,vt=np.linalg.svd(A,full_matrices=False); along=vt[0]; cross=np.array([-along[1],along[0]])
    except Exception:
        along=np.array([0.,1.]); cross=np.array([1.,0.])
    au=(xy-cen)@along; cu=(xy-cen)@cross
    if 'LINE' not in q or q['LINE'].isna().all():
        ls=max(float(line_spacing),1e-6); q['LINE']=np.rint((cu-np.nanmin(cu))/ls).astype(float)
    if 'MARK' not in q or q['MARK'].isna().all():
        ms=max(float(mark_spacing),1e-6); q['MARK']=np.floor((au-np.nanmin(au))/ms).astype(float)
    q['SYNTHETIC_MARKS']=True
    return q


def _tf_layout_offsets(files,frames,mode='auto',grid_width=0.0,grid_height=0.0):
    """Return filename->(dx,dy) for overlapping local grids using A1/C5 style names."""
    ex=[]
    for f,df in zip(files,frames): ex.append((float(df.X.max()-df.X.min()),float(df.Y.max()-df.Y.min())))
    gw=float(grid_width) if grid_width>0 else float(np.ceil(np.nanmedian([x for x,y in ex]))); gh=float(grid_height) if grid_height>0 else float(np.ceil(np.nanmedian([y for x,y in ex])))
    if gw<=0: gw=40.
    if gh<=0: gh=40.
    parsed=[]
    for f in files:
        m=re.search(r'([A-Za-z]+)(\d+)$',Path(f).stem)
        if not m: return None,gw,gh
        letters=m.group(1).upper(); col=int(m.group(2))-1; row=0
        for ch in letters: row=row*26+(ord(ch)-ord('A')+1)
        row-=1; parsed.append((Path(f).name,col,row))
    mincol=min(c for _,c,_ in parsed); minrow=min(r for _,_,r in parsed)
    out={name:((col-mincol)*gw,-(row-minrow)*gh) for name,col,row in parsed}
    return out,gw,gh


def _tf_base_series(path,sensor=2):
    import pandas as pd
    p=Path(path)
    if p.suffix.lower()=='.stn':
        df=_tf_read_geometrics_stn(p,sensor=sensor)
    else:
        try:
            df=_tf_read_geometrics_dat(p)
        except Exception:
            import pandas as pd
            raw=pd.read_csv(p,sep=None,engine='python')
            cols={str(c).upper():c for c in raw.columns}
            rc=next((cols[k] for k in ('READING','FIELD','TOTAL','NT','VALUE') if k in cols),None)
            tc=next((cols[k] for k in ('TIME','DATETIME','TIMESTAMP') if k in cols),None)
            dc=cols.get('DATE',None)
            if rc is None or tc is None: raise
            df=pd.DataFrame({'READING':pd.to_numeric(raw[rc],errors='coerce'),'TIME':raw[tc].astype(str),'DATE':(raw[dc].astype(str) if dc is not None else '')})
    times=[]; vals=[]
    for d,t,v in zip(df['DATE'],df['TIME'],df['READING']):
        dt=_tf_time_seconds(d,t)
        if dt is not None and np.isfinite(v): times.append(dt.timestamp()); vals.append(float(v))
    if len(times)<2: raise SystemExit(f'Base station file {p} does not contain at least two time-stamped readings.')
    o=np.argsort(times); return np.asarray(times)[o],np.asarray(vals)[o]


def _tf_apply_base(df,base_path,sensor=2,reference='median'):
    bt,bv=_tf_base_series(base_path,sensor)
    ft=np.array([(_tf_time_seconds(d,t).timestamp() if _tf_time_seconds(d,t) is not None else np.nan) for d,t in zip(df.DATE,df.TIME)],float)
    good=np.isfinite(ft)
    if not good.any(): raise SystemExit('Field data have no parseable DATE/TIME for base-station correction.')
    bi=np.interp(ft[good],bt,bv,left=np.nan,right=np.nan)
    if np.isnan(bi).any():
        # Nearest endpoint is safer than extrapolating a slope; report coverage.
        bi=np.interp(ft[good],bt,bv)
    if str(reference).lower()=='median': ref=float(np.nanmedian(bv))
    elif str(reference).lower()=='first': ref=float(bv[0])
    else: ref=float(reference)
    out=df.copy(); corr=np.zeros(len(out),float); corr[good]=bi-ref; out['BASE_CORRECTION']=corr; out['READING']=out['READING'].to_numpy(float)-corr
    return out,{'base_file':str(base_path),'base_reference_nT':ref,'base_min_nT':float(np.min(bv)),'base_max_nT':float(np.max(bv)),'base_span_nT':float(np.ptp(bv))}


def _tf_apply_igrf(df,mode,lat,lon,height_m=0.0):
    if mode=='none': return df,None
    if lat is None or lon is None: raise SystemExit('IGRF correction requires --site-lat and --site-lon for local-grid total-field data.')
    try: import ppigrf
    except Exception as exc: raise SystemExit('IGRF mode requires optional package ppigrf (`pip install ppigrf`). MagSurveyPy uses its IGRF-14 implementation when installed.') from exc
    from datetime import datetime
    dts=[_tf_time_seconds(d,t) for d,t in zip(df.DATE,df.TIME)]; good=[x for x in dts if x is not None]
    if not good: raise SystemExit('No valid DATE/TIME for IGRF evaluation.')
    # One model value per minute is sufficient for archaeological grid scale; interpolate in time.
    ts=np.array([x.timestamp() if x is not None else np.nan for x in dts]); t0=np.nanmin(ts); t1=np.nanmax(ts); knots=np.arange(np.floor(t0/60)*60,np.ceil(t1/60)*60+61,60)
    vals=[]
    for tt in knots:
        dt=datetime.fromtimestamp(float(tt)); Be,Bn,Bu=ppigrf.igrf(float(lon),float(lat),float(height_m)/1000.0,dt); vals.append(float(np.sqrt(np.asarray(Be).squeeze()**2+np.asarray(Bn).squeeze()**2+np.asarray(Bu).squeeze()**2)))
    vals=np.asarray(vals); model=np.interp(ts,knots,vals); ref=float(np.nanmedian(model)); out=df.copy()
    if mode=='absolute': out['IGRF_CORRECTION']=model; out['READING']=out.READING.to_numpy(float)-model
    else: out['IGRF_CORRECTION']=model-ref; out['READING']=out.READING.to_numpy(float)-(model-ref)
    return out,{'igrf_mode':mode,'site_lat':float(lat),'site_lon':float(lon),'height_m':float(height_m),'igrf_reference_nT':ref,'igrf_span_nT':float(np.ptp(model))}


def _tf_line_level(df,mode='off'):
    """Robust line/mark baseline correction; no coordinates are moved."""
    import pandas as pd
    if mode=='off': return df,{'mode':'off'}
    q=df.copy(); vals=q.READING.to_numpy(float); removed=np.zeros(len(q),float); global_med=float(np.nanmedian(vals))
    if 'LINE' not in q or q.LINE.isna().all(): raise SystemExit('Line levelling requires LINE labels or --synthetic-marks.')
    for line,idx in q.groupby('LINE',dropna=True).groups.items():
        ii=np.asarray(list(idx),int); z=vals[ii]
        if len(z)<5: continue
        if mode=='median': base=np.full(len(ii),float(np.nanmedian(z))-global_med)
        elif mode=='linear':
            x=np.arange(len(ii),dtype=float); med=np.nanmedian(z); mad=max(1.4826*np.nanmedian(np.abs(z-med)),1e-9); keep=np.abs(z-med)<3.5*mad
            if keep.sum()>=3: c=np.polyfit(x[keep],z[keep],1); trend=np.polyval(c,x); base=trend-np.nanmedian(trend)+float(np.nanmedian(z))-global_med
            else: base=np.full(len(ii),float(np.nanmedian(z))-global_med)
        else: # mark-anchored
            marks=q.iloc[ii]['MARK'].to_numpy(float); base=np.zeros(len(ii),float)
            unique=[m for m in np.unique(marks[np.isfinite(marks)])]
            if not unique: base[:]=float(np.nanmedian(z))-global_med
            else:
                centers=[]; meds=[]
                for m in unique:
                    jj=np.where(marks==m)[0]; centers.append(float(np.median(jj))); meds.append(float(np.nanmedian(z[jj])))
                centers=np.asarray(centers); meds=np.asarray(meds); target=float(np.nanmedian(meds)); base=np.interp(np.arange(len(ii)),centers,meds)-target + (target-global_med)
        removed[ii]=base
    q['LEVEL_CORRECTION']=removed; q['READING']=vals-removed
    return q,{'mode':mode,'rms_correction_nT':float(np.sqrt(np.nanmean(removed**2))),'p95_abs_correction_nT':float(np.nanpercentile(np.abs(removed),95))}



def _tf_traverse_zero(df,mode='off',clip_sigma=3.5,unit='nT'):
    """Zero individual acquisition traverses on the derived archaeology branch.

    Unlike ``--line-level median`` (which aligns line medians to the survey-wide
    median while retaining the absolute field level), traverse-zero explicitly
    removes the baseline of every LINE so the derived values are centred near
    zero.  The REFERENCE_READING column is retained unchanged.
    """
    if mode=='off':
        q=df.copy(); q['TRAVERSE_ZERO_CORRECTION']=0.0
        return q,{'mode':'off','applied':False}
    if 'LINE' not in df or df.LINE.isna().all():
        raise SystemExit('Traverse zeroing requires LINE labels. Use native LINE values or --synthetic-marks when XY are available.')
    q=df.copy(); vals=q.READING.to_numpy(float); corr=np.zeros(len(q),float); bases=[]
    for line,idx in q.groupby('LINE',dropna=True).groups.items():
        ii=np.asarray(list(idx),int); z=vals[ii]; good=np.isfinite(z)
        if good.sum()<5: continue
        zz=z[good]
        if mode=='mean': base=float(np.nanmean(zz))
        elif mode=='median': base=float(np.nanmedian(zz))
        else:  # robust: MAD-clipped mean, falling back to the median.
            med=float(np.nanmedian(zz)); sig=max(1.4826*float(np.nanmedian(np.abs(zz-med))),1e-12)
            keep=np.abs(zz-med)<=float(clip_sigma)*sig
            base=float(np.nanmean(zz[keep])) if keep.sum()>=5 else med
        corr[ii]=base; bases.append((float(line),base,int(good.sum())))
    q['TRAVERSE_ZERO_CORRECTION']=corr; q['READING']=vals-corr
    return q,{'mode':mode,'applied':True,'clip_sigma':float(clip_sigma),'line_count':len(bases),'unit':str(unit),
              'baseline_median':float(np.nanmedian([b for _,b,_ in bases])) if bases else None,
              'baseline_span':float(np.ptp([b for _,b,_ in bases])) if len(bases)>1 else 0.0,
              'rms_correction':float(np.sqrt(np.nanmean(corr*corr))) if len(corr) else 0.0,
              'per_line':[{'line':l,'baseline':b,'samples':n} for l,b,n in bases]}


def _tf_center_raster(arr,mode='off',clip_sigma=3.5):
    """Centre a derived archaeological raster without rescaling amplitudes."""
    out=np.asarray(arr,float).copy(); good=np.isfinite(out)
    if mode=='off' or not good.any(): return out,{'mode':'off','offset':0.0}
    z=out[good]
    if mode=='mean': off=float(np.nanmean(z))
    elif mode=='median': off=float(np.nanmedian(z))
    else:
        med=float(np.nanmedian(z)); sig=max(1.4826*float(np.nanmedian(np.abs(z-med))),1e-12)
        keep=np.abs(z-med)<=float(clip_sigma)*sig
        off=float(np.nanmean(z[keep])) if keep.sum()>=10 else med
    out[good]-=off
    return out,{'mode':mode,'offset':off,'clip_sigma':float(clip_sigma)}


def _tf_background(arr,scale_m,cell_size,method='gaussian'):
    """Return a broad background surface for total-field archaeology residuals."""
    scale=float(scale_m)
    if scale<=0: return np.zeros_like(arr,dtype=float)
    if method=='median':
        px=max(3,int(round(scale/max(float(cell_size),1e-9))))
        if px%2==0: px+=1
        return nan_median(arr,px)
    return nan_gaussian(arr,max(scale/max(float(cell_size),1e-9),1e-6))


def _tf_deslope_grid(df, mode='robust'):
    """Remove only a broad planar trend from one local total-field grid.

    ``robust`` fits an iteratively reweighted plane to background-like samples.
    ``edge`` fits the plane primarily from an outer frame of the local grid so
    broad central archaeological structure has less leverage.  The median field
    level is preserved and the removed plane is exported through
    DESLOPE_CORRECTION.  This remains a derived correction; REFERENCE_READING is
    never changed.
    """
    q=df.copy(); x=q.X.to_numpy(float); y=q.Y.to_numpy(float); z=q.READING.to_numpy(float)
    good=np.isfinite(x)&np.isfinite(y)&np.isfinite(z)
    if good.sum()<20: return q,{'mode':mode,'applied':False,'reason':'too few valid points'}
    x0=float(np.nanmedian(x[good])); y0=float(np.nanmedian(y[good]));
    xx=x-x0; yy=y-y0; A=np.column_stack([xx,yy,np.ones(len(x))])
    keep=good.copy()
    if str(mode)=='edge':
        xmin,xmax=float(np.nanmin(x[good])),float(np.nanmax(x[good])); ymin,ymax=float(np.nanmin(y[good])),float(np.nanmax(y[good]))
        wx=max(1e-6,0.18*(xmax-xmin)); wy=max(1e-6,0.18*(ymax-ymin))
        edge=(x<=xmin+wx)|(x>=xmax-wx)|(y<=ymin+wy)|(y>=ymax-wy)
        keep &= edge
        if keep.sum()<50: keep=good.copy()
    # Iteratively reject compact/high-amplitude anomalies while retaining broad trend.
    weights=np.ones(len(x),float)
    coef=np.array([0.,0.,float(np.nanmedian(z[good]))])
    for _ in range(6):
        ii=np.where(keep & (weights>0))[0]
        if len(ii)<20: break
        sw=np.sqrt(weights[ii]); Aw=A[ii]*sw[:,None]; zw=z[ii]*sw
        try: coef=np.linalg.lstsq(Aw,zw,rcond=None)[0]
        except Exception: break
        resid=z-(A@coef); rr=resid[ii]; med=float(np.nanmedian(rr)); mad=max(1.4826*float(np.nanmedian(np.abs(rr-med))),1e-9)
        u=np.abs(resid-med)/(3.0*mad)
        weights=np.where(u<1.0,(1.0-u*u)**2,0.0); weights[~keep]=0.0
    plane=A@coef; plane-=float(np.nanmedian(plane[good])); plane[~good]=0.0
    q['DESLOPE_CORRECTION']=plane; q['READING']=z-plane
    return q,{'mode':str(mode),'applied':True,'coef_x_nT_per_m':float(coef[0]),'coef_y_nT_per_m':float(coef[1]),
              'rms_correction_nT':float(np.sqrt(np.nanmean(plane[good]**2))),
              'p95_abs_correction_nT':float(np.nanpercentile(np.abs(plane[good]),95)),
              'fit_samples':int(np.sum(weights>0)),'fit_fraction':float(np.mean(weights[good]>0))}


def _tf_grid_points(df,cell_size=0.25,statistic='median',fill_distance=0.5):
    from scipy.stats import binned_statistic_2d
    from scipy.ndimage import distance_transform_edt
    from scipy.interpolate import griddata
    from rasterio.transform import from_origin
    x=df.X.to_numpy(float); y=df.Y.to_numpy(float); z=df.READING.to_numpy(float); good=np.isfinite(x)&np.isfinite(y)&np.isfinite(z); x=x[good]; y=y[good]; z=z[good]
    cs=float(cell_size); xmin=np.floor(x.min()/cs)*cs; xmax=np.ceil(x.max()/cs)*cs; ymin=np.floor(y.min()/cs)*cs; ymax=np.ceil(y.max()/cs)*cs
    xe=np.arange(xmin,xmax+cs*1.001,cs); ye=np.arange(ymin,ymax+cs*1.001,cs)
    g,_,_,_=binned_statistic_2d(x,y,z,statistic=statistic,bins=(xe,ye)); g=g.T
    count,_,_,_=binned_statistic_2d(x,y,z,statistic='count',bins=(xe,ye)); count=count.T
    observed=np.isfinite(g); out=g.copy()
    if fill_distance>0 and (~observed).any() and observed.any():
        # Local linear interpolation with nearest fallback, only within a measured-support distance.
        xc=(xe[:-1]+xe[1:])/2; yc=(ye[:-1]+ye[1:])/2; YY,XX=np.meshgrid(yc,xc,indexing='ij'); pts=np.column_stack([XX[observed],YY[observed]]); vals=g[observed]
        target=~observed
        pred=griddata(pts,vals,(XX,YY),method='linear')
        near=griddata(pts,vals,(XX,YY),method='nearest'); pred=np.where(np.isfinite(pred),pred,near)
        dist=distance_transform_edt(~observed)*cs; fill=target&(dist<=float(fill_distance)); out[fill]=pred[fill]
    # binned_statistic y is south->north; GeoTIFF row 0 must be north.
    out=np.flipud(out); count=np.flipud(count); observed=np.flipud(observed)
    tr=from_origin(xmin,ymax,cs,cs)
    return out,count,observed,tr



def _tf_line_axis(df):
    """Return acquisition-line axis ('x' or 'y') using LINE geometry when possible.

    'y' means traverses run predominantly north/south in the local grid and stripe
    offsets vary across X. 'x' means traverses run predominantly east/west and
    stripe offsets vary across Y.
    """
    try:
        if 'LINE' in df and not df.LINE.isna().all():
            spans=[]
            for _,g in df.groupby('LINE',dropna=True):
                if len(g)<5: continue
                spans.append((float(g.X.max()-g.X.min()),float(g.Y.max()-g.Y.min())))
            if spans:
                sx=float(np.nanmedian([a for a,b in spans])); sy=float(np.nanmedian([b for a,b in spans]))
                return 'y' if sy>=sx else 'x'
    except Exception:
        pass
    xy=df[['X','Y']].to_numpy(float); good=np.isfinite(xy).all(axis=1)
    if good.sum()<3: return 'y'
    A=xy[good]-np.nanmedian(xy[good],axis=0)
    try:
        _,_,vt=np.linalg.svd(A,full_matrices=False); v=vt[0]
        return 'x' if abs(v[0])>=abs(v[1]) else 'y'
    except Exception:
        return 'y'


def _tf_protected_destripe_points(df, cell_size=0.25, width_m=12.0, strength=1.0,
                                   max_correction='auto', smooth_m=0.15, clip_sigma=3.5):
    """Estimate a constant cross-track stripe correction without forcing line medians.

    The correction is derived from a preliminary local raster.  At every along-line
    position a broad cross-track median supplies the local field reference; the robust
    median residual along each cross-track position is then interpreted as the
    acquisition stripe component.  Strong local anomalies are excluded by a MAD gate.
    The result is a *one-dimensional* correction across the acquisition lines, which
    preserves along-line archaeological morphology and broad regional gradients much
    better than independently zeroing every LINE/MARK segment.

    The original/base/IGRF-corrected reading is retained in REFERENCE_READING.  This
    function adds DESTRIPE_CORRECTION and changes only the derived working READING.
    """
    from scipy.ndimage import median_filter, gaussian_filter1d, distance_transform_edt
    q=df.copy()
    if len(q)<20:
        q['DESTRIPE_CORRECTION']=0.0
        return q,{'mode':'protected','applied':False,'reason':'too few points'}
    axis=_tf_line_axis(q)
    cs=max(0.05,min(float(cell_size),0.20))
    # Dense scalar surveys commonly sample at ~0.1 m along line; a small internal
    # grid retains that support while being inexpensive for 20-40 m local grids.
    fill=max(0.6,3.0*cs)
    try:
        pre,_,_,tr=_tf_grid_points(q,cs,'median',fill)
    except Exception as exc:
        q['DESTRIPE_CORRECTION']=0.0
        return q,{'mode':'protected','applied':False,'reason':str(exc)}
    valid=np.isfinite(pre)
    if valid.sum()<20:
        q['DESTRIPE_CORRECTION']=0.0
        return q,{'mode':'protected','applied':False,'reason':'insufficient preliminary raster support'}
    # Nearest fill is used only internally for estimating the stripe vector; it is
    # never exported and cannot create magnetic observations.
    if not valid.all():
        ind=distance_transform_edt(~valid,return_distances=False,return_indices=True)
        work=pre[tuple(ind)]
    else:
        work=pre.copy()
    width=max(3,int(round(float(width_m)/cs))); width += (width%2==0)
    if axis=='y':
        ref=median_filter(work,size=(1,width),mode='nearest'); residual=work-ref
        n=work.shape[1]; corr=np.zeros(n,float)
        for j in range(n):
            v=residual[:,j]; med=float(np.median(v)); mad=1.4826*float(np.median(np.abs(v-med)))
            good=np.ones(len(v),bool) if mad<=1e-12 else np.abs(v-med)<=float(clip_sigma)*mad
            corr[j]=-float(np.median(v[good])) if good.any() else -med
        coords=tr.c+(np.arange(n)+0.5)*tr.a
    else:
        ref=median_filter(work,size=(width,1),mode='nearest'); residual=work-ref
        n=work.shape[0]; corr=np.zeros(n,float)
        for i in range(n):
            v=residual[i,:]; med=float(np.median(v)); mad=1.4826*float(np.median(np.abs(v-med)))
            good=np.ones(len(v),bool) if mad<=1e-12 else np.abs(v-med)<=float(clip_sigma)*mad
            corr[i]=-float(np.median(v[good])) if good.any() else -med
        coords=tr.f+(np.arange(n)+0.5)*tr.e
    corr-=float(np.median(corr))
    if float(smooth_m)>0:
        corr=gaussian_filter1d(corr,max(0.0,float(smooth_m)/cs),mode='nearest')
        corr-=float(np.median(corr))
    z=q.READING.to_numpy(float); zmed=float(np.nanmedian(z)); zmad=1.4826*float(np.nanmedian(np.abs(z-zmed)))
    if str(max_correction).lower()=='auto':
        # Conservative automatic cap.  It is intentionally small relative to the
        # archaeological field spread and prevents broad anomalies from being
        # mistaken for line offsets.  Expert users can provide a numeric nT cap.
        cap=max(2.0,min(5.0,0.40*max(zmad,1e-9)))
    else:
        cap=max(0.0,float(max_correction))
    if cap>0: corr=np.clip(corr,-cap,cap)
    corr*=float(np.clip(strength,0.0,1.0))
    order=np.argsort(coords); cc=coords[order]; cv=corr[order]
    cross=q.X.to_numpy(float) if axis=='y' else q.Y.to_numpy(float)
    pc=np.interp(cross,cc,cv,left=cv[0],right=cv[-1])
    q['DESTRIPE_CORRECTION']=pc
    q['READING']=z+pc
    return q,{
        'mode':'protected','applied':True,'line_axis':axis,'internal_cell_m':float(cs),
        'cross_track_reference_width_m':float(width_m),'strength':float(strength),
        'max_correction_nT':float(cap),'correction_min_nT':float(np.min(pc)),
        'correction_max_nT':float(np.max(pc)),'correction_rms_nT':float(np.sqrt(np.mean(pc**2))),
        'field_robust_sigma_nT':float(zmad),'clip_sigma':float(clip_sigma)
    }



def _tf_adaptive_destripe_points(df, cell_size=0.25, width_m=12.0, strength=1.0,
                                  max_correction='auto', smooth_m=0.15, clip_sigma=3.5):
    """Line-aware protected destriping for dense scalar magnetometry.

    A broad 2-D reference is built only to estimate slowly varying geology.  Each
    physical LINE contributes one robust residual level after strong local anomalies
    are rejected.  Those line residuals are then decomposed into a slowly varying
    cross-line trend plus a short-wavelength acquisition offset.  Only the latter is
    removed.  This avoids forcing every line to one common median while targeting
    the alternating/banded component that creates archaeological map striping.
    """
    from scipy.ndimage import gaussian_filter1d, distance_transform_edt
    q=df.copy(); z=q.READING.to_numpy(float)
    if len(q)<50 or 'LINE' not in q or q.LINE.isna().all():
        qq,meta=_tf_protected_destripe_points(q,cell_size,width_m,strength,max_correction,smooth_m,clip_sigma)
        meta['fallback_from']='adaptive'; return qq,meta
    axis=_tf_line_axis(q); cs=max(0.05,min(float(cell_size),0.20)); fill=max(0.6,3.0*cs)
    try:
        pre,_,_,tr=_tf_grid_points(q,cs,'median',fill)
    except Exception as exc:
        qq,meta=_tf_protected_destripe_points(q,cell_size,width_m,strength,max_correction,smooth_m,clip_sigma)
        meta['fallback_from']='adaptive'; meta['fallback_reason']=str(exc); return qq,meta
    valid=np.isfinite(pre)
    if not valid.any():
        q['DESTRIPE_CORRECTION']=0.0; return q,{'mode':'adaptive','applied':False,'reason':'no preliminary support'}
    if not valid.all():
        ind=distance_transform_edt(~valid,return_distances=False,return_indices=True); work=pre[tuple(ind)]
    else: work=pre.copy()
    # Broad regional field; this is never exported as measured data.
    bg=nan_gaussian(work,max(1.0,float(width_m)/(3.0*cs)))
    x=q.X.to_numpy(float); y=q.Y.to_numpy(float)
    cols=np.rint((x-tr.c)/tr.a-0.5).astype(int); rows=np.rint((y-tr.f)/tr.e-0.5).astype(int)
    rows=np.clip(rows,0,bg.shape[0]-1); cols=np.clip(cols,0,bg.shape[1]-1)
    pred=bg[rows,cols]; residual=z-pred
    line_ids=[]; centers=[]; levels=[]; counts=[]
    cross=q.X.to_numpy(float) if axis=='y' else q.Y.to_numpy(float)
    for lid,idx in q.groupby('LINE',dropna=True).groups.items():
        ii=np.asarray(list(idx),int); r=residual[ii]; r=r[np.isfinite(r)]
        if len(r)<10: continue
        med=float(np.nanmedian(r)); mad=max(1.4826*float(np.nanmedian(np.abs(r-med))),1e-9)
        keep=np.abs(r-med)<=float(clip_sigma)*mad
        if keep.sum()>=5: med=float(np.nanmedian(r[keep]))
        line_ids.append(lid); centers.append(float(np.nanmedian(cross[ii]))); levels.append(med); counts.append(int(len(r)))
    if len(levels)<3:
        qq,meta=_tf_protected_destripe_points(q,cell_size,width_m,strength,max_correction,smooth_m,clip_sigma)
        meta['fallback_from']='adaptive'; meta['fallback_reason']='too few physical lines'; return qq,meta
    centers=np.asarray(centers,float); levels=np.asarray(levels,float); order=np.argsort(centers); centers=centers[order]; levels=levels[order]
    spacing=float(np.nanmedian(np.diff(centers))) if len(centers)>1 else float(cell_size)
    spacing=max(abs(spacing),1e-6); sigma_lines=max(1.0,float(width_m)/(spacing*2.355))
    trend=gaussian_filter1d(levels,sigma_lines,mode='nearest')
    short=levels-trend; short-=float(np.nanmedian(short))
    zmed=float(np.nanmedian(z)); zmad=1.4826*float(np.nanmedian(np.abs(z-zmed)))
    cap=max(2.0,min(6.0,0.45*max(zmad,1e-9))) if str(max_correction).lower()=='auto' else max(0.0,float(max_correction))
    if cap>0: short=np.clip(short,-cap,cap)
    if smooth_m>0 and len(short)>2:
        short=gaussian_filter1d(short,max(0.0,float(smooth_m)/spacing),mode='nearest')
    short*=float(np.clip(strength,0.0,1.0))
    # Correction is minus the estimated short-wavelength line offset.
    corr_by_line={line_ids[i]:-float(short[np.where(order==i)[0][0]]) for i in range(len(line_ids))}
    corr=np.zeros(len(q),float)
    for lid,idx in q.groupby('LINE',dropna=True).groups.items(): corr[np.asarray(list(idx),int)]=corr_by_line.get(lid,0.0)
    q['DESTRIPE_CORRECTION']=corr; q['READING']=z+corr
    return q,{'mode':'adaptive','applied':True,'line_axis':axis,'line_count':int(len(levels)),'median_line_spacing_m':float(spacing),
              'regional_width_m':float(width_m),'trend_sigma_lines':float(sigma_lines),'strength':float(strength),'max_correction_nT':float(cap),
              'correction_min_nT':float(np.nanmin(corr)),'correction_max_nT':float(np.nanmax(corr)),'correction_rms_nT':float(np.sqrt(np.nanmean(corr**2))),
              'field_robust_sigma_nT':float(zmad),'clip_sigma':float(clip_sigma)}

def _tf_robust_median(values, clip_sigma=3.5):
    v=np.asarray(values,float); v=v[np.isfinite(v)]
    if not len(v): return float('nan')
    med=float(np.median(v)); mad=1.4826*float(np.median(np.abs(v-med)))
    if mad>1e-12:
        vv=v[np.abs(v-med)<=float(clip_sigma)*mad]
        if len(vv): med=float(np.median(vv))
    return med



def _tf_edge_profile_constraint(qi,qj,bi,bj,edge_width=2.0,step=0.5):
    """Return a robust matched-edge offset constraint between two placed grids."""
    xi0,xi1,yi0,yi1=bi; xj0,xj1,yj0,yj1=bj
    yov=max(0.0,min(yi1,yj1)-max(yi0,yj0)); xov=max(0.0,min(xi1,xj1)-max(xi0,xj0))
    minyh=max(1e-9,min(yi1-yi0,yj1-yj0)); minxw=max(1e-9,min(xi1-xi0,xj1-xj0))
    tol=max(0.75,float(edge_width)*0.75); orient=None
    if yov>=0.50*minyh and min(abs(xi1-xj0),abs(xj1-xi0))<=tol:
        orient='vertical'
        if abs(xi1-xj0)<=abs(xj1-xi0):
            ai=qi[qi.X>=xi1-float(edge_width)]; bjf=qj[qj.X<=xj0+float(edge_width)]
        else:
            ai=qi[qi.X<=xi0+float(edge_width)]; bjf=qj[qj.X>=xj1-float(edge_width)]
        coord='Y'; lo=max(yi0,yj0); hi=min(yi1,yj1)
    elif xov>=0.50*minxw and min(abs(yi1-yj0),abs(yj1-yi0))<=tol:
        orient='horizontal'
        if abs(yi1-yj0)<=abs(yj1-yi0):
            ai=qi[qi.Y>=yi1-float(edge_width)]; bjf=qj[qj.Y<=yj0+float(edge_width)]
        else:
            ai=qi[qi.Y<=yi0+float(edge_width)]; bjf=qj[qj.Y>=yj1-float(edge_width)]
        coord='X'; lo=max(xi0,xj0); hi=min(xi1,xj1)
    else:
        return None
    if hi<=lo or len(ai)<10 or len(bjf)<10: return None
    st=max(0.20,float(step)); edges=np.arange(lo,hi+st*1.001,st)
    if len(edges)<5: return None
    def profile(df):
        c=df[coord].to_numpy(float); z=df.READING.to_numpy(float); k=np.digitize(c,edges)-1
        out=np.full(len(edges)-1,np.nan)
        for m in range(len(out)):
            v=z[k==m]
            if v.size: out[m]=float(np.nanmedian(v))
        return out
    pa,pb=profile(ai),profile(bjf); valid=np.isfinite(pa)&np.isfinite(pb)
    if valid.sum()<4: return None
    diff=pa[valid]-pb[valid]; dm=float(np.nanmedian(diff)); mad=max(1.4826*float(np.nanmedian(np.abs(diff-dm))),1e-9)
    keep=np.abs(diff-dm)<=3.5*mad
    if keep.sum()>=3: diff=diff[keep]; va=pa[valid][keep]; vb=pb[valid][keep]
    else: va=pa[valid]; vb=pb[valid]
    d=float(np.nanmedian(diff)); spread=float(1.4826*np.nanmedian(np.abs(diff-d))) if len(diff) else float('nan')
    aa=va-float(np.nanmedian(va)); bb=vb-float(np.nanmedian(vb))
    corr=float(np.corrcoef(aa,bb)[0,1]) if len(aa)>=4 and np.nanstd(aa)>1e-12 and np.nanstd(bb)>1e-12 else 0.0
    corr=0.0 if not np.isfinite(corr) else corr
    coverage=float(len(diff))/max(1,len(edges)-1)
    weight=max(1.0,float(len(diff)))*(0.35+0.65*max(0.0,corr))*max(0.25,coverage)
    return {'difference_i_minus_j':d,'matched_bins':int(len(diff)),'spread_nT':spread,'correlation':corr,'coverage':coverage,'weight':weight,'orientation':orient}


def _tf_edge_level_assembled(frames, names, edge_width=2.0, max_correction='auto'):
    """Globally solve constant inter-grid offsets from matched boundary profiles.

    Adjacent edges are binned along their shared boundary and compared position by
    position after robust rejection.  All accepted constraints are solved together
    in one weighted network, avoiding sequential seam propagation.  Only the
    derived working READING is shifted; REFERENCE_READING remains untouched.
    """
    if len(frames)<2:
        for q in frames: q['GRID_LEVEL_CORRECTION']=0.0
        return frames,{'mode':'network-edge','applied':False,'reason':'single grid','constraints':[],'shifts':{str(names[0]) if names else 'grid':0.0}}
    boxes=[(float(q.X.min()),float(q.X.max()),float(q.Y.min()),float(q.Y.max())) for q in frames]
    constraints=[]
    for i in range(len(frames)):
        for j in range(i+1,len(frames)):
            c=_tf_edge_profile_constraint(frames[i],frames[j],boxes[i],boxes[j],edge_width=edge_width,step=max(0.25,min(0.75,float(edge_width)/4)))
            if c is not None:
                c.update({'i':i,'j':j}); constraints.append(c)
    if not constraints:
        for q in frames: q['GRID_LEVEL_CORRECTION']=0.0
        return frames,{'mode':'network-edge','applied':False,'reason':'no adjacent grid boundaries','constraints':[],'shifts':{str(n):0.0 for n in names}}
    n=len(frames); A=[]; b=[]; w=[]
    row=np.zeros(n); row[0]=1.0; A.append(row); b.append(0.0); w.append(1000.0)
    for c in constraints:
        row=np.zeros(n); row[c['j']]=1.0; row[c['i']]=-1.0
        # shift_j - shift_i = median_i - median_j
        A.append(row); b.append(float(c['difference_i_minus_j'])); w.append(float(c['weight']))
    A=np.asarray(A,float); b=np.asarray(b,float); sw=np.sqrt(np.asarray(w,float));
    shifts=np.linalg.lstsq(A*sw[:,None],b*sw,rcond=None)[0]; shifts-=float(np.median(shifts))
    allz=np.concatenate([q.READING.to_numpy(float) for q in frames]); med=float(np.nanmedian(allz)); mad=1.4826*float(np.nanmedian(np.abs(allz-med)))
    if str(max_correction).lower()=='auto':
        well=[abs(float(c['difference_i_minus_j'])) for c in constraints if c.get('correlation',0)>=0.35 and c.get('coverage',0)>=0.60]
        req=float(np.nanpercentile(well,90)) if well else 0.0
        # Because this is a derived seam-matching branch and the corrected total-field
        # reference is preserved separately, allow a well-supported temporal grid offset
        # to exceed the old 2-8 nT cap. Still cap at 25 nT to avoid hiding a wrong layout.
        cap=max(3.0,min(25.0,max(0.85*max(mad,1e-9),1.15*req)))
    else: cap=max(0.0,float(max_correction))
    if cap>0: shifts=np.clip(shifts,-cap,cap)
    out=[]
    for q,sh in zip(frames,shifts):
        qq=q.copy(); qq['GRID_LEVEL_CORRECTION']=float(sh); qq['READING']=qq.READING.to_numpy(float)+float(sh); out.append(qq)
    cons=[]
    for c in constraints:
        cons.append({'grid_i':str(names[c['i']]),'grid_j':str(names[c['j']]),'required_shift_j_minus_i_nT':float(c['difference_i_minus_j']),
                     'matched_bins':c['matched_bins'],'edge_spread_nT':c['spread_nT'],'edge_correlation':c['correlation'],'coverage':c['coverage'],'orientation':c['orientation'],'weight':c['weight']})
    return out,{'mode':'network-edge','applied':True,'edge_width_m':float(edge_width),'max_correction_nT':float(cap),'constraints':cons,'shifts':{str(nm):float(sh) for nm,sh in zip(names,shifts)}}



def _tf_layout_raster(df, step=0.5):
    """Coarse north-up local raster used only for layout boundary matching."""
    from scipy.stats import binned_statistic_2d
    x=df.X.to_numpy(float); y=df.Y.to_numpy(float); z=df.READING.to_numpy(float)
    good=np.isfinite(x)&np.isfinite(y)&np.isfinite(z); x=x[good]; y=y[good]; z=z[good]
    if len(x)<20: return np.empty((0,0),float)
    st=max(0.20,float(step)); xmin,xmax=float(np.nanmin(x)),float(np.nanmax(x)); ymin,ymax=float(np.nanmin(y)),float(np.nanmax(y))
    xe=np.arange(xmin,xmax+st*1.001,st); ye=np.arange(ymin,ymax+st*1.001,st)
    if len(xe)<3 or len(ye)<3: return np.empty((0,0),float)
    g,_,_,_=binned_statistic_2d(x,y,z,statistic='median',bins=(xe,ye)); return np.flipud(g.T)


def _tf_layout_edge_profile(arr, side, edge_cells=3):
    if arr.size==0: return np.array([],float)
    ec=max(1,min(int(edge_cells),max(1,min(arr.shape)//3)))
    if side=='N': strip=arr[:ec,:]; p=np.nanmedian(strip,axis=0)
    elif side=='S': strip=arr[-ec:,:]; p=np.nanmedian(strip,axis=0)
    elif side=='W': strip=arr[:,:ec]; p=np.nanmedian(strip,axis=1)
    else: strip=arr[:,-ec:]; p=np.nanmedian(strip,axis=1)
    p=np.asarray(p,float); good=np.isfinite(p)
    if good.sum()<4: return p
    xi=np.arange(len(p),dtype=float); p2=p.copy(); p2[~good]=np.interp(xi[~good],xi[good],p[good])
    # Remove level and linear edge trend so temporal offsets/broad gradients do not dominate adjacency inference.
    c=np.polyfit(xi,p2,1); p2=p2-np.polyval(c,xi); med=float(np.median(p2)); mad=max(1.4826*float(np.median(np.abs(p2-med))),1e-9)
    return (p2-med)/mad


def _tf_layout_edge_score(arr_a, side_a, arr_b, side_b, edge_cells=3):
    pa=_tf_layout_edge_profile(arr_a,side_a,edge_cells); pb=_tf_layout_edge_profile(arr_b,side_b,edge_cells)
    ga=np.isfinite(pa); gb=np.isfinite(pb)
    if ga.sum()<4 or gb.sum()<4: return {'score':0.0,'corr':0.0,'grad_corr':0.0,'nrmse':99.0}
    n=max(16,min(160,max(len(pa),len(pb)))); t=np.linspace(0,1,n)
    def rs(p):
        good=np.isfinite(p); x=np.linspace(0,1,len(p)); return np.interp(t,x[good],p[good])
    a=rs(pa); b=rs(pb); a-=np.median(a); b-=np.median(b)
    sa=max(1.4826*np.median(np.abs(a-np.median(a))),1e-9); sb=max(1.4826*np.median(np.abs(b-np.median(b))),1e-9)
    a/=sa; b/=sb
    corr=float(np.corrcoef(a,b)[0,1]) if np.std(a)>1e-12 and np.std(b)>1e-12 else 0.0
    da=np.diff(a); db=np.diff(b); gc=float(np.corrcoef(da,db)[0,1]) if np.std(da)>1e-12 and np.std(db)>1e-12 else 0.0
    corr=0.0 if not np.isfinite(corr) else corr; gc=0.0 if not np.isfinite(gc) else gc
    nrmse=float(np.sqrt(np.mean((a-b)**2))); rm=float(np.exp(-0.65*nrmse))
    score=float(np.clip(0.58*((corr+1)/2)+0.22*((gc+1)/2)+0.20*rm,0,1))
    return {'score':score,'corr':corr,'grad_corr':gc,'nrmse':nrmse}


def _tf_infer_layout_from_frames(files,frames,grid_width=0.0,grid_height=0.0,edge_width=2.0,profile_step=0.5,allow_rotations=True,beam_width=350,top_n=3):
    """Infer a rectangular local-grid arrangement from magnetic boundary continuity.

    The search is intentionally confidence-reporting rather than authoritative: it
    evaluates many connected jigsaw-like arrangements, fixes one grid at the origin
    to remove global translation/rotation ambiguity, and returns the best few layouts.
    """
    n=len(frames)
    if n==0: raise ValueError('No grids for layout inference')
    ext=[(float(f.X.max()-f.X.min()),float(f.Y.max()-f.Y.min())) for f in frames]
    gw=float(grid_width) if float(grid_width)>0 else float(np.nanmedian([e[0] for e in ext])); gh=float(grid_height) if float(grid_height)>0 else float(np.nanmedian([e[1] for e in ext]))
    gw=max(gw,1e-6); gh=max(gh,1e-6); step=max(0.20,float(profile_step)); edge_cells=max(1,int(round(float(edge_width)/step)))
    base=[_tf_layout_raster(df,step) for df in frames]; rots=(0,1,2,3) if allow_rotations else (0,)
    arr={(i,r):np.rot90(base[i],r) for i in range(n) for r in rots}
    sides={ (1,0):('E','W'),(-1,0):('W','E'),(0,1):('N','S'),(0,-1):('S','N') }
    cache={}
    def compat(i,ri,j,rj,delta):
        key=(i,ri,j,rj,delta)
        if key in cache: return cache[key]
        sa,sb=sides[delta]; d=_tf_layout_edge_score(arr[(i,ri)],sa,arr[(j,rj)],sb,edge_cells)
        # LINE continuity is weak corroborating evidence only.
        try:
            ai=frames[i].LINE.dropna(); bj=frames[j].LINE.dropna(); bonus=0.0
            if len(ai) and len(bj):
                gap=min(abs(float(ai.max())-float(bj.min())),abs(float(bj.max())-float(ai.min())))
                if gap<=2.0: bonus=0.035
            d=dict(d); d['score']=float(np.clip(d['score']+bonus,0,1)); d['line_bonus']=bonus
        except Exception: pass
        cache[key]=d; return d
    # state: (score_sum, edge_count, placements dict idx:(x,y,rot))
    states=[(0.0,0,{0:(0,0,0)})]
    for _ in range(1,n):
        cand=[]
        for score_sum,ecount,pl in states:
            occupied={(x,y) for x,y,r in pl.values()}; frontier=set()
            for x,y,r in pl.values():
                for dx,dy in sides: 
                    if (x+dx,y+dy) not in occupied: frontier.add((x+dx,y+dy))
            unplaced=[i for i in range(n) if i not in pl]
            for j in unplaced:
                for pos in frontier:
                    x,y=pos
                    for rj in rots:
                        add=0.0; ne=0
                        for dx,dy in sides:
                            nb=(x-dx,y-dy)
                            for i,(xi,yi,ri) in pl.items():
                                if (xi,yi)==nb:
                                    d=compat(i,ri,j,rj,(dx,dy)); add+=d['score']; ne+=1; break
                        if ne==0: continue
                        new=dict(pl); new[j]=(x,y,rj)
                        # tiny compactness preference resolves otherwise equal sprawling arrangements.
                        xs=[v[0] for v in new.values()]; ys=[v[1] for v in new.values()]; area=(max(xs)-min(xs)+1)*(max(ys)-min(ys)+1)
                        rank=score_sum+add-0.004*area
                        cand.append((rank,ecount+ne,new))
        if not cand: break
        # Deduplicate exact placements and retain a diverse high-scoring beam.
        cand.sort(key=lambda x:(x[0]/max(1,x[1]),x[0]),reverse=True); seen=set(); states=[]
        for st in cand:
            key=tuple(sorted((i,*v) for i,v in st[2].items()))
            if key in seen: continue
            seen.add(key); states.append(st)
            if len(states)>=int(beam_width): break
    finals=[]
    for score_sum,ecount,pl in states:
        if len(pl)!=n: continue
        avg=float(score_sum/max(1,ecount)); finals.append((avg,score_sum,ecount,pl))
    if not finals: raise ValueError('Could not construct a connected inferred layout')
    finals.sort(key=lambda x:x[0],reverse=True); finals=finals[:max(1,int(top_n))]
    candidates=[]
    for avg,ss,ec,pl in finals:
        minx=min(v[0] for v in pl.values()); miny=min(v[1] for v in pl.values())
        rows=[]
        for i,(x,y,r) in sorted(pl.items()):
            rows.append({'file':Path(files[i]).name,'offset_x':float((x-minx)*gw),'offset_y':float((y-miny)*gh),'rotation_deg':int((r*90)%360),'grid_x':int(x-minx),'grid_y':int(y-miny)})
        candidates.append({'average_edge_score':avg,'edge_score_sum':float(ss),'adjacency_count':int(ec),'rows':rows})
    best=candidates[0]; second=candidates[1]['average_edge_score'] if len(candidates)>1 else 0.0
    sep=max(0.0,best['average_edge_score']-second); confidence=float(np.clip(0.78*best['average_edge_score']+0.22*min(1.0,sep/0.08),0,1))
    return {'grid_width_m':gw,'grid_height_m':gh,'profile_step_m':step,'edge_width_m':float(edge_width),'confidence':confidence,'best':best,'candidates':candidates}


def _tf_write_layout_products(info,out_csv,report_json=None,preview_png=None,title='Inferred grid layout'):
    import csv as _csv, json as _json
    out_csv=Path(out_csv); out_csv.parent.mkdir(parents=True,exist_ok=True)
    with out_csv.open('w',newline='',encoding='utf-8') as fh:
        w=_csv.DictWriter(fh,fieldnames=['file','offset_x','offset_y','rotation_deg','confidence']); w.writeheader()
        for r in info['best']['rows']:
            w.writerow({'file':r['file'],'offset_x':f"{r['offset_x']:.6f}",'offset_y':f"{r['offset_y']:.6f}",'rotation_deg':r['rotation_deg'],'confidence':f"{info['confidence']:.4f}"})
    if report_json:
        Path(report_json).parent.mkdir(parents=True,exist_ok=True); Path(report_json).write_text(_json.dumps(info,indent=2),encoding='utf-8')
    if preview_png:
        import matplotlib.pyplot as plt
        rows=info['best']['rows']; gw=info['grid_width_m']; gh=info['grid_height_m']
        fig,ax=plt.subplots(figsize=(8,8))
        for r in rows:
            rect=plt.Rectangle((r['offset_x'],r['offset_y']),gw,gh,fill=False,linewidth=2); ax.add_patch(rect)
            ax.text(r['offset_x']+gw/2,r['offset_y']+gh/2,f"{r['file']}\n{r['rotation_deg']}°",ha='center',va='center',fontsize=9)
        ax.set_aspect('equal'); ax.autoscale(); ax.set_xlabel('Local X [m]'); ax.set_ylabel('Local Y [m]'); ax.set_title(f"{title}\nconfidence={info['confidence']:.2f}, edge score={info['best']['average_edge_score']:.2f}")
        ax.grid(True,alpha=.2); Path(preview_png).parent.mkdir(parents=True,exist_ok=True); fig.savefig(preview_png,dpi=180,bbox_inches='tight'); plt.close(fig)
    return out_csv

def _bartington_header(path):
    """Parse a supported companion HDR into typed grid metadata."""
    p=Path(path); text=p.read_text(encoding='utf-8',errors='replace')
    raw={}
    for line in text.splitlines():
        if '=' not in line: continue
        k,v=line.split('=',1); raw[k.strip().lower()]=v.strip()
    def num(key,default=None):
        v=raw.get(key)
        if v is None:return default
        m=re.search(r'[-+]?\d+(?:\.\d+)?',v)
        return float(m.group(0)) if m else default
    g=raw.get('grid size',''); mm=re.search(r'([0-9.]+)\s*x\s*([0-9.]+)',g,re.I)
    return {
        'header_file':str(p),'time':raw.get('time'),'date':raw.get('date'),'grid_number':int(round(num('grid number',0) or 0)),
        'number_of_sensors':int(round(num('number of sensors',1) or 1)),
        'grid_width_m':float(mm.group(1)) if mm else None,'grid_height_m':float(mm.group(2)) if mm else None,
        'collection_method':raw.get('method of collection',''),'starting_direction':raw.get('starting direction',''),
        'data_range':num('data range'),'line_spacing_m':num('line spacing'),'sampling_per_m':num('sampling'),
        'sensor_spacing_m':num('sensor spacing'),'reported_mean':num('mean'),'reported_max':num('max'),'reported_min':num('min'),
        'raw':raw,
    }


def _bartington_companion(dat_path, suffix='.hdr'):
    """Find a same-stem companion metadata/data file case-insensitively."""
    p=Path(dat_path); direct=p.with_suffix(suffix)
    if direct.exists(): return direct
    target=p.stem.lower(); ext=suffix.lower()
    try:
        for q in p.parent.iterdir():
            if q.is_file() and q.stem.lower()==target and q.suffix.lower()==ext: return q
    except Exception:
        pass
    return direct


def _discover_bartington_files(inputs):
    """Return paired DAT files that have companion HDR metadata."""
    out=[]; seen=set()
    for inp in inputs:
        p=Path(inp)
        if p.is_dir():
            cand=sorted([q for q in p.rglob('*') if q.is_file() and q.suffix.lower()=='.dat'],key=_natural_path_key)
        else:
            cand=[p] if p.is_file() and p.suffix.lower()=='.dat' else []
        for q in cand:
            if not _bartington_companion(q,'.hdr').exists(): continue
            key=str(q.resolve())
            if key not in seen: seen.add(key); out.append(q)
    return out


def _bartington_read_pair(dat_path,nodata='auto',saturation='keep'):
    """Read one Grad601 HDR+DAT local grid as X/Y/gradient observations.

    The paired DAT supplied by SW0601 is already an XYZ table.  Empty exported
    cells may be encoded as 2047.5.  Saturated values at the selected ±range are
    reported and are retained by default rather than silently deleting potentially
    real strong archaeological anomalies.
    """
    import pandas as pd
    p=Path(dat_path); hp=_bartington_companion(p,'.hdr')
    if not hp.exists(): raise ValueError(f'{p}: companion HDR is missing')
    meta=_bartington_header(hp)
    try: a=np.loadtxt(p,dtype=float)
    except Exception as exc: raise ValueError(f'{p}: could not read three-column XYZ DAT: {exc}') from exc
    a=np.atleast_2d(a)
    if a.shape[1]<3: raise ValueError(f'{p}: expected X Y gradient columns; found {a.shape[1]} column(s)')
    x=a[:,0].astype(float); y=a[:,1].astype(float); z=a[:,2].astype(float)
    finite=np.isfinite(x)&np.isfinite(y)&np.isfinite(z); sentinel=np.zeros(len(z),bool)
    dr=meta.get('data_range')
    if str(nodata).lower()=='auto':
        # 2047.5 is the common SW0601 empty-cell code. Also reject any value
        # grossly beyond the configured instrument range, never merely ±range.
        sentinel=np.isclose(z,2047.5,rtol=0,atol=1e-9)
        if dr is not None and np.isfinite(dr): sentinel |= np.abs(z)>max(500.0,5.0*abs(float(dr)))
    else:
        try: sentinel=np.isclose(z,float(nodata),rtol=0,atol=1e-9)
        except Exception: raise SystemExit('--nodata-value must be auto or a numeric value.')
    valid=finite&~sentinel
    sat=np.zeros(len(z),bool)
    if dr is not None and np.isfinite(dr) and float(dr)>0: sat=valid&(np.abs(z)>=float(dr)-1e-9)
    if saturation=='nan': valid &= ~sat
    xv=x[valid]; yv=y[valid]; zv=z[valid]
    if len(zv)<4: raise ValueError(f'{p}: too few valid magnetic samples after empty-cell handling')
    # DAT coordinates are authoritative. Reconstruct only acquisition labels for
    # optional traverse processing. East/West traverses run along X (cross-line Y);
    # North/South traverses run along Y (cross-line X). If the HDR direction is
    # absent, infer the cross-line coordinate as the axis with fewer unique centres.
    direction=str(meta.get('starting_direction','')).strip().lower()
    ux=np.unique(np.round(xv,9)); uy=np.unique(np.round(yv,9))
    if direction.startswith(('n','s')):
        cross=xv; along=yv
    elif direction.startswith(('e','w')):
        cross=yv; along=xv
    elif len(ux)<=len(uy):
        cross=xv; along=yv
    else:
        cross=yv; along=xv
    cu=np.sort(np.unique(np.round(cross,9))); line_map={float(v):i for i,v in enumerate(cu)}
    lines=np.array([line_map.get(float(round(v,9)),0) for v in cross],float)
    mark_spacing=5.0; marks=np.floor((along-float(np.nanmin(along)))/mark_spacing).astype(float)
    df=pd.DataFrame({'X':xv,'Y':yv,'READING':zv,'LINE':lines,'MARK':marks,'SOURCE_FILE':p.name})
    meta.update({'file':str(p),'format':'fluxgate-hdr-xyz','units':'nT/m','rows_total':int(len(z)),'rows_valid':int(len(df)),
                 'empty_cells':int(np.sum(sentinel)),'saturated_samples':int(np.sum(sat)),'saturation_policy':saturation,
                 'numeric_mean_valid':float(np.nanmean(zv)),'numeric_median_valid':float(np.nanmedian(zv)),
                 'numeric_min_valid':float(np.nanmin(zv)),'numeric_max_valid':float(np.nanmax(zv)),
                 'line_count':int(len(cu)),'line_axis':('X' if cross is xv else 'Y'),'along_axis':('Y' if along is yv else 'X')})
    return df,meta


def _bartington_despike_raster(arr,sigma=0.0):
    """Conservative 3x3 robust spike replacement for derived fluxgate rasters."""
    out=np.asarray(arr,float).copy(); good=np.isfinite(out)
    if float(sigma)<=0 or good.sum()<20: return out,{'applied':False,'sigma':float(sigma),'replaced':0}
    med=nan_median(out,3); resid=out-med; rr=resid[good&np.isfinite(med)]
    cen=float(np.nanmedian(rr)); rs=max(1.4826*float(np.nanmedian(np.abs(rr-cen))),1e-12)
    mask=good&np.isfinite(med)&(np.abs(resid-cen)>float(sigma)*rs)
    out[mask]=med[mask]
    return out,{'applied':True,'sigma':float(sigma),'robust_residual_sigma':rs,'replaced':int(mask.sum()),'fraction':float(mask.sum()/max(good.sum(),1))}


def _apply_grid_layout_frame(df,offset):
    """Apply local grid offset/quarter-turn rotation without changing sample values."""
    q=df.copy(); dx,dy,ang=offset; x=q.X.to_numpy(float); y=q.Y.to_numpy(float)
    xmin=float(np.nanmin(x)); ymin=float(np.nanmin(y)); xr=x-xmin; yr=y-ymin; th=np.deg2rad(float(ang))
    q['X']=xr*np.cos(th)-yr*np.sin(th)+float(dx); q['Y']=xr*np.sin(th)+yr*np.cos(th)+float(dy)
    return q


def _total_field(argv):
    """Geometrics/caesium total-field archaeological pipeline."""
    import argparse,json,csv
    import pandas as pd
    import matplotlib.pyplot as plt
    p=argparse.ArgumentParser(prog='magsurveypy.py total-field',formatter_class=argparse.RawDescriptionHelpFormatter,
      description='''Process scalar/total-field archaeological magnetometry, especially Geometrics/caesium DAT and STN surveys.

The workflow preserves raw total field, reconstructs STN positions from physical MARK records when present, can generate synthetic LINE/MARK labels from existing XY when labels are absent, applies optional base-station or IGRF temporal correction, optional robust line/mark levelling and grid desloping, assembles multiple local grids, and writes corrected points plus a north-up GeoTIFF.

Scalar total-field profiles are named by their processing behavior. `high-resolution-scalar` emphasizes dense scalar acquisition/resampling with restrained processing; `deslope-highpass` enables per-grid desloping plus an explicit high-pass interpretation branch. Always retain the raw/corrected total-field products.''')
    p.add_argument('input',nargs='+',type=Path,help='One or more Geometrics .dat/.stn files, or directories containing them. DAT with X Y READING TIME DATE LINE MARK is preferred for final processing.')
    p.add_argument('-o','--output',type=Path,required=True); p.add_argument('--site-name',default='Site')
    p.add_argument('--format',choices=('auto','dat','stn'),default='auto'); p.add_argument('--sensor',choices=('1','2','mean'),default='2',help='For raw STN dual-sensor records, select sensor 1, sensor 2 (default, matching common exported DAT), or mean. Mean is only appropriate when both sensors represent effectively co-located total-field observations.')
    p.add_argument('--preset',choices=('none','high-resolution-scalar','deslope-highpass'),default='none',help='Transparent scalar-magnetometry starting profiles. high-resolution-scalar emphasizes dense local scalar processing; deslope-highpass performs per-grid desloping plus a conservative high-pass interpretation branch. The corrected total field is always retained separately.')
    p.add_argument('--base-file',type=Path,default=None,help='Optional stationary base-station DAT/STN. The base variation is interpolated to field timestamps and removed while preserving a selectable reference level.')
    p.add_argument('--base-reference',default='median',help='median (default), first, or numeric nT reference for base-station correction.')
    p.add_argument('--igrf',choices=('none','trend','absolute'),default='none',help='Optional IGRF-14 correction through ppigrf. trend removes only model variation relative to median; absolute subtracts total IGRF field. Requires site lat/lon.')
    p.add_argument('--site-lat',type=float,default=None); p.add_argument('--site-lon',type=float,default=None); p.add_argument('--height-m',type=float,default=0.0)
    p.add_argument('--synthetic-marks',action='store_true',help='If LINE/MARK labels are missing but XY exist, infer line IDs by survey orientation/spacing and create along-line mark bins. Coordinates and readings are not fabricated.')
    p.add_argument('--line-spacing',type=float,default=0.5,metavar='METRES',help='Expected line spacing used only for synthetic LINE inference. Default 0.5 m.')
    p.add_argument('--mark-spacing',type=float,default=5.0,metavar='METRES',help='Artificial mark interval along each inferred line. Default 5 m. Marks are processing constraints/labels, not new measurements.')
    p.add_argument('--line-level',choices=('off','median','linear','mark'),default='off',help='Optional expert point-domain baseline correction. median/linear/mark can remove real broad archaeology when line medians differ for geological reasons; default is off. Prefer --destripe adaptive for routine stripe removal; the corrected reference is retained separately.')
    p.add_argument('--traverse-zero',choices=('off','mean','median','robust'),default='off',help='Derived archaeology-branch traverse zeroing. mean/median/robust subtract each LINE baseline so the derived field is near 0 nT. REFERENCE_READING remains absolute/corrected total field. robust uses a MAD-clipped mean. Do not combine with --line-level unless deliberately comparing methods.')
    p.add_argument('--traverse-zero-sigma',type=float,default=3.5,metavar='SIGMA',help='MAD-sigma clipping threshold for --traverse-zero robust. Default 3.5.')
    p.add_argument('--destripe',choices=('off','protected','adaptive'),default='adaptive',help='Raster-supported acquisition-stripe correction for scalar/total-field grids. adaptive (default) estimates line-to-line acquisition offsets relative to a broad regional field; protected estimates a cross-track correction from robust local comparisons and keeps the base/IGRF-corrected total field separately. off disables it.')
    p.add_argument('--destripe-width',type=float,default=12.0,metavar='METRES',help='Cross-track neighbourhood used to estimate the protected stripe reference. Default: 12 m. Larger values isolate line-to-line offsets from broad archaeology; excessively large values can mix unrelated regional trends.')
    p.add_argument('--destripe-strength',type=float,default=1.0,metavar='0..1',help='Fraction of the protected stripe correction applied to the derived raster. Default: 1.0. The original corrected total field is always retained.')
    p.add_argument('--destripe-max-correction',default='auto',metavar='AUTO|NT',help='Maximum absolute protected stripe correction. auto uses a conservative field-spread-based cap (normally about 2-5 nT); provide a numeric nT value for expert control.')
    p.add_argument('--destripe-smooth',type=float,default=0.15,metavar='METRES',help='Light cross-track smoothing of the estimated stripe correction vector. Default: 0.15 m. This smooths the correction, not the magnetic raster.')
    p.add_argument('--destripe-clip-sigma',type=float,default=3.5,metavar='SIGMA',help='Robust anomaly-protection threshold used while estimating stripe offsets. Default: 3.5 MAD-sigma; smaller values protect more strong anomalies, larger values use more of the field.')
    p.add_argument('--deslope',choices=('off','robust','edge'),default='off',help='Optional broad planar trend removal on the derived branch. robust uses an iteratively protected plane; edge estimates the plane mainly from the outer grid frame to protect central archaeology. Default: off.')
    p.add_argument('--deslope-grid',action='store_true',help=argparse.SUPPRESS)
    p.add_argument('--assemble',choices=('overlap','none'),default='none',help='Assembly mode. none (default) requires an explicit layout CSV for local-coordinate multi-grid surveys; overlap preserves already-common coordinates. Automatic layout guessing is intentionally not provided.')
    p.add_argument('--grid-level',choices=('off','edge','network'),default='network',help='Derived constant matching between physically adjacent local grids after assembly. network (default) compares matched magnetic boundary profiles and solves all grid offsets together; edge is an alias for the same network solver. The corrected total-field reference is never altered. off preserves each grid level exactly.')
    p.add_argument('--grid-edge-width',type=float,default=2.0,metavar='METRES',help='Width of boundary bands used by --grid-level edge. Default: 2 m. Compact extreme anomalies are robustly down-weighted.')
    p.add_argument('--grid-level-max-correction',default='auto',metavar='AUTO|NT',help='Maximum absolute constant shift applied to any derived local grid during edge matching. auto uses a conservative field-spread-based cap; numeric values are nT.')
    p.add_argument('--layout-csv',type=Path,default=None,help='Explicit file,offset_x,offset_y,rotation_deg layout. Overrides automatic filename assembly.')
    p.add_argument('--layout-confidence',type=float,default=0.70,metavar='0..1',help=argparse.SUPPRESS)
    p.add_argument('--layout-edge-width',type=float,default=2.0,metavar='METRES',help=argparse.SUPPRESS)
    p.add_argument('--layout-profile-step',type=float,default=0.5,metavar='METRES',help=argparse.SUPPRESS)
    p.add_argument('--layout-rotations',choices=('off','quarter-turns'),default='off',help=argparse.SUPPRESS)
    p.add_argument('--grid-width',type=float,default=0.0); p.add_argument('--grid-height',type=float,default=0.0)
    p.add_argument('--cell-size',type=float,default=0.25,metavar='METRES'); p.add_argument('--statistic',choices=('median','mean'),default='median'); p.add_argument('--fill-distance',type=float,default=0.5,metavar='METRES')
    p.add_argument('--crs',default='local',help='CRS of assembled coordinates, e.g. EPSG:3844/EPSG:32635, or local (default).')
    p.add_argument('--low-pass',type=float,default=0.0,metavar='METRES',help='Optional Gaussian low-pass on the raster, sigma metres. Prefer the separate filter command for detailed manual filtering.')
    p.add_argument('--high-pass',type=float,default=0.0,metavar='METRES',help='Optional archaeological background-removal scale in metres. 0 off. The subtraction method is selected by --background-method.')
    p.add_argument('--background-method',choices=('gaussian','median'),default='gaussian',help='Broad background estimator for --high-pass and --archaeology-scales. gaussian is smooth and conventional; median is more resistant to compact strong anomalies.')
    p.add_argument('--archaeology-center',choices=('off','mean','median','robust'),default='off',help='Optional final zero-centering of the derived archaeology raster. This subtracts one constant only; amplitudes are not rescaled. median/robust are preferred for archaeology.')
    p.add_argument('--archaeology-scales',default='',metavar='M1,M2,...',help='Optional additional high-pass residual scales, e.g. 5,10,20. Each is exported as a separate archaeology GeoTIFF for multiscale interpretation; the main --high-pass product is unchanged.')
    p.add_argument('--cores',type=int,default=0)
    p.add_argument('--colorbar-position',choices=('right','bottom'),default='bottom',help='Thin comparison colourbars on the right (vertical) or bottom (horizontal). Default: bottom.')
    a=p.parse_args(argv); configure_runtime_cores(a.cores)
    if a.traverse_zero_sigma<=0: raise SystemExit('--traverse-zero-sigma must be > 0.')
    if a.traverse_zero!='off' and a.line_level!='off':
        print('WARNING: --line-level and --traverse-zero are both active. The line-level correction is applied first; traverse-zero then removes each remaining line baseline on the derived branch.',file=sys.stderr,flush=True)
    if not (0.0<=a.destripe_strength<=1.0) or a.destripe_width<=0 or a.destripe_smooth<0 or a.destripe_clip_sigma<=0:
        raise SystemExit('Invalid protected-destripe parameters.')
    if str(a.destripe_max_correction).lower()!='auto':
        try:
            if float(a.destripe_max_correction)<0: raise ValueError
        except Exception:
            raise SystemExit('--destripe-max-correction must be auto or a non-negative nT value.')
    if a.grid_edge_width<=0:
        raise SystemExit('--grid-edge-width must be > 0.')
    if str(a.grid_level_max_correction).lower()!='auto':
        try:
            if float(a.grid_level_max_correction)<0: raise ValueError
        except Exception:
            raise SystemExit('--grid-level-max-correction must be auto or a non-negative nT value.')
    files=[]
    for inp in a.input:
        if inp.is_dir():
            files += sorted(inp.rglob('*.dat'),key=_natural_path_key) + sorted(inp.rglob('*.stn'),key=_natural_path_key)
        elif inp.is_file(): files.append(inp)
    # Prefer DAT when both DAT and STN with same stem exist; DAT already contains mark-derived XY.
    if a.format=='auto':
        datfiles=[f for f in files if f.suffix.lower()=='.dat']
        if datfiles:
            files=datfiles
        else:
            files=[f for f in files if f.suffix.lower()=='.stn']
    elif a.format=='dat': files=[f for f in files if f.suffix.lower()=='.dat']
    else: files=[f for f in files if f.suffix.lower()=='.stn']
    if not files: raise SystemExit('No DAT/STN total-field files found.')
    frames=[]; metas=[]; sensor=1 if a.sensor=='1' else (2 if a.sensor=='2' else 0)
    for f in files:
        try: df=_tf_read_geometrics_dat(f) if f.suffix.lower()=='.dat' else _tf_read_geometrics_stn(f,sensor=sensor)
        except Exception as exc: print(f'SKIP {f}: {exc}',file=sys.stderr); continue
        if a.synthetic_marks and (df.LINE.isna().all() or df.MARK.isna().all()): df=_tf_synthetic_line_marks(df,a.line_spacing,a.mark_spacing)
        raw=df.READING.to_numpy(float).copy(); meta={'file':str(f),'rows':len(df),'raw_median_nT':float(np.nanmedian(raw)),'raw_range_nT':[float(np.nanmin(raw)),float(np.nanmax(raw))],'line_count':int(df.LINE.nunique(dropna=True)),'mark_count':int(df.MARK.nunique(dropna=True))}
        if a.base_file is not None: df,bm=_tf_apply_base(df,a.base_file,sensor=sensor,reference=a.base_reference); meta['base']=bm
        if a.igrf!='none': df,im=_tf_apply_igrf(df,a.igrf,a.site_lat,a.site_lon,a.height_m); meta['igrf']=im
        # REFERENCE_READING is the retained scalar field after only
        # explicit temporal/base/main-field corrections. All spatial levelling
        # remains a derived branch and is auditable.
        df['REFERENCE_READING']=df.READING.to_numpy(float)
        if a.line_level!='off': df,lm=_tf_line_level(df,a.line_level); meta['line_level']=lm
        # Traverse-zero is intentionally delayed until after absolute-field spatial
        # correction/assembly.  This keeps *_total_field_destriped.tif in absolute
        # nT while the archaeology branch receives the explicit zero-traverse step.
        deslope_mode=('robust' if a.deslope_grid else a.deslope)
        if deslope_mode!='off' or a.preset=='deslope-highpass':
            if a.preset=='deslope-highpass' and deslope_mode=='off': deslope_mode='edge'
            df,dm=_tf_deslope_grid(df,deslope_mode); meta['deslope']=dm
        if a.destripe=='adaptive':
            df,sm=_tf_adaptive_destripe_points(df,a.cell_size,a.destripe_width,a.destripe_strength,a.destripe_max_correction,a.destripe_smooth,a.destripe_clip_sigma); meta['protected_destripe']=sm
        elif a.destripe=='protected':
            df,sm=_tf_protected_destripe_points(df,a.cell_size,a.destripe_width,a.destripe_strength,a.destripe_max_correction,a.destripe_smooth,a.destripe_clip_sigma); meta['protected_destripe']=sm
        else:
            df['DESTRIPE_CORRECTION']=0.0; meta['protected_destripe']={'mode':'off','applied':False}
        frames.append(df); metas.append(meta)
    if not frames: raise SystemExit('No total-field files could be parsed.')
    # Layout/assembly.
    offsets={}; layout_info=None
    if a.layout_csv:
        with a.layout_csv.open(newline='',encoding='utf-8-sig') as fh:
            for r in csv.DictReader(fh): offsets[Path(r['file']).name]=(float(r.get('offset_x',0) or 0),float(r.get('offset_y',0) or 0),float(r.get('rotation_deg',0) or 0))
    elif len(frames)>1 and a.assemble=='infer':
        layout_info=_tf_infer_layout_from_frames(files,frames,a.grid_width,a.grid_height,a.layout_edge_width,a.layout_profile_step,a.layout_rotations=='quarter-turns')
        offsets={r['file']:(r['offset_x'],r['offset_y'],r['rotation_deg']) for r in layout_info['best']['rows']}
        print(f"Inferred grid layout: confidence={layout_info['confidence']:.2f}, mean boundary score={layout_info['best']['average_edge_score']:.2f}",flush=True)
    elif len(frames)>1 and a.assemble=='auto':
        # Filename-assisted regular-grid assembly. Use --assemble infer when filenames do not encode the layout.
        om,gw,gh=_tf_layout_offsets(files,frames,'auto',a.grid_width,a.grid_height)
        if om is not None:
            offsets={k:(v[0],v[1],0.0) for k,v in om.items()}
    assembled=[]
    for f,df in zip(files,frames):
        q=df.copy(); key=Path(f).name
        if key in offsets:
            dx,dy,ang=offsets[key]; x=q.X.to_numpy(float); y=q.Y.to_numpy(float); xmin=float(np.nanmin(x)); ymin=float(np.nanmin(y)); xr=x-xmin; yr=y-ymin; th=np.deg2rad(ang); q['X']=xr*np.cos(th)-yr*np.sin(th)+dx; q['Y']=xr*np.sin(th)+yr*np.cos(th)+dy
        assembled.append(q)
    grid_level_info={'mode':'off','applied':False}
    if a.grid_level in {'edge','network'} and len(assembled)>1:
        assembled,grid_level_info=_tf_edge_level_assembled(assembled,[Path(f).name for f in files],a.grid_edge_width,a.grid_level_max_correction)
    else:
        for q in assembled: q['GRID_LEVEL_CORRECTION']=0.0
    # Build a second point branch for archaeology.  Absolute spatial processing
    # (line-level/deslope/destripe/grid matching) remains in `assembled`; only the
    # archaeology copy is zeroed per physical LINE.  Doing this per grid avoids
    # accidental grouping of repeated local LINE numbers across different grids.
    assembled_arch=[]
    for i,q in enumerate(assembled):
        aq=q.copy()
        if a.traverse_zero!='off':
            aq,tm=_tf_traverse_zero(aq,a.traverse_zero,a.traverse_zero_sigma,'nT'); metas[i]['traverse_zero']=tm
        else:
            aq['TRAVERSE_ZERO_CORRECTION']=0.0; metas[i]['traverse_zero']={'mode':'off','applied':False}
        assembled_arch.append(aq)
    allp=pd.concat(assembled,ignore_index=True); allarch=pd.concat(assembled_arch,ignore_index=True); prefix=grid_site_slug(a.site_name)
    root=Path(a.output); ad=root/'ASC'; cd=root/'CSV'; gd=root/'GeoTIFF'; pdout=_native_png_dirs(root)['comparison']; rd=root/'Reports'; [d.mkdir(parents=True,exist_ok=True) for d in (ad,cd,gd,rd)]
    if layout_info is not None:
        _tf_write_layout_products(layout_info,rd/f'{prefix}_inferred_grid_layout.csv',rd/f'{prefix}_grid_layout_candidates.json',pdout/f'{prefix}_inferred_grid_layout.png',title=f'{prefix} inferred grid layout')
        if layout_info['confidence'] < float(a.layout_confidence):
            raise SystemExit(f"Automatic layout confidence {layout_info['confidence']:.2f} is below --layout-confidence {a.layout_confidence:.2f}. Review Reports/{prefix}_inferred_grid_layout.csv or use `mspy layout gui ...` to create the layout manually.")
    # Preserve the absolute/corrected branch and export the archaeology point branch separately.
    csvp=cd/f'{prefix}_total_field_corrected_points.csv'; allp.to_csv(csvp,index=False)
    archcsvp=cd/f'{prefix}_total_field_archaeology_points.csv'; allarch.to_csv(archcsvp,index=False)
    ascp=ad/f'{prefix}_total_field_corrected.asc'; procasc=ad/f'{prefix}_total_field_processed.asc'; archasc=ad/f'{prefix}_total_field_archaeology_points.asc'
    with ascp.open('w',encoding='utf-8') as fh:
        for x,y,z,src in zip(allp.X,allp.Y,allp.REFERENCE_READING,allp.SOURCE_FILE): fh.write(f'{x:.4f}\t{y:.4f}\t{z:.8f}\t{src}\t0\n')
    with procasc.open('w',encoding='utf-8') as fh:
        for x,y,z,src in zip(allp.X,allp.Y,allp.READING,allp.SOURCE_FILE): fh.write(f'{x:.4f}\t{y:.4f}\t{z:.8f}\t{src}\t0\n')
    with archasc.open('w',encoding='utf-8') as fh:
        for x,y,z,src in zip(allarch.X,allarch.Y,allarch.READING,allarch.SOURCE_FILE): fh.write(f'{x:.4f}\t{y:.4f}\t{z:.8f}\t{src}\t0\n')
    refp=allp.copy(); refp['READING']=refp.REFERENCE_READING.to_numpy(float)
    raster_ref,count,observed,transform=_tf_grid_points(refp,a.cell_size,a.statistic,a.fill_distance)
    raster_work,_,_,transform2=_tf_grid_points(allp,a.cell_size,a.statistic,a.fill_distance)
    raster_archbase,_,_,transform_arch=_tf_grid_points(allarch,a.cell_size,a.statistic,a.fill_distance)
    hp=float(a.high_pass); lp=float(a.low_pass)
    if a.preset=='deslope-highpass' and hp<=0: hp=5.0
    processed=raster_archbase.copy()
    if lp>0: processed=nan_gaussian(processed,lp/a.cell_size)
    if hp>0: processed=processed-_tf_background(processed,hp,a.cell_size,a.background_method)
    processed,center_info=_tf_center_raster(processed,a.archaeology_center,a.traverse_zero_sigma)
    # Optional multiscale interpretation products retain true amplitudes; each
    # scale is a separate residual, never a numerical rescaling to a display range.
    scales=[]
    if str(a.archaeology_scales).strip():
        for tok in str(a.archaeology_scales).split(','):
            tok=tok.strip()
            if not tok: continue
            try: val=float(tok)
            except Exception: raise SystemExit('--archaeology-scales must be a comma-separated list of positive metre values, e.g. 5,10,20.')
            if val<=0: raise SystemExit('--archaeology-scales values must be > 0.')
            if val not in scales: scales.append(val)
    rawt=gd/f'{prefix}_total_field_corrected.tif'; dstt=gd/f'{prefix}_total_field_destriped.tif'; proct=gd/f'{prefix}_total_field_archaeology.tif'; countt=gd/f'{prefix}_measurement_density.tif'; remt=gd/f'{prefix}_total_field_preprocessing_removed.tif'
    tags={'software':APP_NAME,'version':APP_VERSION,'author':AUTHOR,'source_files':';'.join(Path(f).name for f in files),'base_station':str(a.base_file) if a.base_file else 'none','igrf':a.igrf,'line_level':a.line_level,'traverse_zero':a.traverse_zero,'destripe':a.destripe,'destripe_width_m':a.destripe_width,'deslope_mode':('robust' if a.deslope_grid else a.deslope),'preset':a.preset,'background_method':a.background_method,'archaeology_center':a.archaeology_center}
    _archaeomag_write_like(rawt,raster_ref,transform,a.crs,{**tags,'product':'corrected scalar total magnetic field reference','warning':'Preservation-first reference after explicit base/IGRF correction only; spatial stripe/line processing is written separately.'},'Total magnetic field [nT]')
    _archaeomag_write_like(dstt,raster_work,transform2,a.crs,{**tags,'product':'derived destriped total magnetic field','warning':'Derived spatial correction; compare with corrected reference and preprocessing-removed raster.'},'Destriped field [nT]')
    _archaeomag_write_like(remt,raster_ref-raster_work,transform,a.crs,{**tags,'product':'total-field spatial preprocessing removed component'},'Removed preprocessing [nT]')
    _archaeomag_write_like(proct,processed,transform_arch,a.crs,{**tags,'product':'derived archaeology total-field raster','high_pass_m':hp,'low_pass_m':lp,'centering_offset_nT':center_info.get('offset',0.0),'warning':'Derived processing branch; corrected total-field reference is retained separately. Values are residual nT amplitudes, not display-rescaled.'},'Archaeological magnetic anomaly [nT]')
    multiscale_products=[]
    scale_source=raster_archbase.copy()
    if lp>0: scale_source=nan_gaussian(scale_source,lp/a.cell_size)
    for sc in scales:
        arr=scale_source-_tf_background(scale_source,sc,a.cell_size,a.background_method)
        arr,ci=_tf_center_raster(arr,a.archaeology_center,a.traverse_zero_sigma)
        token=(f'{sc:g}').replace('.','p')
        qp=gd/f'{prefix}_total_field_archaeology_hp_{token}m.tif'
        _archaeomag_write_like(qp,arr,transform_arch,a.crs,{**tags,'product':'multiscale archaeological total-field residual','high_pass_m':sc,'centering_offset_nT':ci.get('offset',0.0)},'Archaeological magnetic anomaly [nT]')
        multiscale_products.append(str(qp))
    _archaeomag_write_like(countt,np.where(count>0,count,np.nan),transform,a.crs,{**tags,'units':'count','product':'measurement density'},'Measurement count')
    refmed=float(np.nanmedian(raster_ref)); reflim=max(float(np.nanpercentile(np.abs(raster_ref-refmed),98)),1e-9)
    workmed=float(np.nanmedian(raster_work)); worklim=max(float(np.nanpercentile(np.abs(raster_work-workmed),98)),1e-9)
    pmed=float(np.nanmedian(processed)); plim=max(float(np.nanpercentile(np.abs(processed-pmed),98)),1e-9)
    fig,axs=plt.subplots(1,3,figsize=(17.2,5.1),constrained_layout=False)
    fig.subplots_adjust(left=.025,right=.985,bottom=.18,top=.91,wspace=.13)
    ims=[]
    for ax,dat,title,med,lim in zip(axs,[raster_ref,raster_work,processed],['Corrected reference','Destriped candidate','Archaeology branch'],[refmed,workmed,pmed],[reflim,worklim,plim]):
        im=ax.imshow(dat,origin='upper',cmap='gray_r',vmin=med-lim,vmax=med+lim); ims.append(im); ax.set_title(title); ax.set_axis_off()
    # Individual scales avoid implying that the high-pass branch has the same absolute offset as total field.
    # Each bar is attached to its panel so the long dimension cannot exceed the rendered panel.
    for ax,im in zip(axs,ims):
        _publication_colorbar(fig,ax,im,'nT',a.colorbar_position,fontsize=7.5)
    fig.savefig(pdout/f'{prefix}_total_field_comparison.png',dpi=220,bbox_inches='tight',pad_inches=.06); plt.close(fig)
    rep={'software_version':APP_VERSION,'application':APP_NAME,'site':prefix,'input_files':[str(f) for f in files],'file_qc':metas,'rows':len(allp),'assembly_offsets':{k:list(v) for k,v in offsets.items()},'grid_level':grid_level_info,'cell_size_m':a.cell_size,'statistic':a.statistic,'fill_distance_m':a.fill_distance,'base_file':str(a.base_file) if a.base_file else None,'igrf_mode':a.igrf,'line_level':a.line_level,'traverse_zero':a.traverse_zero,'traverse_zero_sigma':a.traverse_zero_sigma,'destripe':a.destripe,'destripe_width_m':a.destripe_width,'destripe_strength':a.destripe_strength,'destripe_max_correction':a.destripe_max_correction,'synthetic_marks':a.synthetic_marks,'preset':a.preset,'high_pass_m':hp,'background_method':a.background_method,'archaeology_center':center_info,'archaeology_scales_m':scales,'low_pass_m':lp,'products':{'corrected_points_csv':str(csvp),'archaeology_points_csv':str(archcsvp),'corrected_asc':str(ascp),'processed_asc':str(procasc),'archaeology_points_asc':str(archasc),'corrected_total_field':str(rawt),'destriped_total_field':str(dstt),'preprocessing_removed':str(remt),'archaeology_raster':str(proct),'multiscale_archaeology':multiscale_products,'density':str(countt)},'processing_note':'Preservation-first absolute/corrected total field and the spatially corrected absolute branch remain in nT near the geomagnetic field level. Traverse zeroing and background removal are applied only to a separately exported archaeology point/raster branch. Residual amplitudes remain true nT and are never rescaled to a display interval.'}
    (rd/f'{prefix}_total_field_report.json').write_text(json.dumps(rep,indent=2,default=str),encoding='utf-8')
    print(f'Total-field corrected reference: {rawt}\nDestriped raster: {dstt}\nArchaeology branch: {proct}\nCorrected points: {csvp}\nArchaeology points: {archcsvp}',flush=True)
    return 0

def _bartington_fluxgate(argv):
    '''Fluxgate/gradiometer archaeological grid pipeline.'''
    import argparse,csv,json
    import pandas as pd
    import matplotlib.pyplot as plt
    p=argparse.ArgumentParser(prog='mspy survey grid --protocol fluxgate',formatter_class=argparse.RawDescriptionHelpFormatter,
      description='Process supported paired metadata + data local grids as fluxgate/gradiometer data.\n\nSample coordinates are preserved exactly. Companion metadata can supply grid geometry, acquisition metadata, selected range and sensor configuration. Recognized invalid/saturation cells are handled by the established adapter. The original assembled gradient field is retained separately from traverse/grid levelling, despiking and filtering.',
      epilog='Example:\n  mspy survey grid --project Site --protocol fluxgate --workflow archaeology --cell-size 0.25\n\nFor multiple local grids create Layouts/grid_layout.csv first with:\n  mspy layout gui --project Site --protocol fluxgate')
    p.add_argument('input',nargs='+',type=Path,help='Paired .dat/.hdr files or directories containing them.')
    p.add_argument('-o','--output',type=Path,required=True); p.add_argument('--site-name',default='Site')
    p.add_argument('--layout-csv',type=Path,default=None,help='Explicit file,offset_x,offset_y,rotation_deg layout for multiple local grids.')
    p.add_argument('--assemble',choices=('none','overlap'),default='none',help='none requires a layout for multiple overlapping local grids; overlap is only for files already in one common coordinate system.')
    p.add_argument('--grid-level',choices=('off','network'),default='network',help='Solve conservative constant offsets between physically adjacent assembled grids on the derived branch. The reference gradient field is unchanged.')
    p.add_argument('--grid-edge-width',type=float,default=2.0,metavar='METRES')
    p.add_argument('--grid-level-max-correction',default='auto',metavar='AUTO|NT/M')
    p.add_argument('--traverse-zero',choices=('off','mean','median','robust'),default='off',help='Optional per-traverse zeroing on the derived fluxgate branch. robust uses a MAD-clipped mean; median is a common archaeological zero-mean-traverse analogue.')
    p.add_argument('--traverse-zero-sigma',type=float,default=3.5)
    p.add_argument('--despike-sigma',type=float,default=0.0,metavar='SIGMA',help='Conservative 3x3 raster despike threshold. 0 disables. Values >=6 are intentionally conservative.')
    p.add_argument('--low-pass',type=float,default=0.0,metavar='METRES',help='Optional Gaussian smoothing sigma in metres. 0 off.')
    p.add_argument('--high-pass',type=float,default=0.0,metavar='METRES',help='Optional broad background-removal scale. Fluxgate gradient data often need no high-pass; use only when justified.')
    p.add_argument('--background-method',choices=('gaussian','median'),default='gaussian')
    p.add_argument('--center',choices=('off','mean','median','robust'),default='median',help='Subtract one final constant from the derived archaeology raster. Default median. This does not rescale amplitudes.')
    p.add_argument('--nodata-value',default='auto',metavar='AUTO|VALUE',help='Empty DAT cell code. auto recognises the common 2047.5 sentinel when inconsistent with the HDR range.')
    p.add_argument('--saturation-policy',choices=('keep','nan'),default='keep',help='Values exactly at the selected +/- Data Range are reported as saturated. keep (default) preserves them; nan removes them from derived gridding.')
    p.add_argument('--cell-size',type=float,default=0.25,metavar='METRES'); p.add_argument('--statistic',choices=('median','mean'),default='median'); p.add_argument('--fill-distance',type=float,default=0.5,metavar='METRES')
    p.add_argument('--crs',default='local'); p.add_argument('--cores',type=int,default=0); p.add_argument('--colorbar-position',choices=('right','bottom'),default='bottom')
    a=p.parse_args(argv); configure_runtime_cores(a.cores)
    if a.cell_size<=0 or a.fill_distance<0 or a.grid_edge_width<=0 or a.traverse_zero_sigma<=0 or a.despike_sigma<0 or a.low_pass<0 or a.high_pass<0:
        raise SystemExit('Invalid fluxgate processing parameter: distances/sigmas must be non-negative and cell/grid widths positive.')
    files=_discover_bartington_files(a.input)
    if not files: raise SystemExit('No paired fluxgate/gradiometer .dat + .hdr files found.')
    good_files=[]; frames_ref=[]; frames_work=[]; metas=[]
    for f in files:
        try: df,meta=_bartington_read_pair(f,a.nodata_value,a.saturation_policy)
        except Exception as exc: print(f'SKIP {f}: {exc}',file=sys.stderr); continue
        df['REFERENCE_READING']=df.READING.to_numpy(float)
        frames_ref.append(df.copy()); q=df.copy()
        if a.traverse_zero!='off': q,tm=_tf_traverse_zero(q,a.traverse_zero,a.traverse_zero_sigma,'nT/m'); meta['traverse_zero']=tm
        else: q['TRAVERSE_ZERO_CORRECTION']=0.0
        good_files.append(f); frames_work.append(q); metas.append(meta)
    files=good_files
    if not frames_work: raise SystemExit('No fluxgate/gradiometer grids could be parsed.')
    offsets={}
    if a.layout_csv:
        with a.layout_csv.open(newline='',encoding='utf-8-sig') as fh:
            for r in csv.DictReader(fh): offsets[Path(r['file']).name]=(float(r.get('offset_x',0) or 0),float(r.get('offset_y',0) or 0),float(r.get('rotation_deg',0) or 0))
        missing=[f.name for f in files if f.name not in offsets]
        if missing: raise SystemExit('Layout CSV does not assign: '+', '.join(missing))
    elif len(frames_work)>1 and a.assemble!='overlap':
        raise SystemExit('Multiple fluxgate/gradiometer local grids found. Create a layout with `mspy layout gui --project PROJECT` or supply --layout-csv. Use --assemble overlap only when coordinates are already common.')
    assembled_ref=[]; assembled_work=[]
    for f,rf,wf in zip(files,frames_ref,frames_work):
        if f.name in offsets:
            assembled_ref.append(_apply_grid_layout_frame(rf,offsets[f.name])); assembled_work.append(_apply_grid_layout_frame(wf,offsets[f.name]))
        else:
            assembled_ref.append(rf.copy()); assembled_work.append(wf.copy())
    grid_level_info={'mode':'off','applied':False}
    if a.grid_level=='network' and len(assembled_work)>1:
        assembled_work,grid_level_info=_tf_edge_level_assembled(assembled_work,[f.name for f in files],a.grid_edge_width,a.grid_level_max_correction)
    else:
        for q in assembled_work: q['GRID_LEVEL_CORRECTION']=0.0
    allref=pd.concat(assembled_ref,ignore_index=True); allp=pd.concat(assembled_work,ignore_index=True); prefix=grid_site_slug(a.site_name)
    root=Path(a.output); ad=root/'ASC'; cd=root/'CSV'; gd=root/'GeoTIFF'; pdout=_native_png_dirs(root)['comparison']; rd=root/'Reports'; [d.mkdir(parents=True,exist_ok=True) for d in (ad,cd,gd,rd)]
    csvp=cd/f'{prefix}_fluxgate_points.csv'; allp.to_csv(csvp,index=False)
    refasc=ad/f'{prefix}_fluxgate_reference.asc'; procasc=ad/f'{prefix}_fluxgate_processed.asc'
    with refasc.open('w',encoding='utf-8') as fh:
        for x,y,z,src in zip(allref.X,allref.Y,allref.REFERENCE_READING,allref.SOURCE_FILE): fh.write(f'{x:.4f}\t{y:.4f}\t{z:.8f}\t{src}\t0\n')
    with procasc.open('w',encoding='utf-8') as fh:
        for x,y,z,src in zip(allp.X,allp.Y,allp.READING,allp.SOURCE_FILE): fh.write(f'{x:.4f}\t{y:.4f}\t{z:.8f}\t{src}\t0\n')
    rp=allref.copy(); rp['READING']=rp.REFERENCE_READING.to_numpy(float)
    raster_ref,count,observed,transform=_tf_grid_points(rp,a.cell_size,a.statistic,a.fill_distance)
    raster_work,_,_,transform2=_tf_grid_points(allp,a.cell_size,a.statistic,a.fill_distance)
    raster_work,despike_info=_bartington_despike_raster(raster_work,a.despike_sigma)
    processed=raster_work.copy()
    if a.low_pass>0: processed=nan_gaussian(processed,a.low_pass/a.cell_size)
    if a.high_pass>0: processed=processed-_tf_background(processed,a.high_pass,a.cell_size,a.background_method)
    processed,center_info=_tf_center_raster(processed,a.center,a.traverse_zero_sigma)
    reft=gd/f'{prefix}_fluxgate_reference.tif'; workt=gd/f'{prefix}_fluxgate_processed.tif'; archt=gd/f'{prefix}_fluxgate_archaeology.tif'; countt=gd/f'{prefix}_measurement_density.tif'
    tags={'software':APP_NAME,'version':APP_VERSION,'author':AUTHOR,'acquisition_class':'fluxgate/gradiometer grid','units':'nT/m','source_files':';'.join(f.name for f in files),'traverse_zero':a.traverse_zero,'grid_level':a.grid_level,'despike_sigma':a.despike_sigma,'background_method':a.background_method,'high_pass_m':a.high_pass,'low_pass_m':a.low_pass,'center':a.center}
    _archaeomag_write_like(reft,raster_ref,transform,a.crs,{**tags,'product':'assembled measured fluxgate gradient reference'},'Magnetic gradient [nT/m]')
    _archaeomag_write_like(workt,raster_work,transform2,a.crs,{**tags,'product':'derived levelled/despiked fluxgate gradient'},'Processed magnetic gradient [nT/m]')
    _archaeomag_write_like(archt,processed,transform2,a.crs,{**tags,'product':'derived archaeological fluxgate gradient','centering_offset':center_info.get('offset',0.0),'warning':'Derived archaeology branch; original assembled gradient reference retained separately.'},'Archaeological magnetic gradient [nT/m]')
    _archaeomag_write_like(countt,np.where(count>0,count,np.nan),transform,a.crs,{**tags,'units':'count','product':'measurement density'},'Measurement count')
    refmed=float(np.nanmedian(raster_ref)); reflim=max(float(np.nanpercentile(np.abs(raster_ref-refmed),98)),1e-9); pmed=float(np.nanmedian(processed)); plim=max(float(np.nanpercentile(np.abs(processed-pmed),98)),1e-9)
    fig,axs=plt.subplots(1,2,figsize=(11,5),constrained_layout=True); im0=axs[0].imshow(raster_ref,origin='upper',cmap='gray_r',vmin=refmed-reflim,vmax=refmed+reflim); axs[0].set_title('Fluxgate assembled reference'); im1=axs[1].imshow(processed,origin='upper',cmap='gray_r',vmin=pmed-plim,vmax=pmed+plim); axs[1].set_title('Archaeology branch')
    for ax,im in zip(axs,(im0,im1)): ax.set_axis_off(); _publication_colorbar(fig,ax,im,'nT/m',a.colorbar_position,fontsize=7.5)
    fig.savefig(pdout/f'{prefix}_fluxgate_comparison.png',dpi=220,bbox_inches='tight',pad_inches=.06); plt.close(fig)
    report={'software_version':APP_VERSION,'application':APP_NAME,'acquisition_class':'fluxgate/gradiometer grid','units':'nT/m','site':prefix,'files':[str(f) for f in files],'headers':metas,'rows_valid':int(len(allp)),'assembly_offsets':{k:list(v) for k,v in offsets.items()},'grid_level':grid_level_info,'traverse_zero':a.traverse_zero,'despike':despike_info,'cell_size_m':a.cell_size,'statistic':a.statistic,'fill_distance_m':a.fill_distance,'low_pass_m':a.low_pass,'high_pass_m':a.high_pass,'background_method':a.background_method,'center':center_info,'products':{'reference_asc':str(refasc),'processed_asc':str(procasc),'points_csv':str(csvp),'reference_raster':str(reft),'processed_raster':str(workt),'archaeology_raster':str(archt),'density':str(countt)},'scientific_note':'Fluxgate gradiometer data are processed independently of scalar total-field data. HDR geometry and DAT XYZ coordinates are preserved. 2047.5 empty cells are excluded; +/- range saturation is reported and retained unless --saturation-policy nan is chosen.'}
    rpout=rd/f'{prefix}_fluxgate_report.json'; rpout.write_text(json.dumps(report,indent=2,default=str),encoding='utf-8')
    print(f'Fluxgate reference: {reft}\nFluxgate archaeology branch: {archt}\nReport: {rpout}',flush=True)
    return 0


def _legacy_main(argv=None):
    argv=list(sys.argv[1:] if argv is None else argv)
    if not argv or argv[0] in {'-h','--help'}:
        print(_TOP_HELP.strip()); return 0
    if argv[0] in {'-V','--version','version'}:
        _app_banner()
        print(f'{APP_NAME} {APP_VERSION} — {APP_AUTHOR} — {APP_WEBSITE}'); return 0
    cmd=argv.pop(0)
    argv,results_root,project=_extract_global_routing(argv)
    if argv and argv[0] in {'-h','--help'}:
        if cmd in {'prm','process','assemble','grid','point-grid','enhance','thin','overlap-clean','denoise','denoise-adaptive','surface-compare','interpolate-site','clean-map','regularize-points','presentation','filter','total-field','bartington','background','plough','reproject','segment','image','gnss','rtk','auto','doctor'}:
            return _print_command_help(cmd)
        if cmd=='guide':
            return _print_guide(None)
    argv=_route_output_argv(cmd,argv,results_root,project)
    if cmd=='doctor': _app_banner(); return _doctor()
    if cmd=='help':
        if not argv: print(_TOP_HELP.strip()); return 0
        return _print_command_help(argv[0])
    if cmd=='guide':
        return _print_guide(argv[0] if argv else None)
    if cmd=='help-all':
        print(_TOP_HELP.strip())
        for c in ('prm','process','assemble','grid','point-grid','enhance','thin','overlap-clean','denoise','denoise-adaptive','surface-compare','interpolate-site','clean-map','regularize-points','presentation','filter','total-field','bartington','background','plough','reproject','segment','image','gnss','rtk'):
            print('\n\n'+'#'*90+f'\n# FULL HELP: {c}\n'+'#'*90)
            _print_command_help(c)
        return 0
    if cmd=='surface-compare':
        _app_banner()
        return _v12_surface_compare(argv)
    if cmd=='interpolate-site':
        _app_banner()
        return _archaeology_interpolate(argv)

    if cmd=='denoise-adaptive':
        _app_banner()
        return _v12_adaptive_denoise(argv)

    if cmd=='clean-map':
        _app_banner()
        return _v123_clean_map(argv)

    if cmd=='regularize-points':
        _app_banner()
        return _v123_regularize_points(argv)

    if cmd=='ai-corpus':
        _app_banner(); return _ai_corpus(argv)
    if cmd=='ai-prepare':
        _app_banner(); return _ai_prepare(argv)
    if cmd=='ai-train':
        _app_banner(); return _ai_train(argv)
    if cmd=='ai-enhance':
        _app_banner(); return _ai_enhance(argv)

    if cmd=='presentation':
        _app_banner(); return _presentation_display(argv)
    if cmd=='filter':
        _app_banner(); return _manual_filter(argv)
    if cmd=='total-field':
        _app_banner(); return _total_field(argv)
    if cmd=='bartington':
        _app_banner(); return _bartington_fluxgate(argv)

    if cmd=='point-grid':
        _app_banner(); os.environ['MULTIMAG_CHILD']='1'; return _run_command('grid',['--grid-source','points',*argv])
    if cmd=='rtk':
        _app_banner(); os.environ['MULTIMAG_CHILD']='1'; return _run_command('gnss',argv)
    if cmd=='assemble':
        _app_banner(); os.environ['MULTIMAG_CHILD']='1'; return _run_command('assemble',argv)
    if cmd=='reproject':
        _app_banner(); os.environ['MULTIMAG_CHILD']='1'; return _reproject_wrapper(argv)
    if cmd=='auto':
        if not argv or argv[0] in {'-h','--help'}:
            return _print_command_help('auto')
        target=Path(argv[0])
        actual='prm' if target.is_dir() or target.suffix.lower()=='.prm' else 'process'
        _app_banner(); print(f'AUTO input detection -> {actual}',flush=True)
        os.environ['MULTIMAG_CHILD']='1'
        return _run_command(actual,argv)
    if cmd=='thin':
        _app_banner(); os.environ['MULTIMAG_CHILD']='1'; return _thin_wrapper(argv)
    if cmd=='overlap-clean':
        _app_banner(); os.environ['MULTIMAG_CHILD']='1'; return _overlap_wrapper(argv)
    if cmd=='denoise':
        _app_banner(); os.environ['MULTIMAG_CHILD']='1'; return _denoise_wrapper(argv)
    if cmd=='background':
        _app_banner(); os.environ['MULTIMAG_CHILD']='1'; return _background_wrapper(argv)
    if cmd=='plough':
        _app_banner(); os.environ['MULTIMAG_CHILD']='1'; return _plough_wrapper(argv)
    if cmd not in {'prm','process','grid','enhance','segment','image','gnss'}:
        raise SystemExit(f'Unknown command: {cmd}\n\nUse `python {Path(sys.argv[0]).name} --help`.')
    _app_banner(); os.environ['MULTIMAG_CHILD']='1'
    return _run_command(cmd,argv)


# --- MagSurveyPy grouped user interface -------------------------------------
# Public guide cleanup for the grouped interface.
_GUIDE_TOPICS.pop('track-surface',None)
_GUIDE_TOPICS.update({
'projects': '''PROJECTS
Projects are ordinary folders below Results/. Use `project init`, `project list`, `project status` and `project tree`. Simple output names are routed to Results/PROJECT/STAGE; absolute paths remain untouched. No database or proprietary project format is required.''',
'layout': '''TOTAL-FIELD GRID LAYOUT
Use `layout infer` when local grid coordinates overlap and the field layout is unknown. Magnetic boundary profiles, gradient continuity and weak LINE evidence are combined into a globally consistent candidate network with confidence. Use `layout gui` for the manual matrix editor and `layout validate` before final processing. Low-confidence inference should be reviewed, not forced.''',
'command-groups': '''COMMAND GROUPS
The public CLI is organised as project, survey, layout, process, gnss and tools. `survey` handles initial field data; `process` handles derived rasters; `layout` handles local total-field grid networks. Run `help GROUP COMMAND` for complete scientific options.'''
})


def _has_opt(argv,name):
    return any(str(x)==name or str(x).startswith(name+'=') for x in argv)


def _inject_before_positionals(argv, items):
    # argparse accepts options after positionals, so simply append convenience defaults.
    out=list(argv)
    for k,v in items:
        if not _has_opt(out,k):
            out.append(k)
            if v is not None: out.append(str(v))
    return out


def _discover_total_field_files(inputs, fmt='auto'):
    files=[]
    for inp in inputs:
        p=Path(inp)
        if p.is_dir():
            files += sorted(p.rglob('*.dat'),key=_natural_path_key)+sorted(p.rglob('*.stn'),key=_natural_path_key)
        elif p.is_file(): files.append(p)
    if fmt=='auto':
        dat=[f for f in files if f.suffix.lower()=='.dat']; files=dat if dat else [f for f in files if f.suffix.lower()=='.stn']
    elif fmt=='dat': files=[f for f in files if f.suffix.lower()=='.dat']
    elif fmt=='stn': files=[f for f in files if f.suffix.lower()=='.stn']
    # natural dedupe
    seen=set(); out=[]
    for f in files:
        r=str(f.resolve())
        if r not in seen: seen.add(r); out.append(f)
    return out


def _layout_infer_cli(argv):
    import argparse,json
    p=argparse.ArgumentParser(prog='magsurveypy.py layout infer',formatter_class=argparse.RawDescriptionHelpFormatter,
      description='''Infer the arrangement of local total-field grids from their measured data.

Each candidate shared boundary is compared after removing absolute level and broad linear edge trend. The score uses magnetic-profile correlation, gradient continuity and robust shape error. LINE continuity is only weak supporting evidence. A beam search then solves the complete connected grid arrangement rather than accepting each neighbour independently.

The result is a normal layout CSV which can be inspected, edited, reused, or opened in `layout gui`. Automatic inference is deliberately confidence-reporting: magnetically quiet or repetitive sites may be ambiguous.''')
    p.add_argument('input',nargs='+',type=Path,help='DAT/STN files or directories containing local grids.')
    p.add_argument('-o','--output',type=Path,required=True,help='Output layout CSV.')
    p.add_argument('--format',choices=('auto','dat','stn'),default='auto')
    p.add_argument('--grid-width',type=float,default=0.0,metavar='M',help='Known grid width. 0 estimates the median from data extents.')
    p.add_argument('--grid-height',type=float,default=0.0,metavar='M',help='Known grid height. 0 estimates the median from data extents.')
    p.add_argument('--edge-width',type=float,default=2.0,metavar='M',help='Boundary band used to compare neighbouring grids. Default 2 m.')
    p.add_argument('--profile-step',type=float,default=0.5,metavar='M',help='Along-edge comparison sampling. Default 0.5 m.')
    p.add_argument('--rotations',choices=('off','quarter-turns'),default='quarter-turns',help='Allow 0/90/180/270 degree grid rotations. Default quarter-turns.')
    p.add_argument('--top',type=int,default=3,help='Number of candidate layouts stored in the JSON report. Default 3.')
    p.add_argument('--confidence',type=float,default=0.70,metavar='0..1',help='Confidence level considered high enough for unattended assembly. The CSV is still written below this value for manual review.')
    p.add_argument('--cores',type=int,default=0)
    a=p.parse_args(argv); configure_runtime_cores(a.cores)
    files=_discover_total_field_files(a.input,a.format)
    if len(files)<2: raise SystemExit('Layout inference needs at least two DAT/STN grid files.')
    frames=[]
    for f in files:
        try: frames.append(_tf_read_geometrics_dat(f) if f.suffix.lower()=='.dat' else _tf_read_geometrics_stn(f))
        except Exception as exc: raise SystemExit(f'Cannot read {f}: {exc}')
    with stage_progress('Grid-layout magnetic boundary matching'):
        info=_tf_infer_layout_from_frames(files,frames,a.grid_width,a.grid_height,a.edge_width,a.profile_step,a.rotations=='quarter-turns',top_n=a.top)
    report=a.output.with_name(a.output.stem+'_candidates.json'); preview=a.output.with_name(a.output.stem+'_preview.png')
    _tf_write_layout_products(info,a.output,report,preview)
    print(f'Inferred layout CSV: {a.output}')
    print(f'Candidate report: {report}')
    print(f'Preview: {preview}')
    print(f"Overall confidence: {info['confidence']:.2f}; mean matched-edge score: {info['best']['average_edge_score']:.2f}")
    if info['confidence']<a.confidence:
        print('WARNING: layout is ambiguous. Review the preview/candidate report or open `layout gui` before processing.',flush=True)
    return 0


def _layout_validate_cli(argv):
    import argparse,csv,json
    p=argparse.ArgumentParser(prog='magsurveypy.py layout validate',formatter_class=argparse.RawDescriptionHelpFormatter,
      description='Validate a reusable local-grid layout for total-field or fluxgate/gradiometer grids, check duplicate assignments/overlaps, and calculate magnetic continuity along adjacent boundaries.')
    p.add_argument('input',nargs='+',type=Path); p.add_argument('--layout-csv',type=Path,required=True)
    p.add_argument('--instrument',choices=('total-field','bartington'),default='total-field'); p.add_argument('--format',choices=('auto','dat','stn'),default='auto'); p.add_argument('--edge-width',type=float,default=2.0)
    p.add_argument('-o','--output',type=Path,default=None,help='Optional JSON validation report.')
    a=p.parse_args(argv)
    files=_discover_bartington_files(a.input) if a.instrument=='bartington' else _discover_total_field_files(a.input,a.format); by={f.name:f for f in files}
    rows=[]
    with a.layout_csv.open(newline='',encoding='utf-8-sig') as fh:
        for r in csv.DictReader(fh): rows.append(r)
    if not rows: raise SystemExit('Layout CSV contains no rows.')
    used=[]; frames=[]; names=[]; offsets=[]
    for r in rows:
        nm=Path(r.get('file','')).name
        if nm not in by: raise SystemExit(f'Layout references missing file: {nm}')
        if nm in used: raise SystemExit(f'Layout assigns the same file more than once: {nm}')
        used.append(nm); f=by[nm]
        q=_bartington_read_pair(f)[0] if a.instrument=='bartington' else (_tf_read_geometrics_dat(f) if f.suffix.lower()=='.dat' else _tf_read_geometrics_stn(f))
        dx=float(r.get('offset_x',0) or 0); dy=float(r.get('offset_y',0) or 0); ang=float(r.get('rotation_deg',0) or 0)
        x=q.X.to_numpy(float); y=q.Y.to_numpy(float); xmin=float(np.nanmin(x)); ymin=float(np.nanmin(y)); xr=x-xmin; yr=y-ymin; th=np.deg2rad(ang)
        q['X']=xr*np.cos(th)-yr*np.sin(th)+dx; q['Y']=xr*np.sin(th)+yr*np.cos(th)+dy
        frames.append(q); names.append(nm); offsets.append((dx,dy,ang))
    boxes=[(float(q.X.min()),float(q.X.max()),float(q.Y.min()),float(q.Y.max())) for q in frames]
    overlaps=[]
    for i in range(len(boxes)):
        for j in range(i+1,len(boxes)):
            a0,a1,b0,b1=boxes[i]; c0,c1,d0,d1=boxes[j]; ox=max(0,min(a1,c1)-max(a0,c0)); oy=max(0,min(b1,d1)-max(b0,d0))
            if ox>0.5 and oy>0.5: overlaps.append({'grid_i':names[i],'grid_j':names[j],'overlap_m2':float(ox*oy)})
    # Reuse network edge matcher without retaining corrected values.
    _,edge=_tf_edge_level_assembled(frames,names,a.edge_width,'auto')
    report={'instrument':a.instrument,'layout_csv':str(a.layout_csv),'files':names,'unassigned_files':[x for x in by if x not in used],'overlaps':overlaps,'edge_continuity':edge,
            'status':'PASS' if not overlaps and not [x for x in by if x not in used] else 'REVIEW'}
    if a.output: Path(a.output).write_text(json.dumps(report,indent=2),encoding='utf-8'); print(f'Report: {a.output}')
    print(f"Layout validation: {report['status']}; assigned {len(used)}/{len(by)} files; overlaps={len(overlaps)}; matched boundaries={len(edge.get('constraints',[]))}")
    return 0


def _layout_gui_cli(argv):
    import argparse,csv,math
    p=argparse.ArgumentParser(prog='magsurveypy.py layout gui',formatter_class=argparse.RawDescriptionHelpFormatter,
      description='''Open the manual local-grid layout editor for total-field or fluxgate/gradiometer surveys.

Assign each discovered grid to a matrix cell, choose 0/90/180/270 degree rotation, preview the network and save one reusable layout CSV. Row 1 is the TOP of the displayed network; Y increases upward.''')
    p.add_argument('input',nargs='+',type=Path); p.add_argument('-o','--output',type=Path,required=True)
    p.add_argument('--instrument',choices=('total-field','bartington'),default='total-field'); p.add_argument('--format',choices=('auto','dat','stn'),default='auto'); p.add_argument('--grid-width',type=float,default=None); p.add_argument('--grid-height',type=float,default=None)
    p.add_argument('--rows',type=int,default=0); p.add_argument('--cols',type=int,default=0); p.add_argument('--suggest',action='store_true',help=argparse.SUPPRESS)
    a=p.parse_args(argv); a.suggest=False
    if a.instrument=='bartington':
        files=_discover_bartington_files(a.input)
        if files:
            hs=[_bartington_header(f.with_suffix('.hdr')) for f in files]
            widths=[h.get('grid_width_m') for h in hs if h.get('grid_width_m')]; heights=[h.get('grid_height_m') for h in hs if h.get('grid_height_m')]
            if a.grid_width is None: a.grid_width=float(np.nanmedian(widths)) if widths else 20.0
            if a.grid_height is None: a.grid_height=float(np.nanmedian(heights)) if heights else 20.0
    else:
        files=_discover_total_field_files(a.input,a.format)
        if a.grid_width is None: a.grid_width=40.0
        if a.grid_height is None: a.grid_height=40.0
    if not files: raise SystemExit('No compatible local grid files found for the selected instrument.')
    try:
        import tkinter as tk
        from tkinter import ttk,messagebox
    except Exception as exc: raise SystemExit(f'Tk GUI is unavailable: {exc}')
    suggested=None
    if a.suggest and len(files)>1:
        try:
            frames=[(_bartington_read_pair(f)[0] if a.instrument=='bartington' else (_tf_read_geometrics_dat(f) if f.suffix.lower()=='.dat' else _tf_read_geometrics_stn(f))) for f in files]
            suggested=_tf_infer_layout_from_frames(files,frames,a.grid_width,a.grid_height,2.0,0.5,True)
        except Exception as exc: print(f'Automatic suggestion unavailable: {exc}',file=sys.stderr)
    n=len(files); rows=a.rows or int(math.ceil(math.sqrt(n))); cols=a.cols or int(math.ceil(n/rows))
    if suggested:
        rr=suggested['best']['rows']; cols=max(r['grid_x'] for r in rr)+1; rows=max(r['grid_y'] for r in rr)+1
    try: root=tk.Tk()
    except Exception as exc: raise SystemExit(f'Cannot open GUI (is a graphical desktop available?): {exc}')
    root.title(f'MagSurveyPy Grid Layout Editor — {a.instrument}'); root.geometry('1000x720')
    top=ttk.Frame(root,padding=8); top.pack(fill='x')
    rv=tk.IntVar(value=rows); cv=tk.IntVar(value=cols); wv=tk.DoubleVar(value=a.grid_width); hv=tk.DoubleVar(value=a.grid_height)
    for lab,var in [('Rows',rv),('Columns',cv),('Grid width m',wv),('Grid height m',hv)]:
        ttk.Label(top,text=lab).pack(side='left',padx=(4,2)); ttk.Entry(top,textvariable=var,width=7).pack(side='left',padx=(0,8))
    body=ttk.Frame(root,padding=8); body.pack(fill='both',expand=True); cells=[]
    options=['(empty)']+[f.name for f in files]
    sugmap={}
    if suggested:
        maxy=max(r['grid_y'] for r in suggested['best']['rows'])
        for r in suggested['best']['rows']: sugmap[(maxy-r['grid_y'],r['grid_x'])]=(r['file'],str(r['rotation_deg']))
    def rebuild():
        nonlocal cells
        for ch in body.winfo_children(): ch.destroy()
        cells=[]; nr=max(1,int(rv.get())); nc=max(1,int(cv.get()))
        for r in range(nr):
            row=[]
            for c in range(nc):
                fr=ttk.LabelFrame(body,text=f'row {r+1}, col {c+1}',padding=4); fr.grid(row=r,column=c,padx=3,pady=3,sticky='nsew')
                fv=tk.StringVar(value='(empty)'); av=tk.StringVar(value='0')
                if (r,c) in sugmap: fv.set(sugmap[(r,c)][0]); av.set(sugmap[(r,c)][1])
                ttk.Combobox(fr,textvariable=fv,values=options,state='readonly',width=18).pack(fill='x')
                ttk.Combobox(fr,textvariable=av,values=['0','90','180','270'],state='readonly',width=6).pack(pady=(4,0))
                row.append((fv,av))
            cells.append(row)
        for c in range(nc): body.columnconfigure(c,weight=1)
        for r in range(nr): body.rowconfigure(r,weight=1)
    def auto_fill():
        vals=[f.name for f in files]; k=0
        for row in cells:
            for fv,av in row:
                fv.set(vals[k] if k<len(vals) else '(empty)'); av.set('0'); k+=1
    def current_rows():
        nr=len(cells); out=[]; seen=set(); gw=float(wv.get()); gh=float(hv.get())
        for r,row in enumerate(cells):
            for c,(fv,av) in enumerate(row):
                nm=fv.get()
                if nm=='(empty)': continue
                if nm in seen: raise ValueError(f'{nm} is assigned more than once')
                seen.add(nm); out.append({'file':nm,'offset_x':c*gw,'offset_y':(nr-1-r)*gh,'rotation_deg':int(av.get())})
        missing=[f.name for f in files if f.name not in seen]
        return out,missing
    def preview():
        try: rows0,missing=current_rows()
        except Exception as exc: messagebox.showerror('Layout error',str(exc)); return
        import matplotlib.pyplot as plt
        fig,ax=plt.subplots(figsize=(7,7)); gw=float(wv.get()); gh=float(hv.get())
        for rr in rows0:
            ax.add_patch(plt.Rectangle((rr['offset_x'],rr['offset_y']),gw,gh,fill=False,linewidth=2)); ax.text(rr['offset_x']+gw/2,rr['offset_y']+gh/2,f"{rr['file']}\n{rr['rotation_deg']}°",ha='center',va='center')
        ax.set_aspect('equal'); ax.autoscale(); ax.grid(True,alpha=.2); ax.set_title('Manual grid layout preview'+(f' — missing {len(missing)} file(s)' if missing else '')); plt.show()
    def save():
        try: rows0,missing=current_rows()
        except Exception as exc: messagebox.showerror('Layout error',str(exc)); return
        if missing and not messagebox.askyesno('Unassigned files',f'{len(missing)} file(s) are not assigned. Save anyway?'): return
        a.output.parent.mkdir(parents=True,exist_ok=True)
        with a.output.open('w',newline='',encoding='utf-8') as fh:
            wr=csv.DictWriter(fh,fieldnames=['file','offset_x','offset_y','rotation_deg']); wr.writeheader(); wr.writerows(rows0)
        messagebox.showinfo('Saved',f'Layout saved to\n{a.output}'); root.destroy()
    buttons=ttk.Frame(top); buttons.pack(side='right'); ttk.Button(buttons,text='Rebuild',command=rebuild).pack(side='left',padx=2); ttk.Button(buttons,text='Fill filenames',command=auto_fill).pack(side='left',padx=2); ttk.Button(buttons,text='Preview',command=preview).pack(side='left',padx=2); ttk.Button(buttons,text='Save CSV',command=save).pack(side='left',padx=2)
    rebuild(); root.mainloop(); return 0


def _archaeology_interpolate(argv):
    """Interpolate once from the authoritative normalized ASC point cloud.

    MagSurveyPy rejects raster-as-data input here. Measurements are
    robustly aggregated to measured-cell medians, and one uniform interpolation
    model is then applied across the surveyed footprint.  Existing GeoTIFFs may
    be inspected only to inherit CRS metadata; their magnetic values are never
    read as interpolation observations.
    """
    import argparse, json, math, time
    import numpy as np
    import rasterio
    import matplotlib.pyplot as plt
    from pathlib import Path
    from rasterio.transform import from_origin
    from scipy.ndimage import binary_closing, binary_fill_holes, distance_transform_edt
    from scipy.spatial import cKDTree
    from scipy.stats import binned_statistic_2d

    desc="""Create one archaeological interpolation directly from normalized measurements.

NORMAL USE
----------
  mspy process interpolate --project Site

ASC-FIRST WORKFLOW
-------------
  normalized/corrected ASC measurements
       -> robust measured-cell medians (default 0.25 m)
       -> ONE uniform site-wide interpolation
       -> Results/INTERPOLATED

The default 'archaeology' method is a linear Delaunay/TIN surface built from
measured-cell medians.  It does not change interpolation algorithm around strong
anomalies.  A positive-weight IDW fallback is used only for numerical/edge holes
inside the accepted survey footprint.  Automatic clipping is interpolation-only
and deliberately conservative: by default it targets only the extreme 0.20%
of the robust absolute-deviation tail, with no low sigma ceiling.

Raster -> raster re-interpolation is intentionally disabled.  NATIVE/ASC and
TOTAL_FIELD/ASC values are never modified by this command.

METHODS
-------
  archaeology  Recommended: uniform linear TIN + edge/numerical IDW fallback.
  tin          Uniform linear Delaunay/TIN surface.
  idw          Classical positive-weight inverse-distance weighting.
  kriging      Local ordinary kriging with a spherical variogram.
  cubic        Clough-Tocher cubic surface, bounded to nearby measured support.
  nearest      Nearest measured-cell value (diagnostic alternative).

Examples:
  mspy process interpolate --project Site
  mspy process interpolate --project Site --input ./points.asc --method archaeology
  mspy process interpolate ./points.asc --project Site --method idw
  mspy process interpolate --project Site --method tin --clip off
  mspy process interpolate --project Site --method kriging
"""
    p=argparse.ArgumentParser(prog='magsurveypy.py process interpolate',description=desc,
                              formatter_class=argparse.RawDescriptionHelpFormatter)
    p.add_argument('input',nargs='?',type=Path,help='Normalized ASC file or Results stage containing ASC/*.asc. GeoTIFF magnetic-value input is intentionally rejected.')
    p.add_argument('--input',dest='input_option',type=Path,default=None,help='Explicit alternative to the positional input path. Both forms use the same interpolation engine.')
    p.add_argument('-o','--output',type=Path,default=None,help='Output directory. Project mode defaults to Results/INTERPOLATED.')
    basic=p.add_argument_group('Basic archaeological interpolation')
    basic.add_argument('--method',choices=('archaeology','idw','tin','kriging','cubic','nearest'),default='archaeology',
                       help='Default archaeology = one site-wide linear TIN on measured-cell medians with positive-weight fallback only for edge/numerical holes.')
    basic.add_argument('--cell-size',type=float,default=0.25,metavar='METRES',help='Measured-cell aggregation/output size. Default: 0.25 m; project default is used automatically.')
    basic.add_argument('--clip',default='auto',metavar='AUTO|OFF|VALUE',
                       help='Interpolation-only clipping. auto conservatively controls only the extreme ferrous tail; VALUE means +/-VALUE around robust median; off disables clipping.')
    basic.add_argument('--site-name',default=None,help='Output prefix. Project mode sets this automatically.')
    basic.add_argument('--crs',default='auto',help='CRS for the ASC coordinates. auto inherits it from a companion stage GeoTIFF when possible; otherwise local.')
    # Retain parsing compatibility without allowing this legacy option to select raster values.
    basic.add_argument('--source-product',default=None,help=argparse.SUPPRESS)
    adv=p.add_argument_group('Advanced controls (normally leave at defaults)')
    adv.add_argument('--neighbors',type=int,default=12,help='Neighbours for IDW fallback/IDW/local bounds. Default: 12.')
    adv.add_argument('--power',type=float,default=2.0,help='IDW distance exponent. Default: 2.0.')
    adv.add_argument('--clip-percentile',type=float,default=99.8,help='Absolute-deviation percentile used by --clip auto. Default: 99.8 (clips only the extreme 0.20%% tail before interpolation; Rupea validation places this near +/-206 magnetic units).')
    adv.add_argument('--clip-sigma-floor',type=float,default=20.0,help='Minimum auto clip half-range in robust sigma units. Default: 20. No sigma ceiling is imposed.')
    adv.add_argument('--gap-policy',choices=('auto','preserve','bridge'),default='auto',help='Gap handling. auto (default) fills only small locally supported gaps and preserves larger acquisition holes as NoData; preserve uses the same rule with an explicit --max-gap; bridge deliberately reconstructs a continuous footprint.')
    adv.add_argument('--max-gap',default='auto',metavar='AUTO|METRES',help='Largest acquisition gap allowed to be filled. auto derives a conservative threshold from output cell size. Larger gaps remain NoData.')
    adv.add_argument('--footprint',choices=('continuous','measured'),default=None,help=argparse.SUPPRESS)
    adv.add_argument('--footprint-close',type=float,default=None,metavar='METRES',help=argparse.SUPPRESS)
    adv.add_argument('--max-observations',type=int,default=150000,help='Safety cap for global/cubic triangulation. The archaeology/TIN default automatically uses overlapping local tiles on large sites so all nearby measured-cell support is retained. Default: 150000.')
    adv.add_argument('--kriging-neighbors',type=int,default=12,help='Local neighbours for ordinary kriging. Default: 12.')
    adv.add_argument('--kriging-range',type=float,default=1.5,metavar='METRES',help='Spherical variogram range for kriging. Default: 1.5 m.')
    adv.add_argument('--kriging-nugget',type=float,default=0.0,help='Kriging nugget variance. Default: 0.')
    adv.add_argument('--cores',type=int,default=0,help='CPU/thread budget. 0 uses the available CPU count/project default.')
    a=p.parse_args(argv)
    if a.input is not None and a.input_option is not None:
        raise SystemExit('Provide the interpolation source either positionally or with --input, not both.')
    a.input=a.input_option if a.input_option is not None else a.input
    if a.input is None:
        raise SystemExit('An interpolation source is required. Provide INPUT or --input INPUT.')
    if a.output is None: a.output=Path('INTERPOLATED')
    a.cores=configure_runtime_cores(a.cores)
    if a.cell_size<=0: raise SystemExit('--cell-size must be > 0')
    if a.neighbors<1 or a.power<=0: raise SystemExit('--neighbors must be >=1 and --power must be >0')
    if not (90.0<a.clip_percentile<100.0): raise SystemExit('--clip-percentile must be between 90 and 100')
    if a.clip_sigma_floor<0: raise SystemExit('--clip-sigma-floor must be >=0')
    if a.footprint_close is not None and a.footprint_close<0: raise SystemExit('--footprint-close must be >=0')
    if a.max_observations<1000: raise SystemExit('--max-observations must be >=1000')
    if a.kriging_neighbors<2 or a.kriging_range<=0 or a.kriging_nugget<0: raise SystemExit('Invalid kriging settings')

    a.output.mkdir(parents=True,exist_ok=True)
    gd=a.output/'GeoTIFF'; pd=_native_png_dirs(a.output)['qc']; rd=a.output/'Reports'
    for d in (gd,rd): d.mkdir(parents=True,exist_ok=True)
    t0=time.perf_counter()

    inp=Path(a.input)
    if inp.is_file() and inp.suffix.lower() not in {'.asc','.txt','.xyz','.csv'}:
        raise SystemExit('Raster-to-raster interpolation is disabled. Provide a normalized ASC or a Results stage containing ASC/*.asc.')
    if inp.is_dir() and inp.name.upper()=='TOTAL_FIELD':
        ad=inp/'ASC'
        proc=sorted(ad.glob('*_total_field_processed.asc'),key=_natural_path_key) if ad.exists() else []
        corr=sorted(ad.glob('*_total_field_corrected.asc'),key=_natural_path_key) if ad.exists() else []
        source_asc=(proc[0] if proc else (corr[0] if corr else _resolve_project_asc(inp)))
    else:
        source_asc=_resolve_project_asc(inp)
    if not source_asc.exists(): raise SystemExit(f'Authoritative ASC does not exist: {source_asc}')

    # CRS metadata is optional and never supplies magnetic values.  In project
    # mode inherit it from any companion GeoTIFF so output remains georeferenced.
    crs='local' if str(a.crs).lower()=='auto' else str(a.crs)
    metadata_raster=None
    if str(a.crs).lower()=='auto' and inp.is_dir():
        dirs=[inp/'GeoTIFF',inp]
        candidates=[]
        for d in dirs:
            if d.exists(): candidates.extend(sorted(d.glob('*.tif'),key=_natural_path_key))
        for q in candidates:
            try:
                with rasterio.open(q) as ds:
                    if ds.crs:
                        crs=str(ds.crs); metadata_raster=str(q); break
            except Exception:
                continue

    chunks=[]
    n_points=0
    with stage_progress('Interpolation 1/5: reading authoritative ASC measurements'):
        for q in _iter_xyz_chunks(source_asc):
            if len(q):
                chunks.append(np.asarray(q,dtype=np.float64)); n_points+=len(q)
        if not chunks: raise SystemExit(f'No finite XYZ measurements found in {source_asc}')
        pts=np.concatenate(chunks,axis=0); del chunks
        x=pts[:,0].astype(float,copy=False); y=pts[:,1].astype(float,copy=False); z=pts[:,2].astype(float,copy=False)
        good=np.isfinite(x)&np.isfinite(y)&np.isfinite(z); x=x[good]; y=y[good]; z=z[good]
        if len(z)<3: raise SystemExit('At least three finite measurements are required for interpolation.')

    # Some legacy ASC exports encode UTM zone as a 100,000,000-style X prefix.
    # The normalized parser historically strips this for gridding; preserve that
    # coordinate convention here without touching magnetic values.
    zone_prefix_removed=0.0
    if np.nanmedian(np.abs(x))>=1.0e7:
        zone_prefix_removed=float(math.floor(np.nanmedian(x)/1.0e8)*1.0e8)
        x=x-zone_prefix_removed

    cs=float(a.cell_size)
    xmin=math.floor(float(np.nanmin(x))/cs)*cs; xmax=math.ceil(float(np.nanmax(x))/cs)*cs
    ymin=math.floor(float(np.nanmin(y))/cs)*cs; ymax=math.ceil(float(np.nanmax(y))/cs)*cs
    if xmax<=xmin: xmax=xmin+cs
    if ymax<=ymin: ymax=ymin+cs
    xedges=np.arange(xmin,xmax+1.0001*cs,cs,dtype=float)
    yedges=np.arange(ymin,ymax+1.0001*cs,cs,dtype=float)
    if len(xedges)<2 or len(yedges)<2: raise SystemExit('Could not construct output grid extent from ASC coordinates.')
    with stage_progress('Interpolation 2/5: robust measured-cell medians'):
        stat=binned_statistic_2d(x,y,z,statistic='median',bins=[xedges,yedges]).statistic
        cnt=binned_statistic_2d(x,y,z,statistic='count',bins=[xedges,yedges]).statistic
        measured=np.flipud(np.asarray(stat,float).T)
        count=np.flipud(np.asarray(cnt,float).T)
        observed=np.isfinite(measured)&(count>0)
        if observed.sum()<3: raise SystemExit('Fewer than three measured cells remain after cell aggregation.')
        transform=from_origin(float(xedges[0]),float(yedges[-1]),cs,cs)

    values=np.asarray(measured[observed],float)
    center=float(np.nanmedian(values)); sigma=float(_v12_robust_sigma(values))
    absdev=np.abs(values-center)
    clip_mode=str(a.clip).strip().lower(); clip_limit=None
    if clip_mode in {'off','none','false','0'}:
        lo=hi=None
    elif clip_mode=='auto':
        tail=float(np.nanpercentile(absdev,float(a.clip_percentile))) if len(absdev) else 0.0
        floor=float(a.clip_sigma_floor)*max(sigma,1e-12)
        # No low sigma ceiling: the percentile controls the
        # genuinely extreme ferrous tail instead of flattening strong dipoles.
        clip_limit=float(max(tail,floor,1e-12)); lo=center-clip_limit; hi=center+clip_limit
    else:
        try: clip_limit=abs(float(a.clip))
        except Exception: raise SystemExit('--clip must be auto, off, or a positive numeric value such as 200')
        if not np.isfinite(clip_limit) or clip_limit<=0: raise SystemExit('Numeric --clip must be > 0')
        lo=center-clip_limit; hi=center+clip_limit
    clipped_values=values.copy() if lo is None else np.clip(values,lo,hi)
    nclip=int(np.count_nonzero(np.abs(clipped_values-values)>1e-12)); clipped_fraction=float(nclip/max(len(values),1))
    measured_clipped=measured.copy(); measured_clipped[observed]=clipped_values

    with stage_progress('Interpolation 3/5: small-gap support / large-gap preservation'):
        gap_policy=str(a.gap_policy).lower()
        if a.footprint=='measured':
            gap_policy='preserve'; max_gap_m=0.0
        elif a.footprint=='continuous':
            gap_policy='bridge'; max_gap_m=None
        else:
            mg=str(a.max_gap).strip().lower()
            if mg in {'auto','default',''}:
                max_gap_m=max(4.0*cs,1.0)
            else:
                try: max_gap_m=float(mg)
                except Exception: raise SystemExit('--max-gap must be auto or a non-negative distance in metres')
                if not np.isfinite(max_gap_m) or max_gap_m<0: raise SystemExit('--max-gap must be >= 0')
        if gap_policy=='bridge':
            close_m=(float(a.footprint_close) if a.footprint_close is not None else max(1.0,4.0*cs))
            rpx=max(1,int(math.ceil(close_m/cs)))
            gy,gx=np.ogrid[-rpx:rpx+1,-rpx:rpx+1]
            structure=(gx*gx+gy*gy)<=rpx*rpx
            closed=binary_closing(observed,structure=structure)
            footprint=binary_fill_holes(closed); footprint|=observed
            preserved_gaps=np.zeros_like(observed,dtype=bool)
            effective_gap_m=float('inf')
        else:
            effective_gap_m=float(max_gap_m)
            if effective_gap_m<=0:
                footprint=observed.copy()
            else:
                rpx=max(1,int(math.ceil((0.5*effective_gap_m)/cs)))
                gy,gx=np.ogrid[-rpx:rpx+1,-rpx:rpx+1]
                structure=(gx*gx+gy*gy)<=rpx*rpx
                footprint=binary_closing(observed,structure=structure)
                footprint|=observed
            continuous=binary_fill_holes(footprint.copy())|footprint
            preserved_gaps=continuous & ~footprint
        if not footprint.any(): raise SystemExit('Could not construct the interpolation footprint.')

    obs_rc=np.column_stack(np.nonzero(observed))
    obs_xy=np.column_stack((transform.c+(obs_rc[:,1]+0.5)*cs,
                            transform.f-(obs_rc[:,0]+0.5)*cs)).astype(float)
    obs_v=np.asarray(measured_clipped[observed],float)
    tree=cKDTree(obs_xy)
    target=footprint & ~observed
    tar_rc=np.column_stack(np.nonzero(target))
    tar_xy=np.column_stack((transform.c+(tar_rc[:,1]+0.5)*cs,
                            transform.f-(tar_rc[:,0]+0.5)*cs)).astype(float) if len(tar_rc) else np.empty((0,2),float)
    out=np.full_like(measured,np.nan,float); out[observed]=obs_v

    def idw_predict(points_xy,power=None,neighbors=None):
        if len(points_xy)==0: return np.empty(0,float)
        kk=min(max(1,int(neighbors if neighbors is not None else a.neighbors)),len(obs_v))
        pp=max(float(power if power is not None else a.power),1e-9)
        ans=np.empty(len(points_xy),float); chunk=120000
        for i in range(0,len(points_xy),chunk):
            q=points_xy[i:i+chunk]
            dist,idx=tree.query(q,k=kk,workers=max(1,int(a.cores)))
            if kk==1: dist=dist[:,None]; idx=idx[:,None]
            exact=dist<=1e-12; vv=obs_v[idx]
            w=np.where(exact,0.0,1.0/np.maximum(dist,1e-12)**pp)
            pred=np.sum(w*vv,axis=1)/np.maximum(np.sum(w,axis=1),1e-30)
            any_exact=exact.any(axis=1)
            if any_exact.any():
                erows=np.flatnonzero(any_exact)
                pred[erows]=vv[erows,np.argmax(exact[erows],axis=1)]
            ans[i:i+len(q)]=pred
        return ans

    method=str(a.method).lower(); fallback_cells=0; triangulation_nodes=len(obs_v); triangulation_subsampled=False
    triangulation_mode='not-applicable'

    def _linear_tin_predict_all_support():
        """Linear Delaunay interpolation using all LOCAL measured-cell support.

        Small sites use one global triangulation. Large sites are evaluated in
        overlapping spatial tiles. Each tile predicts only its core but is
        triangulated from an expanded support margin, so the same linear-TIN
        rule is applied everywhere without the unstable global node subsampling
        that made strong Rupea gap predictions depend on an arbitrary cap.
        """
        if len(tar_xy)==0:
            return np.empty(0,float),'global-all-support',0
        from scipy.interpolate import LinearNDInterpolator
        # A full triangulation is efficient and exact for moderate sites.
        if len(obs_v)<=int(a.max_observations):
            try:
                origin=np.nanmedian(obs_xy,axis=0)
                interp=LinearNDInterpolator(obs_xy-origin,obs_v,fill_value=np.nan,rescale=False)
                return np.asarray(interp(tar_xy-origin),float),'global-all-support',len(obs_v)
            except Exception as exc:
                print(f'TIN warning: {exc}; positive-weight fallback will cover affected footprint cells.',file=sys.stderr)
                return np.full(len(tar_xy),np.nan,float),'global-all-support-failed',len(obs_v)

        ny,nx=observed.shape
        tile_cells=max(32,int(round(20.0/max(cs,1e-12))))
        margin_m=max(3.0,4.0*(effective_gap_m if np.isfinite(effective_gap_m) else max(1.0,4.0*cs)),8.0*cs)
        margin_cells=max(4,int(math.ceil(margin_m/max(cs,1e-12))))
        target_index=np.full((ny,nx),-1,dtype=np.int32)
        target_index[tar_rc[:,0],tar_rc[:,1]]=np.arange(len(tar_rc),dtype=np.int32)
        pred=np.full(len(tar_xy),np.nan,float)
        max_local=0; tiles=0
        for r0 in range(0,ny,tile_cells):
            r1=min(ny,r0+tile_cells)
            for c0 in range(0,nx,tile_cells):
                c1=min(nx,c0+tile_cells)
                core=target_index[r0:r1,c0:c1]
                pos=core[core>=0]
                if len(pos)==0: continue
                er0=max(0,r0-margin_cells); er1=min(ny,r1+margin_cells)
                ec0=max(0,c0-margin_cells); ec1=min(nx,c1+margin_cells)
                om=observed[er0:er1,ec0:ec1]
                rr,cc=np.nonzero(om)
                if len(rr)<3: continue
                rr=rr+er0; cc=cc+ec0
                node_v=measured_clipped[rr,cc]
                node_xy=np.column_stack((transform.c+(cc+0.5)*cs,transform.f-(rr+0.5)*cs)).astype(float)
                origin=np.array([transform.c+(0.5*(c0+c1))*cs,transform.f-(0.5*(r0+r1))*cs],float)
                try:
                    interp=LinearNDInterpolator(node_xy-origin,node_v,fill_value=np.nan,rescale=False)
                    pred[pos]=np.asarray(interp(tar_xy[pos]-origin),float)
                except Exception as exc:
                    print(f'Local TIN warning at rows {r0}:{r1}, cols {c0}:{c1}: {exc}',file=sys.stderr)
                max_local=max(max_local,len(node_v)); tiles+=1
        return pred,f'tiled-all-support:{tiles}-tiles,max-local-{max_local}',len(obs_v)

    with stage_progress('Interpolation 4/5: one uniform site-wide surface'):
        if method in {'archaeology','tin'}:
            pred,triangulation_mode,triangulation_nodes=_linear_tin_predict_all_support()
            if len(tar_xy):
                bad=~np.isfinite(pred)
                if bad.any():
                    pred[bad]=idw_predict(tar_xy[bad],power=2.0,neighbors=12); fallback_cells=int(bad.sum())
                out[target]=pred
        elif method=='cubic':
            node_xy=obs_xy; node_v=obs_v
            if len(node_v)>int(a.max_observations):
                # Cubic is an optional interpretation alternative. Deterministic
                # spatial reduction keeps it bounded; the default archaeology/TIN
                # path above never subsamples local measured support.
                take=np.linspace(0,len(node_v)-1,int(a.max_observations),dtype=int)
                node_xy=node_xy[take]; node_v=node_v[take]
                triangulation_nodes=len(node_v); triangulation_subsampled=True
            triangulation_mode='global-cubic'
            if len(tar_xy):
                from scipy.interpolate import CloughTocher2DInterpolator
                try:
                    origin=np.nanmedian(node_xy,axis=0)
                    interp=CloughTocher2DInterpolator(node_xy-origin,node_v,fill_value=np.nan,rescale=False)
                    pred=np.asarray(interp(tar_xy-origin),float)
                except Exception as exc:
                    print(f'Cubic warning: {exc}; positive-weight fallback will cover affected footprint cells.',file=sys.stderr)
                    pred=np.full(len(tar_xy),np.nan,float)
                kk=min(max(4,int(a.neighbors)),len(obs_v)); _,ix=tree.query(tar_xy,k=kk,workers=max(1,int(a.cores)))
                if kk==1: ix=ix[:,None]
                local=obs_v[ix]; lmin=np.nanmin(local,axis=1); lmax=np.nanmax(local,axis=1)
                finite=np.isfinite(pred); pred[finite]=np.clip(pred[finite],lmin[finite],lmax[finite])
                bad=~np.isfinite(pred)
                if bad.any(): pred[bad]=idw_predict(tar_xy[bad],power=2.0,neighbors=12); fallback_cells=int(bad.sum())
                out[target]=pred
        elif method=='idw':
            out[target]=idw_predict(tar_xy)
        elif method=='nearest':
            if len(tar_xy):
                _,ix=tree.query(tar_xy,k=1,workers=max(1,int(a.cores))); out[target]=obs_v[ix]
        elif method=='kriging':
            triangulation_mode='local-ordinary-kriging'
            if len(tar_xy):
                kk=min(max(2,int(a.kriging_neighbors)),len(obs_v)); rng=float(a.kriging_range); nug=float(a.kriging_nugget)
                sill=max(float(sigma*sigma),float(np.nanvar(obs_v))*0.25,1e-12)
                pred=np.empty(len(tar_xy),float)
                def gamma(h):
                    h=np.asarray(h,float); u=np.minimum(h/rng,1.0)
                    return nug+sill*np.where(h<rng,1.5*u-0.5*u**3,1.0)
                chunk=10000
                for j0 in range(0,len(tar_xy),chunk):
                    q=tar_xy[j0:j0+chunk]; dist,ix=tree.query(q,k=kk,workers=max(1,int(a.cores)))
                    if kk==1: dist=dist[:,None]; ix=ix[:,None]
                    for jj in range(len(q)):
                        xy=obs_xy[ix[jj]]; vv=obs_v[ix[jj]]
                        dd=np.hypot(xy[:,None,0]-xy[None,:,0],xy[:,None,1]-xy[None,:,1])
                        K=np.empty((kk+1,kk+1),float); K[:kk,:kk]=gamma(dd); K[:kk,kk]=1; K[kk,:kk]=1; K[kk,kk]=0
                        rhs=np.r_[gamma(dist[jj]),1.0]
                        try: w=np.linalg.solve(K,rhs)[:kk]; pred[j0+jj]=float(np.dot(w,vv))
                        except np.linalg.LinAlgError: pred[j0+jj]=float(idw_predict(q[jj:jj+1],neighbors=kk)[0]); fallback_cells+=1
                out[target]=pred

    out[~footprint]=np.nan
    missing=int(np.sum(footprint&~np.isfinite(out)))
    if missing:
        rc=np.column_stack(np.nonzero(footprint&~np.isfinite(out)))
        xy=np.column_stack((transform.c+(rc[:,1]+0.5)*cs,transform.f-(rc[:,0]+0.5)*cs))
        out[footprint&~np.isfinite(out)]=idw_predict(xy,power=2.0,neighbors=12); fallback_cells+=len(rc)
    support=distance_transform_edt(~observed)*cs; support[~footprint]=np.nan

    prefix=_site_slug_from_source(source_asc,a.site_name)
    tags_base={'software':APP_NAME,'version':APP_VERSION,'author':AUTHOR,'site':prefix,
               'authoritative_source':str(source_asc),'source_type':'normalized ASC point cloud',
               'raster_values_used':'false','cell_statistic':'median','cell_size_m':cs,
               'method':method,'uniform_site_wide_rule':'true','anomaly_dependent_switching':'false',
               'positioning_note':'coordinates are consumed exactly as written by the acquisition/ASC stage'}
    rawmed=gd/f'{prefix}_measured_cell_median.tif'
    clipmed=gd/f'{prefix}_interpolation_input_clipped.tif'
    final=gd/f'{prefix}_interpolated.tif'
    countp=gd/f'{prefix}_measurement_count.tif'
    footp=gd/f'{prefix}_interpolation_footprint.tif'
    gapsp=gd/f'{prefix}_preserved_gaps.tif'
    supp=gd/f'{prefix}_point_support_distance.tif'
    with stage_progress('Interpolation 5/5: writing GeoTIFF and QC products'):
        _archaeomag_write_like(rawmed,measured,transform,crs,{**tags_base,'product':'unmodified measured-cell medians'},'Measured-cell median')
        _archaeomag_write_like(clipmed,measured_clipped,transform,crs,{**tags_base,'product':'derived interpolation input','clip_mode':a.clip,'clip_lower':lo,'clip_upper':hi},'Interpolation input')
        _archaeomag_write_like(final,out,transform,crs,{**tags_base,'product':'single site-wide interpolated surface','fallback_cells':fallback_cells,'triangulation_mode':triangulation_mode},'Interpolated magnetic field')
        _archaeomag_write_like(countp,np.where(count>0,count,np.nan),transform,crs,{**tags_base,'product':'measurement count per robust median cell'},'Measurement count')
        _archaeomag_write_like(footp,np.where(footprint,1.0,np.nan),transform,crs,{**tags_base,'product':'interpolation footprint','gap_policy':gap_policy,'max_gap_m':effective_gap_m},'Interpolation footprint')
        _archaeomag_write_like(gapsp,np.where(preserved_gaps,1.0,np.nan),transform,crs,{**tags_base,'product':'preserved acquisition gaps','gap_policy':gap_policy,'max_gap_m':effective_gap_m},'Preserved acquisition gaps')
        _archaeomag_write_like(supp,support,transform,crs,{**tags_base,'product':'distance to nearest measured cell'},'Support distance [m]')

    qcp=pd/f'{prefix}_interpolation_QC.png'
    show_center=float(np.nanmedian(values)); lim=max(float(np.nanpercentile(np.abs(values-show_center),98.5)),max(sigma*4,1e-9))
    fig,axs=plt.subplots(1,3,figsize=(15.8,5.55),constrained_layout=False)
    fig.subplots_adjust(left=.055,right=.985,bottom=.25,top=.91,wspace=.18)
    im0=axs[0].imshow(measured,origin='upper',cmap='gray_r',vmin=show_center-lim,vmax=show_center+lim); axs[0].set_title(f'Measured-cell medians ({cs:g} m)')
    im1=axs[1].imshow(out,origin='upper',cmap='gray_r',vmin=show_center-lim,vmax=show_center+lim); axs[1].set_title(f'One site-wide {"linear TIN" if method=="archaeology" else method}')
    im2=axs[2].imshow(support,origin='upper',cmap='viridis'); axs[2].set_title('Distance to measured support [m]')
    for ax in axs: ax.set_xlabel('Easting cells'); ax.set_ylabel('Northing cells')
    # Measured nodes and the interpolated surface use the same quantitative
    # range, so one shared bar is clearer and avoids duplicated long total-field labels.
    _publication_shared_colorbar(fig,axs[:2],im0,'magnetic units','bottom',fontsize=7.5,tick_fontsize=6.5,thickness=.085,pad=.58)
    _publication_colorbar(fig,axs[2],im2,'m','bottom',fontsize=7.5,tick_fontsize=6.5,thickness=.085,pad=.58)
    fig.savefig(qcp,dpi=210,bbox_inches='tight',pad_inches=.05); plt.close(fig)

    support_vals=support[footprint]
    report={
      'application':APP_NAME,'version':APP_VERSION,'site':prefix,
      'authoritative_asc':str(source_asc),'input_argument':str(inp),
      'source_raster_used_for_magnetic_values':False,'metadata_raster_only':metadata_raster,
      'raster_to_raster_reinterpolation':False,'crs':crs,'zone_prefix_removed_from_x':zone_prefix_removed,
      'raw_points_read':int(n_points),'finite_points_used':int(len(z)),'cell_size_m':cs,'measured_cell_statistic':'median',
      'measured_cells':int(observed.sum()),'footprint_cells':int(footprint.sum()),'predicted_gap_cells':int(target.sum()),
      'clip':{'mode':a.clip,'percentile':float(a.clip_percentile),'sigma_floor':float(a.clip_sigma_floor),'robust_center':center,'robust_sigma':sigma,'lower':lo,'upper':hi,'measured_cells_clipped':nclip,'fraction_clipped':clipped_fraction},
      'interpolation':{'requested_method':method,'effective_default':('linear-tin-with-positive-idw-edge-fallback' if method=='archaeology' else method),
                       'same_rule_everywhere':True,'anomaly_dependent_method_switching':False,'fallback_cells':int(fallback_cells),
                       'triangulation_nodes':int(triangulation_nodes),'triangulation_mode':triangulation_mode,'triangulation_subsampled_for_safety':bool(triangulation_subsampled),
                       'neighbors':int(a.neighbors),'idw_power':float(a.power),'gap_policy':gap_policy,'max_gap_m':(None if not np.isfinite(effective_gap_m) else float(effective_gap_m)),'preserved_gap_cells':int(preserved_gaps.sum())},
      'support_distance_m':{'median':float(np.nanmedian(support_vals)),'p95':float(np.nanpercentile(support_vals,95)),'max':float(np.nanmax(support_vals))},
      'missing_inside_final_footprint':int(np.sum(footprint&~np.isfinite(out))),
      'products':{'measured_cell_medians':str(rawmed),'interpolation_input':str(clipmed),'interpolated':str(final),'measurement_count':str(countp),'footprint':str(footp),'preserved_gaps':str(gapsp),'support_distance':str(supp),'qc_png':str(qcp)},
      'scientific_policy':'ASC is authoritative. Magnetic values are never taken from a prior raster. Measured-cell medians are preserved as a separate derived diagnostic. Automatic clipping affects only the derived interpolation input. The default gap policy fills only small locally supported interruptions and preserves larger acquisition holes as NoData. The archaeology default applies the same linear Delaunay/TIN rule everywhere, with positive-weight IDW only for numerical/edge holes inside accepted support.',
      'processing_seconds':float(time.perf_counter()-t0)
    }
    rp=rd/f'{prefix}_interpolation_report.json'; rp.write_text(json.dumps(report,indent=2,default=str),encoding='utf-8')
    txt=rd/f'{prefix}_interpolation_report.txt'
    txt.write_text('\n'.join([
        f'MagSurveyPy {APP_VERSION} — ASC-first archaeological interpolation',
        f'Authoritative ASC: {source_asc}',
        'Raster magnetic values used as observations: NO',
        'Raster -> raster re-interpolation: NO',
        f'Raw finite measurement points: {len(z):,}',f'Measured-cell median nodes: {int(observed.sum()):,}',f'Cell size: {cs:g} m',
        f'Method: {method}' + (' (effective: one uniform linear TIN + positive IDW edge/numerical fallback)' if method=='archaeology' else ''),
        f'Interpolation-only clipping: {a.clip}',
        ('Clip range: OFF' if lo is None else f'Clip range: {lo:.6g} .. {hi:.6g} (center {center:.6g}; abs-dev p{a.clip_percentile:g}; floor {a.clip_sigma_floor:g} sigma)'),
        f'Measured cells clipped: {nclip:,} ({100*clipped_fraction:.4f}%)',
        f'Gap policy: {gap_policy}',f'Maximum small gap filled: {"continuous bridge" if not np.isfinite(effective_gap_m) else f"{effective_gap_m:g} m"}',f'Preserved large-gap cells: {int(preserved_gaps.sum()):,}',
        f'Footprint cells: {int(footprint.sum()):,}',f'Predicted small-gap cells: {int(target.sum()):,}',f'Edge/numerical fallback cells: {int(fallback_cells):,}',
        f'Final internal NoData cells inside accepted support: {int(np.sum(footprint&~np.isfinite(out))):,}',
        'Original ASC modified: NO','NATIVE/TOTAL_FIELD source values modified: NO',f'Output: {final}'
    ])+'\n',encoding='utf-8')
    print(f'ASC-FIRST ARCHAEOLOGICAL INTERPOLATION: {method}',flush=True)
    print(f'Authoritative measurements: {source_asc}',flush=True)
    print(f'Measured-cell medians: {int(observed.sum()):,} at {cs:g} m; raster-as-data: DISABLED',flush=True)
    if lo is None: print('Extreme-value clipping: OFF (derived interpolation only)',flush=True)
    else: print(f'Extreme-tail clipping: {lo:.3f} .. {hi:.3f}; clipped {nclip:,}/{len(values):,} measured cells ({100*clipped_fraction:.4f}%)',flush=True)
    gap_desc=('continuous bridge' if not np.isfinite(effective_gap_m) else f'{effective_gap_m:g} m max small gap')
    print(f'Gap policy: {gap_policy}; {gap_desc}; preserved large-gap cells: {int(preserved_gaps.sum()):,}',flush=True)
    print(f'Interpolation support: {int(footprint.sum()):,} cells; small-gap predictions: {int(target.sum()):,}; IDW fallback: {fallback_cells:,}; internal NoData inside accepted support: {int(np.sum(footprint&~np.isfinite(out))):,}',flush=True)
    print(f'Interpolated raster: {final}',flush=True); print(f'QC report: {rp}',flush=True)
    return 0


def _workspace_root(value=None):
    # New projects use ~/MagSurveyPy_Projects.  When no explicit workspace is
    # supplied, an existing historical project workspace is detected silently
    # so users do not have to move working survey projects merely to update the app.
    if value:
        return Path(value).expanduser().resolve()
    env=os.environ.get('MAGSURVEYPY_WORKSPACE')
    if env:
        return Path(env).expanduser().resolve()
    preferred=Path.home()/'MagSurveyPy_Projects'
    compatibility=Path.home()/'ArchaeoMag_Projects'
    if preferred.exists() or not compatibility.exists():
        return preferred.resolve()
    return compatibility.resolve()


def _project_paths(project,workspace=None):
    root=_workspace_root(workspace)/_safe_project_name(project)
    raw=root/'RawData'

    def preferred(canonical, *legacy):
        """Use public folder names for new projects while reading older trees."""
        if canonical.exists(): return canonical
        for old in legacy:
            if old.exists(): return old
        return canonical

    multichannel=preferred(raw/'Multichannel', raw/'PRM')
    total_field=preferred(raw/'TotalField')
    fluxgate=preferred(raw/'Fluxgate', raw/'Bartington')
    generic=preferred(raw/'Generic')
    gnss=preferred(raw/'GNSS')
    base=preferred(raw/'BaseStation')
    return {
        'root':root,'meta':root/'project.json','raw':raw,
        'multichannel':multichannel,'total_field':total_field,'fluxgate':fluxgate,
        'generic':generic,'gnss':gnss,'base':base,
        'prm':multichannel,'bartington':fluxgate,
        'layouts':root/'Layouts','layout':root/'Layouts'/'grid_layout.csv','config':root/'Config',
        'results':root/'Results','reports':root/'Reports','exports':root/'Exports',
        'logs':root/'Logs','temp':root/'Temp'
    }



def _unique_numbered_path(path):
    """Return PATH if free, otherwise PATH_1, PATH_2 ... without deleting anything."""
    from pathlib import Path
    q=Path(path)
    if not q.exists(): return q
    parent=q.parent
    if q.suffix:
        stem=q.stem; suffix=q.suffix
        i=1
        while True:
            cand=parent/f'{stem}_{i}{suffix}'
            if not cand.exists(): return cand
            i+=1
    else:
        name=q.name; i=1
        while True:
            cand=parent/f'{name}_{i}'
            if not cand.exists(): return cand
            i+=1


def _argv_pop_flag(argv,*names):
    """Remove a boolean flag/alias from argv and return (clean_argv, present)."""
    names=set(str(x) for x in names)
    clean=[]; present=False
    for x in list(argv):
        sx=str(x)
        if sx in names:
            present=True; continue
        clean.append(x)
    return clean,present


def _command_project_hint(cmd, argv):
    """Best-effort project name for logging without changing command parsing."""
    vals=[str(x) for x in argv]
    pr=_argv_value(vals,'--project')
    if pr: return _safe_project_name(pr)
    if cmd=='project' and vals:
        sub=vals[0]
        if sub in {'init','import','config','status','tree','path','georeference','history'} and len(vals)>1 and not vals[1].startswith('-'):
            return _safe_project_name(vals[1])
    return None


def _append_project_command_log(project, category, argv_full, workspace=None, status=None, duration=None):
    """Append an exact reusable command to master and category project logs.

    Logging is intentionally plain text so a previous command can be copied back
    into a terminal.  A compact TSV status file is also maintained for auditing.
    """
    if not project: return
    try:
        import shlex, datetime
        pp=_project_paths(project,workspace)
        if not pp['root'].exists(): return
        pp['logs'].mkdir(parents=True,exist_ok=True)
        ts=datetime.datetime.now().astimezone().isoformat(timespec='seconds')
        command='mspy '+shlex.join([str(x) for x in argv_full])
        line=f'[{ts}] {command}\n'
        if status is None:
            for q in (pp['logs']/'commands.log', pp['logs']/f'{_safe_project_name(category).lower()}.log'):
                with q.open('a',encoding='utf-8') as fh: fh.write(line)
        if status is not None:
            # `project init` has no Logs directory at invocation time; preserve its
            # command once the project exists after successful creation.
            master=pp['logs']/'commands.log'
            if not master.exists():
                for q in (master, pp['logs']/f'{_safe_project_name(category).lower()}.log'):
                    with q.open('a',encoding='utf-8') as fh: fh.write(line)
            with (pp['logs']/'command_status.tsv').open('a',encoding='utf-8') as fh:
                if fh.tell()==0: fh.write('timestamp\tcategory\tstatus\tduration_s\tcommand\n')
                dur='' if duration is None else f'{float(duration):.3f}'
                safe=command.replace('\t',' ')
                fh.write(f'{ts}\t{category}\t{status}\t{dur}\t{safe}\n')
    except Exception:
        # Command logging must never make a scientific command fail.
        pass


def _argv_value(argv,name,default=None):
    vals=list(argv)
    for i,x in enumerate(vals):
        sx=str(x)
        if sx==name and i+1<len(vals): return str(vals[i+1])
        if sx.startswith(name+'='): return sx.split('=',1)[1]
    return default


def _argv_without(argv,name,has_value=True):
    vals=list(argv); out=[]; i=0
    while i<len(vals):
        sx=str(vals[i])
        if sx==name:
            i += 2 if has_value else 1; continue
        if has_value and sx.startswith(name+'='):
            i+=1; continue
        out.append(vals[i]); i+=1
    return out


def _argv_promote_input_alias(argv):
    """Accept ``--input PATH`` anywhere a grouped command accepts positional input.

    The scientific engines historically use positional input paths.  Public grouped
    commands also accept the explicit ``--input`` spelling and normalize it to the
    same positional form before dispatch, so both spellings execute identical code.
    Repeated ``--input`` options are preserved for engines accepting multiple inputs.
    """
    vals=list(argv); inputs=[]; clean=[]; i=0
    while i<len(vals):
        sx=str(vals[i])
        if sx=='--input':
            if i+1>=len(vals):
                raise SystemExit('--input requires a file or directory path.')
            inputs.append(vals[i+1]); i+=2; continue
        if sx.startswith('--input='):
            value=sx.split('=',1)[1]
            if not value:
                raise SystemExit('--input requires a file or directory path.')
            inputs.append(value); i+=1; continue
        clean.append(vals[i]); i+=1
    return [*inputs,*clean],inputs


def _coalesce_project_name(namespace, parser=None):
    """Resolve canonical ``--project`` with the historical positional name as an alias.

    New documentation uses ``--project NAME`` consistently across MagSurveyPy.
    Positional project names remain accepted so existing scripts keep working.
    """
    positional=getattr(namespace,'name',None)
    option=getattr(namespace,'project_option',None)
    if positional and option and str(positional)!=str(option):
        msg=f'Project was supplied twice with different values: {positional!r} and {option!r}.'
        if parser is not None: parser.error(msg)
        raise SystemExit(msg)
    name=option or positional
    if not name:
        msg='A project name is required. Use --project PROJECT.'
        if parser is not None: parser.error(msg)
        raise SystemExit(msg)
    namespace.name=str(name)
    return namespace.name


def _ensure_project(project,workspace=None):
    if not project: raise SystemExit('A project name is required. Use --project PROJECT.')
    pp=_project_paths(project,workspace)
    if not pp['meta'].exists():
        raise SystemExit(f"Project '{project}' does not exist in {_workspace_root(workspace)}. Create it first with `mspy project init --project {project}`.")
    return pp


def _load_project_defaults(pp):
    import json
    f=pp['config']/'processing_defaults.json'
    try:
        obj=json.loads(f.read_text(encoding='utf-8'))
        return obj if isinstance(obj,dict) else {}
    except Exception:
        return {}


def _project_default_cli_items(pp,include_grid=True):
    d=_load_project_defaults(pp); out=[]
    if include_grid:
        if d.get('cell_size_m') is not None: out.append(('--cell-size',d['cell_size_m']))
        if d.get('fill_distance_m') is not None: out.append(('--fill-distance',d['fill_distance_m']))
        if d.get('statistic') in {'median','mean'}: out.append(('--statistic',d['statistic']))
    if d.get('cores') is not None: out.append(('--cores',d['cores']))
    return out


def _project_primary_stage(pp):
    for name in ('MULTICHANNEL','TOTAL_FIELD','FLUXGATE','NATIVE','GRID'):
        q=pp['results']/name
        if q.exists(): return q
    raise SystemExit(f"No primary survey result exists in {pp['results']}. Run `survey multichannel` or `survey grid --protocol total-field|fluxgate` first.")


def _infer_project_from_input(argv,workspace_root):
    ws=_workspace_root(workspace_root)
    for x in argv:
        sx=str(x)
        if sx.startswith('-'): continue
        try: p=Path(sx).expanduser().resolve(); rel=p.relative_to(ws)
        except Exception: continue
        if rel.parts: return _safe_project_name(rel.parts[0])
    return None


def _extract_global_routing(argv):
    """Internal output routing for the mature scientific engines."""
    vals=list(argv); workspace=_workspace_root(); project=None; clean=[]; i=0
    while i<len(vals):
        sx=str(vals[i])
        if sx in {'--workspace','--results-root'}:
            if i+1>=len(vals): raise SystemExit(f'{sx} requires a path')
            workspace=_workspace_root(vals[i+1]); i+=2; continue
        if sx.startswith('--workspace=') or sx.startswith('--results-root='):
            workspace=_workspace_root(sx.split('=',1)[1]); i+=1; continue
        if sx=='--project':
            if i+1>=len(vals): raise SystemExit('--project requires a name')
            project=_safe_project_name(vals[i+1]); i+=2; continue
        if sx.startswith('--project='):
            project=_safe_project_name(sx.split('=',1)[1]); i+=1; continue
        clean.append(vals[i]); i+=1
    if project is None:
        for j,x in enumerate(clean):
            sx=str(x)
            if sx=='--site-name' and j+1<len(clean): project=_safe_project_name(clean[j+1]); break
            if sx.startswith('--site-name='): project=_safe_project_name(sx.split('=',1)[1]); break
    if project is None: project=_infer_project_from_input(clean,workspace)
    return clean,workspace,project


def _route_output_argv(command,argv,results_root=None,project=None):
    """Route simple output names to WORKSPACE/PROJECT/Results/STAGE."""
    vals=list(argv); ws=_workspace_root(results_root)
    base=(_project_paths(project,ws)['results'] if project else ws/'_Unassigned'/'Results')
    defaults={'prm':'MULTICHANNEL','process':'GRID','grid':'GRID','enhance':'ENHANCED','segment':'SEGMENT',
              'surface-compare':'INTERPOLATION_COMPARE','interpolate-site':'INTERPOLATED','clean-map':'CLEAN','background':'BACKGROUND',
              'plough':'PLOUGH','thin':'THIN','presentation':'PRESENTATION','filter':'FILTER',
              'total-field':'TOTAL_FIELD','bartington':'FLUXGATE','denoise':'DENOISE','regularize-points':'REGULAR025'}
    idx=None
    for i,x in enumerate(vals):
        sx=str(x)
        if sx in {'-o','--output'} and i+1<len(vals): idx=i+1; break
        if sx.startswith('--output='):
            p=Path(sx.split('=',1)[1])
            if not p.is_absolute() and len(p.parts)==1:
                p=base/_stage_name_for_project(p.name,project,command); vals[i]='--output='+str(p)
            print(f'PROJECT: {project or "(unassigned)"}',flush=True); print(f'RESOLVED OUTPUT: {p}',flush=True); return vals
    if idx is None and command in defaults:
        p=base/defaults[command]; vals += ['-o',str(p)]
        print(f'PROJECT: {project or "(unassigned)"}',flush=True); print(f'RESOLVED OUTPUT: {p}',flush=True); return vals
    if idx is not None:
        p=Path(vals[idx])
        if not p.is_absolute() and len(p.parts)==1:
            p=base/_stage_name_for_project(p.name,project,command); vals[idx]=str(p)
        print(f'PROJECT: {project or "(unassigned)"}',flush=True); print(f'RESOLVED OUTPUT: {p}',flush=True)
    return vals


