        dest={'multichannel':pp['multichannel'],'total-field':pp['total_field'],'fluxgate':pp['fluxgate'],'generic':pp['generic'],'gnss':pp['gnss'],'base-station':pp['base']}[typ]
        dest.mkdir(parents=True,exist_ok=True)
        for src0 in a.source:
            src=src0.expanduser().resolve()
            if not src.exists(): raise SystemExit(f'Source does not exist: {src}')
