def _export_stage_raster(pp, stage=None, explicit=None):
    from pathlib import Path
    if explicit:
        q=Path(explicit).expanduser()
        if not q.exists(): raise SystemExit(f'Export source does not exist: {q}')
        if q.is_file(): return q.resolve()
        root=q
    else:
        if stage:
            st=str(stage).upper()
        elif (pp['results']/'CLEAN').exists():
            st='CLEAN'
        elif (pp['results']/'INTERPOLATED').exists():
            st='INTERPOLATED'
        else:
            st=_project_primary_stage(pp).name
        root=pp['results']/st
        if not root.exists(): raise SystemExit(f'Project stage does not exist: {root}')
    roots=[root/'GeoTIFF',root]
    cands=[]
    for rr in roots:
        if rr.exists(): cands.extend(list(rr.glob('*.tif'))+list(rr.glob('*.tiff')))
    cands=sorted({q.resolve():q.resolve() for q in cands}.values(),key=_natural_path_key)
    if not cands: raise SystemExit(f'No GeoTIFFs found in export source: {root}')
    bad=('count','footprint','support','preserved_gap','mask','removed','difference','uncertainty','correction','input_clipped','measured_cell','density','qc')
    usable=[q for q in cands if not any(b in q.stem.lower() for b in bad)] or cands
    pref=('interpolated','cleaned','clean','destriped','bz_grid','total_field_destriped','total_field_processed','presentation_field')
    for token in pref:
        hit=[q for q in usable if token in q.stem.lower()]
        if len(hit)==1: return hit[0]
    return usable[0]


def _export_read(path):
    import numpy as np, rasterio
    with rasterio.open(path) as ds:
        a=ds.read(1).astype(float); nod=ds.nodata
        if nod is not None: a[a==nod]=np.nan
        tr=ds.transform; crs=ds.crs; bounds=ds.bounds; profile=ds.profile.copy(); tags=ds.tags()
    return a,tr,crs,bounds,profile,tags


def _export_units(path, tags=None):
    try:
        from .lib.analysis import infer_units
        return infer_units(tags or {}, path=path)
    except Exception:
        return 'magnetic units'


def _export_limits(arr, display_range=None, display_min=None, display_max=None, display_std=None):
    import numpy as np
    vals=np.asarray(arr,float); vals=vals[np.isfinite(vals)]
    if not len(vals): return -1.0,1.0,0.0
    median=float(np.nanmedian(vals))
    requested=sum([display_range is not None, display_std is not None, display_min is not None or display_max is not None])
    if requested>1:
        raise SystemExit('Choose one visualization limit mode: --display-min/--display-max, --display-range, or --display-std.')
    if display_min is not None or display_max is not None:
        if display_min is None or display_max is None:
            raise SystemExit('--display-min and --display-max must be supplied together')
        lo=float(display_min); hi=float(display_max)
        if not (np.isfinite(lo) and np.isfinite(hi) and hi>lo):
            raise SystemExit('--display-max must be greater than --display-min')
        return lo,hi,median
    if display_std is not None:
        k=abs(float(display_std))
        if not np.isfinite(k) or k<=0: raise SystemExit('--display-std must be > 0')
        mean=float(np.nanmean(vals)); sd=float(np.nanstd(vals))
        if not np.isfinite(sd) or sd<=0: sd=max(float(np.nanstd(vals-median)),1.0)
        return mean-k*sd,mean+k*sd,mean
    if display_range is not None:
        lim=abs(float(display_range)); return median-lim,median+lim,median
    lim=float(np.nanpercentile(np.abs(vals-median),98.5))
    if not np.isfinite(lim) or lim<=0: lim=max(float(np.nanstd(vals))*3.0,1.0)
    return median-lim,median+lim,median


def _set_export_axis_labels(ax,crs,labels=True,axis_mode='coordinates',data_bounds=None,grid_distance_x=None,grid_distance_y=None,grid_origin_x=None,grid_origin_y=None,label_size=8,tick_size=7):
    """Consistent scientific axes for exports with explicit typography.

    coordinates: full Easting/Northing (or lon/lat) labels, no scientific offset.
    distance: projected metric distances from an origin (default source lower-left),
              optionally using explicit X/Y grid intervals.
    none: no labels/ticks are configured here.
    """
    if not labels or str(axis_mode).lower()=='none':
        return
    try:
        import numpy as np
        from pyproj import CRS
        from matplotlib.ticker import FuncFormatter,MaxNLocator
        cc=CRS.from_user_input(crs) if crs is not None else None
        mode=str(axis_mode).lower()
        if mode=='distance':
            if cc is not None and cc.is_geographic:
                raise SystemExit('--axis-mode distance requires a projected CRS. Reproject first with `export reproject`.')
            b=data_bounds
            ox=float(grid_origin_x) if grid_origin_x is not None else (float(b.left) if b is not None else float(ax.get_xlim()[0]))
            oy=float(grid_origin_y) if grid_origin_y is not None else (float(b.bottom) if b is not None else float(ax.get_ylim()[0]))
            ax.set_xlabel('Grid X distance (m)',fontsize=label_size); ax.set_ylabel('Grid Y distance (m)',fontsize=label_size)
            ax.xaxis.set_major_formatter(FuncFormatter(lambda x,pos:f'{x-ox:.0f}'))
            ax.yaxis.set_major_formatter(FuncFormatter(lambda y,pos:f'{y-oy:.0f}'))
            x0,x1=ax.get_xlim(); y0,y1=ax.get_ylim()
            if grid_distance_x is not None and float(grid_distance_x)>0:
                dx=float(grid_distance_x); lo=np.ceil((min(x0,x1)-ox)/dx)*dx+ox; hi=max(x0,x1)
                ax.set_xticks(np.arange(lo,hi+0.5*dx,dx))
            else:
                ax.xaxis.set_major_locator(MaxNLocator(nbins=6,steps=[1,2,2.5,5,10]))
            if grid_distance_y is not None and float(grid_distance_y)>0:
                dy=float(grid_distance_y); lo=np.ceil((min(y0,y1)-oy)/dy)*dy+oy; hi=max(y0,y1)
                ax.set_yticks(np.arange(lo,hi+0.5*dy,dy))
            else:
                ax.yaxis.set_major_locator(MaxNLocator(nbins=6,steps=[1,2,2.5,5,10]))
            for lab in ax.get_yticklabels(): lab.set_rotation(90); lab.set_va('center'); lab.set_ha('center')
            ax.tick_params(axis='both',labelsize=tick_size); ax.tick_params(axis='y',pad=max(6,tick_size+2))
            return
        if cc is not None and cc.is_geographic:
            ax.set_xlabel('Longitude',fontsize=label_size); ax.set_ylabel('Latitude',fontsize=label_size)
            ax.xaxis.set_major_formatter(FuncFormatter(lambda x,pos:f'{x:.5f}'))
            ax.yaxis.set_major_formatter(FuncFormatter(lambda y,pos:f'{y:.5f}'))
            ax.xaxis.set_major_locator(MaxNLocator(nbins=6)); ax.yaxis.set_major_locator(MaxNLocator(nbins=6))
            for lab in ax.get_yticklabels(): lab.set_rotation(90); lab.set_va('center'); lab.set_ha('center')
            ax.tick_params(axis='both',labelsize=tick_size); ax.tick_params(axis='y',pad=max(6,tick_size+2))
            return
        if cc is not None and cc.is_projected:
            ax.set_xlabel('Easting',fontsize=label_size); ax.set_ylabel('Northing',fontsize=label_size)
            ax.xaxis.set_major_formatter(FuncFormatter(lambda x,pos:f'{x:.0f}'))
            ax.yaxis.set_major_formatter(FuncFormatter(lambda y,pos:f'{y:.0f}'))
            ax.xaxis.set_major_locator(MaxNLocator(nbins=6,steps=[1,2,2.5,5,10]))
            ax.yaxis.set_major_locator(MaxNLocator(nbins=6,steps=[1,2,2.5,5,10]))
            for lab in ax.get_yticklabels(): lab.set_rotation(90); lab.set_va('center'); lab.set_ha('center')
            ax.tick_params(axis='both',labelsize=tick_size); ax.tick_params(axis='y',pad=max(6,tick_size+2))
            return
    except SystemExit:
        raise
    except Exception:
        pass
    ax.set_xlabel('X',fontsize=label_size); ax.set_ylabel('Y',fontsize=label_size); ax.tick_params(axis='both',labelsize=tick_size)


def _set_web_export_axis_labels(ax,render_crs,label_crs,labels=True,axis_mode='coordinates',view_bounds=None,grid_distance_x=None,grid_distance_y=None,label_size=8,tick_size=7):
    """Label an exact Web-Mercator canvas in the scientific raster CRS.

    WebGIS export is rendered in EPSG:3857 so its extent/aspect exactly matches
    Leaflet. Tick text can nevertheless be shown in the first raster's native
    CRS (typically UTM), or as local metric distances from the visible lower-left.
    """
    if not labels or str(axis_mode).lower()=='none': return
    try:
        import numpy as np
        from pyproj import CRS,Transformer
        from rasterio.warp import transform_bounds
        from matplotlib.ticker import FuncFormatter,MaxNLocator
        rc=CRS.from_user_input(render_crs); lc=CRS.from_user_input(label_crs or 'EPSG:4326')
        fwd=Transformer.from_crs(rc,lc,always_xy=True); inv=Transformer.from_crs(lc,rc,always_xy=True)
        x0,x1=ax.get_xlim(); y0,y1=ax.get_ylim(); xm=(x0+x1)/2; ym=(y0+y1)/2
        mode=str(axis_mode).lower()
        if mode=='distance':
            if lc.is_geographic:
                # For geographic source rasters use metric Web-Mercator distance as a
                # display convenience. This is only axis annotation, never data processing.
                ox=min(x0,x1); oy=min(y0,y1)
                ax.set_xlabel('Grid X distance (m)',fontsize=label_size); ax.set_ylabel('Grid Y distance (m)',fontsize=label_size)
                ax.xaxis.set_major_formatter(FuncFormatter(lambda x,pos:f'{x-ox:.0f}')); ax.yaxis.set_major_formatter(FuncFormatter(lambda y,pos:f'{y-oy:.0f}'))
                ax.xaxis.set_major_locator(MaxNLocator(nbins=6,steps=[1,2,2.5,5,10])); ax.yaxis.set_major_locator(MaxNLocator(nbins=6,steps=[1,2,2.5,5,10]))
            else:
                sb=transform_bounds(render_crs,label_crs,min(x0,x1),min(y0,y1),max(x0,x1),max(y0,y1),densify_pts=21); sx0,sy0,sx1,sy1=map(float,sb); smx=(sx0+sx1)/2; smy=(sy0+sy1)/2
                ax.set_xlabel('Grid X distance (m)',fontsize=label_size); ax.set_ylabel('Grid Y distance (m)',fontsize=label_size)
                ax.xaxis.set_major_formatter(FuncFormatter(lambda x,pos:f'{fwd.transform(x,ym)[0]-sx0:.0f}')); ax.yaxis.set_major_formatter(FuncFormatter(lambda y,pos:f'{fwd.transform(xm,y)[1]-sy0:.0f}'))
                if grid_distance_x and float(grid_distance_x)>0:
                    dx=float(grid_distance_x); vals=np.arange(np.ceil(sx0/dx)*dx,sx1+.5*dx,dx); ax.set_xticks([inv.transform(v,smy)[0] for v in vals])
                else: ax.xaxis.set_major_locator(MaxNLocator(nbins=6,steps=[1,2,2.5,5,10]))
                if grid_distance_y and float(grid_distance_y)>0:
                    dy=float(grid_distance_y); vals=np.arange(np.ceil(sy0/dy)*dy,sy1+.5*dy,dy); ax.set_yticks([inv.transform(smx,v)[1] for v in vals])
                else: ax.yaxis.set_major_locator(MaxNLocator(nbins=6,steps=[1,2,2.5,5,10]))
        else:
            ax.xaxis.set_major_locator(MaxNLocator(nbins=6,steps=[1,2,2.5,5,10])); ax.yaxis.set_major_locator(MaxNLocator(nbins=6,steps=[1,2,2.5,5,10]))
            if lc.is_geographic:
                ax.set_xlabel('Longitude',fontsize=label_size); ax.set_ylabel('Latitude',fontsize=label_size)
                ax.xaxis.set_major_formatter(FuncFormatter(lambda x,pos:f'{fwd.transform(x,ym)[0]:.5f}')); ax.yaxis.set_major_formatter(FuncFormatter(lambda y,pos:f'{fwd.transform(xm,y)[1]:.5f}'))
            else:
                ax.set_xlabel('Easting',fontsize=label_size); ax.set_ylabel('Northing',fontsize=label_size)
                ax.xaxis.set_major_formatter(FuncFormatter(lambda x,pos:f'{fwd.transform(x,ym)[0]:.0f}')); ax.yaxis.set_major_formatter(FuncFormatter(lambda y,pos:f'{fwd.transform(xm,y)[1]:.0f}'))
        for lab in ax.get_yticklabels(): lab.set_rotation(90); lab.set_va('center'); lab.set_ha('center')
        ax.tick_params(axis='both',labelsize=tick_size); ax.tick_params(axis='y',pad=max(6,tick_size+2))
    except Exception:
        _set_export_axis_labels(ax,render_crs,labels,axis_mode,view_bounds,grid_distance_x,grid_distance_y,None,None,label_size,tick_size)


def _export_axes_image(ax,arr,bounds,cmap,vmin,vmax,ticks=True,labels=True,grid=True,crs=None,axis_mode='coordinates',data_bounds=None,grid_distance_x=None,grid_distance_y=None,grid_origin_x=None,grid_origin_y=None,label_size=8,tick_size=7,grid_width=0.45,grid_alpha=0.35,display_contrast=1.0,display_brightness=1.0,display_gamma=1.0,display_saturation=1.0):
    dcmap=_display_cmap(cmap,display_contrast,display_brightness,display_gamma,display_saturation)
    im=ax.imshow(arr,origin='upper',extent=(bounds.left,bounds.right,bounds.bottom,bounds.top),cmap=dcmap,vmin=vmin,vmax=vmax,interpolation='nearest')
    ax.set_aspect('equal',adjustable='box')
    ax.set_xlim(float(bounds.left),float(bounds.right)); ax.set_ylim(float(bounds.bottom),float(bounds.top))
    _set_export_axis_labels(ax,crs,labels,axis_mode,data_bounds or bounds,grid_distance_x,grid_distance_y,grid_origin_x,grid_origin_y,label_size,tick_size)
    if not ticks:
        ax.set_xticks([]); ax.set_yticks([])
    if grid and ticks:
        ax.grid(True,linewidth=float(grid_width),alpha=float(grid_alpha))
    return im

def _export_output_dir(pp, kind, requested=None):
    from pathlib import Path
    if requested:
        out=Path(requested).expanduser()
        if not out.is_absolute(): out=pp['exports']/out
    else:
        out=pp['exports']/kind
    out.mkdir(parents=True,exist_ok=True)
    return out


_CARTO_POSITIONS=(
    'inside-bottom-left','inside-bottom-center','inside-bottom-right',
    'inside-top-left','inside-top-center','inside-top-right',
    'outside-bottom-left','outside-bottom-center','outside-bottom-right',
    'outside-top-left','outside-top-center','outside-top-right')


def _style_value(style,name,default=None):
    if isinstance(style,dict): return style.get(name,default)
    return getattr(style,name,default)


def _magnetic_display_label(default_units, style):
    full=_style_value(style,'colorbar_label',None)
    if full not in (None,''): return str(full)
    base=str(_style_value(style,'magnetic_label','Magnetic value') or 'Magnetic value')
    unit=_style_value(style,'magnetic_unit','auto')
    unit=default_units if unit in (None,'auto','AUTO') else str(unit)
    return base if unit=='' else f'{base} ({unit})'


def _display_cmap(cmap='gray_r', contrast=1.0, brightness=1.0, gamma=1.0, saturation=1.0):
    """Return a display-only colour map with tone controls applied.

    Magnetic values and quantitative colourbar limits/ticks are unchanged.
    Only rendered RGB colours are modified.
    """
    import numpy as np
    import matplotlib as mpl
    from matplotlib.colors import ListedColormap
    try: base=mpl.colormaps.get_cmap(cmap)
    except Exception: base=mpl.colormaps.get_cmap('gray_r')
    rgba=np.asarray(base(np.linspace(0.0,1.0,1024)),float).copy()
    rgb=np.clip(rgba[:,:3],0.0,1.0)
    c=max(0.0,float(contrast)); b=max(0.0,float(brightness)); g=max(1e-6,float(gamma)); sat=max(0.0,float(saturation))
    # Gamma > 1 brightens mid-tones; contrast is around mid-grey.
    rgb=np.power(rgb,1.0/g)
    rgb=(rgb-0.5)*c+0.5
    rgb=rgb*b
    # Chroma adjustment. Saturation intentionally has no effect on greyscale maps.
    lum=rgb[:,0]*0.2126+rgb[:,1]*0.7152+rgb[:,2]*0.0722
    rgb=lum[:,None]+sat*(rgb-lum[:,None])
    rgba[:,:3]=np.clip(rgb,0.0,1.0)
    return ListedColormap(rgba,name=f'mspy_display_{getattr(base,"name","cmap")}')


def _add_common_style_args(p, *, map_elements=False):
    import argparse
    typ=p.add_argument_group('Typography and magnetic legend')
    typ.add_argument('--title-size',type=float,default=11,help='Figure/map title font size in points.')
    typ.add_argument('--axis-label-size',type=float,default=8,help='Axis-label font size in points.')
    typ.add_argument('--tick-label-size',type=float,default=7,help='Axis tick-label size in points.')
    typ.add_argument('--grid-width',type=float,default=.45,help='Coordinate grid line width.')
    typ.add_argument('--grid-alpha',type=float,default=.35,help='Coordinate grid opacity 0..1.')
    typ.add_argument('--magnetic-label',default='Magnetic value',help='Text before the magnetic unit in the colourbar label.')
    typ.add_argument('--magnetic-unit',default='auto',help='Text inside parentheses, e.g. nT/m, nT, pT, or custom text. auto uses raster metadata; use an empty string for no parentheses.')
    typ.add_argument('--colorbar-label',default=None,help='Complete colourbar-label override. When set, --magnetic-label/--magnetic-unit are ignored.')
    typ.add_argument('--colorbar-label-size',type=float,default=8,help='Colourbar label size in points.')
    typ.add_argument('--colorbar-tick-size',type=float,default=7,help='Colourbar tick-label size in points.')
    typ.add_argument('--colorbar-thickness',type=float,default=.10,help='Colourbar thickness in physical inches.')
    typ.add_argument('--colorbar-pad',type=float,default=None,help='Optional colourbar separation in physical inches.')

    tone=p.add_argument_group('Display-only magnetogram tone (does not change raster values)')
    tone.add_argument('--display-contrast','--contrast',dest='display_contrast',type=float,default=1.0,help='Contrast multiplier. 1 = unchanged; >1 increases contrast.')
    tone.add_argument('--display-brightness','--brightness',dest='display_brightness',type=float,default=1.0,help='Brightness multiplier. 1 = unchanged.')
    tone.add_argument('--display-gamma','--gamma',dest='display_gamma',type=float,default=1.0,help='Gamma. 1 = unchanged; >1 brightens mid-tones; <1 darkens them.')
    tone.add_argument('--display-saturation','--saturation',dest='display_saturation',type=float,default=1.0,help='Colour saturation. 1 = unchanged, 0 = greyscale; no visible effect on greyscale colour maps.')

    brand=p.add_argument_group('Optional credits and branding')
    brand.add_argument('--credit-size',type=float,default=5.7,help='Basemap/provider attribution text size in points.')
    brand.add_argument('--mspy-credit',action=argparse.BooleanOptionalAction,default=False,help='Add the version-neutral MagSurveyPy logo. Off by default.')
    brand.add_argument('--mspy-credit-position',choices=('bottom-left','bottom-center','bottom-right'),default='bottom-left',help='Position of the optional MagSurveyPy logo credit.')
    brand.add_argument('--mspy-credit-size',type=float,default=.10,help='Optional MagSurveyPy logo size (matplotlib image zoom factor).')
    brand.add_argument('--mspy-credit-alpha',type=float,default=1.0,help='Optional MagSurveyPy logo opacity 0..1.')

    if map_elements:
        cart=p.add_argument_group('Scale bar and north arrow')
        cart.add_argument('--scale-bar-position',choices=_CARTO_POSITIONS,default='inside-bottom-left',help='Scale-bar location inside or outside the map frame.')
        cart.add_argument('--scale-bar-style',choices=('blocks','line','simple'),default='blocks',help='Scale-bar design: alternating blocks, metric line, or simple filled bar.')
        cart.add_argument('--scale-bar-length',default='auto',help='Total scale-bar length in metres, or auto.')
        cart.add_argument('--scale-bar-segments',type=int,default=4,help='Number of equal scale-bar segments (1..8).')
        cart.add_argument('--scale-bar-font-size',type=float,default=6.4,help='Scale-bar tick-label size in points.')
        cart.add_argument('--scale-bar-box',action=argparse.BooleanOptionalAction,default=True,help='Draw a background box around the scale bar.')
        cart.add_argument('--scale-bar-box-alpha',type=float,default=.86,help='Scale-bar background opacity 0..1.')
        cart.add_argument('--north-position',choices=_CARTO_POSITIONS,default='inside-top-right',help='North-arrow position inside or outside the map frame.')
        cart.add_argument('--north-size',type=float,default=.115,help='North-arrow image zoom factor.')
        cart.add_argument('--north-box',action=argparse.BooleanOptionalAction,default=True,help='Draw a background box around the north arrow.')
        cart.add_argument('--north-box-alpha',type=float,default=.56,help='North-arrow background opacity 0..1.')


def _carto_anchor(position,width_frac=0.32):
    pos=str(position or 'inside-bottom-left').lower()
    outside=pos.startswith('outside-')
    loc=pos.split('-',1)[1] if '-' in pos else pos
    vertical='top' if 'top' in loc else 'bottom'
    horizontal='center' if 'center' in loc else ('right' if 'right' in loc else 'left')
    if horizontal=='left': x0=0.035
    elif horizontal=='right': x0=0.965-width_frac
    else: x0=0.5-width_frac/2
    if vertical=='bottom': y= -0.095 if outside else 0.050
    else: y=1.075 if outside else 0.935
    return x0,y,horizontal,vertical,outside


def _credit_footer_y(scale_position=None,colorbar_position=None):
    y=-0.085
    if str(colorbar_position or '').lower()=='bottom': y-=0.105
    if str(scale_position or '').startswith('outside-bottom'): y-=0.105
    return y


def _add_mspy_logo_credit_ax(ax, *, enabled=False, position='bottom-left', size=.10, alpha=1.0, y=None):
    """Add the optional version-neutral MagSurveyPy logo; never text/version branding."""
    if not enabled: return False
    try:
        from PIL import Image
        from matplotlib.offsetbox import OffsetImage,AnnotationBbox
        logo=Path(__file__).with_name('assets')/'magsurveypy_logo.png'
        if not logo.exists(): return False
        arr=Image.open(logo).convert('RGBA')
        pos=str(position or 'bottom-left').lower(); x=.0 if pos.endswith('left') else (.5 if pos.endswith('center') else 1.0)
        align_x=0 if pos.endswith('left') else (.5 if pos.endswith('center') else 1)
        yy=float(-.085 if y is None else y)
        oi=OffsetImage(arr,zoom=max(.015,float(size)),alpha=max(0,min(1,float(alpha))))
        ab=AnnotationBbox(oi,(x,yy),xycoords='axes fraction',box_alignment=(align_x,1),frameon=False,annotation_clip=False,zorder=61)
        ax.add_artist(ab); return True
    except Exception:
        return False


def _add_figure_logo_credit(fig, *, enabled=False, position='bottom-left', size=.10, alpha=1.0):
    """Optional version-neutral logo for comparison/analysis/recipe figures."""
    if not enabled: return False
    try:
        import matplotlib.pyplot as plt
        logo=Path(__file__).with_name('assets')/'magsurveypy_logo.png'
        if not logo.exists(): return False
        arr=plt.imread(logo); h,w=arr.shape[:2]; fw,fh=fig.get_size_inches()
        width=max(.035,min(.28,float(size)*1.45)); height=width*(h/w)*(fw/fh)
        pos=str(position or 'bottom-left').lower()
        x=.008 if pos.endswith('left') else (.5-width/2 if pos.endswith('center') else .992-width)
        y=.006
        iax=fig.add_axes([x,y,width,height],zorder=100); iax.imshow(arr,alpha=max(0,min(1,float(alpha)))); iax.set_axis_off(); return True
    except Exception:
        return False


def _add_export_credits(ax, basemap_attribution='', *, fontsize=5.7, scale_position=None, colorbar_position=None,
                        mspy_credit=False,mspy_credit_position='bottom-left',mspy_credit_size=.10,mspy_credit_alpha=1.0,
                        basemap_credit=True):
    """Optional logo and provider attribution below the map; no MagSurveyPy credit by default."""
    y=_credit_footer_y(scale_position,colorbar_position)
    logo_added=_add_mspy_logo_credit_ax(ax,enabled=bool(mspy_credit),position=mspy_credit_position,size=mspy_credit_size,alpha=mspy_credit_alpha,y=y)
    if basemap_credit and basemap_attribution:
        attr_y=y
        # If the optional logo also occupies the right footer, put attribution on the next line.
        if logo_added and str(mspy_credit_position).endswith('right'): attr_y-=0.055
        ax.text(1.0,attr_y,str(basemap_attribution),transform=ax.transAxes,
                ha='right',va='top',fontsize=fontsize,color='0.35',clip_on=False,zorder=60)

def _export_figure_cli(argv):
    import argparse
    from pathlib import Path
    import matplotlib.pyplot as plt
    p=argparse.ArgumentParser(prog='mspy figure single',description='Publication-quality magnetic figure with extensive cartographic, tone and typographic styling. Scientific raster values are never modified.',formatter_class=argparse.RawDescriptionHelpFormatter,epilog='''Examples:
  Exact -10..+10 nT scale:
    mspy figure single --project Foeni --from TOTAL_FIELD --display-min -10 --display-max 10 --magnetic-unit nT

  Display-only contrast/gamma enhancement:
    mspy figure single --project Rupea --from INTERPOLATED --display-range 15 --contrast 1.25 --gamma 1.10

  Optional scale/north/logo:
    mspy figure single --project Rupea --from CLEAN --scale-bar --north-arrow --mspy-credit

Use `mspy guide cartography` for the full styling guide.''' )
    p.add_argument('--project',required=True); p.add_argument('--from',dest='stage',default=None,help='Results stage, e.g. INTERPOLATED or CLEAN.')
    p.add_argument('--input',type=Path,default=None,help='Explicit GeoTIFF instead of automatic stage selection.')
    p.add_argument('-o','--output',type=Path,default=None); p.add_argument('--format',choices=('png','tiff','pdf','svg'),default='png'); p.add_argument('--dpi',type=int,default=300)
    p.add_argument('--display-range',type=float,default=None,metavar='ABS',help='Symmetric range around the raster median.'); p.add_argument('--display-std',type=float,default=None,metavar='N',help='Display-only clipping at mean +/- N standard deviations, e.g. --display-std 2. Does not alter raster values.'); p.add_argument('--display-min',type=float,default=None,help='Exact lower colourbar limit; use together with --display-max.'); p.add_argument('--display-max',type=float,default=None,help='Exact upper colourbar limit; use together with --display-min.'); p.add_argument('--cmap',default='gray_r'); p.add_argument('--title',default=None); p.add_argument('--increment','--new-output',dest='increment',action='store_true',help='Never replace an existing figure. If the target exists, write _1, _2, ... instead.')
    p.add_argument('--colorbar',action=argparse.BooleanOptionalAction,default=True); p.add_argument('--colorbar-position',choices=('right','bottom'),default='right',help='Thin magnetic colourbar on the right or bottom.')
    p.add_argument('--ticks',action=argparse.BooleanOptionalAction,default=True); p.add_argument('--labels',action=argparse.BooleanOptionalAction,default=True); p.add_argument('--grid',action=argparse.BooleanOptionalAction,default=False)
    p.add_argument('--scale-bar',action=argparse.BooleanOptionalAction,default=False,help='Optional publication scale bar.'); p.add_argument('--north-arrow',action=argparse.BooleanOptionalAction,default=False,help='Optional north arrow.')
    p.add_argument('--axis-mode',choices=('coordinates','distance','none'),default='coordinates',help='coordinates = Easting/Northing; distance = local metric X/Y distance; none = no axis labels.')
    p.add_argument('--grid-distance-x',type=float,default=None,metavar='M'); p.add_argument('--grid-distance-y',type=float,default=None,metavar='M'); p.add_argument('--grid-origin-x',type=float,default=None); p.add_argument('--grid-origin-y',type=float,default=None)
    _add_common_style_args(p,map_elements=True)
    p.add_argument('--workspace',type=Path,default=None)
    a=p.parse_args(argv); pp=_ensure_project(a.project,a.workspace); src=_export_stage_raster(pp,a.stage,a.input); arr,tr,crs,bounds,profile,tags=_export_read(src)
    vmin,vmax,_=_export_limits(arr,a.display_range,a.display_min,a.display_max,a.display_std); out=_export_output_dir(pp,'Figures',a.output); ext='tif' if a.format=='tiff' else a.format
    fp=out/f'{_safe_project_name(a.project)}_{(a.stage or src.stem)}_figure.{ext}'; fp=_unique_numbered_path(fp) if a.increment else fp
    fig,ax=_single_map_figure((bounds.left,bounds.right,bounds.bottom,bounds.top),None)
    im=_export_axes_image(ax,arr,bounds,a.cmap,vmin,vmax,a.ticks,a.labels,a.grid,crs,a.axis_mode,bounds,a.grid_distance_x,a.grid_distance_y,a.grid_origin_x,a.grid_origin_y,a.axis_label_size,a.tick_label_size,a.grid_width,a.grid_alpha,a.display_contrast,a.display_brightness,a.display_gamma,a.display_saturation)
    ax.set_title(a.title or _safe_project_name(a.project),fontsize=a.title_size)
    if a.scale_bar:
        setattr(a,'scale_bar_offset',.13 if a.colorbar and a.colorbar_position=='bottom' and str(a.scale_bar_position).startswith('outside-bottom') else 0.0); _add_publication_scale_bar(ax,bounds,crs,a)
    if a.north_arrow: _add_publication_north_arrow(ax,a)
    if a.colorbar: _publication_colorbar(fig,ax,im,_magnetic_display_label(_export_units(src,tags),a),a.colorbar_position,fontsize=a.colorbar_label_size,tick_fontsize=a.colorbar_tick_size,thickness=a.colorbar_thickness,pad=a.colorbar_pad)
    _add_export_credits(ax,'',fontsize=a.credit_size,scale_position=a.scale_bar_position if a.scale_bar else None,colorbar_position=a.colorbar_position if a.colorbar else None,mspy_credit=a.mspy_credit,mspy_credit_position=a.mspy_credit_position,mspy_credit_size=a.mspy_credit_size,mspy_credit_alpha=a.mspy_credit_alpha,basemap_credit=False)
    fig.savefig(fp,dpi=a.dpi,bbox_inches='tight',pad_inches=.06); plt.close(fig)
    print(f'Scientific figure: {fp}'); return 0

def _nice_scale_interval(width_m, nseg=4, target_fraction=0.32):
    """Choose one fixed, round segment interval for a publication scale bar.

    The bar targets roughly one third of the visible map width.  Every segment
    has the same metric length and all labels stay on one baseline, e.g.
    0  10  20  30  40 m or 0  50  100  150  200 m.
    """
    import math
    wm=float(width_m)
    if not math.isfinite(wm) or wm <= 0:
        return 1.0
    target=max(wm*float(target_fraction)/max(int(nseg),1),1e-9)
    exp=math.floor(math.log10(target))
    vals=[]
    for e in range(exp-3,exp+4):
        base=10.0**e
        for m in (1.0,2.0,2.5,5.0,10.0):
            vals.append(m*base)
    vals=sorted(set(v for v in vals if v>0))
    # Score by closeness to the desired total fraction, with a gentle preference
    # for bars between 27 and 40 percent of the map width so tick text breathes.
    def score(v):
        frac=v*nseg/wm
        penalty=0.0 if 0.27<=frac<=0.40 else min(abs(frac-0.27),abs(frac-0.40))*4.0
        return abs(math.log(max(frac,1e-12)/target_fraction))+penalty
    return min(vals,key=score)


def _format_scale_tick(value_m, use_km=False, final=False):
    v=float(value_m)
    if use_km:
        val=v/1000.0
        txt=f'{val:g}'
        return txt + (' km' if final else '')
    if abs(v-round(v))<1e-8:
        txt=str(int(round(v)))
    elif v>=1:
        txt=f'{v:g}'
    else:
        txt=f'{v:.2f}'.rstrip('0').rstrip('.')
    return txt + (' m' if final else '')


def _metric_width_and_x_delta(bounds,crs,length_m=None):
    """Return approximate map width in metres and x-data delta for length_m."""
    from pyproj import CRS,Geod
    width=float(bounds.right-bounds.left); midy=float((bounds.bottom+bounds.top)/2)
    if crs is None:
        return None,None
    cc=CRS.from_user_input(crs)
    if cc.is_geographic:
        geod=Geod(ellps='WGS84')
        _,_,wm=geod.inv(float(bounds.left),midy,float(bounds.right),midy)
        if length_m is None: return abs(float(wm)),None
        lon2,_,_=geod.fwd(float(bounds.left),midy,90.0,float(length_m))
        return abs(float(wm)),abs(float(lon2-bounds.left))
    fac=1.0
    try:
        fac=float(cc.axis_info[0].unit_conversion_factor or 1.0)
    except Exception:
        fac=1.0
    width_m=abs(width)*fac
    return width_m, (float(length_m)/fac if length_m is not None else None)


def _add_publication_scale_bar(ax,bounds,crs,style=None):
    """Highly configurable metric scale bar that never lets edge labels escape its box."""
    import math
    import matplotlib.patches as patches
    wm,_=_metric_width_and_x_delta(bounds,crs,None)
    if wm is None or wm<=0: return False
    nseg=int(max(1,min(8,int(_style_value(style,'scale_bar_segments',4)))))
    spec=str(_style_value(style,'scale_bar_length','auto')).strip().lower()
    if spec=='auto':
        interval_m=_nice_scale_interval(wm,nseg=nseg,target_fraction=.32); total_m=interval_m*nseg
    else:
        try: total_m=float(spec)
        except Exception: raise SystemExit('--scale-bar-length must be metres or auto')
        if not math.isfinite(total_m) or total_m<=0: raise SystemExit('--scale-bar-length must be positive')
        interval_m=total_m/nseg
    frac=min(.52,max(.16,total_m/wm))
    position=_style_value(style,'scale_bar_position','inside-bottom-left')
    x0,y0,_,vertical,outside=_carto_anchor(position,frac)
    extra=max(0.0,float(_style_value(style,'scale_bar_offset',0.0) or 0.0))
    if outside: y0 = y0-extra if vertical=='bottom' else y0+extra
    bar_h=.011
    fs=max(4.5,float(_style_value(style,'scale_bar_font_size',6.4)))
    box=bool(_style_value(style,'scale_bar_box',True)); alpha=max(0,min(1,float(_style_value(style,'scale_bar_box_alpha',.86))))
    style_name=str(_style_value(style,'scale_bar_style','blocks')).lower()
    label_gap=.012
    labels_above=(vertical=='top')
    label_y=(y0+bar_h+label_gap) if labels_above else (y0-label_gap)
    pad_x=.015; pad_y=.032
    box_y=(y0-.032 if not labels_above else y0-.012)
    box_h=bar_h+.048
    box_patch=None
    if box:
        box_patch=patches.FancyBboxPatch((x0-pad_x,box_y),frac+2*pad_x,box_h,boxstyle='round,pad=0.004',transform=ax.transAxes,
            facecolor='white',edgecolor='0.25',linewidth=.35,alpha=alpha,zorder=30,clip_on=not outside)
        ax.add_patch(box_patch)
    seg=frac/nseg
    if style_name=='blocks':
        for i in range(nseg):
            ax.add_patch(patches.Rectangle((x0+i*seg,y0),seg,bar_h,transform=ax.transAxes,
                facecolor=('0.10' if i%2==0 else 'white'),edgecolor='0.10',linewidth=.55,zorder=31,clip_on=not outside))
    elif style_name=='simple':
        ax.add_patch(patches.Rectangle((x0,y0),frac,bar_h,transform=ax.transAxes,facecolor='0.12',edgecolor='0.10',linewidth=.55,zorder=31,clip_on=not outside))
    else:
        ax.plot([x0,x0+frac],[y0+bar_h/2,y0+bar_h/2],transform=ax.transAxes,color='0.10',lw=1.25,zorder=31,clip_on=not outside)
    use_km=total_m>=2000.0
    texts=[]
    for i in range(nseg+1):
        xx=x0+i*seg
        ax.plot([xx,xx],[y0,y0+1.3*bar_h],transform=ax.transAxes,color='0.10',lw=.58,zorder=32,clip_on=not outside)
        text=_format_scale_tick(interval_m*i,use_km=use_km,final=(i==nseg))
        ha='left' if i==0 else ('right' if i==nseg else 'center')
        va='bottom' if labels_above else 'top'
        t=ax.text(xx,label_y,text,transform=ax.transAxes,ha=ha,va=va,fontsize=fs,color='0.08',zorder=33,clip_on=False)
        texts.append(t)
    # First and last labels face inward.  When a box is requested, make the box
    # the clipping boundary as a final guarantee that labels never escape it.
    if box_patch is not None and not outside:
        for t in texts: t.set_clip_path(box_patch)
    return True


def _add_publication_north_arrow(ax,style=None):
    """Configurable north arrow using the supplied MagSurveyPy graphic."""
    from pathlib import Path
    try:
        from PIL import Image
        from matplotlib.offsetbox import OffsetImage,AnnotationBbox
        path=Path(__file__).with_name('assets')/'north_arrow.png'
        if not path.exists(): return False
        arr=Image.open(path).convert('RGBA')
        position=str(_style_value(style,'north_position','inside-top-right'))
        _,_,horizontal,vertical,outside=_carto_anchor(position,.10)
        x=.035 if horizontal=='left' else (.5 if horizontal=='center' else .965)
        y=(-.025 if outside else .035) if vertical=='bottom' else (1.025 if outside else .965)
        align_x=0 if horizontal=='left' else (.5 if horizontal=='center' else 1)
        align_y=(1 if vertical=='bottom' else 0) if outside else (0 if vertical=='bottom' else 1)
        oi=OffsetImage(arr,zoom=max(.025,float(_style_value(style,'north_size',.115))))
        frame=bool(_style_value(style,'north_box',True)); alpha=max(0,min(1,float(_style_value(style,'north_box_alpha',.56))))
        ab=AnnotationBbox(oi,(x,y),xycoords='axes fraction',box_alignment=(align_x,align_y),frameon=frame,
            bboxprops=dict(boxstyle='round,pad=0.12',facecolor='white',edgecolor='none',alpha=alpha),
            annotation_clip=not outside,zorder=40)
        ax.add_artist(ab); return True
    except Exception:
        return False


def _resolve_basemap_provider(name,custom_url='',attribution=''):
    import xyzservices.providers as providers
    from xyzservices import TileProvider
    n=str(name).lower()
    if n=='esri-satellite': return providers.Esri.WorldImagery,'Esri World Imagery'
    if n=='esri-topo': return providers.Esri.WorldTopoMap,'Esri World Topographic Map'
    if n=='carto-light': return providers.CartoDB.Positron,'CARTO / OpenStreetMap contributors'
    if n=='carto-dark': return providers.CartoDB.DarkMatter,'CARTO / OpenStreetMap contributors'
    if n=='osm': return providers.OpenStreetMap.Mapnik,'OpenStreetMap contributors'
    if n in {'custom','google-satellite'}:
        if not custom_url:
            if n=='google-satellite':
                raise SystemExit('Google satellite requires a licensed XYZ tile URL supplied with --basemap-url. MagSurveyPy does not embed unofficial Google tile endpoints.')
            raise SystemExit('--basemap custom requires --basemap-url URL_TEMPLATE')
        return TileProvider(name='LicensedCustom',url=custom_url,attribution=attribution or ('Google Maps' if n=='google-satellite' else 'Custom basemap')),(attribution or ('Google Maps' if n=='google-satellite' else 'Custom basemap'))
    raise SystemExit(f'Unknown basemap provider: {name}')


def _parse_map_zoom(value):
    if value is None or str(value).lower()=='auto': return 'auto'
    try: z=int(value)
    except Exception: raise SystemExit('--zoom must be auto or an integer 0..22')
    if not 0<=z<=22: raise SystemExit('--zoom must be between 0 and 22')
    return z


def _view_bounds_for_zoom(bounds, crs, zoom, canvas_px=(1150, 850)):
    """Return the map VIEW extent. Integer zoom follows Web-Mercator zoom semantics.

    This is intentionally different from merely changing tile resolution: lowering the
    zoom enlarges the map extent, so the basemap and the magnetometry both become
    smaller inside the exported map. `auto` fits the survey with a small context margin.
    """
    from rasterio.coords import BoundingBox
    z=_parse_map_zoom(zoom)
    if z=='auto':
        dx=float(bounds.right-bounds.left); dy=float(bounds.top-bounds.bottom)
        mx=max(abs(dx)*0.035,1e-12); my=max(abs(dy)*0.035,1e-12)
        return BoundingBox(float(bounds.left)-mx,float(bounds.bottom)-my,float(bounds.right)+mx,float(bounds.top)+my)
    if crs is None:
        raise SystemExit('Integer --zoom requires a real CRS. Use --zoom auto for local coordinates.')
    from rasterio.warp import transform_bounds
    w,s,e,n=transform_bounds(crs,'EPSG:3857',float(bounds.left),float(bounds.bottom),float(bounds.right),float(bounds.top),densify_pts=21)
    cx=(w+e)/2.0; cy=(s+n)/2.0
    metres_per_pixel=156543.03392804097/(2.0**int(z))
    vw=metres_per_pixel*float(canvas_px[0]); vh=metres_per_pixel*float(canvas_px[1])
    vw=max(vw,1.0); vh=max(vh,1.0)
    vw0,vs0,ve0,vn0=cx-vw/2.0,cy-vh/2.0,cx+vw/2.0,cy+vh/2.0
    l,b,r,t=transform_bounds('EPSG:3857',crs,vw0,vs0,ve0,vn0,densify_pts=21)
    return BoundingBox(float(l),float(b),float(r),float(t))


def _view_grid(view_bounds, max_width=1400):
    """Create a practical export canvas and affine transform for one map view."""
    from rasterio.transform import from_bounds
    w=max(abs(float(view_bounds.right-view_bounds.left)),1e-12)
    h=max(abs(float(view_bounds.top-view_bounds.bottom)),1e-12)
    width=int(max_width)
    height=int(round(width*h/w))
    height=max(420,min(height,1400))
    transform=from_bounds(float(view_bounds.left),float(view_bounds.bottom),float(view_bounds.right),float(view_bounds.top),width,height)
    return (height,width),transform


def _warp_magnetic_to_view(arr, src_transform, crs, view_bounds, shape):
    """Warp the magnetic raster into the complete map-view canvas, preserving NoData."""
    import numpy as np
    from rasterio.transform import from_bounds
    from rasterio.warp import reproject,Resampling
    dst=np.full(shape,np.nan,dtype=np.float32)
    dst_transform=from_bounds(float(view_bounds.left),float(view_bounds.bottom),float(view_bounds.right),float(view_bounds.top),shape[1],shape[0])
    reproject(source=np.asarray(arr,dtype=np.float32),destination=dst,src_transform=src_transform,src_crs=crs,
              dst_transform=dst_transform,dst_crs=crs,src_nodata=np.nan,dst_nodata=np.nan,resampling=Resampling.bilinear)
    return dst,dst_transform


def _fetch_basemap_on_raster_grid(bounds,transform,crs,shape,provider,zoom='auto',fallback_osm=False):
    """Download XYZ tiles, warp them to the magnetic raster CRS/grid, return RGBA uint8."""
    import numpy as np
    import rasterio
    from rasterio.transform import from_bounds
    from rasterio.warp import transform_bounds,reproject,Resampling
    try:
        import contextily as cx
    except Exception as exc:
        raise SystemExit('Online basemaps require contextily. Install all standard dependencies with: python -m pip install -r requirements.txt') from exc
    w,s,e,n=transform_bounds(crs,'EPSG:3857',float(bounds.left),float(bounds.bottom),float(bounds.right),float(bounds.top),densify_pts=21)
    try:
        img,ext=cx.bounds2img(w,s,e,n,zoom=zoom,source=provider,ll=False)
    except Exception as exc:
        if fallback_osm:
            try:
                import xyzservices.providers as providers
                print(f'OpenStreetMap tile request failed ({exc}). Falling back to CARTO Positron (OSM-derived cartography).',flush=True)
                img,ext=cx.bounds2img(w,s,e,n,zoom=zoom,source=providers.CartoDB.Positron,ll=False)
            except Exception as exc2:
                raise SystemExit(f'Could not download OSM/cartographic basemap: {exc2}')
        else:
            raise SystemExit(f'Could not download/render basemap: {exc}')
    img=np.asarray(img)
    if img.ndim!=3: raise SystemExit('Basemap provider returned an unexpected tile image.')
    if img.shape[2]==3:
        alpha=np.full(img.shape[:2]+(1,),255,dtype=np.uint8); img=np.concatenate([img.astype(np.uint8),alpha],axis=2)
    else: img=img[:,:,:4].astype(np.uint8)
    left,right,bottom,top=map(float,ext)
    src_transform=from_bounds(left,bottom,right,top,img.shape[1],img.shape[0])
    dst=np.zeros((shape[0],shape[1],4),dtype=np.uint8)
    for band in range(4):
        reproject(img[:,:,band],dst[:,:,band],src_transform=src_transform,src_crs='EPSG:3857',
                  dst_transform=transform,dst_crs=crs,resampling=Resampling.bilinear,src_nodata=None,dst_nodata=0)
    return dst


def _blend_magnetic_basemap(arr,base_rgba,cmap,vmin,vmax,mode='normal',opacity=0.82,basemap_opacity=1.0,display_contrast=1.0,display_brightness=1.0,display_gamma=1.0,display_saturation=1.0):
    """Compose scientific magnetic display above the basemap. Tone controls are display-only."""
    import numpy as np
    import matplotlib as mpl
    z=np.asarray(arr,float); valid=np.isfinite(z)
    norm=mpl.colors.Normalize(vmin=vmin,vmax=vmax,clip=True)
    dcmap=_display_cmap(cmap,display_contrast,display_brightness,display_gamma,display_saturation)
    mag=dcmap(norm(np.where(valid,z,vmin)))[:,:,:3]
    base=np.asarray(base_rgba[:,:,:3],float)/255.0
    ba=np.asarray(base_rgba[:,:,3],float)/255.0
    bop=float(np.clip(basemap_opacity,0,1)); base=base*ba[:,:,None]*bop + (1-ba[:,:,None]*bop)
    m=str(mode).lower()
    if m=='normal': blend=mag
    elif m=='multiply': blend=base*mag
    elif m=='screen': blend=1.0-(1.0-base)*(1.0-mag)
    elif m=='overlay': blend=np.where(base<=0.5,2.0*base*mag,1.0-2.0*(1.0-base)*(1.0-mag))
    elif m=='soft-light': blend=(1-2*mag)*base*base + 2*mag*base
    elif m=='difference': blend=np.abs(base-mag)
    else: raise SystemExit('--blend must be normal, multiply, screen, overlay, soft-light or difference')
    a=np.clip(float(opacity),0,1)*valid.astype(float)
    out=base*(1-a[:,:,None])+np.clip(blend,0,1)*a[:,:,None]
    rgba=np.empty(z.shape+(4,),dtype=float); rgba[:,:,:3]=np.clip(out,0,1); rgba[:,:,3]=1.0
    return rgba,norm,dcmap


def _export_map_cli(argv):
    import argparse
    from pathlib import Path
    import matplotlib.pyplot as plt
    import matplotlib as mpl
    p=argparse.ArgumentParser(prog='mspy export map',description='Publication cartography with highly customizable scale bar, north arrow, magnetic legend, display tone and optional credits. The magnetic survey is always rendered above any basemap.',formatter_class=argparse.RawDescriptionHelpFormatter,epilog='''Examples:
  Exact -20..+20 nT map:
    mspy export map --project Foeni --input archaeology.tif --display-min -20 --display-max 20 --magnetic-unit nT

  Enhanced display without altering the GeoTIFF:
    mspy export map --project Rupea --from INTERPOLATED --contrast 1.25 --brightness 1.05 --gamma 1.10

  No provider credit (only where licensing permits):
    mspy export map --project Rupea --from CLEAN --basemap esri-satellite --no-basemap-credit

  Optional MagSurveyPy logo (off by default):
    mspy export map --project Rupea --from CLEAN --mspy-credit --mspy-credit-position bottom-left

Use `mspy guide cartography` for all scale-bar, north-arrow, legend and typography options.''' )
    p.add_argument('--project',required=True); p.add_argument('--from',dest='stage',default=None); p.add_argument('--input',type=Path,default=None); p.add_argument('-o','--output',type=Path,default=None)
    p.add_argument('--basemap',choices=('none','esri-satellite'),default='none',help='Supported static basemap. Web GIS additionally supports OSM, Esri Topographic and custom services.')
    p.add_argument('--basemap-credit',action=argparse.BooleanOptionalAction,default=True,help='Show basemap/provider attribution independently of MagSurveyPy branding. On by default when a basemap is used; disable only where provider licensing permits.')
    p.add_argument('--zoom',default='auto',help='Map-view zoom: auto or Web-map zoom 0..22. BOTH basemap and magnetometry scale together.')
