    if a.basemap!='none' and crs is None: raise SystemExit('A real CRS is required for an online basemap.')
    vmin,vmax,_=_export_limits(arr,a.display_range,a.display_min,a.display_max,a.display_std); out=_export_output_dir(pp,'Maps',a.output); ext='tif' if a.format=='tiff' else a.format; fp=out/f'{_safe_project_name(a.project)}_{(a.stage or src.stem)}_map.{ext}'; fp=_unique_numbered_path(fp) if a.increment else fp
    zoom_value=_parse_map_zoom(a.zoom); view_bounds=_view_bounds_for_zoom(bounds,crs,zoom_value)
