        ax.set_xlim(float(view_bounds.left),float(view_bounds.right)); ax.set_ylim(float(view_bounds.bottom),float(view_bounds.top))
        _set_export_axis_labels(ax,crs,a.labels,a.axis_mode,bounds,a.grid_distance_x,a.grid_distance_y,a.grid_origin_x,a.grid_origin_y,a.axis_label_size,a.tick_label_size)
