        comp,norm,dcmap=_blend_magnetic_basemap(mag_view,base,a.cmap,vmin,vmax,a.blend,a.opacity,a.basemap_opacity,a.display_contrast,a.display_brightness,a.display_gamma,a.display_saturation)
        ax.imshow(comp,origin='upper',extent=(view_bounds.left,view_bounds.right,view_bounds.bottom,view_bounds.top),interpolation='bilinear',zorder=1)
