_WEB_CMAPS=('gray_r','gray','RdBu_r','seismic','viridis','plasma','inferno','magma','turbo','cividis')
_WEB_BLEND=('normal','multiply','screen','overlay','soft-light','difference')


def _web_layer_meta(path,pp,default_on=False):
    """Build one browser-safe GIS layer description from a project file."""
    import hashlib
    import numpy as np
    from pathlib import Path
    q=Path(path).resolve()
    lid=hashlib.sha1(str(q).encode('utf-8')).hexdigest()[:14]
    suffix=q.suffix.lower()
    if suffix in {'.tif','.tiff'}:
        import rasterio
        from rasterio.warp import transform_bounds
        from rasterio.enums import Resampling
        with rasterio.open(q) as ds:
            if ds.count<1 or ds.crs is None: raise ValueError('raster needs a CRS')
            b4326=transform_bounds(ds.crs,'EPSG:4326',*ds.bounds,densify_pts=21)
            ow=min(ds.width,720); oh=max(1,int(round(ow*ds.height/max(ds.width,1))))
            if oh>720: oh=720; ow=max(1,int(round(oh*ds.width/max(ds.height,1))))
            a=ds.read(1,out_shape=(oh,ow),masked=True,resampling=Resampling.bilinear).astype(float)
            vals=np.asarray(a.compressed(),float)
            if not vals.size: raise ValueError('raster has no finite values')
            med=float(np.nanmedian(vals)); q01=float(np.nanpercentile(vals,1)); q99=float(np.nanpercentile(vals,99)); half=max(abs(q01-med),abs(q99-med),1e-6); half=min(15.0,half) if half>1.0 else half
            stage='EXTERNAL'
            try:
                rel=q.relative_to(pp['results']); stage=rel.parts[0].upper() if rel.parts else 'RESULT'
            except Exception:
                try:
                    rel=q.relative_to(pp['exports']); stage='EXPORT'
                except Exception: pass
            units=_export_units(q,ds.tags())
            return {'id':lid,'type':'raster','name':f'{stage}: {q.stem}','stage':stage,'path':str(q),'bounds':[[float(b4326[1]),float(b4326[0])],[float(b4326[3]),float(b4326[2])]],'vmin':med-half,'vmax':med+half,'data_min':float(np.nanmin(vals)),'data_max':float(np.nanmax(vals)),'mean':float(np.nanmean(vals)),'std':float(np.nanstd(vals)),'p01':q01,'p99':q99,'crs':str(ds.crs),'width':int(ds.width),'height':int(ds.height),'units':units,'default_on':bool(default_on)}
    if suffix in {'.shp','.gpkg','.geojson','.json'}:
        import geopandas as gpd
        gdf=gpd.read_file(q)
        if gdf.empty: raise ValueError('vector is empty')
        if gdf.crs is None: raise ValueError('vector needs a CRS')
        b=gdf.to_crs('EPSG:4326').total_bounds
        fields=[str(c) for c in gdf.columns if str(c)!=str(gdf.geometry.name)]
        geom_types=sorted({str(x) for x in gdf.geometry.geom_type.dropna().unique()})
        return {'id':lid,'type':'vector','name':f'Vector: {q.stem}','stage':'VECTOR','path':str(q),'bounds':[[float(b[1]),float(b[0])],[float(b[3]),float(b[2])]],'crs':str(gdf.crs),'feature_count':int(len(gdf)),'fields':fields[:100],'geometry_types':geom_types,'default_on':bool(default_on)}
    raise ValueError('unsupported GIS file type')


def _web_all_project_files(pp):
    """List addable GIS files without loading them into the browser panel."""
    import hashlib
    out=[]; seen=set(); exts={'.tif':'raster','.tiff':'raster','.shp':'vector','.gpkg':'vector','.geojson':'vector'}
    for base in (pp['results'],pp['exports'],pp['root']/'RawData'):
        if not base.exists(): continue
        for q in sorted(base.rglob('*')):
            if not q.is_file() or q.suffix.lower() not in exts: continue
            if q.suffix.lower()=='.json' and q.name in {'project.json','MANIFEST_SHA256.json'}: continue
            rp=str(q.resolve())
            if rp in seen: continue
            seen.add(rp)
            try: name=str(q.relative_to(pp['root']))
            except Exception: name=q.name
            key=hashlib.sha1(('available:'+rp).encode('utf-8')).hexdigest()[:16]
            rec={'key':key,'name':name,'path':rp,'type':exts[q.suffix.lower()]}
            if rec['type']=='raster':
                try:
                    import rasterio
                    with rasterio.open(q) as ds:
                        rec.update(width=int(ds.width),height=int(ds.height),crs=(str(ds.crs) if ds.crs is not None else None),georeferenced=bool(ds.crs is not None))
                except Exception:
                    rec.update(crs=None,georeferenced=False)
            out.append(rec)
    return out


def _web_collect_layers(pp):
    """Only important results are placed in the panel by default.

    Other project GIS files remain available through the Add layer dialog.
    """
    candidates=[]
    stage_specs=[
        ('MULTICHANNEL',('bz_grid',)),
        ('NATIVE',('bz_grid',)),
        ('GEOREFERENCED',('georeferenced',)),
        ('TOTAL_FIELD',('total_field_archaeology','total_field_destriped','total_field_corrected')),
        ('FLUXGATE',('fluxgate_archaeology','fluxgate_processed','fluxgate_reference','bartington_fluxgate_archaeology','bartington_fluxgate_processed','bartington_fluxgate_reference')),
        ('INTERPOLATED',('interpolated',)),
        ('CLEAN',('cleaned','clean')),
        ('ENHANCED',('subtle_residual','analytic_signal')),
    ]
    for stage,tokens in stage_specs:
        root=pp['results']/stage
        if not root.exists(): continue
        files=sorted(list(root.rglob('*.tif'))+list(root.rglob('*.tiff')),key=_natural_path_key)
        bad=('mask','support','preserved_gap','uncertainty','removed','difference','count','density','correction','clipped','measured_cell')
        files=[q for q in files if not any(b in q.stem.lower() for b in bad)]
        chosen=None
        for tok in tokens:
            hits=[q for q in files if tok in q.stem.lower()]
            if hits: chosen=hits[0]; break
        if chosen is None and files: chosen=files[0]
        if chosen is not None: candidates.append((stage,chosen))
    layers=[]
    # Prefer the principal interpretation stage for each project family.
    stage_names={st for st,_ in candidates}
    default_stage=next((st for st in ('INTERPOLATED','GEOREFERENCED','TOTAL_FIELD','FLUXGATE','CLEAN','MULTICHANNEL','NATIVE','ENHANCED') if st in stage_names),None)
    for st,q in candidates:
        try: layers.append(_web_layer_meta(q,pp,default_on=(st==default_stage)))
        except Exception as exc: print(f'[web] skipped default layer {q}: {exc}',flush=True)
    return layers


def _web_resolve_stretch(arr,item,query):
    import numpy as np
    valid=np.asarray(arr,float); vals=valid[np.isfinite(valid)]
    if not vals.size: return -1.0,1.0
    mode=str(query.get('stretch',['manual'])[0]).lower()
    if mode=='data': return float(np.nanmin(vals)),float(np.nanmax(vals))
    if mode=='stddev':
        try: k=max(0.05,float(query.get('stddev',[2])[0]))
        except Exception: k=2.0
        m=float(np.nanmean(vals)); sd=float(np.nanstd(vals)); return m-k*sd,m+k*sd
    if mode=='cumulative':
        try: lo=max(0,min(49,float(query.get('cut_low',[1])[0]))); hi=max(0,min(49,float(query.get('cut_high',[1])[0])))
        except Exception: lo=hi=1.0
        return float(np.nanpercentile(vals,lo)),float(np.nanpercentile(vals,100-hi))
    try: vmin=float(query.get('vmin',[item.get('vmin',-1)])[0]); vmax=float(query.get('vmax',[item.get('vmax',1)])[0])
    except Exception: vmin,vmax=item.get('vmin',-1),item.get('vmax',1)
    if not np.isfinite(vmin) or not np.isfinite(vmax) or vmax<=vmin: return float(item.get('vmin',-1)),float(item.get('vmax',1))
    return vmin,vmax


def _web_html(project_name,initial_json):
    path=Path(__file__).with_name('web')/'magsurveypy_web.html'
    if not path.exists(): raise SystemExit(f'Web GIS template is missing: {path}')
    return path.read_text(encoding='utf-8').replace('__PROJECT__',str(project_name)).replace('__DATA__',initial_json)


def _web_safe_extract_zip(zp,target):
    import zipfile
    target=Path(target).resolve(); target.mkdir(parents=True,exist_ok=True)
    with zipfile.ZipFile(zp) as z:
        for info in z.infolist():
            dest=(target/info.filename).resolve()
            if target not in dest.parents and dest!=target: raise ValueError('unsafe ZIP path')
        z.extractall(target)


def _web_make_handler(pp):
    """Local responsive Web GIS API using only the Python standard HTTP server."""
    import io,json,uuid,time,zipfile,shutil,re
    from functools import lru_cache
    from http.server import BaseHTTPRequestHandler
    from urllib.parse import urlparse,parse_qs
    import numpy as np
    import rasterio
    from rasterio.warp import calculate_default_transform,reproject,Resampling,transform_bounds
    import matplotlib as mpl
    # The local Web GIS is a server process: never initialise a GUI backend
    # from request threads. Agg also avoids GTK/Qt/IBus file-watch side effects.
    try:
        mpl.use('Agg', force=True)
    except Exception:
        pass
    import threading
    render_lock=threading.RLock()
    layers=_web_collect_layers(pp)
    rindex={x['id']:x for x in layers if x['type']=='raster'}; vindex={x['id']:x for x in layers if x['type']=='vector'}
    available=_web_all_project_files(pp); aindex={x['key']:x for x in available}
    downloads={}
    imported_dir=pp['exports']/'WebGIS'/'Imported'; imported_dir.mkdir(parents=True,exist_ok=True)
    drawing_dir=pp['exports']/'WebGIS'/'Drawings'; drawing_dir.mkdir(parents=True,exist_ok=True)
    map_dir=pp['exports']/'WebGIS'/'Maps'; map_dir.mkdir(parents=True,exist_ok=True)
    georef_dir=pp['results']/'GEOREFERENCED'; georef_dir.mkdir(parents=True,exist_ok=True)

    def public_layer(x): return {k:v for k,v in x.items() if k!='path'}
    def register_path(path,default_on=False):
        meta=_web_layer_meta(path,pp,default_on)
        if meta['type']=='raster': rindex[meta['id']]=meta
        else: vindex[meta['id']]=meta
        return meta
    def add_available_path(path):
        import hashlib
        q=Path(path).resolve(); rp=str(q);
        try: name=str(q.relative_to(pp['root']))
        except Exception: name=q.name
        typ='raster' if q.suffix.lower() in {'.tif','.tiff'} else 'vector'
        key=hashlib.sha1(('available:'+rp).encode('utf-8')).hexdigest()[:16]
        rec={'key':key,'name':name,'path':rp,'type':typ}
        if typ=='raster':
            try:
                with rasterio.open(q) as ds:
                    rec.update(width=int(ds.width),height=int(ds.height),crs=(str(ds.crs) if ds.crs is not None else None),georeferenced=bool(ds.crs is not None))
            except Exception:
                rec.update(crs=None,georeferenced=False)
        aindex[key]=rec
        for i,old in enumerate(available):
            if old.get('key')==key:
                available[i]=rec; break
        else: available.append(rec)
        return rec

    def georef_public_fit(fit):
        return {
            'target_crs':fit.target_crs,'gcp_count':len(fit.residuals),
            'rmse':fit.rmse,'mean_residual':fit.mean_residual,'max_residual':fit.max_residual,
            'rmse_pixels':fit.rmse_pixels,'rmse_m':fit.rmse_m,'max_residual_m':fit.max_residual_m,
            'pixel_size_x':fit.pixel_size_x,'pixel_size_y':fit.pixel_size_y,
            'transform':[float(x) for x in tuple(fit.transform)[:6]],'residuals':fit.residuals,
        }

    def georef_info(rec):
        if rec is None or rec.get('type')!='raster': raise ValueError('Choose a project raster.')
        with rasterio.open(rec['path']) as ds:
            return {'key':rec['key'],'name':rec['name'],'width':int(ds.width),'height':int(ds.height),
                    'crs':str(ds.crs) if ds.crs is not None else None,'georeferenced':bool(ds.crs is not None),
                    'dtype':str(ds.dtypes[0]),'count':int(ds.count),'nodata':(None if ds.nodata is None or (isinstance(ds.nodata,float) and not np.isfinite(ds.nodata)) else ds.nodata),
                    'units':_export_units(Path(rec['path']),ds.tags()),
                    'preview':f'/api/georef/preview/{rec["key"]}.png'}

    def public_state():
        unit_set=sorted({str(x.get('units')) for x in rindex.values() if x.get('units')})
        project_units=unit_set[0] if len(unit_set)==1 else ('mixed' if unit_set else 'unknown')
        return {
            'project':pp['root'].name,
            'layers':[public_layer(x) for x in layers],
            'cmaps':list(_WEB_CMAPS),
            'blends':list(_WEB_BLEND),
            'basemaps':['esri','osm','esri-topo','wms','wmts','none'],
            'units':project_units,
            'application':APP_NAME,
            'version':APP_VERSION,
            'author':APP_AUTHOR,
        }
    html=_web_html(pp['root'].name,json.dumps(public_state(),separators=(',',':'))).encode('utf-8')

    @lru_cache(maxsize=16)
    def wgs84_array(path_text):
        with rasterio.open(path_text) as ds:
            src=ds.read(1,masked=True).filled(np.nan).astype(np.float32)
            transform,width,height=calculate_default_transform(ds.crs,'EPSG:4326',ds.width,ds.height,*ds.bounds)
            maxdim=max(width,height)
            if maxdim>1800:
                scale=1800.0/maxdim; width=max(1,int(round(width*scale))); height=max(1,int(round(height*scale)))
                from rasterio.transform import from_bounds
                bb=transform_bounds(ds.crs,'EPSG:4326',*ds.bounds,densify_pts=21); transform=from_bounds(*bb,width,height)
            dst=np.full((height,width),np.nan,np.float32)
            reproject(src,dst,src_transform=ds.transform,src_crs=ds.crs,dst_transform=transform,dst_crs='EPSG:4326',src_nodata=np.nan,dst_nodata=np.nan,resampling=Resampling.bilinear)
            return dst

    def drawing_to_files(geojson_obj,fmt):
        import geopandas as gpd
        from shapely.geometry import shape
        feats=geojson_obj.get('features',[]) if isinstance(geojson_obj,dict) else []
        if not feats: raise ValueError('drawing has no features')
        stamp=time.strftime('%Y%m%d_%H%M%S'); stem=f'{_safe_project_name(pp["root"].name)}_drawing_{stamp}'
        # Build groups explicitly so Shapefile/GPKG handle mixed geometry safely.
        groups={'points':[],'lines':[],'polygons':[]}
        for f in feats:
            g=shape(f.get('geometry')) if f.get('geometry') else None
            if g is None or g.is_empty: continue
            gt=g.geom_type.lower(); key='points' if 'point' in gt else 'lines' if 'line' in gt else 'polygons' if 'polygon' in gt else None
            if key:
                props=dict(f.get('properties') or {})
                style=props.pop('_msp_style',None)
                if isinstance(style,dict):
                    props.setdefault('msp_color',style.get('color'))
                    props.setdefault('msp_fill',style.get('fillColor'))
                    props.setdefault('msp_w',style.get('weight'))
                    props.setdefault('msp_op',style.get('opacity'))
                    props.setdefault('msp_fop',style.get('fillOpacity'))
                    props.setdefault('msp_rad',style.get('radius'))
                groups[key].append({'geometry':g,**props})
        groups={k:v for k,v in groups.items() if v}
        if not groups: raise ValueError('no supported point/line/polygon drawing features')
        if fmt=='gpkg':
            out=drawing_dir/f'{stem}.gpkg'
            first=True
            for layer_name,rows in groups.items():
                gdf=gpd.GeoDataFrame(rows,geometry='geometry',crs='EPSG:4326')
                gdf.to_file(out,layer=layer_name,driver='GPKG',mode='w' if first else 'a'); first=False
            return out
        folder=drawing_dir/f'{stem}_shp'; folder.mkdir(parents=True,exist_ok=True)
        for layer_name,rows in groups.items():
            gdf=gpd.GeoDataFrame(rows,geometry='geometry',crs='EPSG:4326'); gdf.to_file(folder/f'{layer_name}.shp',driver='ESRI Shapefile')
        out=drawing_dir/f'{stem}_shapefiles.zip'
        with zipfile.ZipFile(out,'w',zipfile.ZIP_DEFLATED) as z:
            for f in folder.rglob('*'):
                if f.is_file(): z.write(f,f.relative_to(folder))
        shutil.rmtree(folder,ignore_errors=True); return out

    def make_download(path):
        token=uuid.uuid4().hex; downloads[token]=Path(path).resolve(); return f'/api/download/{token}'

    def sample_profile_line(item, coords, max_samples=1800):
        """Sample a raster along a multi-vertex WGS84 profile line."""
        from pyproj import Geod,Transformer
        geod=Geod(ellps='WGS84')
        pts=[]
        for c in (coords or []):
            if not isinstance(c,(list,tuple)) or len(c)<2: continue
            try: pts.append((float(c[0]),float(c[1])))
            except Exception: continue
        if len(pts)<2: raise ValueError('profile needs at least two vertices')
        seg=[]; cumulative=[0.0]
        for a,b in zip(pts[:-1],pts[1:]):
            az,_,dist=geod.inv(a[0],a[1],b[0],b[1]); dist=max(0.0,float(dist)); seg.append((a,b,float(az),dist)); cumulative.append(cumulative[-1]+dist)
        total=float(cumulative[-1])
        if total<=0: raise ValueError('profile has zero length')
        ns=max(120,min(int(max_samples),int(total/0.10)+1))
        distances=np.linspace(0.0,total,ns)
        ll=[]; si=0
        for d in distances:
            while si<len(seg)-1 and d>cumulative[si+1]: si+=1
            a,b,az,dist=seg[si]; local=max(0.0,min(dist,float(d-cumulative[si])))
            lon,lat,_=geod.fwd(a[0],a[1],az,local)
            ll.append((lon,lat))
        with rasterio.open(item['path']) as ds:
            tf=Transformer.from_crs('EPSG:4326',ds.crs,always_xy=True)
            xy=[tf.transform(lon,lat) for lon,lat in ll]
            values=[]
            for d,v in zip(distances,ds.sample(xy)):
                z=float(v[0])
                if ds.nodata is not None and z==ds.nodata: z=float('nan')
                values.append({'distance_m':float(d),'value':None if not np.isfinite(z) else z})
        finite=np.array([x['value'] for x in values if x['value'] is not None],float)
        stats={'count':int(finite.size)}
        if finite.size:
            stats.update(min=float(np.nanmin(finite)),max=float(np.nanmax(finite)),mean=float(np.nanmean(finite)),median=float(np.nanmedian(finite)),std=float(np.nanstd(finite)))
        return {'total_distance_m':total,'values':values,'units':item.get('units','unknown'),'stats':stats,'vertices':pts}

    def _web_wms_image(cfg,bounds,crs,shape):
        """Fetch one WMS 1.1.1 GetMap image for the exact export canvas."""
        from urllib.parse import urlencode,urlsplit,urlunsplit,parse_qsl
        from urllib.request import Request,urlopen
        from PIL import Image
        import io
        url=str((cfg or {}).get('url','')).strip()
        layers=str((cfg or {}).get('layers','')).strip()
        if not url or not layers:
            raise ValueError('Custom WMS requires URL and layer name(s).')
        epsg=None
        try: epsg=crs.to_epsg()
        except Exception: pass
        srs=f'EPSG:{epsg}' if epsg else str(crs)
        params=dict(parse_qsl(urlsplit(url).query,keep_blank_values=True))
        params.update({
            'SERVICE':'WMS','REQUEST':'GetMap','VERSION':'1.1.1','LAYERS':layers,
            'STYLES':str((cfg or {}).get('styles','')),
            'FORMAT':str((cfg or {}).get('format','image/png')),
            'TRANSPARENT':'TRUE','SRS':srs,
            'BBOX':f'{bounds.left},{bounds.bottom},{bounds.right},{bounds.top}',
            'WIDTH':str(int(shape[1])),'HEIGHT':str(int(shape[0]))
        })
        p=urlsplit(url); full=urlunsplit((p.scheme,p.netloc,p.path,urlencode(params),p.fragment))
        req=Request(full,headers={'User-Agent':'MagSurveyPy/1.0.3'})
        with urlopen(req,timeout=30) as r:
            raw=r.read()
        im=Image.open(io.BytesIO(raw)).convert('RGBA').resize((shape[1],shape[0]))
        return np.array(im,dtype=np.uint8,copy=True)

    def render_web_export(payload):
        import matplotlib.pyplot as plt
        import matplotlib as mpl2
        import geopandas as gpd
        from rasterio.coords import BoundingBox
        from rasterio.transform import from_bounds
        from pyproj import CRS
        vis=[x for x in payload.get('layers',[]) if x.get('id') in rindex or x.get('id') in vindex]
        raster_specs=[x for x in vis if x.get('type')=='raster' and x.get('id') in rindex]
        target_crs=rasterio.crs.CRS.from_epsg(3857)  # Leaflet render CRS: exact browser extent/aspect
        label_crs=rasterio.crs.CRS.from_epsg(4326)
        if raster_specs:
            with rasterio.open(rindex[raster_specs[0]['id']]['path']) as ds:
                label_crs=ds.crs or label_crs
        b=payload.get('bounds') or {}; wb=float(b.get('west')); sb=float(b.get('south')); eb=float(b.get('east')); nb=float(b.get('north'))
