        if pts is None and ras is None: raise SystemExit('No point table or raster could be resolved for analysis.')
        from .lib.analysis import write_analysis_dashboard
        od=_analysis_output(pp,'Survey',a.output); rep=write_analysis_dashboard(pts,ras,od,_safe_project_name(a.project),a.dpi,mspy_credit=a.mspy_credit,mspy_credit_position=a.mspy_credit_position,mspy_credit_size=a.mspy_credit_size,mspy_credit_alpha=a.mspy_credit_alpha)
        print(f"Survey dashboard: {rep['dashboard']}\nAnalysis JSON: {od/(_safe_project_name(a.project)+'_analysis.json')}")
